// ---- components/locations.js ----
// A shoot's location: its shape, how it reads on one line, and telling two apart.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addLocations = function addLocations(ed) {
  Object.assign(ed, { normalizeLocation, isLocationBlank, formatLocationDisplay, formatLocationDisplayNoCountry, locationKey });
  // Normalizes a shoot's location into the structured shape (name/street/
  // city/zip/country). Handles both a legacy plain-string location (folded
  // into `name`) and the old separate `region` field (folded into `country`)
  // so existing saved shoots keep their data after this schema change.
  function normalizeLocation(loc, legacyRegion) {
    if (loc && typeof loc === 'object') {
      return {
        name: loc.name || '',
        street: loc.street || '',
        city: loc.city || '',
        state: loc.state || '',
        zip: loc.zip || '',
        country: loc.country || legacyRegion || '',
      };
    }
    return { name: loc || '', street: '', city: '', state: '', zip: '', country: legacyRegion || '' };
  }

  function isLocationBlank(loc) {
    return !loc || (!ed.hasText(loc.name) && !ed.hasText(loc.street) && !ed.hasText(loc.city) && !ed.hasText(loc.state) && !ed.hasText(loc.zip) && !ed.hasText(loc.country));
  }

  // Composes a location into one display line: "name — street, city, state zip, Country".
  function formatLocationDisplay(loc) {
    if (!loc) return '';
    const parts = [];
    if (ed.hasText(loc.name)) parts.push(loc.name.trim());
    const cityStateZip = [loc.state, loc.zip].filter(ed.hasText).map(v => v.trim()).join(' ');
    const addressLine = [loc.street, loc.city, cityStateZip].filter(ed.hasText).join(', ');
    if (addressLine) parts.push(addressLine);
    if (loc.country) parts.push(ed.REGION_LABELS[loc.country] || loc.country);
    return parts.join(', ');
  }

  // The same line without the country. The shared PDF goes to talent and crew
  // who are already turning up at the address, so the country only pads out a
  // line that's usually wrapping anyway. Blanking the field rather than
  // reimplementing keeps the two formats from drifting apart.
  function formatLocationDisplayNoCountry(loc) {
    return formatLocationDisplay({ ...(loc || {}), country: '' });
  }

  // Case/whitespace-insensitive identity key for deduping/matching locations
  // (e.g. recognizing a past location was picked again for directions reuse).
  function locationKey(loc) {
    return ['name', 'street', 'city', 'state', 'zip', 'country'].map(k => ((loc && loc[k]) || '').trim().toLowerCase()).join('|');
  }
};
;

// ---- components/categories.js ----
// Kinds of shoot: their names, which show in the lists, the pie colours, new shoots' titles and the look tags.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addCategories = function addCategories(ed) {
  Object.assign(ed, { pickRandomSaveMessage, isCategoryVisible, saveCategoryVisibility, randomNewShootTitle });
  const CATEGORY_LABELS = {
    commercial: 'Commercial',
    content_shoot: 'Content shoot',
    video: 'Video',
    editorial: 'Editorial',
    lighting_test: 'Lighting test',
    portfolio_building: 'Portfolio building',
    test_shoot: 'Test shoot',
    event: 'Event',
    wedding: 'Wedding',
    engagement: 'Engagement',
    family: 'Family',
    headshot: 'Headshot',
    branding: 'Branding',
    publicity: 'Publicity',
    maternity: 'Maternity',
    other: 'Other',
    uncategorized: 'Uncategorized',
  }; ed.CATEGORY_LABELS = CATEGORY_LABELS;

  const CATEGORY_FILTER_ORDER = ['commercial', 'content_shoot', 'video', 'editorial', 'lighting_test', 'portfolio_building', 'test_shoot', 'event', 'wedding', 'engagement', 'family', 'headshot', 'branding', 'publicity', 'maternity', 'other']; ed.CATEGORY_FILTER_ORDER = CATEGORY_FILTER_ORDER;

  // Grammatical plural form of each category, for use as a countable noun in
  // a sentence (e.g. "more commercial shoots than video shoots") — CATEGORY_LABELS
  // are display titles ("Test shoot"), which read wrong dropped straight into
  // a sentence like that ("more Test shoot than Video").
  const CATEGORY_PLURAL_LABELS = {
    commercial: 'commercial shoots',
    video: 'video shoots',
    editorial: 'editorial shoots',
    lighting_test: 'lighting test shoots',
    portfolio_building: 'portfolio building shoots',
    test_shoot: 'test shoots',
    event: 'event shoots',
    wedding: 'wedding shoots',
    engagement: 'engagement shoots',
    family: 'family shoots',
    headshot: 'headshot shoots',
    branding: 'branding shoots',
    publicity: 'publicity shoots',
    maternity: 'maternity shoots',
    other: 'other shoots',
  }; ed.CATEGORY_PLURAL_LABELS = CATEGORY_PLURAL_LABELS;

  // Shared by every "I'm done here" button that used to just say "Save"
  // (Edit Shoot, and the Journal view's closing button) — everything here
  // already autosaves as you go, so these are really just a satisfying
  // confirmation tap, not a literal save action.
  // "I know it auto saves everything I do but I need a button to hit" is
  // held out for now — measured against the Save button's real width, it
  // wraps to 2 lines everywhere except when a delivered-but-not-archived
  // shoot puts Save side by side with Complete Shoot, where it needs ~5
  // lines and would force the button to grow. Left out until it's
  // shortened or swapped for something that fits at that narrower width.
  const SAVE_MESSAGES = [
    'I guess so', 'yup, yup', "that's good", 'okay', 'yes',
    "let's goooo", 'incredible', "I'm a genius", 'so good', 'good work',
    'affirm here', "I'm a visionary",
  ];

  function pickRandomSaveMessage() {
    return SAVE_MESSAGES[Math.floor(Math.random() * SAVE_MESSAGES.length)];
  }

  // Shared by the Shoots and Archive tabs: which category chips a user
  // actually wants cluttering their filter row. Missing entries default to
  // visible so new categories show up automatically.
  const CATEGORY_VISIBILITY_KEY = 'dailies_category_chip_visibility_v1';

  function loadCategoryVisibility() {
    try {
      return JSON.parse(localStorage.getItem(CATEGORY_VISIBILITY_KEY)) || {};
    } catch (e) {
      return {};
    }
  }

  let categoryVisibility = loadCategoryVisibility(); ed.categoryVisibility = categoryVisibility;

  function isCategoryVisible(cat) {
    return categoryVisibility[cat] !== false;
  }

  function saveCategoryVisibility() {
    localStorage.setItem(CATEGORY_VISIBILITY_KEY, JSON.stringify(categoryVisibility));
  }

  // Tonally matched to the app's navy/mango-yellow brand pair: same
  // mid-to-dark, non-neon register, cycled per pie in this fixed order.
  const PIE_COLORS = [
    '#ffd103', // mango yellow (accent)
    '#313d45', // navy (text)
    '#c8683d', // terracotta
    '#5b7c99', // dusty blue
    '#5c8a72', // sage green
    '#8a5a72', // plum
    '#d9a441', // warm sand
    '#7d8a92', // slate
  ]; ed.PIE_COLORS = PIE_COLORS;

  const NEW_SHOOT_TITLES = [
    'we log shoots here',
    'oh yeah, booked and blessed',
    "we're up (planning shoots)",
    'shoot log, obviously',
    "professional shoot planner (that's you)",
    'big dreamer, you',
    'brethren, a new shoot has arrived',
    'imagine photo shoots',
  ];

  function randomNewShootTitle() {
    return NEW_SHOOT_TITLES[Math.floor(Math.random() * NEW_SHOOT_TITLES.length)];
  }

  const VISUAL_LANGUAGE_TAGS = ['Lifestyle', 'Documentary', 'Surrealism', 'Portrait', 'Fashion', 'Fitness', 'Cinematic', 'Commercial', 'Headshot', 'Beauty', 'Couples', 'Other']; ed.VISUAL_LANGUAGE_TAGS = VISUAL_LANGUAGE_TAGS;
  // Tags dropped from VISUAL_LANGUAGE_TAGS. Kept as a named list because the
  // framework lives in saved state, not in the constant above — an existing
  // install has its own copy, so retiring a tag takes a migration (see
  // removeFrameworkTags).
  const RETIRED_VISUAL_LANGUAGE_TAGS = ['Magic realism']; ed.RETIRED_VISUAL_LANGUAGE_TAGS = RETIRED_VISUAL_LANGUAGE_TAGS;
};
;

// ---- data/default-state.js ----
// What a new notebook starts with: the frameworks, the app colour, how it looks, the photographer.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addDefaultState = function addDefaultState(ed) {
  Object.assign(ed, { seedFrameworks, normalizePresentation, defaultState, normalizeSocialHandle, normalizePhotographer, photographerHasInfo, applyAppColor });
  function seedFrameworks() {
    return [
      {
        id: ed.uid(),
        name: 'Visual Language',
        tags: [...ed.VISUAL_LANGUAGE_TAGS],
      },
    ];
  }

  const APP_COLORS = [['mango', 'Mango'], ['orange', 'Orange'], ['berry', 'Berry'], ['fern', 'Fern'], ['ocean', 'Ocean'], ['ink', 'Black']]; ed.APP_COLORS = APP_COLORS;
  const APP_COLOR_KEY = 'df-app-color'; // also read in index.html, before the first paint

  function firstAppColor() {
    let c = null;
    try { c = localStorage.getItem(APP_COLOR_KEY); } catch (e) { /* storage unavailable */ }
    return APP_COLORS.some(([key]) => key === c) ? c : 'mango';
  }
  // How the notebook looks: its color, where the app starts, and the stickers
  // on its cover (their photos are in IndexedDB, see stickerKey).
  function normalizePresentation(saved) {
    const p = saved && typeof saved === 'object' ? saved : {};
    return {
      // None yet (a first launch): the one picked on the shelf, if any.
      color: APP_COLORS.some(([key]) => key === p.color) ? p.color : firstAppColor(),
      // Where it opens: where you left off unless you picked otherwise since
      // that became the default (11-11), so an old 'notebook' carries over.
      start: p.startPicked && (p.start === 'first' || p.start === 'notebook') ? p.start : 'last',
      startPicked: !!p.startPicked,
      stickers: (Array.isArray(p.stickers) ? p.stickers : []).filter(s => s && typeof s.id === 'string'
        && (s.shape === 'circle' || s.shape === 'square' || s.shape === 'rect') && [s.x, s.y, s.size].every(Number.isFinite)),
    };
  }
  const stickerKey = id => `${id}__sticker`; ed.stickerKey = stickerKey;

  // Up here for the same reason as APP_COLORS: normalizeProjects (run by
  // loadState) uses it, and a const declared any further down would throw
  // there and start the app empty.
  const UNTITLED_PROJECT_NAME = 'Untitled project'; ed.UNTITLED_PROJECT_NAME = UNTITLED_PROJECT_NAME;

  function defaultState() {
    return {
      shoots: [],
      projects: [],
      frameworks: seedFrameworks(),
      journalEntries: [],
      titleDisplayMode: 'talent',
      presentation: normalizePresentation(),
      defaultCountry: '',
      dismissedLocationKeys: [],
      dismissedTeamMemberKeys: [],
      dismissedTalentKeys: [],
      dismissedLightingSetupKeys: [],
      photographer: emptyPhotographer(),
    };
  }

  // Who's behind the camera — surfaced on call sheets ahead of the rest of the
  // crew. Every field is optional; the first-run prompt and the app menu both
  // edit this same object.
  function emptyPhotographer() {
    return { name: '', businessName: '', socialPlatform: 'instagram', socialHandle: '', phone: '' };
  }

  // Handle fields prefill with "@" so there's less to type — but if that's
  // all that's left when the field is saved (tapped in, nothing typed,
  // tapped away), it should read as never having been set, not as a real
  // (garbage) handle. Used everywhere a handle gets committed: photographer,
  // talent, team member.
  function normalizeSocialHandle(value) {
    const trimmed = (value || '').trim();
    return trimmed === '@' ? '' : trimmed;
  }

  function normalizePhotographer(p) {
    const src = (p && typeof p === 'object') ? p : {};
    return {
      name: src.name || '',
      businessName: src.businessName || '',
      socialPlatform: src.socialPlatform || 'instagram',
      socialHandle: src.socialHandle || '',
      phone: src.phone || '',
    };
  }

  function photographerHasInfo(p) {
    return !!p && (ed.hasText(p.name) || ed.hasText(p.businessName) || ed.hasText(p.socialHandle) || ed.hasText(p.phone));
  }

  // ---------- App color (the sun menu's: sets :root[data-book] and df-app-color) ----------
  function applyAppColor(color) {
    document.documentElement.dataset.book = color;
    try { localStorage.setItem(APP_COLOR_KEY, color); } catch (err) { /* it just paints mango first next launch */ }
  }
};
;

// ---- data/migrate.js ----
// Old saves brought up to date: journal entries, frameworks, statuses, shoots and projects.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addMigrate = function addMigrate(ed) {
  Object.assign(ed, { migrateJournalEntry, migrateFrameworks, migrateIdeaPhaseStatus, removeFramework, removeFrameworkTags, renameFrameworkTag, migrateShoot, projectsWithMembers, normalizeProjects });
  function migrateJournalEntry(e) {
    const entry = {
      id: e.id || ed.uid(),
      title: e.title || '',
      body: e.body || '',
      tags: Array.isArray(e.tags) ? e.tags : [],
      createdAt: e.createdAt || ed.todayStr(),
    };
    if (e.sourceShootId) entry.sourceShootId = e.sourceShootId;
    return entry;
  }

  // One-time, idempotent cleanup: drops the old Documenting Fictions
  // Principles framework (this app is meant to be shareable, not tied to one
  // photographer's vocabulary) and the Lighting framework (folded into the
  // more robust Lighting setups list instead — see removeFramework in
  // loadState for the accompanying per-shoot frameworkTags cleanup), and
  // upgrades Visual Language's tags forward through each past default set,
  // but only while they still exactly match a known-old default (so a
  // user's own edits are never clobbered).
  function migrateFrameworks(frameworks) {
    let result = frameworks.filter(f => f.name !== 'Documenting Fictions Principles' && f.name !== 'Lighting');
    const oldestVisualTags = ['Narrative Realism', 'Expressive Performance', 'Editorial Aesthetic', 'Cinematic Atmosphere'];
    const midVisualTags = ['Realism', 'Lifestyle', 'Documentary', 'Magic realism', 'Surreal', 'Other'];
    const priorVisualTags = ['Realism', 'Lifestyle', 'Documentary', 'Magic realism', 'Surreal', 'Portrait', 'Other'];
    const laterVisualTags = ['Realism', 'Lifestyle', 'Documentary', 'Magic realism', 'Surrealism', 'Portrait', 'Other'];
    const newVisualTags = ['Lifestyle', 'Documentary', 'Magic realism', 'Surrealism', 'Portrait', 'Fashion', 'Fitness', 'Cinematic', 'Other'];
    const newerVisualTags = ['Lifestyle', 'Documentary', 'Magic realism', 'Surrealism', 'Portrait', 'Fashion', 'Fitness', 'Cinematic', 'Commercial', 'Headshot', 'Test shoot', 'Other'];
    const priorNewestVisualTags = ['Lifestyle', 'Documentary', 'Magic realism', 'Surrealism', 'Portrait', 'Fashion', 'Fitness', 'Cinematic', 'Commercial', 'Headshot', 'Other'];
    const beforeCouplesVisualTags = ['Lifestyle', 'Documentary', 'Surrealism', 'Portrait', 'Fashion', 'Fitness', 'Cinematic', 'Commercial', 'Headshot', 'Beauty', 'Other'];
    const vl = result.find(f => f.name === 'Visual Language');
    if (vl) {
      const current = JSON.stringify(vl.tags);
      if (current === JSON.stringify(oldestVisualTags) || current === JSON.stringify(midVisualTags) || current === JSON.stringify(priorVisualTags) || current === JSON.stringify(laterVisualTags) || current === JSON.stringify(newVisualTags) || current === JSON.stringify(newerVisualTags) || current === JSON.stringify(priorNewestVisualTags) || current === JSON.stringify(beforeCouplesVisualTags)) {
        vl.tags = [...ed.VISUAL_LANGUAGE_TAGS];
      }
    }
    return result.length ? result : ed.seedFrameworks();
  }

  // Drops a whole framework's stale frameworkTags entries once it's been
  // retired (see migrateFrameworks) — mirrors removeFrameworkTags but for a
  // framework that no longer exists at all, so there's no fw.id left to read
  // off the migrated list; the caller passes the id it captured beforehand.
  // "Early idea" (idea_phase) is a retired status — folded into Active
  // planning, the next stage forward, since it never got its own migration
  // and existing shoots there would otherwise keep a status STATUS_LABELS
  // no longer has an entry for.
  function migrateIdeaPhaseStatus(shoots) {
    shoots.forEach(s => {
      if (s.status === 'idea_phase') s.status = 'planning';
    });
  }

  function removeFramework(shoots, frameworkId) {
    if (!frameworkId) return;
    shoots.forEach(s => {
      s.frameworkTags = (s.frameworkTags || []).filter(t => t.frameworkId !== frameworkId);
    });
  }

  // Retires tags from a framework: drops them from the framework's own list and
  // from every shoot that had one checked. Clearing the shoots matters — a
  // selection pointing at a tag with no checkbox left is invisible but still
  // counted, so leaving them behind would quietly skew anything that tallies
  // tags. Also inserts any newly added tags, positioned to match canonicalOrder
  // rather than appended, so the list doesn't reshuffle for existing users.
  function removeFrameworkTags(shoots, frameworks, frameworkName, retiredTags, canonicalOrder) {
    const fw = frameworks.find(f => f.name === frameworkName);
    if (!fw) return;
    const retired = new Set(retiredTags);
    if (!fw.tags.some(t => retired.has(t))) return;

    const kept = fw.tags.filter(t => !retired.has(t));
    const added = canonicalOrder.filter(t => !kept.includes(t));
    // Rebuild in canonical order, keeping any user-added tags the constant
    // doesn't know about pinned to the end.
    const known = canonicalOrder.filter(t => kept.includes(t) || added.includes(t));
    const custom = kept.filter(t => !canonicalOrder.includes(t));
    fw.tags = known.concat(custom);

    shoots.forEach(s => {
      s.frameworkTags = (s.frameworkTags || []).filter(t => !(t.frameworkId === fw.id && retired.has(t.tag)));
    });
  }

  // Renames a specific tag string within a framework's tag list, and keeps
  // any shoot that already had the old tag checked pointed at the new one
  // (otherwise the checkbox would silently appear unchecked after rename).
  function renameFrameworkTag(shoots, frameworks, frameworkName, oldTag, newTag) {
    const fw = frameworks.find(f => f.name === frameworkName);
    if (!fw) return;
    shoots.forEach(s => {
      (s.frameworkTags || []).forEach(t => {
        if (t.frameworkId === fw.id && t.tag === oldTag) t.tag = newTag;
      });
    });
  }

  // Migrates a shoot forward through each past shape this app has used:
  // old flat manifestoTags/visualTags/concept -> frameworkTags[]/premise;
  // old shootType + isProofBuilding -> single category; old deliveryStatus
  // -> lifecycle status; old single reflection field -> lessonsLearned
  // (the closest of the new three reflection boxes, since a clean 3-way
  // split of old freeform text isn't possible).
  function migrateShoot(s, frameworks) {
    if (s.frameworkTags && s.category && s.status !== undefined && s.moodboardComplete !== undefined && Array.isArray(s.references) && s.teamRequired !== undefined && Array.isArray(s.talents) && s.location && typeof s.location === 'object') return s;
    const dfp = frameworks.find(f => f.name === 'Documenting Fictions Principles');
    const vl = frameworks.find(f => f.name === 'Visual Language');
    const frameworkTags = s.frameworkTags || [];
    (s.manifestoTags || []).forEach(tag => { if (dfp) frameworkTags.push({ frameworkId: dfp.id, tag }); });
    (s.visualTags || []).forEach(tag => { if (vl) frameworkTags.push({ frameworkId: vl.id, tag }); });
    const category = s.category || (s.isProofBuilding || s.shootType === 'proof' ? 'portfolio_building' : 'client');
    const status = s.status !== undefined ? s.status : (ed.hasText(s.deliveryStatus) ? 'delivered' : 'prospect');
    const lessonsLearned = s.lessonsLearned !== undefined ? s.lessonsLearned : (s.reflection || '');
    return {
      ...s,
      title: s.title || '',
      status,
      location: ed.normalizeLocation(s.location, s.region),
      startTime: s.startTime || s.time || '',
      endTime: s.endTime || '',
      crewCallTime: s.crewCallTime || '',
      talentCallTime: s.talentCallTime || '',
      premise: s.premise !== undefined ? s.premise : (s.concept || ''),
      character: s.character || '',
      shootGoals: s.shootGoals || '',
      elevatorPitch: s.elevatorPitch || '',
      deliverables: s.deliverables || '',
      aspectRatios: ed.normalizeAspectRatios(s.aspectRatios),
      deliverableDestinations: s.deliverableDestinations || '',
      emotionalBeats: s.emotionalBeats || [],
      worldNotes: s.worldNotes || '',
      lightingNotes: s.lightingNotes || '',
      wardrobeNotes: s.wardrobeNotes || '',
      references: Array.isArray(s.references) ? s.references : (ed.hasText(s.references) ? [s.references] : []),
      frameworkTags,
      category,
      generalNotes: s.generalNotes || '',
      whatWentRight: s.whatWentRight || '',
      couldBeBetter: s.couldBeBetter || '',
      lessonsLearned,
      projectPhoto: s.projectPhoto || null,
      moodboardComplete: s.moodboardComplete || false,
      teamRequired: s.teamRequired || (s.requiresTeam ? 'yes' : ''),
      teamFinalized: s.teamFinalized || false,
      teamMembers: (s.teamMembers || []).map(tm => ({ socialPlatform: 'instagram', ...tm })),
      talents: Array.isArray(s.talents) ? s.talents : (ed.hasText(s.talentName) || (s.socialHandles || []).some(sh => ed.hasText(sh.handle)) ? [{ name: s.talentName || '', socialHandles: s.socialHandles || [] }] : []),
      archived: s.archived || false,
    };
  }

  // A project id (and a shoot's projectId, when it has one) is any non-empty
  // string.
  function isValidProjectId(id) {
    return typeof id === 'string' && id.trim() !== '';
  }

  // The projects that still have at least one shoot. Takes its inputs rather
  // than reading `state`, so loadState can use it too — pruneEmptyProjects is
  // the live-state version.
  function projectsWithMembers(projects, shoots) {
    const used = new Set();
    shoots.forEach(s => {
      if (s && isValidProjectId(s.projectId)) used.add(s.projectId);
    });
    return projects.filter(p => used.has(p.id));
  }

  // Load/import pass for state.projects (see "Projects" further down for what
  // a project is). Keeps well-formed { id, name, createdAt } records — the
  // first of any repeated id wins, names are trimmed and a blank one becomes
  // "Untitled project" — and clears a shoot's projectId that isn't a usable
  // id. A shoot whose project has no record gets the record rebuilt rather
  // than its projectId stripped: an older cached build (whose loadState
  // doesn't know about state.projects) drops every record on its next save
  // but keeps each shoot's projectId, since shoots are saved whole — so
  // rebuilding here brings the grouping back, named after the project's
  // earliest shoot that has a title. Projects left with no shoots are dropped.
  // Called from loadState, so it must not touch `state`, and anything it reads
  // has to be a function declaration or a const declared above
  // `let state = loadState()`.
  function normalizeProjects(rawProjects, shoots) {
    const byId = new Map();
    (Array.isArray(rawProjects) ? rawProjects : []).forEach(p => {
      if (!p || typeof p !== 'object' || !isValidProjectId(p.id) || byId.has(p.id)) return;
      const record = {
        id: p.id,
        name: (typeof p.name === 'string' && p.name.trim()) || ed.UNTITLED_PROJECT_NAME,
        createdAt: (typeof p.createdAt === 'string' && p.createdAt) || ed.todayStr(),
      };
      // A multi-day project's lead day and the signature of what was last
      // mirrored from it (see syncProjectMirrors).
      if (isValidProjectId(p.leadShootId)) record.leadShootId = p.leadShootId;
      if (typeof p.mirrorSig === 'number') record.mirrorSig = p.mirrorSig;
      byId.set(p.id, record);
    });
    const membersById = new Map();
    shoots.forEach(s => {
      if (!s || s.projectId === undefined || s.projectId === '') return;
      if (!isValidProjectId(s.projectId)) {
        s.projectId = '';
        return;
      }
      if (!membersById.has(s.projectId)) membersById.set(s.projectId, []);
      membersById.get(s.projectId).push(s);
    });
    membersById.forEach((members, id) => {
      if (byId.has(id)) return;
      const named = members
        .slice()
        .sort((a, b) => ed.dateTimeSortKey(a).localeCompare(ed.dateTimeSortKey(b)))
        .find(s => typeof s.title === 'string' && s.title.trim());
      byId.set(id, { id, name: named ? named.title.trim() : ed.UNTITLED_PROJECT_NAME, createdAt: ed.todayStr() });
    });
    return projectsWithMembers([...byId.values()], shoots);
  }
};
;

// ---- data/load.js ----
// Loading what's saved (and keeping photos out of it).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addLoad = function addLoad(ed) {
  Object.assign(ed, { loadState, stripPhotos });
  function loadState() {
    try {
      const raw = localStorage.getItem(ed.STORAGE_KEY);
      if (!raw) return ed.defaultState();
      const parsed = JSON.parse(raw);
      const rawFrameworks = (Array.isArray(parsed.frameworks) && parsed.frameworks.length) ? parsed.frameworks : ed.seedFrameworks();
      const retiredLightingFwId = (rawFrameworks.find(f => f.name === 'Lighting') || {}).id;
      const frameworks = ed.migrateFrameworks(rawFrameworks);
      const shoots = (parsed.shoots || []).map(s => ed.migrateShoot(s, frameworks));
      ed.migrateIdeaPhaseStatus(shoots);
      ed.normalizeShootStatuses(shoots);
      ed.removeFramework(shoots, retiredLightingFwId);
      ed.renameFrameworkTag(shoots, frameworks, 'Visual Language', 'Surreal', 'Surrealism');
      ed.removeFrameworkTags(shoots, frameworks, 'Visual Language', ed.RETIRED_VISUAL_LANGUAGE_TAGS, ed.VISUAL_LANGUAGE_TAGS);
      // Needs the shoots in their final shape: it rebuilds any project record
      // a shoot still points at and drops projects left with no shoots.
      const projects = ed.normalizeProjects(parsed.projects, shoots);
      // sourceShootId entries were auto-mirrored from a shoot's own reflection
      // fields — that mirroring is gone (Reflections now only ever shows
      // entries written there directly), so any left over from before are
      // dropped here rather than lingering as orphaned duplicates. The
      // reflection text itself isn't lost: it still lives on the shoot.
      const journalEntries = (Array.isArray(parsed.journalEntries) ? parsed.journalEntries : [])
        .filter(e => !e.sourceShootId)
        .map(ed.migrateJournalEntry);
      return {
        shoots,
        projects,
        frameworks,
        journalEntries,
        titleDisplayMode: parsed.titleDisplayMode === 'title' ? 'title' : 'talent',
        presentation: ed.normalizePresentation(parsed.presentation),
        defaultCountry: typeof parsed.defaultCountry === 'string' ? parsed.defaultCountry : '',
        dismissedLocationKeys: Array.isArray(parsed.dismissedLocationKeys) ? parsed.dismissedLocationKeys : [],
        dismissedTeamMemberKeys: Array.isArray(parsed.dismissedTeamMemberKeys) ? parsed.dismissedTeamMemberKeys : [],
        dismissedTalentKeys: Array.isArray(parsed.dismissedTalentKeys) ? parsed.dismissedTalentKeys : [],
        dismissedLightingSetupKeys: Array.isArray(parsed.dismissedLightingSetupKeys) ? parsed.dismissedLightingSetupKeys : [],
        photographer: ed.normalizePhotographer(parsed.photographer),
      };
    } catch (e) {
      console.error('Failed to load state, starting fresh', e);
      return ed.defaultState();
    }
  }

  // Photos stay on the in-memory objects so rendering can read them
  // synchronously, but they're stripped back out on the way to localStorage —
  // they live in IndexedDB instead (see projectPhotoKey/talentPhotoKey). This
  // is what keeps a routine autosave a small text-only write instead of
  // re-serializing every base64 photo in the library.
  // NOTE: a JSON replacer matches by key name at any depth, so these two names
  // are reserved for photos — don't reuse them for anything that must persist.
  function stripPhotos(key, value) {
    if (key === 'projectPhoto' || key === 'photo') return undefined;
    return value;
  }
};
;

// ---- data/save.js ----
// Saving, and speaking up when the phone's storage is full.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addSave = function addSave(ed) {
  Object.assign(ed, { isStorageFullError, noteStorageFull, saveState });
  // ---------- Storage full ----------
  // When the phone's storage for the app runs out, saves fail: localStorage
  // throws QuotaExceededError and an IndexedDB write aborts with it. Those
  // used to fail silently, so a photo could look added and simply not be
  // there next time. Now they say so — at most once every few seconds,
  // since one full store tends to fail a whole burst of writes at once.
  // Declared up here, ahead of the first saveState(), so it's ready before
  // anything can save.
  const STORAGE_FULL_MESSAGE = "Couldn't save. Your phone's storage for the app may be full. Back up and free some space.";
  let storageFullNoticeAt = 0;

  // Older engines report a full store by code rather than name (22 in
  // WebKit/Chromium, 1014 in Firefox).
  function isStorageFullError(err) {
    if (!err) return false;
    return err.name === 'QuotaExceededError' || err.name === 'NS_ERROR_DOM_QUOTA_REACHED' || err.code === 22 || err.code === 1014;
  }

  // The .catch on photo writes: speaks up when the store is full and stays
  // quiet about anything else, as before (a photo that couldn't be read is
  // not a storage problem).
  function noteStorageFull(err) {
    if (!isStorageFullError(err)) return;
    const now = Date.now();
    if (now - storageFullNoticeAt < 5000) return;
    storageFullNoticeAt = now;
    // Deferred: saveState can run while the app is still starting up,
    // before the toast code further down has been reached. Up longer than a
    // routine toast: it's more to read, and it matters. A notice, so it
    // waits for an Undo toast that's up (the removal it follows) rather
    // than wiping out its button.
    setTimeout(() => ed.showNoticeToast(STORAGE_FULL_MESSAGE, 6000), 0);
  }

  function saveState() {
    // Every save first brings multi-day projects in line: a change to a lead
    // day is mirrored onto the days following it, and a following day that
    // was changed by hand stops following (see syncProjectMirrors).
    ed.syncProjectMirrors();
    try {
      localStorage.setItem(ed.STORAGE_KEY, JSON.stringify(ed.state, ed.stripPhotos));
    } catch (err) {
      // Out of room: the change is still on screen but won't survive a
      // relaunch, so say so. Anything else is a bug and still throws.
      if (!isStorageFullError(err)) throw err;
      noteStorageFull(err);
    }
    ed.freezeShotBoardsSoon(); // a shoot just shot: its boards from Ref stop changing
  }
};
;

// ---- components/shoot-row.js ----
// A shoot as a row in a list, and the compact row.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootRow = function addShootRow(ed) {
  Object.assign(ed, { shootThumbHtml, renderShootRow, renderCompactShootRow });
  const SHOOT_THUMB_EMPTY_SVG = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 8h3l1.5-2h7L17 8h3a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1Z"/><circle cx="12" cy="13" r="3.5"/></svg>`;

  function shootThumbHtml(s) {
    return s.projectPhoto
      ? `<div class="shoot-thumb"><img src="${s.projectPhoto}" alt="" /></div>`
      : `<div class="shoot-thumb shoot-thumb-empty">${SHOOT_THUMB_EMPTY_SVG}</div>`;
  }

  function renderShootRow(container, s, opts) {
    // Lets a section suppress the whole badge outright — e.g. Overview's
    // Proofs pending and Upcoming deadlines sections are each already one
    // homogeneous category, so re-stating "Pending: Proofs" or the status
    // on every row there is redundant. Today/Upcoming shoots mix several
    // statuses together, so the badge still earns its place there.
    const showBadge = !opts || opts.showBadge !== false;
    // Archive opts this in: a delivered shoot doesn't need its own status
    // re-stated there (it's implied by being in Archive), but if it's
    // missing final images that's worth flagging — resolved async below
    // since it requires an IndexedDB lookup, unlike every other badge part.
    const checkFinalImages = !!(showBadge && opts && opts.checkFinalImages && s.status === 'delivered' && !ed.isVideoShoot(s));
    const statusLabel = (showBadge && opts && opts.showStatus && !checkFinalImages) ? (ed.STATUS_LABELS[s.status] || '') : '';
    const pendingLabels = (showBadge && opts && opts.showPending) ? ed.shootPendingLabels(s) : [];
    const pendingText = pendingLabels.length ? `Pending: ${ed.escapeHtml(pendingLabels.join(', '))}` : '';
    // Proofs are only "pending" for the captured step itself — once a shoot
    // moves to waiting_for_selects, proofs have already gone out. Video has
    // no proofs step at all (after Captured it goes to Rough cut).
    const proofsPendingText = (showBadge && s.status === 'captured' && !ed.isVideoShoot(s)) ? 'Pending: Proofs' : '';
    // Once a shoot's captured there's a reflection worth writing eventually —
    // flag it if that's never happened yet, same idea as missing final images.
    // Applies on the Shoots page too, not just Archive, now that reflections
    // are expected any time from captured onward rather than only once archived.
    const hasReflection = ed.hasText(s.whatWentRight) || ed.hasText(s.couldBeBetter) || ed.hasText(s.lessonsLearned);
    const reflectionPendingText = (showBadge && ed.POST_CAPTURE_STATUSES.includes(s.status) && !hasReflection) ? 'Pending: Reflection' : '';
    // Status now gets its own stacked line with a background pill (see
    // .shoot-row-status-pill below) — everything else stays in the old
    // <br>-joined badge, which keeps its existing hidden/shown logic and its
    // async final-images top-up untouched, just moved to its own line under
    // the stack instead of sharing a slot with status.
    const badgeParts = [pendingText, proofsPendingText, reflectionPendingText].filter(Boolean);
    const badgeHtml = badgeParts.join('<br>');
    // Once delivered (or archived) there's nothing left to deliver, so the
    // deadline no longer means anything — don't show it. Otherwise, an
    // overdue deadline still shows, just in red.
    const isOverdue = !!s.deadline && s.deadline < ed.todayStr();
    const dueHtml = (s.deadline && !s.archived && s.status !== 'delivered')
      ? `<span class="shoot-row-date-line shoot-row-due${isOverdue ? ' overdue' : ''}">Due: ${ed.prettyDateShort(s.deadline)}</span>`
      : '';
    const statusHtml = statusLabel
      ? `<span class="shoot-row-status-pill">${ed.escapeHtml(statusLabel)}</span>`
      : '';
    // Opt-in (Today only): "Desert Western · Day 2 of 3" under the date for
    // a shoot that's part of a project, in the date line's own style.
    const rowProject = (opts && opts.showProjectLine && s.projectId) ? ed.findProject(s.projectId) : null;
    const rowDayInfo = rowProject ? ed.projectDayInfo(s) : null;
    const projectLineHtml = rowProject
      ? `<span class="shoot-row-date-line">${ed.escapeHtml(rowProject.name)}${rowDayInfo ? ` · Day ${rowDayInfo.day} of ${rowDayInfo.total}` : ''}</span>`
      : '';
    const div = document.createElement('div');
    div.className = 'shoot-row';
    div.innerHTML = `
      ${shootThumbHtml(s)}
      <div class="shoot-row-body">
        <span class="shoot-row-title"><strong>${ed.escapeHtml(ed.shootDisplayName(s))}</strong></span>
        <span class="shoot-row-date-line">${ed.shootDateLabel(s, ed.prettyDateShort)}</span>
        ${projectLineHtml}
        ${dueHtml}
        ${statusHtml}
        <span class="badge"${badgeHtml ? '' : ' hidden'}>${badgeHtml}</span>
      </div>
      <div class="shoot-row-accent-strip">
        <button type="button" class="row-options-btn" aria-label="Options">&#8942;</button>
      </div>
    `;
    div.addEventListener('click', () => {
      if (opts && opts.switchToShootsTab) document.querySelector('.tab[data-view="shoots"]').click();
      if (opts && opts.openArchiveMode) { ed.openArchiveMode(s.id); return; }
      ed.openShootModal(s.id);
    });
    // The whole yellow strip opens the options, not just the ⋮ circle in it:
    // the strip is what reads as the button, and a tap on it just beside the
    // ⋮ used to open the shoot instead. The ⋮ stays the focusable control
    // (keyboard, VoiceOver); its click bubbles up to here.
    div.querySelector('.shoot-row-accent-strip').addEventListener('click', (e) => {
      e.stopPropagation();
      ed.openShootOptions(s.id);
    });
    if (checkFinalImages) {
      ed.idbGetImages(ed.finalImagesKey(s.id)).then(images => {
        if (images.length) return;
        const badgeEl = div.querySelector('.badge');
        badgeEl.innerHTML = [...badgeParts, 'Pending: Final images'].join('<br>');
        badgeEl.hidden = false;
      }).catch(() => {});
    }
    container.appendChild(div);
  }

  // A smaller, photo-free row for tight spaces (the Overview counter
  // popups) — title, status, and shoot date, each on its own line, so
  // nothing is ever squeezed side-by-side against anything else.
  // opts.openArchiveMode (the project popup, for archived days) opens the
  // read-only Archive mode recap instead, same as a row on the Archive tab.
  function renderCompactShootRow(container, s, opts) {
    const statusLabel = ed.STATUS_LABELS[s.status] || '';
    const div = document.createElement('div');
    div.className = 'shoot-row-compact';
    div.innerHTML = `
      <div class="shoot-row-compact-body">
        <span class="shoot-row-compact-title">${ed.escapeHtml(ed.shootDisplayName(s))}</span>
        ${statusLabel ? `<span class="badge">${ed.escapeHtml(statusLabel)}</span>` : ''}
        <span class="mi-sub">${ed.shootDateLabel(s, ed.prettyDateShort)}</span>
      </div>
      <button type="button" class="row-options-btn" aria-label="Options">&#8942;</button>
    `;
    div.addEventListener('click', () => {
      if (opts && opts.openArchiveMode) { ed.openArchiveMode(s.id); return; }
      ed.openShootModal(s.id);
    });
    div.querySelector('.row-options-btn').addEventListener('click', (e) => {
      e.stopPropagation();
      ed.openShootOptions(s.id);
    });
    container.appendChild(div);
  }
};
;

// ---- components/project-groups.js ----
// Projects in lists: a project's shoots shown together under it.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addProjectGroups = function addProjectGroups(ed) {
  Object.assign(ed, { listItemRep, listItemDate, listItemStatusKey, projectDateRangeText, renderListItem, renderCompactListItem });
  // ---------- Projects in lists ----------
  // Every list of shoot rows (Overview, the counter popups, Shoots, Archive)
  // runs its shoots through collapseProjects() first, so a project's members
  // show as ONE box per list instead of a row per day. The helpers below read
  // either kind of item the same way. Today, Stats and the Journal stay
  // per-shoot and never see project boxes.

  // The shoot an item is sorted and filed by: a plain shoot is its own; a
  // project box uses its rep (collapseProjects: its next day ahead, else its
  // first day).
  function listItemRep(item) {
    return item.kind === 'project' ? item.rep : item.shoot;
  }

  // The date a list item is filed under for a given shoot field ('date' or
  // 'deadline') — a shoot's own value, or a project box's rep's, except for
  // 'deadline', where a project files under the earliest still-owed deadline
  // among its listed members: the same one its Due line shows.
  function listItemDate(item, field) {
    if (item.kind !== 'project') return item.shoot[field] || '';
    if (field === 'deadline') return projectNextDeadline(item.members);
    return item.rep[field] || '';
  }

  // Shoots-tab Status-sort group: a shoot's own status, or for a project box
  // the least-advanced status among its listed members, so the box sits with
  // whatever's still left to do.
  function listItemStatusKey(item) {
    return item.kind === 'project' ? ed.projectGroupStatusKey(item.members) : (item.shoot.status || 'prospect');
  }

  // Short dot-date range in prettyDateShort's locale-ordered numeral style —
  // "10.14–10.16.26" on an M/D/Y device. Two ends in the same year write the
  // year once, on whichever end the locale puts it (the end for M/D/Y and
  // D/M/Y, the start for Y/M/D), so the range still reads in the device's own
  // field order; different years spell out both ends in full; a single date
  // (or two equal ones) is just that date.
  function prettyDateRangeShort(startStr, endStr) {
    if (!startStr || !endStr || startStr === endStr) return ed.prettyDateShort(startStr || endStr);
    if (startStr.slice(0, 4) !== endStr.slice(0, 4)) return `${ed.prettyDateShort(startStr)}–${ed.prettyDateShort(endStr)}`;
    const numeralParts = (dateStr) => {
      const [y, m, d] = dateStr.split('-').map(Number);
      return new Intl.DateTimeFormat(undefined, { year: '2-digit', month: 'numeric', day: 'numeric' })
        .formatToParts(new Date(y, m - 1, d))
        .filter(p => p.type !== 'literal');
    };
    const startParts = numeralParts(startStr);
    const endParts = numeralParts(endStr);
    const join = (parts, withYear) => parts.filter(p => withYear || p.type !== 'year').map(p => p.value).join('.');
    const yearFirst = startParts.length > 0 && startParts[0].type === 'year';
    return yearFirst
      ? `${join(startParts, true)}–${join(endParts, false)}`
      : `${join(startParts, false)}–${join(endParts, true)}`;
  }

  // First-to-last date span of the given members ('' when none has a date).
  // Undated members are simply left out of the span.
  function projectDateRangeText(members) {
    const dates = members.map(s => s.date).filter(Boolean).sort();
    return dates.length ? prettyDateRangeShort(dates[0], dates[dates.length - 1]) : '';
  }

  // A project box's version of shootDateLabel: the same "Shoots:"/"Shot:"
  // prefix ("Shoots" while its last listed day is still ahead or today,
  // "Shot" once every listed day has passed) over the span of its listed
  // members' dates. "Date TBD" when none of them has a date yet. Postponed
  // and canceled days are left out (their dates are only the original plan,
  // see isOffScheduleShoot), unless every dated day is one: then it's the
  // span they were planned for, as "Originally: …", like a shoot row — or,
  // when any of them has been given a new date since (scheduledShootDate,
  // see isOriginalPlanDate), the span of those new dates, read as the plan.
  function projectDateRangeLabel(members) {
    let live = members.filter(ed.isProjectLiveShoot);
    if (!projectDateRangeText(live)) live = members.filter(s => ed.scheduledShootDate(s));
    const range = projectDateRangeText(live);
    if (!range) {
      const original = projectDateRangeText(members);
      return original ? `Originally: ${original}` : 'Date TBD';
    }
    const last = live.map(s => s.date).filter(Boolean).sort().pop();
    return `${last >= ed.todayStr() ? 'Shoots' : 'Shot'}: ${range}`;
  }

  // Earliest still-owed deadline among the given members, by the same rule
  // as Upcoming deadlines (isUpcomingDeadline): overdue still counts (and
  // shows in red), delivered or archived doesn't. '' when there's none.
  function projectNextDeadline(members) {
    return members.filter(ed.isUpcomingDeadline).map(s => s.deadline).sort()[0] || '';
  }

  // One box standing in for a project's members in a list. It uses the same
  // .shoot-row markup and classes as renderShootRow (same 96px thumb, accent
  // strip and 120px body floor) but is filled from the project:
  // - its name, and its rep's cover (else the first member's that has one);
  // - the date span of the members in THIS list;
  // - a "N shoots" line in the date line's style. N counts every member,
  //   archived ones included, so it reads the same in every list, plus
  //   "· 2 of 3 shot" while the project is part-way through capture;
  // - the earliest still-owed deadline, and the union of its listed members'
  //   Pending labels.
  // The same opts as renderShootRow switch the status pill and Pending line
  // on or off. Title + date + count + due + one pill/badge line still fits
  // inside the 120px min-height, so the box lines up with the shoot rows
  // around it. Like a shoot row, it only grows when a long Pending line wraps
  // on a narrow screen. Tapping the box, or its ⋮, opens the project popup,
  // never one shoot; each day is reachable from there.
  function renderProjectRow(container, item, opts) {
    const { project, members, rep } = item;
    const allMembers = ed.projectMembers(project.id);
    const showBadge = !opts || opts.showBadge !== false;
    const statusKey = (showBadge && opts && opts.showStatus) ? ed.projectGroupStatusKey(members) : '';
    const statusLabel = statusKey ? (ed.STATUS_LABELS[statusKey] || '') : '';
    const pendingLabels = (showBadge && opts && opts.showPending)
      ? [...new Set([].concat(...members.map(s => ed.shootPendingLabels(s))))]
      : [];
    const pendingText = pendingLabels.length ? `Pending: ${ed.escapeHtml(pendingLabels.join(', '))}` : '';
    // The same per-day reminders a shoot row adds whenever its badge shows
    // (proofs owed on a captured photo day, a reflection never written),
    // said once for the box when any listed day has them.
    const proofsPendingText = (showBadge && members.some(s => s.status === 'captured' && !ed.isVideoShoot(s))) ? 'Pending: Proofs' : '';
    const reflectionPendingText = (showBadge && members.some(s => ed.POST_CAPTURE_STATUSES.includes(s.status)
      && !ed.hasText(s.whatWentRight) && !ed.hasText(s.couldBeBetter) && !ed.hasText(s.lessonsLearned))) ? 'Pending: Reflection' : '';
    const badgeHtml = [pendingText, proofsPendingText, reflectionPendingText].filter(Boolean).join('<br>');
    // "· 2 of 3 shot" only while the project is part-way through capture
    // (projectShotProgressLabel is the same test projectStatusLabel uses); a
    // project entirely ahead or entirely shot already says so through its
    // dates and the list it sits in.
    const progress = ed.projectShotProgressLabel(allMembers);
    const progressText = progress ? ` · ${progress}` : '';
    const countText = `${allMembers.length} ${allMembers.length === 1 ? 'shoot' : 'shoots'}${progressText}`;
    const deadline = projectNextDeadline(members);
    const isOverdue = !!deadline && deadline < ed.todayStr();
    const dueHtml = deadline
      ? `<span class="shoot-row-date-line shoot-row-due${isOverdue ? ' overdue' : ''}">Due: ${ed.prettyDateShort(deadline)}</span>`
      : '';
    const statusHtml = statusLabel
      ? `<span class="shoot-row-status-pill">${ed.escapeHtml(statusLabel)}</span>`
      : '';
    const coverShoot = (rep && rep.projectPhoto) ? rep : allMembers.find(s => s.projectPhoto);
    const div = document.createElement('div');
    div.className = 'shoot-row';
    div.innerHTML = `
      ${ed.shootThumbHtml(coverShoot || {})}
      <div class="shoot-row-body">
        <span class="shoot-row-title"><strong>${ed.escapeHtml(project.name || ed.UNTITLED_PROJECT_NAME)}</strong></span>
        <span class="shoot-row-date-line">${ed.escapeHtml(projectDateRangeLabel(members))}</span>
        <span class="shoot-row-date-line">${ed.escapeHtml(countText)}</span>
        ${dueHtml}
        ${statusHtml}
        <span class="badge"${badgeHtml ? '' : ' hidden'}>${badgeHtml}</span>
      </div>
      <div class="shoot-row-accent-strip">
        <button type="button" class="row-options-btn" aria-label="Project options">&#8942;</button>
      </div>
    `;
    div.addEventListener('click', () => ed.openProjectPopup(project.id));
    div.querySelector('.row-options-btn').addEventListener('click', (e) => {
      e.stopPropagation();
      ed.openProjectPopup(project.id);
    });
    container.appendChild(div);
  }

  // renderCompactShootRow's counterpart for the Overview counter popups: the
  // project's name, its derived status in the status slot, and the date span
  // of its listed members. The status comes from the listed members only:
  // in "In the edit" that's the days actually in the edit, not a later day
  // still being planned. Tap or ⋮ opens the project popup, which stacks
  // above this one.
  function renderCompactProjectRow(container, item) {
    const { project, members } = item;
    const statusLabel = ed.projectStatusLabel(members);
    const div = document.createElement('div');
    div.className = 'shoot-row-compact';
    div.innerHTML = `
      <div class="shoot-row-compact-body">
        <span class="shoot-row-compact-title">${ed.escapeHtml(project.name || ed.UNTITLED_PROJECT_NAME)}</span>
        ${statusLabel ? `<span class="badge">${ed.escapeHtml(statusLabel)}</span>` : ''}
        <span class="mi-sub">${ed.escapeHtml(projectDateRangeLabel(members))}</span>
      </div>
      <button type="button" class="row-options-btn" aria-label="Project options">&#8942;</button>
    `;
    div.addEventListener('click', () => ed.openProjectPopup(project.id));
    div.querySelector('.row-options-btn').addEventListener('click', (e) => {
      e.stopPropagation();
      ed.openProjectPopup(project.id);
    });
    container.appendChild(div);
  }

  // Draws one collapseProjects() item: a normal shoot row, or a project box.
  function renderListItem(container, item, opts) {
    if (item.kind === 'project') renderProjectRow(container, item, opts);
    else ed.renderShootRow(container, item.shoot, opts);
  }

  // Compact (counter popup) version of renderListItem.
  function renderCompactListItem(container, item) {
    if (item.kind === 'project') renderCompactProjectRow(container, item);
    else ed.renderCompactShootRow(container, item.shoot);
  }
};
;

// ---- data/image-store.js ----
// Mood boards and final images, kept in the phone's database (IndexedDB).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addImageStore = function addImageStore(ed) {
  Object.assign(ed, { idbTransaction, normalizeMoodboardImages, idbGetImages, idbGetManyImages, idbSetImages, idbDeleteImages, noteImagesWritten, finalImagesKey, journalImagesKey, journalEntryImagesKey });
  // ---------- mood board / final image storage (IndexedDB) ----------
  // One connection for the whole session: opening a fresh one for every read
  // was most of what a launch spent waiting on photos (a cover and each
  // talent photo per shoot), on iPhone especially.
  let idbConnection = null;

  function idbOpen() {
    if (!idbConnection) {
      const opening = new Promise((resolve, reject) => {
        const req = indexedDB.open(ed.IDB_NAME, 1);
        req.onupgradeneeded = () => req.result.createObjectStore(ed.IDB_STORE);
        req.onsuccess = () => {
          const db = req.result;
          // Closed out from under us (another tab upgrading, or the browser
          // dropping it): the next call opens a new one — unless a newer
          // connection has already taken this one's place.
          const forget = () => { if (idbConnection === opening) idbConnection = null; };
          db.onversionchange = () => { db.close(); forget(); };
          db.onclose = forget;
          resolve(db);
        };
        req.onerror = () => reject(req.error);
      });
      opening.catch(() => { if (idbConnection === opening) idbConnection = null; });
      idbConnection = opening;
    }
    return idbConnection;
  }

  // Runs one transaction. `run(store)` queues its requests and may return a
  // function that reads their results; the promise settles with that once
  // the whole transaction has. iOS can lose the shared connection while the
  // app sits in the background — a transaction that can't start on it, or
  // dies with the "connection lost" kind of error, gets one retry on a
  // fresh connection.
  function idbTransaction(mode, run, retried) {
    const connection = idbOpen();
    const retry = (err) => {
      if (retried) throw err;
      // Only if it's still the one that failed: a read that failed alongside
      // may already have opened its replacement.
      if (idbConnection === connection) idbConnection = null;
      return idbTransaction(mode, run, true);
    };
    return connection.then(db => {
      let tx;
      try {
        tx = db.transaction(ed.IDB_STORE, mode);
      } catch (err) {
        try { db.close(); } catch (e) { /* already gone */ }
        return retry(err);
      }
      return new Promise((resolve, reject) => {
        let settled = false;
        const fail = (e) => {
          if (settled) return;
          settled = true;
          // A request that fails (a full store comes as one on iPhone, a
          // QuotaExceededError on the put) reaches tx.onerror as its error
          // bubbles up, before the transaction has aborted — tx.error is
          // still null then, so it's read off the request instead. Without
          // that the storage-full notice was handed null and stayed quiet.
          let err = tx.error;
          if (!err && e && e.target && e.target !== tx) {
            try { err = e.target.error; } catch (x) { /* not finished */ }
          }
          if (err && (err.name === 'UnknownError' || err.name === 'InvalidStateError')) {
            try { db.close(); } catch (e) { /* already gone */ }
            Promise.resolve().then(() => retry(err)).then(resolve, reject);
          } else {
            reject(err);
          }
        };
        let read;
        try {
          read = run(tx.objectStore(ed.IDB_STORE));
        } catch (err) {
          settled = true;
          try { tx.abort(); } catch (e) { /* already finished */ }
          reject(err);
          return;
        }
        tx.oncomplete = () => {
          if (settled) return;
          settled = true;
          resolve(typeof read === 'function' ? read() : undefined);
        };
        tx.onerror = fail;
        tx.onabort = fail;
      });
    });
  }

  // Old shoots stored images as plain data-URL strings; normalize to
  // { src, caption } objects so callers never have to branch on shape.
  function normalizeMoodboardImages(images) {
    return (images || []).map(img => (typeof img === 'string' ? { src: img, caption: '' } : img));
  }

  function idbGetImages(key) {
    return idbTransaction('readonly', store => {
      const req = store.get(key);
      return () => normalizeMoodboardImages(req.result);
    });
  }

  // Several keys in one transaction: a Map of key -> images ([] if none).
  function idbGetManyImages(keys) {
    return idbTransaction('readonly', store => {
      const reqs = keys.map(key => [key, store.get(key)]);
      return () => new Map(reqs.map(([key, req]) => [key, normalizeMoodboardImages(req.result)]));
    });
  }

  function idbSetImages(key, images) {
    forgetCachedImages(key);
    return idbTransaction('readwrite', store => { store.put(images, key); }).then(() => noteImagesWritten(key));
  }

  function idbDeleteImages(key) {
    forgetCachedImages(key);
    return idbTransaction('readwrite', store => { store.delete(key); }).then(() => noteImagesWritten(key));
  }

  // Images already read for the Journal list, by key, so redrawing it (every
  // renderAll — each tab switch) draws them straight away instead of
  // emptying every photo strip and filling it again a moment later.
  const journalListImageCache = new Map(); ed.journalListImageCache = journalListImageCache;

  function forgetCachedImages(key) {
    if (key === null) journalListImageCache.clear();
    else journalListImageCache.delete(key);
  }

  // Once a write has landed: anything that keeps its own copy reads again.
  // The Archive slideshow keeps what it last read (see
  // renderArchiveSlideshow) — a write to any final images, or clearing the
  // lot (key null), sends it back to read. Kept off the write's own promise
  // chain, so nothing here can make a write that succeeded look like it
  // failed.
  function noteImagesWritten(key) {
    forgetCachedImages(key);
    setTimeout(() => {
      // A list drawn mid-write could have cached the old copy.
      if (key !== null && !ed.views.journal.hidden && journalListImageCache.has(key)) {
        journalListImageCache.delete(key);
        ed.renderJournal();
      }
      if (key !== null && !String(key).endsWith('__final')) return;
      ed.archiveSlideshowStale = true;
      if (ed.archiveSlideshowLoaded) ed.renderArchiveSlideshow();
    }, 0);
  }

  function finalImagesKey(shootId) {
    return shootId + '__final';
  }

  function journalImagesKey(entryId) {
    return entryId + '__journal';
  }

  // Linked entries share their source shoot's final-images store (see
  // currentJournalImagesKey() for the same rule applied to the open modal);
  // this is the list-view equivalent for looking up any entry's images.
  function journalEntryImagesKey(e) {
    return e.sourceShootId ? finalImagesKey(e.sourceShootId) : journalImagesKey(e.id);
  }
};
;

// ---- data/photo-store.js ----
// Project and talent photos, kept in IndexedDB too.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addPhotoStore = function addPhotoStore(ed) {
  Object.assign(ed, { projectPhotoKey, talentPhotoKey, photoFromEntries, savePhotoToIdb, shootPhotoKeys });
  // ---------- Photo storage (project + talent photos live in IndexedDB) ----------
  // These two used to sit inline on the shoot object as base64 data URLs, which
  // meant every autosave re-serialized all of them into the localStorage blob
  // just to record a title edit. They're stored as a single-entry
  // [{src, caption}] array so they use the exact same store shape as every
  // other image collection here — which also means export/import carries them
  // with no change to the payload format.
  function projectPhotoKey(shootId) {
    return shootId + '__cover';
  }

  function talentPhotoKey(shootId, talentId) {
    return shootId + '__talent_' + talentId;
  }

  function photoFromEntries(entries) {
    return (entries && entries[0] && entries[0].src) || '';
  }

  function savePhotoToIdb(key, dataUrl) {
    return ed.idbSetImages(key, dataUrl ? [{ src: dataUrl, caption: '' }] : []);
  }

  // Every IDB key a shoot owns, so deleting one doesn't orphan rows.
  function shootPhotoKeys(shoot) {
    return [projectPhotoKey(shoot.id)].concat((shoot.talents || []).filter(t => t.id).map(t => talentPhotoKey(shoot.id, t.id)));
  }
};
;

// ---- pages/app-menu/storage-usage.js ----
// Storage usage, in the App menu: what's taking up room.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addAppMenuStorageUsage = function addAppMenuStorageUsage(ed) {
  Object.assign(ed, { categorizeStorageKey, hydratePhotos, carryPhotosOver, migrateInlinePhotos });
  // ---------- Storage usage (App menu) ----------
  // Every image key in the store matches exactly one of these suffix
  // patterns except mood board images, which were the original, un-suffixed
  // shape this store started with — so "none of the above" is what's left
  // for that bucket, not a dedicated pattern of its own.
  function categorizeStorageKey(key) {
    if (key.endsWith('__cover')) return 'cover';
    if (key.endsWith('__final')) return 'final';
    if (key.endsWith('__journal')) return 'journal';
    if (key.endsWith('__sticker')) return 'sticker';
    if (key.includes('__talent_')) return 'talent';
    return 'moodboard';
  }

  // Estimated from the data URL's own encoded length rather than decoding
  // it — base64 inflates the true byte count by ~4/3, so this runs a hair
  // high, but consistently so across every category, which is what matters
  // for comparing them against each other rather than for a byte-exact figure.
  function estimateDataUrlBytes(src) {
    if (!src) return 0;
    const commaIdx = src.indexOf(',');
    const payload = commaIdx === -1 ? src : src.slice(commaIdx + 1);
    return Math.round(payload.length * 0.75);
  }

  function computeIdbStorageBreakdown() {
    return ed.idbTransaction('readonly', store => {
      const totals = { moodboard: 0, cover: 0, talent: 0, final: 0, journal: 0, sticker: 0 };
      const counts = { moodboard: 0, cover: 0, talent: 0, final: 0, journal: 0, sticker: 0 };
      const req = store.openCursor();
      req.onsuccess = (e) => {
        const cursor = e.target.result;
        if (!cursor) return;
        const category = categorizeStorageKey(String(cursor.key));
        ed.normalizeMoodboardImages(cursor.value).forEach(img => {
          totals[category] += estimateDataUrlBytes(img.src);
          counts[category] += 1;
        });
        cursor.continue();
      };
      return () => ({ totals, counts });
    });
  }

  function formatStorageBytes(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  }

  const STORAGE_CATEGORY_LABELS = [
    ['moodboard', 'Mood board photos'],
    ['final', 'Final images'],
    ['cover', 'Cover photos'],
    ['talent', 'Talent photos'],
    ['journal', 'Journal photos'],
    ['sticker', 'Stickers'],
  ];

  async function openStorageUsageModal() {
    const overlay = document.getElementById('storageUsageOverlay');
    const body = document.getElementById('storageUsageBody');
    overlay.hidden = false;
    body.innerHTML = '<p class="field-hint">Calculating…</p>';

    const [estimate, breakdown] = await Promise.all([
      (navigator.storage && navigator.storage.estimate)
        ? navigator.storage.estimate().catch(() => null)
        : Promise.resolve(null),
      computeIdbStorageBreakdown().catch(() => null),
    ]);
    // The popup may have been closed while these were in flight.
    if (overlay.hidden) return;

    const rows = [];
    if (estimate && estimate.usage != null) {
      rows.push(`
        <div class="storage-usage-total">
          <p class="storage-usage-total-label">Total on this device</p>
          <p class="storage-usage-total-value">${formatStorageBytes(estimate.usage)}</p>
        </div>
      `);
    }

    if (breakdown) {
      STORAGE_CATEGORY_LABELS.forEach(([key, label]) => {
        if (!breakdown.counts[key]) return;
        rows.push(`
          <div class="storage-usage-row">
            <p class="storage-usage-row-label">${label}</p>
            <p class="storage-usage-row-value">${formatStorageBytes(breakdown.totals[key])} <span class="storage-usage-row-count">(${breakdown.counts[key]})</span></p>
          </div>
        `);
      });
    }

    let appDataBytes = 0;
    try { appDataBytes = new Blob([localStorage.getItem(ed.STORAGE_KEY) || '']).size; } catch (e) {}
    rows.push(`
      <div class="storage-usage-row">
        <p class="storage-usage-row-label">Shoots, journal &amp; settings (text only)</p>
        <p class="storage-usage-row-value">${formatStorageBytes(appDataBytes)}</p>
      </div>
    `);

    rows.push(`
      <div class="storage-usage-row">
        <p class="storage-usage-row-label">Shoots logged</p>
        <p class="storage-usage-row-value">${ed.state.shoots.length}</p>
      </div>
    `);

    body.innerHTML = rows.join('');
  }

  document.getElementById('storageUsageBtn').addEventListener('click', () => {
    ed.closeAppMenu();
    openStorageUsageModal();
  });
  document.getElementById('storageUsageCloseBtn').addEventListener('click', () => {
    document.getElementById('storageUsageOverlay').hidden = true;
  });
  document.getElementById('storageUsageOverlay').addEventListener('click', (e) => {
    if (e.target === document.getElementById('storageUsageOverlay')) document.getElementById('storageUsageOverlay').hidden = true;
  });

  // Reads every shoot's photos back onto the in-memory state so that all the
  // render code can keep reading shoot.projectPhoto / talent.photo
  // synchronously, exactly as it did when they were stored inline.
  //
  // All in one transaction — at launch this is what the first paint waits
  // on (see the boot code), so it has to be quick. Each result is written
  // onto whatever shoot/talent currently has that id in `state` (looked up
  // when the read lands, not captured up front) — `state` gets swapped by a
  // pull-to-refresh and shoot objects get replaced by copies on every
  // autosave, so a captured reference can already be an orphan by then. It
  // only fills a photo that's missing, so a late read can never put an older
  // copy over one that was just added. If the batch read fails, it falls
  // back to one read per photo, so one bad row can't cost all the others.
  // Resolves to how many photos it filled in, so a caller can skip a repaint
  // when nothing changed.
  function hydratePhotos() {
    const keys = [];
    ed.state.shoots.forEach(shoot => {
      keys.push(ed.projectPhotoKey(shoot.id));
      (shoot.talents || []).forEach(talent => {
        if (talent.id) keys.push(ed.talentPhotoKey(shoot.id, talent.id));
      });
    });
    if (!keys.length) return Promise.resolve(0);
    const readAll = ed.idbGetManyImages(keys).catch(() => Promise.all(keys.map(key => ed.idbGetImages(key)
      .then(entries => [key, entries], () => [key, []])))
      .then(pairs => new Map(pairs)));
    return readAll.then(rows => {
      let filled = 0;
      ed.state.shoots.forEach(shoot => {
        const cover = ed.photoFromEntries(rows.get(ed.projectPhotoKey(shoot.id)));
        if (cover && !shoot.projectPhoto) { shoot.projectPhoto = cover; filled++; }
        (shoot.talents || []).forEach(talent => {
          const src = talent.id ? ed.photoFromEntries(rows.get(ed.talentPhotoKey(shoot.id, talent.id))) : '';
          if (src && !talent.photo) { talent.photo = src; filled++; }
        });
      });
      return filled;
    });
  }

  // Re-attaches the photos already held in memory onto a freshly rebuilt state
  // (matched by id), so reloading `state` from storage — which never has
  // photos, see stripPhotos — can't cause even a single frame of empty
  // thumbnails while IndexedDB is re-read.
  function carryPhotosOver(from, to) {
    const previous = new Map((from.shoots || []).map(s => [s.id, s]));
    (to.shoots || []).forEach(s => {
      const old = previous.get(s.id);
      if (!old) return;
      if (old.projectPhoto && !s.projectPhoto) s.projectPhoto = old.projectPhoto;
      const oldTalents = new Map((old.talents || []).filter(t => t.id).map(t => [t.id, t]));
      (s.talents || []).forEach(t => {
        const o = t.id && oldTalents.get(t.id);
        if (o && o.photo && !t.photo) t.photo = o.photo;
      });
    });
  }

  // One-time move for data saved before photos lived in IDB: anything still
  // inline gets written out to its own key, then dropped from the blob by the
  // next saveState(). Safe to run on every boot — after the first pass there's
  // nothing inline left to find.
  function migrateInlinePhotos() {
    const jobs = [];
    ed.state.shoots.forEach(shoot => {
      if (shoot.projectPhoto) jobs.push(ed.savePhotoToIdb(ed.projectPhotoKey(shoot.id), shoot.projectPhoto));
      (shoot.talents || []).forEach(talent => {
        if (talent.id && talent.photo) jobs.push(ed.savePhotoToIdb(ed.talentPhotoKey(shoot.id, talent.id), talent.photo));
      });
    });
    if (!jobs.length) return Promise.resolve();
    return Promise.all(jobs).then(() => ed.saveState()).catch(() => {});
  }
};
;

// ---- components/projects.js ----
// Projects: groups of shoots (the days of a multi-day shoot, or the shoots of one video).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addProjects = function addProjects(ed) {
  Object.assign(ed, { projectsList, findProject, projectMembers, isProjectLiveShoot, projectDayInfo, projectShotProgressLabel, projectStatusLabel, projectGroupStatusKey, collapseProjects, createProject, pruneEmptyProjects, setShootProject });
  // ---------- Projects (groups of shoots) ----------
  // A project groups shoots that belong together — the days of a multi-day
  // shoot, or several shoots that make up one video. Membership lives only on
  // the shoot (shoot.projectId; '' or missing = no project, and a shoot is in
  // at most one), so a record in state.projects is just { id, name,
  // createdAt }: deleting, archiving or importing a shoot needs no project
  // bookkeeping, and a project left with no shoots is simply dropped
  // (pruneEmptyProjects). Projects own no photos — lists borrow a member
  // shoot's cover — so there are no IndexedDB rows of their own to hydrate,
  // export or clean up. Always go through projectsList() rather than reading
  // state.projects directly.

  // Always an array, even on a state object built before projects existed.
  function projectsList() {
    if (!Array.isArray(ed.state.projects)) ed.state.projects = [];
    return ed.state.projects;
  }

  function findProject(id) {
    if (!id) return undefined;
    return projectsList().find(p => p.id === id);
  }

  // Every shoot in the project, archived ones included, in shoot-date order
  // (date TBD last, same as every other date-sorted list).
  function projectMembers(projectId) {
    if (!projectId) return [];
    return ed.state.shoots
      .filter(s => s.projectId === projectId)
      .sort((a, b) => ed.dateTimeSortKey(a).localeCompare(ed.dateTimeSortKey(b)));
  }

  // Postponed (key: rescheduled) and Canceled shoots are off the schedule —
  // the date they keep is only the original plan (see isOffScheduleShoot) —
  // so they don't count as a day of the project or toward its progress.
  function isProjectLiveShoot(s) {
    return s.status !== 'rescheduled' && s.status !== 'canceled';
  }

  // "Day 2 of 3": a shoot's place among its project's distinct shoot dates
  // (two shoots on the same date are the same day). null when there's
  // nothing useful to say — not in a project, no date yet, postponed or
  // canceled, or a project that only spans one date.
  function projectDayInfo(shoot) {
    if (!shoot || !shoot.projectId || !findProject(shoot.projectId)) return null;
    if (!shoot.date || !isProjectLiveShoot(shoot)) return null;
    const dates = [...new Set(projectMembers(shoot.projectId)
      .filter(s => s.date && isProjectLiveShoot(s))
      .map(s => s.date))].sort();
    const idx = dates.indexOf(shoot.date);
    if (dates.length < 2 || idx === -1) return null;
    return { day: idx + 1, total: dates.length };
  }

  // The least-advanced status among the given shoots, in STATUS_LABELS order
  // (a missing status reads as Prospect, same as everywhere else).
  function projectLeastAdvancedStatus(shoots) {
    const order = Object.keys(ed.STATUS_LABELS);
    let best = -1;
    shoots.forEach(s => {
      const idx = order.indexOf(s.status || 'prospect');
      if (idx !== -1 && (best === -1 || idx < best)) best = idx;
    });
    return best === -1 ? 'prospect' : order[best];
  }

  // "2 of 3 shot" while a project is part-way through its shoot days (some
  // of its live shoots captured or later, some not yet); '' otherwise. Split
  // out of projectStatusLabel because list boxes show only this part next to
  // the shoot count.
  function projectShotProgressLabel(members) {
    const live = (members || []).filter(isProjectLiveShoot);
    const shotCount = live.filter(s => ed.isPostCaptureStatus(s.status)).length;
    return shotCount && shotCount < live.length ? `${shotCount} of ${live.length} shot` : '';
  }

  // One status for a whole project: its progress while it's part-shot,
  // otherwise the status of the shoot furthest behind (a project is only as
  // far along as its slowest day). With every shoot off the schedule it's
  // Canceled if they all are, else Postponed. '' for no shoots at all.
  function projectStatusLabel(members) {
    const list = members || [];
    if (!list.length) return '';
    const live = list.filter(isProjectLiveShoot);
    if (!live.length) return list.every(s => s.status === 'canceled') ? ed.STATUS_LABELS.canceled : ed.STATUS_LABELS.rescheduled;
    return projectShotProgressLabel(live) || ed.STATUS_LABELS[projectLeastAdvancedStatus(live)] || '';
  }

  // Which Shoots-tab Status group a project's box goes in — the same rule as
  // projectStatusLabel, as a status key.
  function projectGroupStatusKey(members) {
    const list = members || [];
    const live = list.filter(isProjectLiveShoot);
    if (!live.length) return list.length && list.every(s => s.status === 'canceled') ? 'canceled' : 'rescheduled';
    return projectLeastAdvancedStatus(live);
  }

  // The shoot that stands in for a project in a list (its thumbnail, its
  // placement by date or category): the next shoot day from today on, else
  // the earliest-dated one, else simply the first one given. A postponed or
  // canceled day's kept date doesn't count (scheduledShootDate).
  function projectRepresentative(members) {
    if (!members || !members.length) return null;
    const today = ed.todayStr();
    const dated = members
      .filter(s => ed.scheduledShootDate(s))
      .sort((a, b) => ed.dateTimeSortKey(a).localeCompare(ed.dateTimeSortKey(b)));
    return dated.find(s => s.date >= today) || dated[0] || members[0];
  }

  // Folds a list of shoots into list items, in the order each first appears:
  // a shoot outside any project stays { kind: 'shoot', shoot }, and a
  // project's shoots become one { kind: 'project', project, members, rep }
  // where the first of them was. `members` is only the project's shoots that
  // are in THIS list, in list order (projectMembers() has all of them), and
  // `rep` is projectRepresentative() of those. A projectId whose record is
  // missing reads as no project.
  function collapseProjects(shoots) {
    const projectsById = new Map(projectsList().map(p => [p.id, p]));
    const items = [];
    const projectItems = new Map();
    (shoots || []).forEach(s => {
      const project = s.projectId ? projectsById.get(s.projectId) : undefined;
      if (!project) {
        items.push({ kind: 'shoot', shoot: s });
        return;
      }
      let item = projectItems.get(project.id);
      if (!item) {
        item = { kind: 'project', project, members: [], rep: null };
        projectItems.set(project.id, item);
        items.push(item);
      }
      item.members.push(s);
    });
    projectItems.forEach(item => { item.rep = projectRepresentative(item.members); });
    return items;
  }

  // Doesn't save. Link a shoot to it (setShootProject) straight away — until
  // one is, the next pruneEmptyProjects() drops it again.
  function createProject(name) {
    const project = {
      id: ed.uid(),
      name: (typeof name === 'string' && name.trim()) || ed.UNTITLED_PROJECT_NAME,
      createdAt: ed.todayStr(),
    };
    projectsList().push(project);
    return project;
  }

  // Doesn't save. Run after anything that can take a project's last shoot
  // away (deleting a shoot, taking one out, moving one to another project).
  function pruneEmptyProjects() {
    ed.state.projects = ed.projectsWithMembers(projectsList(), ed.state.shoots);
  }

  // Puts a shoot in a project ('' takes it out), replacing the shoot object
  // the same way every other shoot edit does. Every later save keeps it:
  // autosaveShoot spreads the old shoot under the form's data, and the form
  // never gathers projectId. Then drops any project this left empty. Doesn't
  // save or render. Returns the updated shoot, or null (and changes nothing)
  // when the shoot isn't in state.shoots yet or the project doesn't exist.
  function setShootProject(shootId, projectId) {
    const idx = ed.state.shoots.findIndex(x => x.id === shootId);
    if (idx === -1) return null;
    if (projectId && !findProject(projectId)) return null;
    const prev = ed.state.shoots[idx];
    // A shoot that changes projects (or leaves one) is no longer one of a
    // multi-day project's following days — it never follows another lead.
    const moving = (prev.projectId || '') !== (projectId || '');
    ed.state.shoots[idx] = { ...prev, projectId: projectId || '', ...(moving ? { followsLead: false } : {}) };
    pruneEmptyProjects();
    return ed.state.shoots[idx];
  }
};
;

// ---- components/multi-day-mirroring.js ----
// Multi-day shoots: the other days mirror the first day's details and pictures.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addMultiDayMirroring = function addMultiDayMirroring(ed) {
  Object.assign(ed, { projectLeadOf, projectFollowers, mirrorSignature, applyLeadDetails, syncProjectMirrors, onShootImagesChanged, mirrorLeadImages });
  // ---------- Multi-day mirroring ----------
  // A project made with "Multi-day shoot" has a lead day — the shoot it was
  // made from (project.leadShootId) — and its other days follow it
  // (shoot.followsLead). Everything planned on the lead is mirrored onto
  // the following days, now and on every later change: title, category,
  // talent, team, location and directions, the concept fields, shooting
  // notes, deliverables, deadline, references, frameworks, lighting setups,
  // the mood board and its cover. Each day keeps its own date, times,
  // status, shot list, reflection and final images. Changing any mirrored
  // detail on a following day by hand makes that day its own from then on
  // (followsLead off), and the lead's later changes skip it.
  //
  // The text/list details are compared by signature on every save (run from
  // saveState), so every way of editing a shoot — the form, the ⋮ menu,
  // Shoot mode, the talent popup — is covered without hooks of its own.
  // Photos live in IndexedDB, so mood board and cover changes are reported
  // separately through onShootImagesChanged().

  // The lead day, if the project has one that's still in it.
  function projectLeadOf(project) {
    if (!project || !project.leadShootId) return null;
    const lead = ed.state.shoots.find(s => s.id === project.leadShootId);
    return lead && lead.projectId === project.id ? lead : null;
  }

  // The shoots currently following a project's lead.
  function projectFollowers(project, lead) {
    return ed.state.shoots.filter(s => s.projectId === project.id && s.followsLead && s.id !== lead.id);
  }

  // The mirrored text/list details as one comparable number, normalized the
  // way the Edit Shoot form round-trips them (trimmed references, tags in a
  // fixed order, no list ids, the team platform defaulted), so opening a
  // following day and closing it untouched never reads as an edit. Photos
  // are left out on purpose: at launch they arrive from IndexedDB a moment
  // after everything else, which would look like a change.
  function mirrorSignature(s) {
    const loc = ed.normalizeLocation(s.location);
    // Only tags the form can actually show (their framework and tag still
    // exist — Manage Frameworks can delete or rename them without touching
    // shoots), once each, since a re-save through the form drops the rest.
    const frameworkTags = [...new Set((s.frameworkTags || [])
      .filter(t => (ed.state.frameworks || []).some(fw => fw.id === t.frameworkId && (fw.tags || []).includes(t.tag)))
      .map(t => `${t.frameworkId}|${t.tag}`))].sort();
    return ed.hashString(JSON.stringify([
      // Trimmed like the form saves them (Shoot mode stores text as typed).
      ['title', 'teamRequired', 'talentDirections', 'teamDirections', 'locationDirections',
        'premise', 'character', 'worldNotes', 'shootGoals', 'elevatorPitch', 'shootingNotes',
        'deliverables', 'deliverableDestinations', 'deadline'].map(k => (typeof s[k] === 'string' ? s[k].trim() : '')),
      // A category the form has no option for (e.g. an old shoot's 'client')
      // reads back from the form as none at all.
      ed.CATEGORY_LABELS[s.category] ? s.category : '',
      !!s.teamFinalized,
      !!s.moodboardComplete,
      (s.talents || []).map(t => [(t.name || '').trim(), (t.socialHandles || []).map(h => [h.platform || '', h.handle || ''])]),
      (s.teamMembers || []).map(tm => [tm.name || '', tm.role || '', tm.socialPlatform || 'instagram', tm.socialHandle || '']),
      [loc.name, loc.street, loc.city, loc.state, loc.zip, loc.country],
      ed.normalizeAspectRatios(s.aspectRatios),
      (s.references || []).map(r => (typeof r === 'string' ? r.trim() : '')).filter(Boolean),
      frameworkTags,
      (s.lightingSetups || []).map(l => [l.name || '', l.characteristics || '', l.description !== undefined ? l.description : (l.text || '')]),
    ]));
  }

  // Copies the lead's mirrored details onto one following day — in place,
  // since Shoot mode and the form hold live references to shoot objects. A
  // category change brings the day's status along to its nearest
  // equivalent, the same as flipping the category in the form does.
  function applyLeadDetails(lead, day) {
    ['title', 'category', 'teamRequired', 'talentDirections', 'teamDirections', 'locationDirections',
      'premise', 'character', 'worldNotes', 'shootGoals', 'elevatorPitch', 'shootingNotes',
      'deliverables', 'deliverableDestinations', 'deadline'].forEach(k => { day[k] = lead[k] || ''; });
    day.teamFinalized = !!lead.teamFinalized;
    day.moodboardComplete = !!lead.moodboardComplete;
    day.teamMembers = (lead.teamMembers || []).map(tm => ({ ...tm }));
    day.location = ed.normalizeLocation(lead.location);
    day.aspectRatios = ed.normalizeAspectRatios(lead.aspectRatios);
    day.references = [...(lead.references || [])];
    day.frameworkTags = (lead.frameworkTags || []).map(t => ({ ...t }));
    day.lightingSetups = (lead.lightingSetups || []).map(item => ({
      id: ed.uid(),
      name: item.name || '',
      characteristics: item.characteristics || '',
      description: item.description !== undefined ? item.description : (item.text || ''),
    }));
    // Same people (same talent ids) as the lead. A photo the lead hasn't got
    // in memory keeps the day's own copy rather than blanking it; a new or
    // changed one is written to this day's own IndexedDB row too, so it
    // survives a reload.
    const previous = new Map((day.talents || []).map(t => [t.id, t]));
    day.talents = (lead.talents || []).map(t => {
      const id = t.id || ed.uid();
      const prev = previous.get(id);
      const photo = t.photo || (prev && prev.photo) || '';
      if (t.photo && (!prev || prev.photo !== t.photo)) ed.savePhotoToIdb(ed.talentPhotoKey(day.id, id), t.photo).catch(() => {});
      return { id, name: t.name || '', socialHandles: (t.socialHandles || []).map(h => ({ ...h })), photo };
    });
    day.status = ed.remapStatusForCategory(day.status || 'prospect', day.category);
  }

  // Lets the user know a day just stopped following, and refreshes its
  // Multi-day row if that day's the one open.
  function announceDayDetached(day, lead) {
    const info = ed.projectDayInfo(day);
    const leadInfo = ed.projectDayInfo(lead);
    const dayName = info ? `Day ${info.day}` : 'This day';
    const leadName = leadInfo ? `Day ${leadInfo.day}` : 'the first day';
    // A notice: the removal that set this off usually has its Undo toast
    // up, which this waits for — and if that Undo puts the day back to
    // following (reattachDayIfMatchingLead), it's dropped.
    const dayId = day.id;
    ed.showNoticeToast(`${dayName} now has its own changes, so later edits to ${leadName} won't copy to it`, 3200, () => {
      const live = ed.state.shoots.find(s => s.id === dayId);
      return !!live && !live.followsLead;
    });
    if (!ed.shootModalOverlay.hidden && ed.currentShootId === day.id) ed.updateMultiDayRow();
  }

  // Run by saveState before every save. For each project with a lead: a
  // following day whose details no longer match what was last mirrored onto
  // it was edited by hand, so it stops following — unless it now matches
  // the lead anyway (the talent popup updates a person on every shoot at
  // once). Then, if the lead itself changed since the last mirror, its
  // details are copied onto every day still following it.
  function syncProjectMirrors() {
    if (!ed.state || !Array.isArray(ed.state.shoots) || !Array.isArray(ed.state.projects)) return;
    ed.state.projects.forEach(project => {
      const lead = projectLeadOf(project);
      if (!lead) return;
      const leadSig = mirrorSignature(lead);
      projectFollowers(project, lead).forEach(day => {
        const sig = mirrorSignature(day);
        if (sig === day.mirrorSig) return;
        if (sig === leadSig) { day.mirrorSig = sig; return; }
        day.followsLead = false;
        delete day.mirrorSig;
        announceDayDetached(day, lead);
      });
      if (leadSig === project.mirrorSig) return;
      projectFollowers(project, lead).forEach(day => {
        applyLeadDetails(lead, day);
        day.mirrorSig = mirrorSignature(day);
      });
      project.mirrorSig = leadSig;
    });
  }

  // Called once a shoot's mood board ({ board: true }) and/or cover
  // ({ cover: true }) has been changed by hand — both live in IndexedDB,
  // outside the signature above. On a lead day it copies what changed onto
  // every following day; on a following day it counts as making that day
  // its own. A cover set from a day's own final images is never reported:
  // it belongs to that day.
  //
  // shootImagesChangedAt: when each project day last had its photos changed
  // this way (this session only). An Undo that would put a day back to
  // following its lead (reattachDayIfMatchingLead) leaves it be when its own
  // or the lead's photos were changed since — the signature can't see them.
  const shootImagesChangedAt = new Map(); ed.shootImagesChangedAt = shootImagesChangedAt;
  function onShootImagesChanged(shootId, what) {
    const shoot = ed.state.shoots.find(s => s.id === shootId);
    if (!shoot || !shoot.projectId) return;
    shootImagesChangedAt.set(shootId, Date.now());
    const project = ed.findProject(shoot.projectId);
    const lead = projectLeadOf(project);
    if (!lead) return;
    if (shoot.id === lead.id) {
      mirrorLeadImages(project, lead, what || { board: true });
      return;
    }
    if (!shoot.followsLead) return;
    shoot.followsLead = false;
    delete shoot.mirrorSig;
    announceDayDetached(shoot, lead);
    ed.saveState();
  }

  // The lead's mood board and/or cover (per `what`), copied onto each
  // following day's own IndexedDB rows — or just onto `targets` — and the
  // cover onto the in-memory shoot for the lists too. A day that already
  // has final images of its own keeps its cover: once it's been shot, its
  // cover is its own photo, not the plan's.
  function mirrorLeadImages(project, lead, what, targets) {
    const days = targets || projectFollowers(project, lead);
    const wantBoard = !!(what && what.board);
    const wantCover = !!(what && what.cover);
    if (!days.length || (!wantBoard && !wantCover)) return Promise.resolve();
    return Promise.all([
      wantBoard ? ed.idbGetImages(lead.id).catch(() => null) : Promise.resolve(null),
      wantCover ? ed.idbGetImages(ed.projectPhotoKey(lead.id)).catch(() => null) : Promise.resolve(null),
    ]).then(([board, coverRows]) => {
      const cover = wantCover ? (ed.photoFromEntries(coverRows) || lead.projectPhoto || '') : '';
      return Promise.all(days.map(day => {
        const writes = [];
        if (board) writes.push(ed.idbSetImages(day.id, board.map(img => ({ ...img }))));
        if (cover) {
          writes.push(ed.idbGetImages(ed.finalImagesKey(day.id)).catch(() => []).then(finals => {
            if (finals.length) return;
            const live = ed.state.shoots.find(x => x.id === day.id);
            if (live) live.projectPhoto = cover;
            return ed.savePhotoToIdb(ed.projectPhotoKey(day.id), cover);
          }));
        }
        return Promise.all(writes.map(w => w.catch(() => {})));
      }));
    }).then(() => ed.renderAll()).catch(() => {});
  }
};
;

// ---- components/shoot-copies.js ----
// A blank shoot, and copying a shoot for another day of its project.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootCopies = function addShootCopies(ed) {
  Object.assign(ed, { copyShootForProject });
  // Every field a saved shoot carries — the Edit Shoot form's own set
  // (gatherShootFormData) plus the older ones migrateShoot fills in — each at
  // its empty default, so a shoot made in code reads exactly like one saved
  // through the form. Location starts with the default country, same as a
  // new shoot draft. projectPhoto lives in memory only (see stripPhotos),
  // like on every other shoot.
  function blankShootRecord(id) {
    return {
      id,
      title: '',
      status: 'prospect',
      date: '',
      deadline: '',
      startTime: '',
      endTime: '',
      crewCallTime: '',
      talentCallTime: '',
      location: ed.normalizeLocation({ country: ed.state.defaultCountry || '' }),
      talents: [],
      category: '',
      premise: '',
      character: '',
      shootGoals: '',
      elevatorPitch: '',
      deliverables: '',
      aspectRatios: [],
      deliverableDestinations: '',
      worldNotes: '',
      moodboardComplete: false,
      teamRequired: '',
      teamFinalized: false,
      teamMembers: [],
      references: [],
      frameworkTags: [],
      whatWentRight: '',
      couldBeBetter: '',
      lessonsLearned: '',
      talentDirections: '',
      teamDirections: '',
      shootingNotes: '',
      locationDirections: '',
      shotList: [],
      lightingSetups: [],
      emotionalBeats: [],
      lightingNotes: '',
      wardrobeNotes: '',
      generalNotes: '',
      projectPhoto: null,
      archived: false,
      projectId: '',
    };
  }

  // Makes a new shoot in the source's project (or overrides.projectId) and
  // adds it to state.shoots; the caller saves and renders. The only
  // overrides read are `date` and `projectId`.
  //   'day':   the next day of the same shoot. Carries over what stays the
  //            same from day to day — title, talent (with their photos),
  //            team, location, times, directions, the concept, shooting
  //            notes, video deliverables, deadline, references, frameworks,
  //            lighting setups (fresh ids), the mood board and the cover
  //            photo — and nothing that belongs to a day that already
  //            happened: no date (that's overrides.date), reflection, final
  //            images, capture/edit timestamps or reminder flags. A source
  //            that's already been shot hands over the shots it didn't tick
  //            off as the new day's list; otherwise the list starts empty.
  //            Status stays put while the source is still before the shoot,
  //            else it starts back at Active planning.
  //   'brief': another shoot for the same project — just the concept, video
  //            deliverables, deadline, references and frameworks, in Active
  //            planning; no title, date, people, place or photos.
  // Photos are read from IndexedDB first (at boot the in-memory copies may
  // not have hydrated yet), falling back to what's in memory, and every
  // write has landed before this resolves, so opening the new shoot straight
  // away finds its mood board, cover and talent photos in place. The shoot
  // is pushed only after those awaits, so it always lands in the live
  // `state` (a pull-to-refresh swaps that object out).
  async function copyShootForProject(src, mode, overrides) {
    const opts = overrides || {};
    // By id: an autosave since the caller looked the source up replaces the
    // shoot object, which would leave `src` an orphan holding older data.
    const source = (src && ed.state.shoots.find(x => x.id === src.id)) || src;
    if (!source) return null;
    let id = ed.uid();
    while (ed.state.shoots.some(x => x.id === id)) id = ed.uid();
    const shoot = blankShootRecord(id);
    shoot.projectId = opts.projectId !== undefined ? (opts.projectId || '') : (source.projectId || '');
    shoot.date = typeof opts.date === 'string' ? opts.date : '';

    // The brief — the part both modes share.
    shoot.category = source.category || '';
    shoot.premise = source.premise || '';
    shoot.character = source.character || '';
    shoot.worldNotes = source.worldNotes || '';
    shoot.shootGoals = source.shootGoals || '';
    shoot.elevatorPitch = source.elevatorPitch || '';
    shoot.deliverables = source.deliverables || '';
    shoot.aspectRatios = ed.normalizeAspectRatios(source.aspectRatios);
    shoot.deliverableDestinations = source.deliverableDestinations || '';
    shoot.deadline = source.deadline || '';
    shoot.references = Array.isArray(source.references) ? [...source.references] : [];
    shoot.frameworkTags = (source.frameworkTags || []).map(t => ({ ...t }));

    if (mode === 'day') {
      shoot.title = source.title || '';
      shoot.status = ['prospect', 'planning', 'waiting_to_shoot'].includes(source.status) ? source.status : 'planning';
      shoot.startTime = source.startTime || '';
      shoot.endTime = source.endTime || '';
      shoot.crewCallTime = source.crewCallTime || '';
      shoot.talentCallTime = source.talentCallTime || '';
      shoot.location = ed.normalizeLocation(source.location);
      shoot.locationDirections = source.locationDirections || '';
      shoot.talentDirections = source.talentDirections || '';
      shoot.teamDirections = source.teamDirections || '';
      shoot.shootingNotes = source.shootingNotes || '';
      shoot.teamRequired = source.teamRequired || '';
      shoot.teamFinalized = !!source.teamFinalized;
      shoot.teamMembers = (source.teamMembers || []).map(tm => ({ socialPlatform: 'instagram', ...tm }));
      shoot.moodboardComplete = !!source.moodboardComplete;
      // Same old-shape handling as openShootModal; fresh ids since they're
      // per-list ids, not shared identities.
      shoot.lightingSetups = (source.lightingSetups || []).map(item => ({
        id: ed.uid(),
        name: item.name || '',
        characteristics: item.characteristics || '',
        description: item.description !== undefined ? item.description : (item.text || ''),
      }));
      // Blank rows are dropped too — they'd only be empty lines to delete.
      // A must-have still not got stays one.
      shoot.shotList = ed.isPostCaptureStatus(source.status)
        ? (source.shotList || [])
          .filter(item => item && !item.checked && typeof item.text === 'string' && ed.hasText(item.text))
          .map(item => ({ ...(item.id ? { id: ed.uid() } : {}), text: item.text, checked: false, ...(item.starred ? { starred: true } : {}) }))
        : [];

      const sourceTalents = source.talents || [];
      const readRows = key => ed.idbGetImages(key).catch(() => []);
      const [moodboardImages, coverRows, talentRows] = await Promise.all([
        readRows(source.id),
        readRows(ed.projectPhotoKey(source.id)),
        // A talent without an id can't have a row (the key needs one), so its
        // photo, if any, can only be the in-memory one.
        Promise.all(sourceTalents.map(t => (t.id ? readRows(ed.talentPhotoKey(source.id, t.id)) : Promise.resolve([])))),
      ]);
      // Same talent ids — the photo keys include the shoot id, so they can't
      // collide — so the same person stays recognisable across days.
      shoot.talents = sourceTalents.map((t, i) => ({
        id: t.id || ed.uid(),
        name: t.name || '',
        socialHandles: (t.socialHandles || []).map(sh => ({ ...sh })),
        photo: ed.photoFromEntries(talentRows[i]) || t.photo || '',
      }));
      shoot.projectPhoto = ed.photoFromEntries(coverRows) || source.projectPhoto || null;

      const writes = [];
      if (moodboardImages.length) writes.push(ed.idbSetImages(id, moodboardImages.map(img => ({ ...img }))));
      if (shoot.projectPhoto) writes.push(ed.savePhotoToIdb(ed.projectPhotoKey(id), shoot.projectPhoto));
      shoot.talents.forEach(t => {
        if (t.photo) writes.push(ed.savePhotoToIdb(ed.talentPhotoKey(id, t.id), t.photo));
      });
      // One failed write shouldn't sink the rest (or the new shoot): the
      // photos are on the in-memory shoot regardless, same as after any
      // other failed photo save.
      await Promise.all(writes.map(w => w.catch(() => {})));
    } else {
      shoot.status = 'planning';
    }

    // The project may have been ungrouped (or lost its last shoot) while
    // the photos above were copying. Pointing the new shoot at a record
    // that's gone would have the next load rebuild that project, undoing the
    // ungroup — so it lands as a shoot of its own instead.
    if (shoot.projectId && !ed.findProject(shoot.projectId)) shoot.projectId = '';

    // Same bookkeeping as a shoot created through the form (autosaveShoot).
    ed.applyStatusTimestamps(shoot, null, shoot.status);
    ed.state.shoots.push(shoot);
    return shoot;
  }
};
;

// ---- components/image-resize.js ----
// Making pictures smaller before they're kept.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addImageResize = function addImageResize(ed) {
  Object.assign(ed, { resizeImageFile, resizeDataUrlThumb });
  function resizeImageFile(file, maxDim, quality) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onerror = () => reject(reader.error);
      reader.onload = () => {
        const img = new Image();
        img.onerror = reject;
        img.onload = () => {
          let { width, height } = img;
          if (width > maxDim || height > maxDim) {
            if (width > height) { height = Math.round(height * maxDim / width); width = maxDim; }
            else { width = Math.round(width * maxDim / height); height = maxDim; }
          }
          const canvas = document.createElement('canvas');
          canvas.width = width;
          canvas.height = height;
          canvas.getContext('2d').drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', quality));
        };
        img.src = reader.result;
      };
      reader.readAsDataURL(file);
    });
  }

  function resizeDataUrlThumb(dataUrl, maxDim, quality) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onerror = reject;
      img.onload = () => {
        let { width, height } = img;
        if (width > maxDim || height > maxDim) {
          if (width > height) { height = Math.round(height * maxDim / width); width = maxDim; }
          else { width = Math.round(width * maxDim / height); height = maxDim; }
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        canvas.getContext('2d').drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      };
      img.src = dataUrl;
    });
  }
};
;

// ---- components/page-turn.js ----
// Tabs and pages: going to a tab, turning a page, and each section as one page.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addPageTurn = function addPageTurn(ed) {
  Object.assign(ed, { pageCopy, clearTurn, playTurn, turnToView });
  // ---------- tab navigation ----------
  const views = {
    overview: document.getElementById('view-overview'),
    shoots: document.getElementById('view-shoots'),
    archive: document.getElementById('view-archive'),
    journal: document.getElementById('view-journal'),
    stats: document.getElementById('view-stats'),
  }; ed.views = views;

  // ---------- Turning a page ----------
  // A sheet swings over on its hinge, carrying a copy of a page. The copy
  // only looks like the page: it can't be touched and goes on a timer, not on
  // the animation's end, so it can never be left covering anything.
  const turnTimers = new WeakMap();
  const motionOk = () => !matchMedia('(prefers-reduced-motion: reduce)').matches; ed.motionOk = motionOk;

  function pageCopy(source, tidy) {
    const rect = source.getBoundingClientRect();
    const copy = source.cloneNode(true);
    // A select's choice isn't part of what cloning carries over.
    const selects = copy.querySelectorAll('select');
    source.querySelectorAll('select').forEach((el, i) => { if (selects[i]) selects[i].selectedIndex = el.selectedIndex; });
    if (tidy) tidy(copy);
    copy.hidden = false;
    copy.inert = true;
    copy.style.margin = '0'; // the holder already sits where the page's box does
    const holder = document.createElement('div');
    holder.className = 'nb-turn-copy';
    holder.style.width = `${rect.width}px`;
    holder.appendChild(copy);
    return { holder, left: rect.left, top: rect.top };
  }

  function clearTurn(layer) {
    clearTimeout(turnTimers.get(layer));
    layer.querySelectorAll('.nb-turn, .nb-turn-under').forEach(el => el.remove());
  }

  function playTurn(layer, kind, leafCopy, underCopy) {
    clearTurn(layer);
    const base = layer.getBoundingClientRect();
    const add = (className, copy) => {
      const sheet = document.createElement('div');
      sheet.className = className;
      layer.appendChild(sheet);
      if (copy) {
        // offsetLeft/Top ignore the sheet's own swing.
        copy.holder.style.left = `${copy.left - base.left - sheet.offsetLeft}px`;
        copy.holder.style.top = `${copy.top - base.top - sheet.offsetTop}px`;
        sheet.appendChild(copy.holder);
      }
    };
    if (underCopy) add('nb-turn-under', underCopy);
    add(`nb-turn${kind ? ` ${kind}` : ''}`, leafCopy);
    turnTimers.set(layer, setTimeout(() => clearTurn(layer), 640));
  }

  // Set just before a tab's click that should turn the page: the navigator,
  // the side tabs and a swipe. The app's own jumps between screens don't.
  ed.turnNextTab = false;

  function turnToView(view) {
    const tab = document.querySelector(`.tabbar .tab[data-view="${view}"]`);
    if (!tab || tab.classList.contains('active')) return;
    ed.turnNextTab = motionOk();
    tab.click();
  }


  // ---------- Pages ----------
  // Open, the notebook is plain pages the size of the screen (user, 11-12):
  // each section is one page that scrolls, and only going from one section
  // to the next turns a page. The page machinery stays, with one page to a
  // flow: `atoms` are still what's drawn, in order, each with its headings,
  // for whatever asks which page something is on.
  const LINE = 28; ed.LINE = LINE; // the Journal's ruled line
  const screenFlows = {}; ed.screenFlows = screenFlows;
  const screenAt = { overview: 0, shoots: 0, archive: 0, journal: 0, stats: 0 }; ed.screenAt = screenAt;
  ed.statsFlows = [];
  const currentScreen = () => document.documentElement.dataset.view; ed.currentScreen = currentScreen;
};
;

// ---- components/last-place.js ----
// Where you left off: remembered, and opened again next time.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addLastPlace = function addLastPlace(ed) {
  Object.assign(ed, { readLastPlace, saveLastPlace, queueLastPlace });
  // ---------- Where you left off ----------
  // iOS closes a home-screen app whenever it likes, so the place is kept in
  // localStorage: the book shut or open, the section and its pages, an open
  // shoot and its page, Archive mode and its page, and the filters. Read once
  // at launch (setupNotebook); written a moment after each page change, and
  // straight away when the app goes to the background. Nothing is written
  // until the launch has put the last place back.
  const LAST_PLACE_KEY = 'df_last_place';
  let lastPlaceTimer = 0;
  ed.lastPlaceArmed = false;
  ed.resumePlace = null;
  function readLastPlace() {
    try {
      const place = JSON.parse(localStorage.getItem(LAST_PLACE_KEY) || 'null');
      return place && typeof place === 'object' ? place : null;
    } catch (e) { return null; }
  }
  function saveLastPlace() {
    clearTimeout(lastPlaceTimer);
    if (!ed.lastPlaceArmed) return;
    try {
      const shootOpen = !ed.shootModalOverlay.hidden && ed.currentShootId;
      const archiveOpen = !ed.archiveModeOverlay.hidden && ed.archiveModeShootId;
      localStorage.setItem(LAST_PLACE_KEY, JSON.stringify({
        book: document.getElementById('bookOverlay').hidden ? 'open' : 'shut',
        view: ed.currentScreen(),
        pages: ed.screenAt,
        scrollY: ed.bodyScrollLockCount > 0 ? ed.bodyScrollLockY : window.scrollY,
        archiveFilter: ed.archiveFilter,
        journalFilter: ed.journalFilter,
        statsYearFilter: ed.statsYearFilter,
        shoot: shootOpen ? { id: ed.currentShootId, page: { id: ed.shootPageId, sub: ed.shootSub } } : null,
        archive: archiveOpen ? { id: ed.archiveModeShootId, at: ed.archiveAt } : null,
        shootMode: !ed.shootModeOverlay.hidden && ed.getShootModeShootId() ? { id: ed.getShootModeShootId(), at: ed.shootModeAt } : null,
      }));
    } catch (e) { /* storage unavailable: it just opens where the sun menu's fallback says */ }
  }
  function queueLastPlace() {
    if (!ed.lastPlaceArmed) return;
    clearTimeout(lastPlaceTimer);
    lastPlaceTimer = setTimeout(saveLastPlace, 500);
  }
};
;

// ---- components/screen-size.js ----
// How tall the screen really is (the gap iOS leaves), measured at the start and on resize.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addScreenSize = function addScreenSize(ed) {
  Object.assign(ed, { measureScreenGap });
  // Installed on the home screen, iOS can lay the page out a status bar short
  // of the real screen (WebKit bug 254868): bottom:0 and 100svh stop that far
  // above the bottom, leaving a blank band. --screen-gap carries what bottom:0
  // is short by and --nb-h the screen's true height. Measured from what CSS
  // itself gets, only as an installed app, only upright. A keyboard-sized
  // reading is a different problem (see setupTabbarDriftFix) and is ignored.
  const SCREEN_GAP_MAX = 80;
  const layoutBoxProbe = document.createElement('div'); ed.layoutBoxProbe = layoutBoxProbe;
  layoutBoxProbe.style.cssText = 'position:fixed;top:0;bottom:0;left:0;width:0;visibility:hidden;pointer-events:none';
  const smallHeightProbe = document.createElement('div'); ed.smallHeightProbe = smallHeightProbe;
  smallHeightProbe.style.cssText = 'position:fixed;top:0;left:0;width:0;height:100svh;visibility:hidden;pointer-events:none';
  const statusBarProbe = document.createElement('div');
  statusBarProbe.id = 'nbStatusBarProbe';
  statusBarProbe.style.cssText = 'position:fixed;top:0;left:0;width:0;height:env(safe-area-inset-top);visibility:hidden;pointer-events:none';
  document.body.append(layoutBoxProbe, smallHeightProbe, statusBarProbe);
  // Installed, the navigator hangs from the top at the screen's real bottom (see styles/notebook-popups.css).
  if (navigator.standalone === true || matchMedia('(display-mode: standalone)').matches) document.documentElement.classList.add('nb-installed');
  let screenGap = 0; ed.screenGap = screenGap;
  ed.screenShortHeight = 0;
  let screenLaidOut = 0;
  let screenGapUpright = null;
  const screenHeightNow = () => layoutBoxProbe.getBoundingClientRect().height + screenGap; ed.screenHeightNow = screenHeightNow;

  function measureScreenGap() {
    if (!(navigator.standalone === true || matchMedia('(display-mode: standalone)').matches)) return false;
    if (ed.isTurned()) return false; // turned back upright: the page is its own upright screen
    const upright = window.innerWidth < window.innerHeight;
    // A keyboard makes for odd readings, unless the phone has just been turned.
    const field = document.activeElement;
    if (upright === screenGapUpright && field && field.matches('input, textarea, select, [contenteditable]')) return false;
    if (window.visualViewport && window.visualViewport.scale > 1.01) return false;
    const full = Math.max(screen.width, screen.height);
    const hasStatusBar = upright && statusBarProbe.getBoundingClientRect().height > 0;
    const shortBy = (el) => full - el.getBoundingClientRect().height;
    const boxShort = shortBy(layoutBoxProbe);
    // (Only the page's own box: 100svh can be off on its own, see below.)
    if (upright && boxShort > SCREEN_GAP_MAX) return false;
    screenGapUpright = upright;
    // iOS draws nothing in the strip it's short by (on the iPhone the
    // navigator vanished in it), so everything stays above it: --nb-h is the
    // height iOS laid out, and .nb-short drops the room kept for the home bar,
    // which is that strip's height further down anyway.
    const shortHeight = hasStatusBar && boxShort >= 8 ? Math.round(full - boxShort) : 0;
    // Installed, everything is laid out from the height iOS laid the page out
    // at, never 100svh: on iOS 26 that can be a status bar short of the
    // screen even when the page isn't, which left the navigator that high with
    // the list showing under it (user's screenshot, 11-12).
    const laidOut = Math.round(layoutBoxProbe.getBoundingClientRect().height);
    if (shortHeight === ed.screenShortHeight && laidOut === screenLaidOut) return false;
    ed.screenShortHeight = shortHeight;
    screenLaidOut = laidOut;
    document.documentElement.classList.toggle('nb-short', !!shortHeight);
    document.documentElement.style.setProperty('--nb-h', `${laidOut}px`);
    return true;
  }
  measureScreenGap();
};
;

// ---- components/screen-pages.js ----
// A screen laid out as notebook pages: what goes on each page.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addScreenPages = function addScreenPages(ed) {
  Object.assign(ed, { drawFlowPage, buildFlow, statsFlat, screenPageCount, syncPageSide, drawScreenPage, repaginate });
  function atomBottom(a) {
    const el = a.also && a.also.length ? a.also[a.also.length - 1] : a.el;
    return el.getBoundingClientRect().bottom;
  }

  function clearSlice(body) {
    body.style.height = '';
    body.style.overflow = '';
    body.firstElementChild.style.transform = '';
  }

  function drawFlowPage(flow, at) {
    flow.root.querySelectorAll('.pg-first').forEach(el => el.classList.remove('pg-first'));
    flow.parts.forEach(el => el.classList.add('pg-off'));
    flow.bodies.forEach(clearSlice);
    const page = flow.pages[at];
    if (!page) return;
    const show = (el) => {
      for (let n = el; n && n !== flow.root && n.classList.contains('pg-off'); n = n.parentElement) n.classList.remove('pg-off');
    };
    const spans = new Map();
    page.atoms.forEach((a) => {
      show(a.el);
      (a.also || []).forEach(show);
      a.heads.forEach(show);
      if (a.row === undefined) return;
      const span = spans.get(a.el);
      if (span) span.count++;
      else spans.set(a.el, { first: a.row, count: 1, rows: a.rows });
    });
    // A long entry shows through a window as tall as its lines on this page.
    spans.forEach(({ first, count, rows }, body) => {
      if (count === rows) return;
      body.style.height = `${count * ed.LINE}px`;
      body.style.overflow = 'hidden';
      body.firstElementChild.style.transform = `translateY(${-first * ed.LINE}px)`;
    });
    if (at > 0) {
      // Whatever starts a later page starts at the top of it.
      const first = page.atoms[0].heads[0] || page.atoms[0].el;
      for (let n = first; n && n !== flow.root; n = n.parentElement) n.classList.add('pg-first');
    }
  }

  // A flow is one page holding everything; nothing is cut off or hidden.
  function buildFlow(root, atomsOf) {
    root.querySelectorAll('.pg-off, .pg-first').forEach(el => el.classList.remove('pg-off', 'pg-first'));
    root.querySelectorAll('.jb-in').forEach(el => clearSlice(el.parentElement));
    const atoms = atomsOf(root);
    return { root, parts: new Set(), pageEnd: Infinity, pages: atoms.length ? [{ atoms, drawn: new Set() }] : [], bodies: new Set() };
  }

  // The headings a row sits under: its group's, and every group above that.
  function headsAbove(el, root) {
    const heads = [];
    for (let n = el; n && n !== root; n = n.parentElement) {
      if (n.matches('.shoot-status-rows, .upcoming-subheading-rows') && n.previousElementSibling) heads.unshift(n.previousElementSibling);
      else if (n.matches('.section-block')) heads.unshift(n.querySelector(':scope > h2'));
    }
    return heads;
  }
  const listAtoms = (root, selector) => [...root.querySelectorAll(selector)]
    .filter(el => !el.hidden)
    .map(el => ({ el, heads: headsAbove(el, root) }));

  function journalAtoms(root) {
    const atoms = [];
    root.querySelectorAll('.journal-entry-images:not([hidden])').forEach((grid) => {
      // Photo rows take whole ruled lines, so what follows stays on the rules.
      const thumb = grid.querySelector('.moodboard-thumb');
      if (!thumb) return;
      grid.style.gridAutoRows = `${Math.ceil(thumb.offsetHeight / ed.LINE) * ed.LINE}px`;
      grid.style.rowGap = '0';
      grid.style.alignItems = 'start';
    });
    // Like a real notebook, nothing is written twice: a heading goes with the
    // first line under it (so it's never left alone at the foot of a page), and
    // a card that runs over just carries on at the top of the next page.
    const claimed = new Set();
    root.querySelectorAll('#journalList .log-card').forEach((card) => {
      const above = headsAbove(card, root).filter(h => !claimed.has(h));
      above.forEach(h => claimed.add(h));
      let pending = null;
      const lead = () => { const h = pending || []; pending = null; return h; };
      if (card.classList.contains('journal-entry-card')) {
        const heading = card.querySelector('.journal-entry-heading');
        pending = [...above, heading];
        const before = atoms.length;
        const body = card.querySelector('.journal-entry-body');
        const rows = Math.round(body.offsetHeight / ed.LINE);
        for (let row = 0; row < rows; row++) atoms.push({ el: body, heads: lead(), row, rows });
        const grid = card.querySelector('.journal-entry-images');
        if (grid && !grid.hidden) {
          const lines = new Map();
          [...grid.children].forEach((thumb) => {
            const top = Math.round(thumb.getBoundingClientRect().top);
            if (!lines.has(top)) lines.set(top, []);
            lines.get(top).push(thumb);
          });
          lines.forEach(([el, ...also]) => atoms.push({ el, also, heads: lead() }));
        }
        const tags = card.querySelector('.journal-entry-tags');
        if (tags && !tags.hidden) atoms.push({ el: tags, heads: lead() });
        if (atoms.length === before) atoms.push({ el: heading, heads: above });
        atoms[atoms.length - 1].hang = true;
        return;
      }
      const week = card.querySelector(':scope > .log-week-heading');
      pending = [...above, week];
      [...card.querySelector('.journal-paper').children].forEach((child) => {
        if (child.matches('.log-section-label')) { pending = [...(pending || []), child]; return; }
        if (child.matches('ul')) [...child.children].forEach(el => atoms.push({ el, heads: lead() }));
        else atoms.push({ el: child, heads: lead() });
      });
      if (atoms.length) atoms[atoms.length - 1].hang = true;
    });
    const empty = document.getElementById('journalEmpty');
    if (!empty.hidden) atoms.push({ el: empty, heads: [] });
    return atoms;
  }

  const SCREEN_ATOMS = {
    overview: root => listAtoms(root, '#newShootBtn, #statsRow, .section-block:not([hidden]) .shoot-row'),
    shoots: root => listAtoms(root, '#shootSortToggle, #shootSortOptions, #shootList .shoot-row, #shootEmpty'),
    archive: root => listAtoms(root, '#archiveSlideshow, #archiveFilterToggle, #archiveFilters, #archiveList .shoot-row, #archiveEmpty'),
    journal: journalAtoms,
  };

  function statsAtoms(page) {
    const title = page.querySelector('.stats-page-title');
    const heads = title ? [title] : [];
    const atoms = [];
    const pie = page.querySelector(':scope > .pie-chart');
    if (pie) atoms.push({ el: pie, heads });
    const hint = page.querySelector(':scope > .empty-hint');
    if (hint) atoms.push({ el: hint, heads });
    const toolbar = page.querySelector('.world-map-toolbar');
    const map = page.querySelector('.world-map-scroll');
    if (toolbar && map) atoms.push({ el: toolbar, also: [map], heads });
    page.querySelectorAll('.stats-legend > .stats-legend-row').forEach(el => atoms.push({ el, heads }));
    page.querySelectorAll('.stats-region-group').forEach((group) => {
      const heading = group.querySelector('.stats-region-heading');
      const cities = [...group.querySelectorAll('.stats-legend-row-nested')];
      if (!cities.length) atoms.push({ el: heading, heads });
      cities.forEach(el => atoms.push({ el, heads: [...heads, heading] }));
    });
    return atoms;
  }

  // Every breakdown is on the one page, one under another.
  function statsFlat() {
    return ed.statsFlows.length ? [{ stat: 0, sub: 0 }] : [];
  }

  function buildStatsFlows() {
    const was = statsFlat()[screenNow('stats')];
    ed.statsFlows = [...ed.statsCarousel.querySelectorAll('.stats-page')].map(page => buildFlow(page, statsAtoms));
    const flat = statsFlat();
    const sub = was ? was.sub : 0;
    const stay = flat.filter(p => p.stat === ed.statsPageIdx);
    const landing = stay[Math.min(sub, stay.length - 1)];
    ed.screenAt.stats = landing ? flat.indexOf(landing) : 0;
  }

  function screenPageCount(view) {
    if (view === 'stats') return Math.max(1, statsFlat().length);
    const flow = ed.screenFlows[view];
    return (flow && flow.pages.length) || 1;
  }

  // screenAt is the page asked for; it isn't cut down here, because a pass
  // drawn before the photos are in can be shorter than the screen really is.
  const screenNow = view => Math.max(0, Math.min(ed.screenAt[view], screenPageCount(view) - 1)); ed.screenNow = screenNow;

  // There are no left- and right-hand pages any more: every page is the screen.
  function syncPageSide() {
    document.documentElement.dataset.side = 'recto';
  }

  function drawScreenPage(view) {
    ed.queueLastPlace();
    const count = screenPageCount(view);
    const at = screenNow(view);
    syncPageSide();
    let flow = ed.screenFlows[view];
    let sub = at;
    if (view === 'stats') {
      const spot = statsFlat()[at];
      if (spot) {
        ed.statsFlows.forEach((f, stat) => drawFlowPage(f, stat === spot.stat ? spot.sub : 0));
        ed.statsPageIdx = spot.stat;
        ed.positionStatsTrack();
        ed.renderStatsDots();
        ed.updateStatsCarouselHeight();
        flow = ed.statsFlows[spot.stat];
        sub = spot.sub;
      }
    } else if (flow) {
      drawFlowPage(flow, at);
    }
    const page = flow && flow.pages[sub];
    // Only something too tall for any page lets the window scroll.
    document.documentElement.classList.toggle('pg-tall', !!page && atomBottom(page.atoms[page.atoms.length - 1]) + window.scrollY > flow.pageEnd + 0.5);
    document.getElementById('nbScreenNum').textContent = `${at + 1} / ${count}`;
    document.getElementById('nbScreenPrev').disabled = at <= 0;
    document.getElementById('nbScreenNext').disabled = at >= count - 1;
  }

  function repaginate(view) {
    const root = ed.views[view];
    if (!root || root.hidden || ed.currentScreen() !== view) return;
    if (view === 'stats') buildStatsFlows();
    else ed.screenFlows[view] = buildFlow(root, SCREEN_ATOMS[view]);
    drawScreenPage(view);
  }
};
;

// ---- components/page-pan.js ----
// Turning between a screen's pages: the slide, the spread, the buttons and the keys.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addPagePan = function addPagePan(ed) {
  Object.assign(ed, { clearPan, turnScreenPage, stepScreenPage });
  // Moving along an open spread. Two pictures of the page, side by side, slide
  // across over the real page, which is already the new one underneath.
  const PAN_MS = 460;
  let panLayer = null;
  let panTimer = 0;

  function clearPan() {
    clearTimeout(panTimer);
    if (panLayer) panLayer.remove();
    panLayer = null;
    document.documentElement.classList.remove('nb-panning');
  }

  function pinTo(el, rect) {
    Object.assign(el.style, {
      position: 'absolute', left: `${rect.left}px`, top: `${rect.top}px`, width: `${rect.width}px`, height: `${rect.height}px`,
      right: 'auto', bottom: 'auto',
    });
  }

  // One side of the spread as it's drawn right now. Where the frame's parts
  // sit depends on the side the book is on, so the picture keeps its own.
  function spreadPicture(view) {
    const board = document.querySelector('.nb-board');
    const rect = board.getBoundingClientRect();
    const frame = board.cloneNode(true);
    frame.querySelectorAll('.nb-turn, .nb-turn-under').forEach(el => el.remove());
    frame.querySelectorAll('[id]').forEach(el => el.removeAttribute('id'));
    pinTo(frame, rect);
    frame.style.boxShadow = 'none';
    frame.style.borderRadius = getComputedStyle(board).borderRadius;
    ['.nb-board-page', '.nb-screen-foot'].forEach((part) => {
      const { left, right, top, bottom, borderRadius } = getComputedStyle(board.querySelector(part));
      Object.assign(frame.querySelector(part).style, { left, right, top, bottom, borderRadius });
    });
    const side = document.createElement('div');
    side.className = 'nb-pan-side';
    const copy = ed.pageCopy(ed.views[view]);
    copy.holder.style.left = `${copy.left}px`;
    copy.holder.style.top = `${copy.top}px`;
    side.append(copy.holder, frame);
    const tabs = document.querySelector('.nb-screen-tabs:not(.nb-screen-tabs-shoot)');
    if (tabs.getClientRects().length) {
      const tabsCopy = tabs.cloneNode(true);
      pinTo(tabsCopy, tabs.getBoundingClientRect());
      tabsCopy.style.display = 'flex';
      tabsCopy.style.visibility = 'visible';
      side.appendChild(tabsCopy);
    }
    return { side, rect };
  }

  function panSpread(view, to) {
    clearPan();
    ed.clearTurn(document.querySelector('.nb-board'));
    const before = spreadPicture(view);
    ed.scrollPageTo(0);
    ed.screenAt[view] = to;
    ed.drawScreenPage(view);
    const after = spreadPicture(view);
    const goingOn = to > 0;
    const left = goingOn ? before : after;
    const right = goingOn ? after : before;
    const distance = left.rect.right - right.rect.left;
    right.side.style.left = `${distance}px`;
    const strip = document.createElement('div');
    strip.className = `nb-pan-strip ${goingOn ? 'on' : 'back'}`;
    strip.style.setProperty('--pan', `${-distance}px`);
    strip.append(left.side, right.side);
    panLayer = document.createElement('div');
    panLayer.className = 'nb-pan';
    panLayer.setAttribute('aria-hidden', 'true');
    panLayer.appendChild(strip);
    document.body.appendChild(panLayer);
    document.documentElement.classList.add('nb-panning');
    panTimer = setTimeout(clearPan, PAN_MS + 40);
  }

  function turnScreenPage(view, to) {
    const from = ed.screenNow(view);
    if (to < 0 || to >= ed.screenPageCount(view) || to === from) return;
    clearPan();
    const turning = ed.motionOk();
    // The left and right pages lie open side by side: no leaf between them.
    if (turning && view === 'overview' && (from === 0 || to === 0)) { panSpread(view, to); return; }
    const oldCopy = turning ? ed.pageCopy(ed.views[view]) : null;
    ed.scrollPageTo(0); // only a page with something too tall on it could be scrolled
    ed.screenAt[view] = to;
    ed.drawScreenPage(view);
    if (!turning) return;
    const board = document.querySelector('.nb-board');
    if (to > from) ed.playTurn(board, '', oldCopy);
    else ed.playTurn(board, 'back', ed.pageCopy(ed.views[view]), oldCopy);
  }
  function stepScreenPage(by) {
    const view = ed.currentScreen();
    const to = ed.screenNow(view) + by;
    if (to >= 0 && to < ed.screenPageCount(view)) { turnScreenPage(view, to); return; }
    // Turning past a section's last page (or back past its first) carries on
    // into the next section, as a leaf turn, landing on its first page either
    // way. Nothing comes before Overview: the book only shuts from the navigator.
    const order = [...document.querySelectorAll('.tabbar .tab')].map(tab => tab.dataset.view);
    const next = order[order.indexOf(view) + Math.sign(by)];
    if (next) ed.turnToView(next);
  }
  document.getElementById('nbScreenPrev').addEventListener('click', () => stepScreenPage(-1));
  document.getElementById('nbScreenNext').addEventListener('click', () => stepScreenPage(1));

  // Opening or closing a filter row changes the room on the page, and a new
  // filter starts from the first page.
  [['shootSortOptions', 'shoots'], ['archiveFilters', 'archive'], ['journalFilters', 'journal'], ['statsYearFilters', 'stats']].forEach(([id, view]) => {
    const el = document.getElementById(id);
    new MutationObserver(() => ed.repaginate(view)).observe(el, { attributes: true, attributeFilter: ['hidden'] });
    el.addEventListener('click', (e) => { if (e.target.closest('.chip')) ed.screenAt[view] = 0; }, true);
  });

  document.querySelectorAll('.tab').forEach(btn => {
    btn.addEventListener('click', () => {
      const view = btn.dataset.view;
      const activeBefore = document.querySelector('.tab.active');
      const previous = activeBefore ? activeBefore.dataset.view : view;
      const turning = ed.turnNextTab && previous !== view;
      ed.turnNextTab = false;
      const oldCopy = turning ? ed.pageCopy(ed.views[previous]) : null;
      clearPan();
      document.querySelectorAll('.tab').forEach(b => b.classList.toggle('active', b === btn));
      document.documentElement.dataset.view = view;
      Object.entries(ed.views).forEach(([key, el]) => { el.hidden = key !== view; });
      // Stop the Archive photo rotation the moment you leave it, rather than
      // waiting on renderArchiveSlideshow's async pass to notice.
      if (view !== 'archive') ed.stopArchiveSlideshow();
      ed.scrollPageTo(0);
      // Turning to a screen opens it at its first page.
      ed.screenAt[view] = 0;
      if (view === 'stats') ed.statsPageIdx = 0;
      ed.syncPageSide();
      ed.renderAll();
      if (turning) {
        const order = [...document.querySelectorAll('.tabbar .tab')].map(tab => tab.dataset.view);
        const board = document.querySelector('.nb-board');
        // Going on, the old page swings away; going back, the page before
        // swings in over it.
        if (order.indexOf(view) > order.indexOf(previous)) ed.playTurn(board, '', oldCopy);
        else ed.playTurn(board, 'back', ed.pageCopy(ed.views[view]), oldCopy);
      }
      // Journal's intro was rewritten when the Log and Reflections notebooks
      // merged into one page, under a new key so anyone who dismissed the old
      // wording sees the new one once.
      ed.showTabIntro(view === 'journal' ? 'journal2' : view);
    });
  });
};
;

// ---- components/first-time-intros.js ----
// First-time intros: the popup each tab shows the first time it's opened.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addFirstTimeIntros = function addFirstTimeIntros(ed) {
  Object.assign(ed, { showTabIntro });
  // ---------- First-time tab intro popups ----------
  const TAB_INTROS = {
    overview: {
      title: 'Overview',
      text: "this is your at-a-glance dashboard to see how many shoots are ready to go, still being planned, or waiting on a team or mood board, plus what's coming up next. tap '+ new shoot' anytime to start logging one.",
    },
    shoots: {
      title: 'Shoots',
      text: 'every active shoot lives here, grouped by status from early idea through delivered. Filter by category up top, and tap any card to reopen it.',
    },
    archive: {
      title: 'Archive',
      text: "shoots move here once you mark them complete, keeping your active list clean while still letting you look back. This is also where you'll find backup and restore for all your data.",
    },
    journal2: {
      title: 'Weekly',
      text: "one running page with two kinds of entries. The weekly log fills itself in for every week you shoot: which shoots happened, their categories, and the lessons learned pulled from each shoot's reflection. Tap any shoot or takeaway to see where it came from. Tap '+' to add your own reflection anytime, and tag entries with hashtags so you can find them again later. The table of contents jumps you to any entry or week.",
    },
    stats: {
      title: 'Stats',
      text: 'swipe between breakdowns of your visual languages, categories, team members, statuses, and locations. tap any slice to see exactly which shoots are behind it.',
    },
    // Shown once, right after the first automatic daily report is dismissed —
    // that's the moment the report exists in your head and "where did that go?"
    // is the natural next question. Routed through showTabIntro so it reuses
    // the same popup and seen-once bookkeeping as the tab intros.
    // Shown once, right after shoot mode is declined — the moment the question
    // "fine, but how do I get it back?" actually occurs to you.
    'shootmode:where': {
      title: 'Whenever you want it',
      text: "no problem. Shoot mode is always one tap away: open the shoot and hit 'Shoot mode' in the bar at the bottom of the page.",
    },
    'report:bell': {
      title: 'Find this again',
      text: "that was your daily report. It turns up once a day with anything that needs attention. You can pull it back up whenever you like: tap the bell at the top of the Overview screen.",
    },
  };

  const TAB_INTRO_KEY = 'dailies_seen_tab_intros_v1';

  function loadSeenTabIntros() {
    try {
      return JSON.parse(localStorage.getItem(TAB_INTRO_KEY)) || {};
    } catch (e) {
      return {};
    }
  }

  let seenTabIntros = loadSeenTabIntros();

  function showTabIntro(view) {
    const intro = TAB_INTROS[view];
    if (!intro || seenTabIntros[view]) return;
    document.getElementById('tabIntroTitle').textContent = intro.title;
    document.getElementById('tabIntroText').textContent = intro.text;
    document.getElementById('tabIntroOverlay').hidden = false;
    seenTabIntros[view] = true;
    localStorage.setItem(TAB_INTRO_KEY, JSON.stringify(seenTabIntros));
  }

  document.getElementById('tabIntroCloseBtn').addEventListener('click', () => {
    document.getElementById('tabIntroOverlay').hidden = true;
  });
};
;

// ---- pages/app-menu/photographer.js ----
// Photographer information: who's behind the camera.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addAppMenuPhotographer = function addAppMenuPhotographer(ed) {
  Object.assign(ed, { maybeShowPhotographerPrompt });
  // ---------- Photographer information ----------
  // Asked once on first open, and editable any time from the app menu. The
  // prompt is marked seen as soon as it's shown (not on save), so declining to
  // fill it in doesn't mean being asked again every launch.
  const PHOTOGRAPHER_PROMPT_KEY = 'dailies_seen_photographer_prompt_v1';

  function openPhotographerModal(isFirstRun) {
    const p = ed.normalizePhotographer(ed.state.photographer);
    document.getElementById('photographerNameInput').value = p.name;
    document.getElementById('photographerBusinessInput').value = p.businessName;
    document.getElementById('photographerPlatformSelect').value = p.socialPlatform;
    document.getElementById('photographerHandleInput').value = p.socialHandle || '@';
    document.getElementById('photographerPhoneInput').value = p.phone;
    document.getElementById('photographerIntroText').hidden = !isFirstRun;
    document.getElementById('photographerModalTitle').textContent =
      isFirstRun ? 'Welcome! A bit about you' : 'Photographer information';
    document.getElementById('photographerModalOverlay').hidden = false;
  }

  function closePhotographerModal() {
    document.getElementById('photographerModalOverlay').hidden = true;
  }

  function savePhotographerFromForm() {
    ed.state.photographer = ed.normalizePhotographer({
      name: document.getElementById('photographerNameInput').value.trim(),
      businessName: document.getElementById('photographerBusinessInput').value.trim(),
      socialPlatform: document.getElementById('photographerPlatformSelect').value,
      socialHandle: ed.normalizeSocialHandle(document.getElementById('photographerHandleInput').value),
      phone: document.getElementById('photographerPhoneInput').value.trim(),
    });
    ed.saveState();
    closePhotographerModal();
  }

  document.getElementById('photographerSaveBtn').addEventListener('click', savePhotographerFromForm);
  document.getElementById('photographerCloseBtn').addEventListener('click', closePhotographerModal);
  document.getElementById('photographerModalOverlay').addEventListener('click', (e) => {
    if (e.target === document.getElementById('photographerModalOverlay')) closePhotographerModal();
  });

  document.getElementById('photographerInfoBtn').addEventListener('click', () => {
    ed.closeAppMenu();
    openPhotographerModal(false);
  });

  function maybeShowPhotographerPrompt() {
    if (localStorage.getItem(PHOTOGRAPHER_PROMPT_KEY)) return;
    localStorage.setItem(PHOTOGRAPHER_PROMPT_KEY, '1');
    openPhotographerModal(true);
  }
};
;

// ---- components/swatch-intro.js ----
// The first-time intro to the status swatch button.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addSwatchIntro = function addSwatchIntro(ed) {
  Object.assign(ed, { maybeShowStatusSwatchIntro });
  // ---------- First-time status swatch button intro ----------
  // Shown once, the first time a new shoot is created, so it's clear the
  // "Status: ..." button up top is tappable rather than just a label.
  const STATUS_SWATCH_INTRO_KEY = 'dailies_seen_status_swatch_intro_v1'; ed.STATUS_SWATCH_INTRO_KEY = STATUS_SWATCH_INTRO_KEY;

  function maybeShowStatusSwatchIntro() {
    if (localStorage.getItem(STATUS_SWATCH_INTRO_KEY)) return;
    document.getElementById('statusSwatchIntroOverlay').hidden = false;
    localStorage.setItem(STATUS_SWATCH_INTRO_KEY, '1');
  }

  document.getElementById('statusSwatchIntroCloseBtn').addEventListener('click', () => {
    document.getElementById('statusSwatchIntroOverlay').hidden = true;
  });
};
;

// ---- pages/overview/overview.js ----
// The Overview tab (home): its buttons and counters.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addOverview = function addOverview(ed) {
  Object.assign(ed, { lockBodyScroll, unlockBodyScroll, scrollPageTo, anyPopupOpen, openStatBoxDetail, refreshOpenStatBoxDetail, closeStatBoxDetail });
  // ---------- Overview (home) ----------
  document.getElementById('newShootBtn').addEventListener('click', () => ed.openShootModal(null));

  const STAT_BOX_FILTERS = {
    // Photo shoots in Editing, plus every video step after Captured and
    // before Delivered (Rough cut, Client review, Revisions): video has no
    // separate selects stage, so its whole edit lives in this one tile.
    editing: s => !s.archived && ed.isInTheEditStatus(s.status),
    // Only shoots still being planned or waiting to shoot. Prospects are too
    // early for anyone to have a team or mood board started, and a shoot
    // that's captured, in selects/editing, delivered, postponed or canceled
    // is past needing either — it used to sneak into this count (and list)
    // through an unfinalized team alone, under a title that says "mood
    // boards pending".
    pending: s => !s.archived && (s.status === 'planning' || s.status === 'waiting_to_shoot') && ed.shootPendingLabels(s).length > 0,
    // Captured or later with no reflection written yet — the same shoots
    // whose rows say "Pending: Reflection" and that the daily report
    // reminds about (archived ones aren't counted, as with the other tiles).
    reflections: s => !s.archived && ed.isPostCaptureStatus(s.status)
      && !ed.hasText(s.whatWentRight) && !ed.hasText(s.couldBeBetter) && !ed.hasText(s.lessonsLearned),
  }; ed.STAT_BOX_FILTERS = STAT_BOX_FILTERS;

  const STAT_BOX_TITLES = {
    pending: 'Teams + mood boards pending',
    editing: 'In the edit',
    reflections: 'Pending reflections',
  }; ed.STAT_BOX_TITLES = STAT_BOX_TITLES;

  document.getElementById('statsRow').addEventListener('click', (e) => {
    const box = e.target.closest('.stat-box');
    if (!box) return;
    const key = box.dataset.stat;
    openStatBoxDetail(STAT_BOX_FILTERS[key], STAT_BOX_TITLES[key], key);
  });

  // Tracks which stat box's list is showing so closeShootModal can re-apply
  // the same filter — the popup stacks UNDER the shoot modal rather than
  // closing when a row's shoot is opened (see .stat-box-detail-overlay's
  // z-index comment), so without this a shoot you just completed from here
  // stayed listed until you closed and reopened the popup by hand.
  ed.activeStatBoxKey = null;

  // Reference-counted rather than a single on/off flag — the stat box detail
  // popup and the shoot modal can be open at once (a shoot opened from a stat
  // box list stacks on top rather than closing it first, see the z-index
  // comment above), so the second lock must not stomp the first one's saved
  // scroll position, and the page should only actually unlock once both are
  // closed again.
  ed.bodyScrollLockY = 0;
  ed.bodyScrollLockCount = 0;
  ed.onPageLetGo = null; // the notebook's nudge (nudgeShortScreen), for once no popup holds the page
  function lockBodyScroll() {
    if (ed.bodyScrollLockCount === 0) {
      ed.bodyScrollLockY = window.scrollY;
      document.body.style.position = 'fixed';
      document.body.style.top = `-${ed.bodyScrollLockY}px`;
      document.body.style.left = '0';
      document.body.style.right = '0';
    }
    ed.bodyScrollLockCount++;
  }
  function unlockBodyScroll() {
    ed.bodyScrollLockCount = Math.max(0, ed.bodyScrollLockCount - 1);
    if (ed.bodyScrollLockCount === 0) {
      document.body.style.position = '';
      document.body.style.top = '';
      document.body.style.left = '';
      document.body.style.right = '';
      window.scrollTo(0, ed.bodyScrollLockY);
      if (ed.onPageLetGo) setTimeout(ed.onPageLetGo, 80);
    }
  }

  // Scrolls the page — or, while a popup holds it locked, sets where it
  // will be once the popup closes (a tab switched under a popup, as "Done
  // shooting" does, opens at the top rather than at the old tab's place).
  function scrollPageTo(y) {
    if (ed.bodyScrollLockCount > 0) {
      ed.bodyScrollLockY = y;
      document.body.style.top = `-${y}px`;
    } else {
      window.scrollTo(0, y);
    }
  }

  // Every popup holds the page still: while any popup layer is showing, the
  // page underneath is locked (the lock above, taken once for all of them),
  // so dragging on a popup — App options, say — can't scroll the screen
  // below it. It watches each layer's `hidden` attribute rather than every
  // open/close function, so any popup built as one of these layers is
  // covered. (The stat box/project popups and the shoot page also take the
  // lock themselves; the count above keeps that from doubling up.)
  const POPUP_LAYER_SELECTOR = '.modal-overlay, .stat-box-detail-overlay, .stats-detail-overlay, .image-viewer-overlay';
  const popupLayers = [...document.querySelectorAll(POPUP_LAYER_SELECTOR)]; ed.popupLayers = popupLayers;
  let popupScrollLocked = false;

  function anyPopupOpen() {
    return popupLayers.some(layer => !layer.hidden);
  }

  // Slow work that has no popup up while it runs: a backup being gathered,
  // a PDF being built or sitting in the share sheet, a restore being
  // written. A new version is never swapped in meanwhile (see
  // updateCanReloadNow): its reload would drop the work halfway, share
  // sheet, "Backup saved" and all, without a word. A count, not a flag, since
  // two can overlap (a backup still gathering while a PDF builds).
  ed.busyTasks = 0;

  function syncPopupScrollLock() {
    const open = anyPopupOpen();
    if (open === popupScrollLocked) return;
    popupScrollLocked = open;
    if (open) {
      lockBodyScroll();
    } else {
      unlockBodyScroll();
      // A launch popup that had to wait for the screen to clear (see the
      // Monday brief).
      ed.runOwedLaunchPopups();
    }
  }

  const popupLayerObserver = new MutationObserver(syncPopupScrollLock);
  popupLayers.forEach(layer => popupLayerObserver.observe(layer, { attributes: true, attributeFilter: ['hidden'] }));

  // Split out from openStatBoxDetail so a later refresh (see closeShootModal)
  // can repaint just the list, without replaying the open animation or
  // re-locking scroll on a popup that's already open.
  function renderStatBoxDetailList(filterFn) {
    const shoots = ed.state.shoots.filter(filterFn)
      .sort((a, b) => ed.dateTimeSortKey(a).localeCompare(ed.dateTimeSortKey(b)));
    // One compact box per project, matching the tile's own count (see
    // renderOverview), placed where its earliest listed day would sit.
    const items = ed.collapseProjects(shoots);
    const list = document.getElementById('statBoxDetailList');
    list.innerHTML = '';
    items.forEach(item => ed.renderCompactListItem(list, item));
    document.getElementById('statBoxDetailEmpty').hidden = items.length > 0;
  }

  function openStatBoxDetail(filterFn, title, key) {
    ed.activeStatBoxKey = key;
    document.getElementById('statBoxDetailTitle').textContent = title;
    renderStatBoxDetailList(filterFn);
    const overlay = document.getElementById('statBoxDetailOverlay');
    overlay.hidden = false;
    lockBodyScroll();
    requestAnimationFrame(() => requestAnimationFrame(() => overlay.classList.add('open')));
  }

  // The stat box popup stacks UNDER the shoot modal rather than closing when
  // a row's shoot is opened (see .stat-box-detail-overlay's z-index comment),
  // so every path that can close the shoot modal — save, delete (both the
  // in-modal button and the options-menu one), complete, unarchive — needs
  // to call this or a shoot that just stopped matching the active filter
  // (mood board checked off, deleted, completed…) sits there stale until
  // the popup itself is closed and reopened by hand.
  function refreshOpenStatBoxDetail() {
    if (ed.activeStatBoxKey && !document.getElementById('statBoxDetailOverlay').hidden) {
      renderStatBoxDetailList(STAT_BOX_FILTERS[ed.activeStatBoxKey]);
    }
  }

  function closeStatBoxDetail() {
    ed.activeStatBoxKey = null;
    const overlay = document.getElementById('statBoxDetailOverlay');
    overlay.classList.remove('open');
    unlockBodyScroll();
    setTimeout(() => { overlay.hidden = true; }, 200);
  }

  document.getElementById('statBoxDetailCloseBtn').addEventListener('click', closeStatBoxDetail);
  document.getElementById('statBoxDetailOverlay').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) closeStatBoxDetail();
  });
};
;

// ---- pages/projects/project-popup.js ----
// A project's popup: its shoots, renaming it, and its buttons.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addProjectsProjectPopup = function addProjectsProjectPopup(ed) {
  Object.assign(ed, { openProjectPopup, refreshOpenProjectPopup, closeProjectPopup });
  // ---------- Project popup ----------
  // A project's own page: every member shoot (archived included) as the
  // same compact rows the stat box popup uses, plus the project-level
  // actions. Built on the stat box popup's overlay/modal classes, so it
  // shares that z-index — under the shoot modal (10) and the kebab sheet
  // (20), so a row's shoot or ⋮ opened from here stacks on top — and
  // renderAll() repaints it (refreshOpenProjectPopup) once they close,
  // the same job refreshOpenStatBoxDetail does for the stat boxes.
  let activeProjectId = null;
  let projectPopupHideTimer = null;
  // Guards "+ Add a day" against a double tap starting a second copy while
  // the first is still awaiting its IndexedDB writes (and Archive/Ungroup
  // against changing the project mid-copy).
  let projectPopupBusy = false;

  // Title, summary and member list only — the rename row is left exactly
  // as it is, so a repaint while you're typing a new name never wipes it.
  function renderProjectPopupBody(project) {
    const members = ed.projectMembers(project.id);
    document.getElementById('projectDetailTitle').textContent = project.name;
    const n = members.length;
    document.getElementById('projectDetailSummary').textContent = [
      `${n} shoot${n === 1 ? '' : 's'}`,
      // Only the days still on the schedule (see isOffScheduleShoot).
      ed.projectDateRangeText(members.filter(ed.isProjectLiveShoot)),
      ed.projectStatusLabel(members),
    ].filter(Boolean).join(' · ');
    // Flips once every shoot in the project is archived, the same way the
    // ⋮ menu's Archive/Unarchive shoot item does for one shoot.
    document.getElementById('projectArchiveBtn').textContent =
      members.length && members.every(s => s.archived) ? 'Unarchive project' : 'Archive project';
    const list = document.getElementById('projectDetailList');
    list.innerHTML = '';
    members.forEach(s => {
      // The stock compact row, so its tap (opens the shoot modal, which
      // stacks above this popup) and its ⋮ (normal shoot options) work
      // here unchanged; only the title gets its "Day N" prefix. An archived
      // day opens its Archive mode recap instead, like on the Archive tab.
      ed.renderCompactShootRow(list, s, { openArchiveMode: !!s.archived });
      const info = ed.projectDayInfo(s);
      if (!info) return;
      const titleEl = list.lastElementChild && list.lastElementChild.querySelector('.shoot-row-compact-title');
      if (titleEl) titleEl.textContent = `Day ${info.day} · ${titleEl.textContent}`;
    });
  }

  function hideProjectRename() {
    document.getElementById('projectRenameRow').hidden = true;
  }

  function openProjectPopup(projectId) {
    const project = ed.findProject(projectId);
    if (!project || !ed.projectMembers(project.id).length) return;
    // Already open (e.g. "Open <name>" from a member's ⋮ while this is
    // showing) just repaints — no second scroll lock, no replayed fade.
    const wasOpen = activeProjectId !== null;
    if (activeProjectId !== projectId) hideProjectRename();
    activeProjectId = projectId;
    // A reopen inside a previous close's 200ms fade must not be hidden
    // out from under itself when that timer lands.
    clearTimeout(projectPopupHideTimer);
    renderProjectPopupBody(project);
    const overlay = document.getElementById('projectDetailOverlay');
    overlay.hidden = false;
    if (wasOpen) return;
    overlay.querySelector('.stat-box-detail-modal').scrollTop = 0;
    ed.lockBodyScroll();
    requestAnimationFrame(() => requestAnimationFrame(() => overlay.classList.add('open')));
  }

  // Called at the end of every renderAll(): anything that changes a shoot
  // re-renders the lists, and this keeps the popup underneath in step —
  // or closes it once the project is gone (ungrouped, last shoot deleted
  // or moved out).
  function refreshOpenProjectPopup() {
    if (activeProjectId === null) return;
    const project = ed.findProject(activeProjectId);
    if (!project || !ed.projectMembers(project.id).length) {
      closeProjectPopup();
      return;
    }
    renderProjectPopupBody(project);
  }

  function closeProjectPopup() {
    if (activeProjectId === null) return;
    activeProjectId = null;
    hideProjectRename();
    const overlay = document.getElementById('projectDetailOverlay');
    overlay.classList.remove('open');
    ed.unlockBodyScroll();
    clearTimeout(projectPopupHideTimer);
    projectPopupHideTimer = setTimeout(() => { overlay.hidden = true; }, 200);
  }

  document.getElementById('projectDetailCloseBtn').addEventListener('click', closeProjectPopup);
  document.getElementById('projectDetailOverlay').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) closeProjectPopup();
  });

  // A new day carries the latest day forward: same talent, team, location,
  // times, concept, mood board and lighting, dated the day after it.
  document.getElementById('projectAddDayBtn').addEventListener('click', async () => {
    const project = ed.findProject(activeProjectId);
    if (!project || projectPopupBusy) return;
    const members = ed.projectMembers(project.id);
    if (!members.length) return;
    // projectMembers is date-sorted with undated shoots last, so the last
    // dated member is the latest day — the new one is dated the day after.
    // A postponed or canceled day's kept date isn't a day of the project.
    const dated = members.filter(s => ed.scheduledShootDate(s));
    const latest = dated.length ? dated[dated.length - 1] : members[members.length - 1];
    let nextDate = '';
    if (ed.scheduledShootDate(latest)) {
      const [y, m, d] = latest.date.split('-').map(Number);
      nextDate = ed.formatDate(new Date(y, m - 1, d + 1));
    }
    projectPopupBusy = true;
    try {
      // Carries the latest day forward (its times, status, any shots it
      // didn't get to)...
      const shoot = await ed.copyShootForProject(latest, 'day', { date: nextDate });
      // ...and in a multi-day project, then takes on the lead's mirrored
      // details, mood board and cover as they are now (read after the copy,
      // so an edit made to Day 1 meanwhile isn't missed) and follows it.
      const liveProject = ed.findProject(project.id);
      const lead = ed.projectLeadOf(liveProject);
      if (lead && shoot.projectId === project.id) {
        ed.applyLeadDetails(lead, shoot);
        await ed.mirrorLeadImages(liveProject, lead, { board: true, cover: true }, [shoot]);
        shoot.followsLead = true;
        shoot.mirrorSig = ed.mirrorSignature(shoot);
      }
      ed.saveState();
      ed.renderAll();
      ed.refreshOpenStatBoxDetail();
      if (shoot.projectId) {
        const info = ed.projectDayInfo(shoot);
        const dayNumber = info ? info.day : ed.projectMembers(project.id).length;
        ed.showToast(`Day ${dayNumber} added to ${project.name}`);
      } else {
        ed.showToast(`${project.name} was ungrouped, so this was added as its own shoot`);
      }
      // A row tapped while the copy was still being written may already
      // have the shoot modal open — re-filling it would drop unsaved typing.
      if (ed.shootModalOverlay.hidden) ed.openShootModal(shoot.id);
    } catch (err) {
      ed.showToast("Couldn't add a day. Please try again.");
    } finally {
      projectPopupBusy = false;
    }
  });

  document.getElementById('projectRenameBtn').addEventListener('click', () => {
    const project = ed.findProject(activeProjectId);
    if (!project) return;
    const row = document.getElementById('projectRenameRow');
    if (!row.hidden) { row.hidden = true; return; }
    const input = document.getElementById('projectRenameInput');
    input.value = project.name;
    row.hidden = false;
    input.focus();
  });

  function saveProjectRename() {
    const project = ed.findProject(activeProjectId);
    const name = document.getElementById('projectRenameInput').value.trim();
    hideProjectRename();
    // An emptied box reads as "never mind" rather than wiping the name.
    if (!project || !name || name === project.name) return;
    ed.state.projects = ed.projectsList().map(p => (p.id === project.id ? { ...p, name } : p));
    ed.saveState();
    ed.renderAll();
    ed.refreshOpenStatBoxDetail();
  }

  document.getElementById('saveProjectRenameBtn').addEventListener('click', saveProjectRename);

  document.getElementById('projectRenameInput').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') saveProjectRename();
  });

  // Archives every shoot in the project in one go (whatever their status,
  // same as the ⋮ menu's Archive shoot), or brings them all back once the
  // whole project is archived. Days already archived on their own just stay
  // archived. The popup stays open on the result, now reading Unarchive.
  document.getElementById('projectArchiveBtn').addEventListener('click', async () => {
    const project = ed.findProject(activeProjectId);
    // Not mid-copy: a day still being added would miss the change.
    if (!project || projectPopupBusy) return;
    const members = ed.projectMembers(project.id);
    if (!members.length) return;
    const unarchiving = members.every(s => s.archived);
    const n = members.length;
    const who = n === 1 ? 'Its 1 shoot moves' : `All ${n} shoots move`;
    // Not red: archiving is undone from this same button.
    const ok = await ed.askConfirm(unarchiving
      ? { title: `Unarchive ${project.name}?`, text: `${who} back to Shoots.`, confirmLabel: 'Unarchive', cancelLabel: 'Keep archived' }
      : { title: `Archive ${project.name}?`, text: `${who} to Archive.`, confirmLabel: 'Archive', cancelLabel: 'Keep in Shoots' });
    // The popup only asks; the project is re-checked in case it's gone (or
    // a copy started) while it was up.
    if (!ok || activeProjectId !== project.id || !ed.findProject(project.id) || projectPopupBusy) return;
    ed.state.shoots = ed.state.shoots.map(s => (s.projectId === project.id ? { ...s, archived: !unarchiving } : s));
    ed.saveState();
    ed.renderAll();
    ed.refreshOpenStatBoxDetail();
    ed.showToast(unarchiving ? `${project.name} is back in Shoots` : `${project.name} moved to Archive`);
  });

  document.getElementById('projectUngroupBtn').addEventListener('click', async () => {
    const project = ed.findProject(activeProjectId);
    // Not mid-copy: the day being added would otherwise land after its
    // project is already gone.
    if (!project || projectPopupBusy) return;
    const n = ed.projectMembers(project.id).length;
    const rest = n === 1 ? 'Its 1 shoot stays as a separate shoot.' : `Its ${n} shoots stay as separate shoots.`;
    // Not red: every shoot stays, only the grouping goes.
    const ok = await ed.askConfirm({ title: `Ungroup ${project.name}?`, text: rest, confirmLabel: 'Ungroup', cancelLabel: 'Keep together' });
    if (!ok || activeProjectId !== project.id || !ed.findProject(project.id) || projectPopupBusy) return;
    // Read again after the answer, so it's exactly the days in it now.
    const members = ed.projectMembers(project.id);
    members.forEach(s => ed.setShootProject(s.id, ''));
    // Removed explicitly as well, rather than leaning only on the prune
    // inside setShootProject, so ungrouping never depends on how that
    // prune decides "empty".
    ed.state.projects = ed.projectsList().filter(p => p.id !== project.id);
    ed.saveState();
    closeProjectPopup();
    ed.renderAll();
    ed.refreshOpenStatBoxDetail();
  });
};
;

// ---- pages/overview/draw-overview.js ----
// Drawing the Overview tab.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addOverviewDrawOverview = function addOverviewDrawOverview(ed) {
  Object.assign(ed, { renderOverview });
  function renderOverview() {
    drawOverview();
    ed.repaginate('overview');
  }
  function drawOverview() {
    const todayShoots = ed.state.shoots.filter(ed.isToday)
      .sort((a, b) => ed.dateTimeSortKey(a).localeCompare(ed.dateTimeSortKey(b)));
    const upcomingShoots = ed.state.shoots.filter(ed.isUpcoming)
      .sort((a, b) => ed.dateTimeSortKey(a).localeCompare(ed.dateTimeSortKey(b)));
    const deadlineShoots = ed.state.shoots.filter(ed.isUpcomingDeadline)
      .filter(s => ed.weekBucket(s.deadline) === 'this_week' || ed.weekBucket(s.deadline) === 'next_week')
      .sort((a, b) => ed.dateSortKey(a.deadline).localeCompare(ed.dateSortKey(b.deadline)));
    // Video has no proofs step, so a captured video shoot isn't listed here.
    const proofsPendingShoots = ed.state.shoots.filter(s => !s.archived && s.status === 'captured' && !ed.isVideoShoot(s))
      .sort((a, b) => ed.dateTimeSortKey(a).localeCompare(ed.dateTimeSortKey(b)));

    // A project's members collapse into one box per list (collapseProjects),
    // so every list below and each counter's number counts a project once —
    // a tile's number always matches the rows its popup shows. Today is the
    // one exception: a project day happening today is listed as itself.
    const upcomingItems = ed.collapseProjects(upcomingShoots);
    const proofsPendingItems = ed.collapseProjects(proofsPendingShoots);
    const deadlineItems = ed.collapseProjects(deadlineShoots);

    const pendingTeamMoodboardCount = ed.collapseProjects(ed.state.shoots.filter(ed.STAT_BOX_FILTERS.pending)).length;
    const inTheEditCount = ed.collapseProjects(ed.state.shoots.filter(ed.STAT_BOX_FILTERS.editing)).length;
    const pendingReflectionsCount = ed.collapseProjects(ed.state.shoots.filter(ed.STAT_BOX_FILTERS.reflections)).length;

    // "REFLECTIONS" is wider than a tile on most phones, which stretched its
    // column past the other two: the soft hyphen lets it break as
    // "REFLEC-TIONS" only where it doesn't fit, so the tiles stay equal.

    document.getElementById('statsRow').innerHTML = `
      <div class="stat-box" data-stat="pending">
        <span class="stat-num">${pendingTeamMoodboardCount}</span>
        <span class="stat-label">Teams + mood boards pending</span>
      </div>
      <div class="stat-box" data-stat="editing">
        <span class="stat-num">${inTheEditCount}</span>
        <span class="stat-label">In the edit</span>
      </div>
      <div class="stat-box" data-stat="reflections">
        <span class="stat-num">${pendingReflectionsCount}</span>
        <span class="stat-label">Pending reflec&shy;tions</span>
      </div>
    `;

    document.getElementById('todaySection').hidden = todayShoots.length === 0;
    document.getElementById('todayCount').textContent = `[${todayShoots.length}]`;
    const todayList = document.getElementById('todayShootsList');
    todayList.innerHTML = '';
    // Today lists each shoot day as itself (a project's other days are still
    // one box under Upcoming), so a project day says which project it's from.
    todayShoots.forEach(s => ed.renderShootRow(todayList, s, { showStatus: true, showProjectLine: true }));

    // A section with nothing in it isn't on the page at all.
    document.getElementById('upcomingSection').hidden = !upcomingItems.length;
    document.getElementById('upcomingCount').textContent = `[${upcomingItems.length}]`;
    const upList = document.getElementById('upcomingShootsList');
    upList.innerHTML = '';
    if (upcomingItems.length) ed.renderBucketedShoots(upList, upcomingItems, ['this_week', 'next_week', 'later'], 'date', { showStatus: true });

    document.getElementById('proofsPendingSection').hidden = !proofsPendingItems.length;
    document.getElementById('proofsPendingCount').textContent = `[${proofsPendingItems.length}]`;
    const proofsList = document.getElementById('proofsPendingShootsList');
    proofsList.innerHTML = '';
    proofsPendingItems.forEach(item => ed.renderListItem(proofsList, item, { showBadge: false }));

    document.getElementById('upcomingDeadlinesSection').hidden = !deadlineItems.length;
    document.getElementById('upcomingDeadlinesCount').textContent = `[${deadlineItems.length}]`;
    const deadlineList = document.getElementById('upcomingDeadlinesShootsList');
    deadlineList.innerHTML = '';
    if (deadlineItems.length) ed.renderBucketedShoots(deadlineList, deadlineItems, ['this_week', 'next_week'], 'deadline', { showBadge: false });

    // Section heading colors alternate dynamically, always starting with
    // yellow — Today drops out of the page entirely when nothing's due
    // today, so whichever section actually lands first (Today or Upcoming)
    // gets yellow, not a section tied to a fixed color.
    const overviewSectionIds = ['todaySection', 'upcomingSection', 'proofsPendingSection', 'upcomingDeadlinesSection'];
    let nextIsYellow = true;
    overviewSectionIds.forEach(id => {
      const section = document.getElementById(id);
      if (section.hidden) return;
      const heading = section.querySelector('h2');
      heading.classList.toggle('heading-yellow', nextIsYellow);
      heading.classList.toggle('heading-navy', !nextIsYellow);
      nextIsYellow = !nextIsYellow;
    });
  }
};
;

// ---- pages/shoots/shoot-log.js ----
// The Shoots tab (the shoot log).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootsShootLog = function addShootsShootLog(ed) {
  Object.assign(ed, { renderCategoryFilterChips, renderShoots });
  // ---------- Shoot Log view ----------
  // The Shoots page has three sort modes, each with its own nested-heading
  // scheme:
  //  - 'status' (default): grouped by status, same as always.
  //  - 'shoot_date': ignores status entirely and reorganizes every shoot by
  //    how soon it happens.
  //  - 'category': grouped by shoot category, only showing categories that
  //    actually have a shoot in them.
  // The chosen sort is remembered on this device (like collapsed sections),
  // so the Shoots page reopens the way it was left, even after a relaunch.
  const SHOOT_SORT_KEY = 'dailies_shoot_sort_v1';
  const SHOOT_SORT_LABELS = { status: 'Status', shoot_date: 'Shoot date', category: 'Category' };

  function loadShootSort() {
    try {
      const saved = localStorage.getItem(SHOOT_SORT_KEY);
      return SHOOT_SORT_LABELS[saved] ? saved : 'status';
    } catch (e) {
      return 'status';
    }
  }

  let shootSort = loadShootSort();

  const SHOOT_DATE_BUCKET_ORDER = ['this_week', 'next_week', 'later_this_month', 'next_month', 'future', 'past', 'undated'];
  const SHOOT_DATE_BUCKET_LABELS = {
    past: 'Past',
    this_week: 'This week',
    next_week: 'Next week',
    later_this_month: 'Later this month',
    next_month: 'Next month',
    future: 'In the future',
    undated: 'Undated',
  };

  // Buckets a shoot date by proximity for the 'shoot_date' sort — a finer
  // breakdown than weekBucket() (which only serves Overview's this/next/later
  // split), since this needs to separate "later this month" from "next month"
  // from "further out," and also has to account for dates already in the
  // past (weekBucket() is only ever used for upcoming, not-yet-shot dates).
  function shootDateBucket(dateStr) {
    if (!dateStr) return 'undated';
    const [y, m, d] = dateStr.split('-').map(Number);
    const date = new Date(y, m - 1, d);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const startOfThisWeek = new Date(today);
    startOfThisWeek.setDate(today.getDate() - ed.daysIntoWeek(today));
    const endOfThisWeek = new Date(startOfThisWeek);
    endOfThisWeek.setDate(startOfThisWeek.getDate() + 6);
    const startOfNextWeek = new Date(endOfThisWeek);
    startOfNextWeek.setDate(endOfThisWeek.getDate() + 1);
    const endOfNextWeek = new Date(startOfNextWeek);
    endOfNextWeek.setDate(startOfNextWeek.getDate() + 6);
    const endOfThisMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0);
    const endOfNextMonth = new Date(today.getFullYear(), today.getMonth() + 2, 0);

    if (date < startOfThisWeek) return 'past';
    if (date <= endOfThisWeek) return 'this_week';
    if (date <= endOfNextWeek) return 'next_week';
    if (date <= endOfThisMonth) return 'later_this_month';
    if (date <= endOfNextMonth) return 'next_month';
    return 'future';
  }

  function renderShootSortOptions() {
    document.getElementById('shootSortToggle').textContent = `Sort: ${SHOOT_SORT_LABELS[shootSort]}`;
    document.querySelectorAll('#shootSortOptions .chip').forEach(chip => {
      chip.classList.toggle('active', chip.dataset.sort === shootSort);
    });
  }

  document.getElementById('shootSortToggle').addEventListener('click', () => {
    const options = document.getElementById('shootSortOptions');
    options.hidden = !options.hidden;
  });

  document.getElementById('shootSortOptions').addEventListener('click', (e) => {
    const chip = e.target.closest('.chip');
    if (!chip || !chip.dataset.sort) return;
    shootSort = chip.dataset.sort;
    try { localStorage.setItem(SHOOT_SORT_KEY, shootSort); } catch (e) { /* ignore */ }
    document.getElementById('shootSortOptions').hidden = true;
    renderShoots();
  });

  function renderCategoryFilterChips(containerId, toggleId, activeFilter) {
    const container = document.getElementById(containerId);
    const visibleCats = ed.CATEGORY_FILTER_ORDER.filter(ed.isCategoryVisible);
    container.innerHTML = `
      <button type="button" class="chip ${activeFilter === 'all' ? 'active' : ''}" data-filter="all">All</button>
      ${visibleCats.map(cat => `<button type="button" class="chip ${activeFilter === cat ? 'active' : ''}" data-filter="${cat}">${ed.CATEGORY_LABELS[cat]}</button>`).join('')}
      <button type="button" class="chip chip-manage"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg> Edit</button>
    `;
    document.getElementById(toggleId).textContent = `Filter: ${activeFilter === 'all' ? 'All' : (ed.CATEGORY_LABELS[activeFilter] || 'All')}`;
  }

  // Shared renderer for one nested group (status / date bucket / category)
  // on the Shoots page — same collapsible pill-heading + rows-wrap structure
  // regardless of which sort mode built the group. Takes collapseProjects()
  // items, so a project shows as one box (see renderListItem).
  function renderShootGroup(list, groupKey, label, items, visibleIndex) {
    const groupEl = document.createElement('div');
    groupEl.className = 'shoot-status-group';

    const heading = document.createElement('h2');
    heading.className = `status-group-heading ${visibleIndex % 2 === 0 ? 'heading-yellow' : 'heading-navy'}`;
    heading.textContent = label;

    const rowsWrap = document.createElement('div');
    rowsWrap.className = 'shoot-status-rows';
    items.forEach(item => ed.renderListItem(rowsWrap, item, { showPending: true }));

    groupEl.appendChild(heading);
    groupEl.appendChild(rowsWrap);
    list.appendChild(groupEl);
  }

  // Default — grouped by status, same as always: every group orders by
  // shoot date except the edit stages (Editing, and video's Rough cut/Client
  // review/Revisions), which order by deadline since that's the date that
  // actually matters once a shoot's already been captured. A project box
  // goes in the group of its least-advanced listed day (listItemStatusKey)
  // and sorts by its rep, through the same comparators.
  function renderShootsByStatus(list, items) {
    let visibleIndex = 0;
    Object.keys(ed.STATUS_LABELS).forEach(statusKey => {
      const group = items.filter(item => ed.listItemStatusKey(item) === statusKey)
        .sort((a, b) => {
          const repA = ed.listItemRep(a);
          const repB = ed.listItemRep(b);
          // Edit stages sort by the deadline each row shows (for a project
          // box, its earliest still-owed one — see listItemDate).
          return ed.isInTheEditStatus(statusKey)
            ? ed.dateSortKey(ed.listItemDate(a, 'deadline')).localeCompare(ed.dateSortKey(ed.listItemDate(b, 'deadline')))
            : ed.dateTimeSortKey(repA).localeCompare(ed.dateTimeSortKey(repB));
        });
      if (!group.length) return;
      renderShootGroup(list, statusKey, ed.STATUS_LABELS[statusKey], group, visibleIndex);
      visibleIndex++;
    });
  }

  // Ignores status entirely — every shoot lands in one bucket by how soon
  // (or how long ago) its shoot date is; a project box by its rep's date
  // (its next day ahead, else its first day). A postponed or canceled
  // shoot's kept date is only the original plan, so it files as Undated,
  // where it always sat back when that date was wiped.
  function renderShootsByDate(list, items) {
    const buckets = new Map();
    items.forEach(item => {
      const bucket = shootDateBucket(ed.scheduledShootDate(ed.listItemRep(item)));
      if (!buckets.has(bucket)) buckets.set(bucket, []);
      buckets.get(bucket).push(item);
    });
    let visibleIndex = 0;
    SHOOT_DATE_BUCKET_ORDER.forEach(bucketKey => {
      const group = buckets.get(bucketKey);
      if (!group || !group.length) return;
      group.sort((a, b) => ed.dateTimeSortKey(ed.listItemRep(a)).localeCompare(ed.dateTimeSortKey(ed.listItemRep(b))));
      renderShootGroup(list, `date:${bucketKey}`, SHOOT_DATE_BUCKET_LABELS[bucketKey], group, visibleIndex);
      visibleIndex++;
    });
  }

  // Grouped by category — only categories with at least one shoot show up,
  // in the app's usual category order (not alphabetical; that's just for
  // the Edit Shoot category dropdown). A project box files under its rep's
  // category.
  function renderShootsByCategory(list, items) {
    const buckets = new Map();
    items.forEach(item => {
      const cat = ed.listItemRep(item).category || 'other';
      if (!buckets.has(cat)) buckets.set(cat, []);
      buckets.get(cat).push(item);
    });
    let visibleIndex = 0;
    ed.CATEGORY_FILTER_ORDER.forEach(cat => {
      const group = buckets.get(cat);
      if (!group || !group.length) return;
      group.sort((a, b) => ed.dateTimeSortKey(ed.listItemRep(a)).localeCompare(ed.dateTimeSortKey(ed.listItemRep(b))));
      renderShootGroup(list, `cat:${cat}`, ed.CATEGORY_LABELS[cat] || 'Other', group, visibleIndex);
      visibleIndex++;
    });
  }

  function renderShoots() {
    drawShoots();
    ed.repaginate('shoots');
  }
  function drawShoots() {
    renderShootSortOptions();
    const list = document.getElementById('shootList');
    // Collapsed once for the whole page, so every sort mode files a
    // project's box exactly once (by its rep, or its least-advanced day for
    // Status) rather than splitting it across groups.
    const items = ed.collapseProjects(ed.state.shoots.filter(s => !s.archived));

    list.innerHTML = '';
    document.getElementById('shootEmpty').hidden = items.length !== 0;

    if (shootSort === 'shoot_date') renderShootsByDate(list, items);
    else if (shootSort === 'category') renderShootsByCategory(list, items);
    else renderShootsByStatus(list, items);
  }
};
;

// ---- pages/archive/archive.js ----
// The Archive tab.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addArchive = function addArchive(ed) {
  Object.assign(ed, { startArchiveSlideshow, stopArchiveSlideshow, loadArchiveSlideshow, renderArchiveSlideshow, renderArchive });
  // ---------- Archive view ----------
  ed.archiveFilter = 'all';
  let archiveSlideshowTimer = null;
  // null until the first read lands, so even "no photos" gets drawn once
  // (it shows the empty-state line).
  let archiveSlideshowSignature = null;
  // The slideshow's photos are the app's biggest, so they're not read at
  // launch: loadArchiveSlideshow runs a moment after the first paint (or
  // straight away if Archive is opened first). After that it only reads
  // again when final images change (noteImagesWritten) or the set of shoots
  // does — not on every renderAll, which runs on every tab switch.
  ed.archiveSlideshowLoaded = false;
  ed.archiveSlideshowStale = true;
  let archiveSlideshowShootsKey = '';
  // One read at a time: a burst of writes (deleting or importing many
  // shoots) folds into the read already running plus one catch-up, rather
  // than a full read of every final image per write.
  let archiveSlideshowReading = false;

  // The rotation is deliberately split out from the DOM build below. Each tick
  // cross-fades and scales a full-size photo over 4.2s on a 4.2s interval, so
  // something is always animating — left running it would keep compositing
  // large bitmaps while you're on a completely different tab. It's started
  // only while Archive is actually on screen (see stopArchiveSlideshow's
  // callers: tab switches and the app going to the background).
  function startArchiveSlideshow() {
    stopArchiveSlideshow();
    const container = document.getElementById('archiveSlideshow');
    if (!container || ed.views.archive.hidden || document.hidden) return;
    const imgs = container.querySelectorAll('img');
    if (imgs.length < 2) return;
    let idx = Array.prototype.findIndex.call(imgs, im => im.classList.contains('active'));
    if (idx < 0) idx = 0;
    archiveSlideshowTimer = setInterval(() => {
      const current = container.querySelectorAll('img');
      if (!current.length) return;
      current[idx].classList.remove('active');
      idx = (idx + 1) % current.length;
      current[idx].classList.add('active');
    }, 4200);
  }

  function stopArchiveSlideshow() {
    clearInterval(archiveSlideshowTimer);
    archiveSlideshowTimer = null;
  }

  function loadArchiveSlideshow() {
    ed.archiveSlideshowLoaded = true;
    renderArchiveSlideshow();
  }

  // Pulls final images across every non-video shoot (any status) and cycles
  // through them; skips a rebuild if the image set hasn't actually changed so
  // the animation doesn't restart every time renderAll() runs. Video shoots
  // have no final images (any left from before a switch to video are hidden).
  function renderArchiveSlideshow() {
    // Not loaded yet (see archiveSlideshowLoaded) — unless Archive's the
    // screen being shown.
    if (!ed.archiveSlideshowLoaded) {
      if (ed.views.archive.hidden) return;
      ed.archiveSlideshowLoaded = true;
    }
    const shoots = ed.state.shoots.filter(s => !ed.isVideoShoot(s));
    const shootsKey = shoots.map(s => s.id).join('|');
    // Nothing's changed since the last read — the path taken when you
    // navigate back to Archive, where the DOM is already built but the
    // rotation is stopped.
    if (!ed.archiveSlideshowStale && shootsKey === archiveSlideshowShootsKey) {
      startArchiveSlideshow();
      return;
    }
    if (archiveSlideshowReading) {
      ed.archiveSlideshowStale = true;
      return;
    }
    archiveSlideshowReading = true;
    ed.archiveSlideshowStale = false;
    archiveSlideshowShootsKey = shootsKey;
    ed.idbGetManyImages(shoots.map(s => ed.finalImagesKey(s.id))).then(rows => {
      archiveSlideshowReading = false;
      // Something changed while this was reading: skip this result and read
      // once more.
      const currentKey = ed.state.shoots.filter(s => !ed.isVideoShoot(s)).map(s => s.id).join('|');
      if (ed.archiveSlideshowStale || currentKey !== archiveSlideshowShootsKey) {
        ed.archiveSlideshowStale = true;
        renderArchiveSlideshow();
        return;
      }
      const images = [];
      shoots.forEach(shoot => {
        (rows.get(ed.finalImagesKey(shoot.id)) || []).forEach(img => { if (img.src) images.push({ src: img.src, shootId: shoot.id }); });
      });
      const signature = images.map(img => img.src).join('|');
      // Unchanged image set (a write that didn't change what's shown): leave
      // the existing <img>s alone, but still re-evaluate the timer.
      if (signature === archiveSlideshowSignature) {
        startArchiveSlideshow();
        return;
      }
      archiveSlideshowSignature = signature;
      ed.shuffleArray(images);

      stopArchiveSlideshow();
      const container = document.getElementById('archiveSlideshow');
      // The photo on screen stays until the new first one has faded in over
      // it — no cut to an empty box when the set changes while you watch.
      const showing = images.length ? container.querySelector('img.active') : null;
      container.querySelectorAll('img').forEach(img => { if (img !== showing) img.remove(); });
      document.getElementById('archiveSlideshowEmpty').hidden = images.length > 0;
      if (!images.length) return;

      let first = null;
      images.forEach(entry => {
        const img = document.createElement('img');
        img.src = entry.src;
        img.dataset.shootId = entry.shootId;
        container.appendChild(img);
        if (!first) first = img;
      });
      // The first photo fades in with the slideshow's own cross-fade rather
      // than popping in, when Archive's on screen as it loads (built while
      // Archive's hidden, it's simply there when you get to it).
      void first.offsetWidth;
      first.classList.add('active');
      if (showing) {
        showing.classList.remove('active');
        // The rotation starts once the old photo's gone, so it counts from
        // the new set only.
        setTimeout(() => {
          showing.remove();
          startArchiveSlideshow();
        }, 1250);
      } else {
        startArchiveSlideshow();
      }
    }).catch(() => {
      archiveSlideshowReading = false;
      ed.archiveSlideshowStale = true;
    });
  }

  document.getElementById('archiveSlideshow').addEventListener('click', (e) => {
    // The photo on screen, not whatever the tap hit: every photo is stacked
    // in the same spot (the hidden ones only faded out), so the last one in
    // the list would take every tap.
    const img = e.currentTarget.querySelector('img.active') || e.target.closest('img');
    if (!img) return;
    const shoot = ed.state.shoots.find(s => s.id === img.dataset.shootId);
    if (!shoot) return;
    // An archived shoot's photo opens its Archive mode recap, same as its
    // row in the list below (its "shoot details" button goes on to the
    // page). The slideshow also shows final images from shoots that aren't
    // archived yet, which have no Archive mode, so those still open the
    // page on the Shoots tab.
    if (shoot.archived) { ed.openArchiveMode(shoot.id); return; }
    document.querySelector(`.tab[data-view="${shoot.archived ? 'archive' : 'shoots'}"]`).click();
    ed.openShootModal(shoot.id);
  });

  document.getElementById('archiveFilterToggle').addEventListener('click', () => {
    const filters = document.getElementById('archiveFilters');
    filters.hidden = !filters.hidden;
  });

  document.getElementById('archiveFilters').addEventListener('click', (e) => {
    if (e.target.closest('.chip-manage')) {
      document.getElementById('archiveFilters').hidden = true;
      ed.openCategoryVisibilityModal();
      return;
    }
    const chip = e.target.closest('.chip');
    if (!chip || !chip.dataset.filter) return;
    ed.archiveFilter = chip.dataset.filter;
    document.getElementById('archiveFilters').hidden = true;
    renderArchive();
  });

  // Groups archived shoots into year > month buckets, most recent first, so
  // a growing archive stays browsable instead of one long flat list.
  // Undated shoots (no shoot date recorded) fall into their own trailing
  // "Undated" bucket rather than disappearing. Same collapsible pill
  // heading as the Shoots screen's status groups, nested one level for
  // months — collapse state persists per year and per year+month.
  function renderArchive() {
    drawArchive();
    ed.repaginate('archive');
  }
  function drawArchive() {
    renderArchiveSlideshow();
    ed.renderCategoryFilterChips('archiveFilters', 'archiveFilterToggle', ed.archiveFilter);
    const list = document.getElementById('archiveList');
    // Filter first, then collapse: a project box stands for the members that
    // match the active category filter (its date span covers just those).
    // It's filed by its rep's date (for a fully past project, its first day),
    // so it shows once, under one month, even when its days straddle a month
    // or year boundary. Newest first, same as before.
    let shoots = ed.state.shoots.filter(s => s.archived);
    if (ed.archiveFilter !== 'all') shoots = shoots.filter(s => s.category === ed.archiveFilter);
    const items = ed.collapseProjects(shoots)
      .sort((a, b) => ed.dateSortKey(ed.listItemRep(b).date).localeCompare(ed.dateSortKey(ed.listItemRep(a).date)));

    list.innerHTML = '';
    document.getElementById('archiveEmpty').hidden = items.length !== 0;

    const years = new Map();
    items.forEach(item => {
      const date = ed.listItemRep(item).date;
      const year = date ? date.slice(0, 4) : 'Undated';
      const month = date ? date.slice(5, 7) : '00';
      if (!years.has(year)) years.set(year, new Map());
      const months = years.get(year);
      if (!months.has(month)) months.set(month, []);
      months.get(month).push(item);
    });

    const sortedYears = [...years.keys()].sort((a, b) => {
      if (a === 'Undated') return 1;
      if (b === 'Undated') return -1;
      return b.localeCompare(a);
    });

    let visibleYearIndex = 0;
    sortedYears.forEach(year => {
      const months = years.get(year);
      const sortedMonths = [...months.keys()].sort((a, b) => b.localeCompare(a));

      const yearGroupEl = document.createElement('div');
      yearGroupEl.className = 'shoot-status-group';

      const yearHeading = document.createElement('h2');
      yearHeading.className = `status-group-heading ${visibleYearIndex % 2 === 0 ? 'heading-yellow' : 'heading-navy'}`;
      yearHeading.textContent = year;

      const yearRowsWrap = document.createElement('div');
      yearRowsWrap.className = 'shoot-status-rows';

      if (year === 'Undated') {
        // Undated only ever has the one '00' month bucket anyway — a
        // second "Undated" sub-heading under the "Undated" year heading
        // is pure redundancy, so just list the shoots directly.
        sortedMonths.forEach(month => {
          months.get(month).forEach(item => ed.renderListItem(yearRowsWrap, item, { showBadge: false, openArchiveMode: true }));
        });
      } else {
        let visibleMonthIndex = 0;
        sortedMonths.forEach(month => {
          const monthGroupEl = document.createElement('div');
          monthGroupEl.className = 'archive-month-group';

          const monthHeading = document.createElement('h3');
          monthHeading.className = `status-group-heading archive-month-heading ${visibleMonthIndex % 2 === 0 ? 'heading-yellow' : 'heading-navy'}`;
          monthHeading.textContent = ed.monthLabel(month);

          const monthRowsWrap = document.createElement('div');
          monthRowsWrap.className = 'shoot-status-rows';
          months.get(month).forEach(item => ed.renderListItem(monthRowsWrap, item, { showBadge: false, openArchiveMode: true }));

          monthGroupEl.appendChild(monthHeading);
          monthGroupEl.appendChild(monthRowsWrap);
          yearRowsWrap.appendChild(monthGroupEl);
          visibleMonthIndex++;
        });
      }

      yearGroupEl.appendChild(yearHeading);
      yearGroupEl.appendChild(yearRowsWrap);
      list.appendChild(yearGroupEl);
      visibleYearIndex++;
    });
  }
};
;

// ---- pages/journal/journal.js ----
// The Journal tab: the entry that's open, its photos and its tags.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addJournal = function addJournal(ed) {
  Object.assign(ed, { askDeletePhoto, renderJournalImages, renderJournalViewImages, getAllUsedJournalTags, renderJournalListImages });
  // ---------- Journal ----------
  ed.currentJournalEntry = null;
  ed.journalIsNew = false;
  ed.journalMode = 'view';
  ed.currentJournalTags = [];
  ed.journalSaveTimer = null;
  ed.journalHasImages = false;
  ed.journalPromptOffered = null;

  // 300 photography-specific reflection prompts (craft, personal growth,
  // business growth) offered via the "Need a starting prompt?" button.
  const JOURNAL_PROMPTS = window.EyeWords.journalPrompts; ed.JOURNAL_PROMPTS = JOURNAL_PROMPTS;

  // The journal list can run long — offers a quick way back to the top
  // without hunting for it. Only relevant while the Journal is the active
  // tab; hidden the instant it isn't.
  const journalScrollTopBtn = document.getElementById('journalScrollTopBtn');
  function updateJournalScrollTopBtn() {
    journalScrollTopBtn.hidden = ed.views.journal.hidden || window.scrollY < 400;
  }
  window.addEventListener('scroll', updateJournalScrollTopBtn, { passive: true });
  journalScrollTopBtn.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  // Linked entries (auto-compiled from a shoot's post-shoot reflection)
  // share the shoot's own final-images store instead of getting a separate
  // copy — same files, no duplicated storage. Standalone entries get their
  // own dedicated key.
  function currentJournalImagesKey() {
    if (!ed.currentJournalEntry) return null;
    return ed.currentJournalEntry.sourceShootId
      ? ed.finalImagesKey(ed.currentJournalEntry.sourceShootId)
      : ed.journalImagesKey(ed.currentJournalEntry.id);
  }

  // The one question behind every photo's × (journal, mood board, final
  // images) and the image viewer's Delete, so they all read the same.
  function askDeletePhoto() {
    return ed.askConfirm({ title: 'Delete this photo?', text: "This can't be undone.", confirmLabel: 'Delete photo', cancelLabel: 'Keep it', danger: true });
  }

  // Shared renderer for both the edit-mode grid (add/delete affordances) and
  // the view-mode grid (read-only gallery) — same images, same image viewer,
  // just with the mutating controls left out when editable is false.
  function renderImagesGrid(grid, key, editable, onChanged) {
    grid.innerHTML = '';
    if (!key) { ed.journalHasImages = false; return; }
    ed.idbGetImages(key).then(images => {
      // journalHasImages feeds autosaveJournal()'s "does this entry have any
      // content" check, so it has to stay accurate in view mode too — not
      // just while the edit-mode grid (with its add/delete controls) is up.
      ed.journalHasImages = images.length > 0;
      grid.innerHTML = images.length ? '' : (editable ? '<p class="empty-hint">No photos yet.</p>' : '');
      images.forEach((img, idx) => {
        const thumb = document.createElement('div');
        thumb.className = 'moodboard-thumb';
        thumb.innerHTML = `<img src="${img.src}" alt="" data-idx="${idx}" />` +
          (editable ? `<button type="button" class="final-thumb-delete" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>` : '');
        grid.appendChild(thumb);
      });
      if (editable) {
        grid.querySelectorAll('.final-thumb-delete').forEach(btn => {
          btn.addEventListener('click', async () => {
            if (!(await askDeletePhoto())) return;
            ed.idbGetImages(key).then(imgs => {
              imgs.splice(Number(btn.dataset.idx), 1);
              return ed.idbSetImages(key, imgs);
            }).then(() => {
              onChanged();
              ed.scheduleJournalAutosave();
            });
          });
        });
      }
      grid.querySelectorAll('.moodboard-thumb img').forEach(imgEl => {
        imgEl.addEventListener('click', () => {
          ed.openImageViewer(images, Number(imgEl.dataset.idx), key, onChanged, false);
        });
      });
    }).catch(() => { grid.innerHTML = ''; });
  }

  function renderJournalImages() {
    renderImagesGrid(document.getElementById('journalImagesGrid'), currentJournalImagesKey(), true, renderJournalImages);
  }

  function renderJournalViewImages() {
    renderImagesGrid(document.getElementById('journalViewImagesGrid'), currentJournalImagesKey(), false, renderJournalViewImages);
  }

  document.getElementById('addJournalPhotos').addEventListener('click', () => {
    document.getElementById('journalImagesFileInput').click();
  });

  document.getElementById('journalImagesFileInput').addEventListener('change', (e) => {
    const files = [...e.target.files];
    e.target.value = '';
    if (!files.length) return;
    const key = currentJournalImagesKey();
    if (!key) return;
    Promise.all(files.map(f => ed.resizeImageFile(f, 1280, 0.72)))
      .then(newImages => ed.idbGetImages(key).then(existing => {
        const combined = existing.concat(newImages.map(src => ({ src, caption: '' })));
        return ed.idbSetImages(key, combined);
      }))
      .then(() => {
        renderJournalImages();
        ed.scheduleJournalAutosave();
      })
      .catch(ed.noteStorageFull);
  });

  function getAllUsedJournalTags() {
    const set = new Set();
    ed.state.journalEntries.forEach(e => (e.tags || []).forEach(t => set.add(t)));
    return [...set].sort();
  }

  // Read-only photo strip for an entry rendered inline in the list.
  //
  // Deliberately NOT renderImagesGrid(): that one maintains journalHasImages
  // for the open editor's autosave "does this entry have any content" check,
  // and the list redraws while an entry can still be open — sharing it would
  // let a background list render overwrite the editor's flag with some other
  // entry's answer.
  function renderJournalListImages(grid, key) {
    // Already read once: drawn straight away (see journalListImageCache).
    const cached = ed.journalListImageCache.get(key);
    if (cached) {
      drawJournalListImages(grid, key, cached);
      return Promise.resolve();
    }
    return ed.idbGetImages(key).then(images => {
      ed.journalListImageCache.set(key, images);
      drawJournalListImages(grid, key, images);
    }).catch(() => { grid.hidden = true; });
  }

  function drawJournalListImages(grid, key, images) {
    grid.hidden = !images.length;
    grid.innerHTML = '';
    images.forEach((img, idx) => {
      const thumb = document.createElement('div');
      thumb.className = 'moodboard-thumb';
      thumb.innerHTML = `<img src="${img.src}" alt="" />`;
      thumb.querySelector('img').addEventListener('click', (ev) => {
        // The whole sheet of paper is tappable, so a photo tap has to stop
        // here or it also fires the edit / jump-to-shoot handler underneath.
        ev.stopPropagation();
        ed.openImageViewer(images, idx, key, () => ed.renderJournal(), false);
      });
      grid.appendChild(thumb);
    });
  }
};
;

// ---- pages/journal/journal-cards.js ----
// The Journal list: the header band, an entry's card, entries by year and month.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addJournalCards = function addJournalCards(ed) {
  Object.assign(ed, { applyJournalHeaderBand, renderJournalEntryCard, renderYearMonthGroups });
  // Sizes .journal-paper's --header-band (see the CSS) to this specific
  // entry's actual title/date height, so the blank band above the ruling
  // always fully covers it — a fixed guess would either crop a long wrapped
  // title or leave excess blank space under a short one — and sits the
  // heading on the first visible rule, at the bottom of that band. Reads as 0 (and is
  // skipped) whenever the card isn't laid out yet — not just inside a
  // collapsed month/year group, but even a fully-visible one: renderYear-
  // MonthGroups builds a whole year's months and cards in memory before
  // attaching that year to the live list in one shot, so every card is still
  // a detached, unlaid-out node at the moment renderItem builds it,
  // regardless of collapse state. Never call this from inside renderItem —
  // it always reads 0 there. renderJournal's own post-pass (after
  // renderYearMonthGroups returns, once the list is genuinely in the
  // document) is what actually measures correctly for a visible entry;
  // onReveal covers the collapsed-group case for everything left over.
  function applyJournalHeaderBand(card) {
    const heading = card.querySelector('.journal-entry-heading');
    const paper = card.querySelector('.journal-paper');
    if (!heading || !paper || !heading.offsetHeight) return;
    // .journal-paper's own 14px top padding sits above the heading, plus a
    // little extra room for open space above the title, snapped up to the
    // ruled-line pattern's own existing line positions (21, 49, 77, 105px,
    // ... — see .journal-paper's 22px background-position) so the band's
    // bottom edge lands exactly on a real rule instead of slicing one in half.
    const headingBottom = 14 + heading.offsetHeight;
    const minBand = headingBottom + 8;
    const band = Math.ceil((minBand - 21) / 28) * 28 + 21;
    paper.style.setProperty('--header-band', band + 'px');
    // The heading is whole 28px rows (see .journal-entry-heading), so this
    // margin drops it to the bottom of the band: its last row sits right on
    // the first visible rule, any extra title rows stack above it, and the
    // entry's own text — which follows directly — starts on the first row
    // below that rule. The leftover space lands above the title.
    heading.style.marginTop = (band - headingBottom) + 'px';
  }

  // One entry, rendered inline on lined notebook paper under a coloured title
  // banner — the same card shape the Log uses for a week, so the two kinds of
  // entry read as one continuous scrolling page rather than a list of things
  // to open.
  function renderJournalEntryCard(container, e) {
    const card = document.createElement('div');
    card.className = 'card log-card journal-entry-card';
    // Anchor the table of contents scrolls to (see scrollToJournalItem).
    card.dataset.entryId = e.id;
    // Alternates within the month it lands in, so collapsing a month never
    // leaves two same-coloured banners stacked against each other.
    const headingColorClass = container.children.length % 2 === 0 ? 'heading-yellow' : 'heading-navy';
    const linkedShoot = e.sourceShootId ? ed.state.shoots.find(s => s.id === e.sourceShootId) : null;
    // Same "--- shoot name" credit the Log puts after each takeaway; this entry
    // was compiled from that shoot's reflection, so it's the same attribution.
    const credit = linkedShoot
      ? `<span class="log-takeaway-source"> --- ${ed.escapeHtml(ed.shootDisplayName(linkedShoot))}</span>`
      : '';
    const tagsHtml = (e.tags || []).map(t => `<span class="beat-chip view-only">${ed.escapeHtml(t)}</span>`).join('');

    card.innerHTML = `
      <div class="log-week-heading ${headingColorClass} journal-entry-binding">
        <button type="button" class="journal-entry-options" aria-label="Options">&#8942;</button>
      </div>
      <div class="journal-paper log-paper">
        <div class="journal-entry-heading">
          <span class="journal-entry-title">${ed.escapeHtml(e.title || 'Untitled entry')}</span>
          <span class="journal-entry-date">${ed.prettyDate(e.createdAt)}</span>
        </div>
        <div class="journal-entry-body"><div class="jb-in">${ed.escapeHtml(e.body || '')}${credit}</div></div>
        <div class="journal-entry-images moodboard-grid" hidden></div>
        <div class="journal-entry-tags"${tagsHtml ? '' : ' hidden'}>${tagsHtml}</div>
      </div>
    `;

    const paper = card.querySelector('.journal-paper');
    if (linkedShoot) {
      // Auto-compiled entries are never edited here — they route back to the
      // shoot's own reflection fields so the two stay in sync. Reuses the Log's
      // "this refers to" popup rather than a confirm(), so tapping a reflection
      // behaves exactly like tapping a weekly log takeaway.
      paper.addEventListener('click', () => ed.showLogShootRef(e.sourceShootId));
    } else {
      // Hand-written entries open straight into the editor: the body is already
      // fully readable right here, so a read-only stop on the way would be a
      // popup that shows you what you're already looking at.
      paper.addEventListener('click', () => ed.openJournalModal(e.id, 'edit'));
    }

    card.querySelector('.journal-entry-options').addEventListener('click', (ev) => {
      ev.stopPropagation();
      ed.openJournalOptions(e.id);
    });

    container.appendChild(card);
    // Returned (not fire-and-forget) so scrollToJournalItem can wait for
    // every card's cover photos to finish loading before it scrolls — those
    // load from IndexedDB asynchronously and would otherwise grow cards
    // above the target after the scroll already landed, shoving it back out
    // of view.
    return ed.renderJournalListImages(card.querySelector('.journal-entry-images'), ed.journalEntryImagesKey(e));
  }

  // Collapsible year > month nesting for the Journal (and its table of
  // contents), so log weeks and written entries fold and scroll together.
  // Archive grows its own copy of this shape straight from shoot dates; this
  // one takes the date off each item via dateOf(), so it can group anything.
  //
  // Order within a month is whatever order `items` arrives in — callers sort
  // first. Headings alternate colour by *visible* index so a fold never leaves
  // two same-coloured bars stacked.
  function renderYearMonthGroups(list, items, opts) {
    const { dateOf, keyPrefix, renderItem, onReveal } = opts;
    // The Journal itself runs on in pages; only its contents list folds.
    const foldable = keyPrefix !== 'journal';
    // Collects whatever each renderItem call returns (e.g. a journal card's
    // image-loading promise) so a caller that needs to know when everything
    // has actually finished rendering — not just synchronously appended —
    // can Promise.all() this. Callers that don't care just ignore it.
    const results = [];

    const years = new Map();
    items.forEach(item => {
      const d = dateOf(item);
      const year = d ? d.slice(0, 4) : 'Undated';
      const month = d ? d.slice(5, 7) : '00';
      if (!years.has(year)) years.set(year, new Map());
      const months = years.get(year);
      if (!months.has(month)) months.set(month, []);
      months.get(month).push(item);
    });

    const sortedYears = [...years.keys()].sort((a, b) => {
      if (a === 'Undated') return 1;
      if (b === 'Undated') return -1;
      return b.localeCompare(a);
    });

    let visibleYearIndex = 0;
    sortedYears.forEach(year => {
      const months = years.get(year);
      const sortedMonths = [...months.keys()].sort((a, b) => b.localeCompare(a));

      const yearGroupEl = document.createElement('div');
      yearGroupEl.className = 'shoot-status-group';

      const yearCollapseKey = `${keyPrefix}:${year}`;
      const yearCollapsed = foldable && ed.isSectionCollapsed(yearCollapseKey);
      const yearHeading = document.createElement('h2');
      yearHeading.className = `status-group-heading ${visibleYearIndex % 2 === 0 ? 'heading-yellow' : 'heading-navy'}${yearCollapsed ? ' collapsed' : ''}`;
      yearHeading.innerHTML = `${ed.escapeHtml(year)}${foldable ? ed.COLLAPSE_ARROW_SVG : ''}`;

      const yearRowsWrap = document.createElement('div');
      yearRowsWrap.className = 'shoot-status-rows';
      yearRowsWrap.hidden = yearCollapsed;

      if (year === 'Undated') {
        // Undated only ever has the one '00' month bucket, so an "Undated"
        // sub-heading under the "Undated" year heading is the same word twice.
        sortedMonths.forEach(month => {
          months.get(month).forEach(item => results.push(renderItem(yearRowsWrap, item)));
        });
      } else {
        let visibleMonthIndex = 0;
        sortedMonths.forEach(month => {
          const monthGroupEl = document.createElement('div');
          monthGroupEl.className = 'archive-month-group';

          const monthCollapseKey = `${keyPrefix}:${year}:${month}`;
          const monthCollapsed = foldable && ed.isSectionCollapsed(monthCollapseKey);
          const monthHeading = document.createElement('h3');
          monthHeading.className = `status-group-heading archive-month-heading ${visibleMonthIndex % 2 === 0 ? 'heading-yellow' : 'heading-navy'}${monthCollapsed ? ' collapsed' : ''}`;
          monthHeading.innerHTML = `${ed.escapeHtml(ed.monthLabel(month))}${foldable ? ed.COLLAPSE_ARROW_SVG : ''}`;

          const monthRowsWrap = document.createElement('div');
          monthRowsWrap.className = 'shoot-status-rows';
          monthRowsWrap.hidden = monthCollapsed;
          months.get(month).forEach(item => results.push(renderItem(monthRowsWrap, item)));

          if (foldable) monthHeading.addEventListener('click', () => {
            const nowHidden = !monthRowsWrap.hidden;
            monthRowsWrap.hidden = nowHidden;
            monthHeading.classList.toggle('collapsed', nowHidden);
            ed.setSectionCollapsed(monthCollapseKey, nowHidden);
            if (!nowHidden && onReveal) onReveal(monthRowsWrap);
          });

          monthGroupEl.appendChild(monthHeading);
          monthGroupEl.appendChild(monthRowsWrap);
          yearRowsWrap.appendChild(monthGroupEl);
          visibleMonthIndex++;
        });
      }

      if (foldable) yearHeading.addEventListener('click', () => {
        const nowHidden = !yearRowsWrap.hidden;
        yearRowsWrap.hidden = nowHidden;
        yearHeading.classList.toggle('collapsed', nowHidden);
        ed.setSectionCollapsed(yearCollapseKey, nowHidden);
        if (!nowHidden && onReveal) onReveal(yearRowsWrap);
      });

      yearGroupEl.appendChild(yearHeading);
      yearGroupEl.appendChild(yearRowsWrap);
      list.appendChild(yearGroupEl);
      visibleYearIndex++;
    });

    return results;
  }
};
;

// ---- pages/journal/journal-list.js ----
// The Journal list: its order, filters and feed, and drawing it.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addJournalList = function addJournalList(ed) {
  Object.assign(ed, { journalFeedItems, renderJournal });
  // createdAt only holds a date (see todayStr), so two entries written the
  // same day compare equal — journalEntries is append-only (always pushed,
  // never unshifted), so the array's own order already IS creation order.
  // Array.sort is stable, and stability alone would keep same-day ties in
  // that oldest-first order, which is the wrong direction for "most recent
  // first" — breaking ties by original index (reversed) fixes that without
  // needing a real timestamp field.
  function sortJournalEntriesRecent(entries) {
    return entries
      .map((e, i) => [e, i])
      .sort(([ea, ia], [eb, ib]) => {
        const cmp = (eb.createdAt || '').localeCompare(ea.createdAt || '');
        return cmp !== 0 ? cmp : ib - ia;
      })
      .map(([e]) => e);
  }

  // Filter chips, same pattern as the Archive's: a toggle showing the current
  // choice, and a row of chips that opens under it and closes again on a pick.
  // Not remembered between launches — it opens on everything each time.
  ed.journalFilter = 'all';
  const JOURNAL_FILTERS = [
    { key: 'all', label: 'All' },
    { key: 'log', label: 'Weekly log' },
    { key: 'entries', label: 'My entries' },
  ]; ed.JOURNAL_FILTERS = JOURNAL_FILTERS;

  function renderJournalFilterChips() {
    document.getElementById('journalFilters').innerHTML = JOURNAL_FILTERS
      .map(f => `<button type="button" class="chip ${f.key === ed.journalFilter ? 'active' : ''}" data-filter="${f.key}">${f.label}</button>`)
      .join('');
    // "Filter: " is dropped where the band is too narrow for all three (styles/journal-legal-pad.css).
    document.getElementById('journalFilterToggle').innerHTML =
      `<span class="jt-word">Filter: </span>${ed.escapeHtml(JOURNAL_FILTERS.find(f => f.key === ed.journalFilter).label)}`;
    // The Weekly tab is the weekly log. Entries written here back when it was
    // the Journal still show in it (new ones are written in Overthoughts), so
    // the filter is only there when there are some.
    document.getElementById('journalFilterToggle').style.display = ed.state.journalEntries.length ? '' : 'none';
  }

  document.getElementById('journalFilterToggle').addEventListener('click', () => {
    const filters = document.getElementById('journalFilters');
    filters.hidden = !filters.hidden;
  });

  document.getElementById('journalFilters').addEventListener('click', (e) => {
    const chip = e.target.closest('.chip');
    if (!chip || !chip.dataset.filter) return;
    ed.journalFilter = chip.dataset.filter;
    document.getElementById('journalFilters').hidden = true;
    renderJournal();
  });

  // Every card on the Journal page, newest first: the auto-generated weekly
  // log weeks and the entries written by hand, merged by date. A tie goes to
  // the entry — a week is dated by its Monday start, so anything written that
  // day is the more recent of the two.
  function journalFeedItems() {
    const entries = ed.journalFilter === 'log' ? [] : sortJournalEntriesRecent(ed.state.journalEntries)
      .map(e => ({ type: 'entry', date: e.createdAt || '', entry: e }));
    const weeks = ed.journalFilter === 'entries' ? [] : ed.computeWeeklyLog()
      .map(w => ({ type: 'week', date: ed.formatDate(w.start), week: w }));
    const merged = [];
    let i = 0;
    let j = 0;
    while (i < entries.length || j < weeks.length) {
      if (j >= weeks.length || (i < entries.length && entries[i].date >= weeks[j].date)) merged.push(entries[i++]);
      else merged.push(weeks[j++]);
    }
    return merged;
  }

  function renderJournalFeedItem(container, item) {
    if (item.type === 'week') return ed.renderLogWeekCard(container, item.week);
    return ed.renderJournalEntryCard(container, item.entry);
  }

  // Nested by year > month of each item's own date (an entry's createdAt, a
  // log week's start) — same grouping structure Archive uses for shoots.
  // Returns a promise that resolves once every card's cover photos have
  // finished loading (see renderJournalEntryCard) — most callers can ignore
  // it, but scrollToJournalItem needs it so the layout has stopped shifting
  // before it scrolls.
  function renderJournal() {
    const photos = drawJournal();
    ed.repaginate('journal');
    return photos.then((done) => { ed.repaginate('journal'); return done; });
  }
  function drawJournal() {
    // Sorted before grouping, because renderYearMonthGroups keeps whatever
    // order it's handed.
    const items = journalFeedItems();

    const list = document.getElementById('journalList');
    list.innerHTML = '';
    renderJournalFilterChips();
    const empty = document.getElementById('journalEmpty');
    empty.hidden = items.length !== 0;
    if (!empty.hidden) {
      empty.textContent = ed.journalFilter === 'log'
        ? "No weekly log yet. It fills in on its own once a shoot is marked captured."
        : ed.journalFilter === 'entries'
          ? "No entries of your own yet. Tap + to write one. Anything on your mind?"
          : "No weekly log yet. It fills in on its own once a shoot is marked captured.";
    }

    const imagePromises = ed.renderYearMonthGroups(list, items, {
      dateOf: item => item.date,
      keyPrefix: 'journal',
      renderItem: renderJournalFeedItem,
      // Covers a card in a month/year that's still collapsed at this point —
      // it stays genuinely unmeasurable (real height 0) until the group
      // holding it is actually opened, which is what this re-runs for.
      onReveal: wrap => wrap.querySelectorAll('.journal-entry-card').forEach(ed.applyJournalHeaderBand),
    });
    // Every card just built is a real, attached, laid-out node now — each
    // year's whole subtree (months, cards, all of it) only gets appended to
    // `list` at the very end of building that year (see renderYearMonth-
    // Groups), so nothing in it could be measured correctly any earlier than
    // this, not even a card in a section that's expanded by default.
    list.querySelectorAll('.journal-entry-card').forEach(ed.applyJournalHeaderBand);
    return Promise.all(imagePromises);
  }
};
;

// ---- pages/journal/contents.js ----
// The Journal's table of contents.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addJournalContents = function addJournalContents(ed) {
  // ---------- Journal table of contents ----------
  // Reuses renderYearMonthGroups with its own 'journalToc' keyPrefix, so
  // expanding/collapsing a year or month inside the TOC popup never disturbs
  // what's expanded in the real list underneath (and vice versa).
  function renderJournalTocItem(container, item) {
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'journal-toc-item' + (item.type === 'week' ? ' journal-toc-item-log' : '');
    row.textContent = item.type === 'week' ? item.week.label : (item.entry.title || 'Untitled entry');
    row.addEventListener('click', () => scrollToJournalItem(item));
    container.appendChild(row);
  }

  function openJournalToc() {
    const items = ed.journalFeedItems();
    const list = document.getElementById('journalTocList');
    list.innerHTML = '';
    document.getElementById('journalTocEmpty').hidden = items.length !== 0;
    ed.renderYearMonthGroups(list, items, {
      dateOf: item => item.date,
      keyPrefix: 'journalToc',
      renderItem: renderJournalTocItem,
    });
    document.getElementById('journalTocOverlay').hidden = false;
  }

  document.getElementById('journalTocBtn').addEventListener('click', openJournalToc);

  // Expands whichever year/month the item actually lives under in the real
  // list (that list's own 'journal' collapse keys, independent of the TOC's),
  // then scrolls it to the top of the same scrolling space.
  function scrollToJournalItem(item) {
    document.getElementById('journalTocOverlay').hidden = true;
    const selector = item.type === 'week'
      ? `.log-card[data-week-key="${item.date}"]`
      : `.journal-entry-card[data-entry-id="${item.entry.id}"]`;
    // The photos have to be in first: they decide where it ends up.
    ed.renderJournal().then(() => {
      const card = document.querySelector(selector);
      if (!card) return;
      const top = card.getBoundingClientRect().top + window.scrollY - parseFloat(getComputedStyle(document.getElementById('app')).paddingTop);
      window.scrollTo({ top: Math.max(0, top), behavior: ed.motionOk() ? 'smooth' : 'auto' });
    });
  }
};
;

// ---- pages/journal/weekly-log.js ----
// The Journal's weekly log (a recap it writes itself).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addJournalWeeklyLog = function addJournalWeeklyLog(ed) {
  Object.assign(ed, { weekRangeLabel, computeWeeklyLog, logTakeaways, showLogShootRef, logWeekPaperHtml, wireLogShootRefs, renderLogWeekCard });
  // ---------- Journal weekly log (auto-generated recap) ----------
  // Fully derived from state.shoots — nothing here is persisted, so editing
  // a shoot's category or lessons-learned later just updates the log the
  // next time it's opened. Weeks run Monday to Sunday, like everywhere else
  // in the app (daysIntoWeek).
  function shootWeekWindow(dateStr) {
    const [y, m, d] = dateStr.split('-').map(Number);
    const date = new Date(y, m - 1, d);
    const start = new Date(date);
    start.setDate(date.getDate() - ed.daysIntoWeek(date));
    const end = new Date(start);
    end.setDate(start.getDate() + 6);
    return { start, end };
  }

  function weekRangeLabel(start, end) {
    const startMonth = ed.MONTH_NAMES[start.getMonth()].slice(0, 3);
    const endMonth = ed.MONTH_NAMES[end.getMonth()].slice(0, 3);
    if (start.getMonth() === end.getMonth()) {
      return `${startMonth} ${start.getDate()}–${end.getDate()}, ${end.getFullYear()}`;
    }
    return `${startMonth} ${start.getDate()} – ${endMonth} ${end.getDate()}, ${end.getFullYear()}`;
  }

  function computeWeeklyLog() {
    const shotShoots = ed.state.shoots.filter(s => s.date && ed.POST_CAPTURE_STATUSES.includes(s.status));
    const weeks = new Map();
    shotShoots.forEach(s => {
      const { start, end } = shootWeekWindow(s.date);
      const key = ed.formatDate(start);
      if (!weeks.has(key)) weeks.set(key, { start, end, shoots: [] });
      weeks.get(key).shoots.push(s);
    });
    return Array.from(weeks.values())
      .sort((a, b) => b.start - a.start)
      .map(w => ({
        // Kept so the list can group weeks by year > month. A week straddling
        // a month boundary files under the month it *starts* in, matching the
        // month its label leads with.
        start: w.start,
        label: weekRangeLabel(w.start, w.end),
        shoots: w.shoots.slice().sort((a, b) => a.date.localeCompare(b.date)),
        takeaways: logTakeaways(w.shoots),
      }));
  }

  // Keeps each takeaway tied to the shoot it came from (rather than a
  // flat list of strings) so tapping one can open that same shoot.
  // One shoot's Lessons Learned is always exactly one takeaway here —
  // splitting on every newline used to turn a single entry into
  // several bullets the moment it had a paragraph break in it, which
  // read as several distinct lessons instead of the one the shoot
  // actually had. Internal line breaks are collapsed to spaces rather
  // than dropped outright, so the text stays readable as one bullet.
  function logTakeaways(shoots) {
    return shoots
      .map(s => ({ text: (s.lessonsLearned || '').replace(/\s*\n+\s*/g, ' ').trim(), shootId: s.id }))
      .filter(t => t.text);
  }

  // Tapping a shoot or takeaway in the Log opens a small "this refers to"
  // popup rather than jumping straight to the shoot modal — the Log is a
  // read-only recap, so a confirm step avoids an accidental jump away from it.
  let logShootRefId = null;

  function showLogShootRef(shootId) {
    const s = ed.state.shoots.find(x => x.id === shootId);
    if (!s) return;
    logShootRefId = shootId;
    document.getElementById('logShootRefName').textContent = ed.shootDisplayName(s);
    document.getElementById('logShootRefOverlay').hidden = false;
  }

  document.getElementById('logShootRefCancelBtn').addEventListener('click', () => {
    document.getElementById('logShootRefOverlay').hidden = true;
  });

  document.getElementById('logShootRefViewBtn').addEventListener('click', () => {
    document.getElementById('logShootRefOverlay').hidden = true;
    const shootId = logShootRefId;
    if (!shootId) return;
    const s = ed.state.shoots.find(x => x.id === shootId);
    if (!s) return;
    // Asked from the Monday brief's copy of the week, which would otherwise
    // sit on top of the shoot it's opening (the same layer, later in the
    // page).
    ed.leaveMondayBrief();
    document.querySelector(`.tab[data-view="${s.archived ? 'archive' : 'shoots'}"]`).click();
    ed.openShootModal(shootId);
    // Land on the Reflection page rather than the first one: that's where
    // the takeaway was written, so it's what you came to look at.
    ed.showPostShootContentExpanded();
    ed.showShootPage('postShootHeading');
    ed.updateShootModalTitleFromScroll();
  });

  document.getElementById('logShootRefOverlay').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) e.currentTarget.hidden = true;
  });

  // A week's page of the Log: its shoots and takeaways on the lined paper.
  // The Monday brief shows last week's too, under labels of its own (on a
  // Monday, "this week" is the new one).
  function logWeekPaperHtml(w, shootsLabel, noTakeawaysText) {
    const shootsHtml = w.shoots.map(s =>
      `<li data-shoot-id="${s.id}">${ed.escapeHtml(ed.shootDisplayName(s))} <span class="log-shoot-category">(${ed.escapeHtml(ed.CATEGORY_LABELS[s.category] || 'Uncategorized')})</span></li>`
    ).join('');
    const takeawaysHtml = w.takeaways.length
      // Each takeaway is credited to its shoot inline, so the list still reads
      // as attributed even before you tap through to confirm which one.
      ? `<ul class="log-takeaways">${w.takeaways.map(t => {
          const from = ed.shootDisplayName(ed.state.shoots.find(x => x.id === t.shootId) || {});
          const credit = from ? `<span class="log-takeaway-source"> --- ${ed.escapeHtml(from)}</span>` : '';
          return `<li data-shoot-id="${t.shootId}">${ed.escapeHtml(t.text)}${credit}</li>`;
        }).join('')}</ul>`
      : `<p class="log-no-takeaways">${noTakeawaysText}</p>`;
    return `
      <div class="journal-paper log-paper">
        <p class="log-section-label">${shootsLabel}</p>
        <ul class="log-shoots">${shootsHtml}</ul>
        <p class="log-section-label">Takeaways</p>
        ${takeawaysHtml}
      </div>
    `;
  }

  function wireLogShootRefs(card) {
    card.querySelectorAll('.log-shoots li[data-shoot-id], .log-takeaways li[data-shoot-id]').forEach(li => {
      li.addEventListener('click', () => showLogShootRef(li.dataset.shootId));
    });
  }

  // One week of the Log, on the same lined notebook paper the written entries
  // use — the Log is the other half of the same journal, so it reads as
  // written on the same pad rather than as a report about it.
  function renderLogWeekCard(container, w) {
    const card = document.createElement('div');
    card.className = 'card log-card';
    // Anchor the table of contents scrolls to (see scrollToJournalItem).
    card.dataset.weekKey = ed.formatDate(w.start);
    // Alternates within the month it lands in, so collapsing a month never
    // leaves two same-coloured banners stacked against each other.
    const headingColorClass = container.children.length % 2 === 0 ? 'heading-yellow' : 'heading-navy';
    card.innerHTML = `
      <p class="log-week-heading ${headingColorClass}">${ed.escapeHtml(w.label)}</p>
      ${logWeekPaperHtml(w, 'Shoots this week', 'No takeaways logged this week.')}
    `;
    wireLogShootRefs(card);
    container.appendChild(card);
  }
};
;

// ---- pages/journal/entry-options.js ----
// An entry's options (its menu on the list card), its tags, and saving as you write.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addJournalEntryOptions = function addJournalEntryOptions(ed) {
  Object.assign(ed, { openJournalOptions, closeJournalOptions, askDeleteJournalEntry, openPostShootJournalPrompt, renderJournalTagsChips, renderJournalTagsSuggestions, autosaveJournal, scheduleJournalAutosave, saveJournalNow });
  // ---------- Journal entry options (kebab menu on the list card) ----------
  ed.optionsJournalEntryId = null;

  function openJournalOptions(id) {
    ed.optionsJournalEntryId = id;
    document.getElementById('journalOptionsOverlay').hidden = false;
  }

  function closeJournalOptions() {
    document.getElementById('journalOptionsOverlay').hidden = true;
    ed.optionsJournalEntryId = null;
  }

  document.getElementById('journalOptionsCancelBtn').addEventListener('click', closeJournalOptions);

  document.getElementById('journalOptionsOverlay').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) closeJournalOptions();
  });

  // Both ways of deleting an entry (its ⋮ here, or Delete inside the entry)
  // ask the same thing.
  function askDeleteJournalEntry() {
    return ed.askConfirm({ title: 'Delete this journal entry?', text: "This can't be undone.", confirmLabel: 'Delete entry', cancelLabel: 'Keep it', danger: true });
  }

  document.getElementById('deleteJournalOptionBtn').addEventListener('click', async () => {
    const id = ed.optionsJournalEntryId;
    closeJournalOptions();
    if (!id) return;
    if (!(await askDeleteJournalEntry())) return;
    const entry = ed.state.journalEntries.find(e => e.id === id);
    if (entry && !entry.sourceShootId) {
      ed.idbDeleteImages(ed.journalImagesKey(entry.id)).catch(() => {});
    }
    ed.state.journalEntries = ed.state.journalEntries.filter(e => e.id !== id);
    ed.saveState();
    ed.renderJournal();
  });

  // Auto-generated post-shoot journal entries aren't edited in place —
  // editing always routes back through the shoot's own reflection fields
  // so the two stay in sync.
  function openPostShootJournalPrompt(shootId) {
    const s = ed.state.shoots.find(x => x.id === shootId);
    if (!s) { ed.showToast("This shoot no longer exists."); return; }
    document.querySelector(`.tab[data-view="${s.archived ? 'archive' : 'shoots'}"]`).click();
    ed.openShootModal(shootId);
    ed.showShootPage('postShootHeading');
  }

  function renderJournalTagsChips() {
    const container = document.getElementById('journalTagsChips');
    container.innerHTML = ed.currentJournalTags.map((t, idx) => `
      <span class="beat-chip">${ed.escapeHtml(t)}<button type="button" class="journal-tag-remove" data-idx="${idx}">&times;</button></span>
    `).join('');
    container.querySelectorAll('.journal-tag-remove').forEach(btn => {
      btn.addEventListener('click', () => {
        ed.currentJournalTags.splice(Number(btn.dataset.idx), 1);
        renderJournalTagsChips();
        renderJournalTagsSuggestions();
        scheduleJournalAutosave();
      });
    });
  }

  function renderJournalTagsSuggestions() {
    const container = document.getElementById('journalTagsSuggestions');
    const suggestions = ed.getAllUsedJournalTags().filter(t => !ed.currentJournalTags.includes(t));
    container.innerHTML = suggestions.map(t => `<button type="button" class="beat-suggestion" data-tag="${ed.escapeHtml(t)}">+ ${ed.escapeHtml(t)}</button>`).join('');
    container.querySelectorAll('.beat-suggestion').forEach(btn => {
      btn.addEventListener('click', () => addJournalTag(btn.dataset.tag));
    });
  }

  function addJournalTag(text) {
    const trimmed = text.trim().replace(/^#/, '');
    if (!trimmed || ed.currentJournalTags.includes(trimmed)) return;
    ed.currentJournalTags.push(trimmed);
    renderJournalTagsChips();
    renderJournalTagsSuggestions();
    scheduleJournalAutosave();
  }

  const journalTagsInput = document.getElementById('journalTagsInput'); ed.journalTagsInput = journalTagsInput;
  journalTagsInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addJournalTag(journalTagsInput.value);
      journalTagsInput.value = '';
    }
  });

  function autosaveJournal() {
    if (!ed.currentJournalEntry) return;
    // View mode has no editable fields, so there's nothing on the entry to
    // re-derive from the form — skip straight to the content check below
    // (the edit-mode form fields may still hold a previous entry's draft).
    if (ed.journalMode === 'edit') {
      ed.currentJournalEntry.title = document.getElementById('journalSubject').value;
      ed.currentJournalEntry.body = document.getElementById('journalBody').value;
      ed.currentJournalEntry.tags = [...ed.currentJournalTags];
    }

    const hasContent = ed.hasText(ed.currentJournalEntry.title) || ed.hasText(ed.currentJournalEntry.body) || ed.currentJournalEntry.tags.length > 0 || ed.journalHasImages;
    const idx = ed.state.journalEntries.findIndex(x => x.id === ed.currentJournalEntry.id);

    if (hasContent) {
      if (idx === -1) {
        ed.state.journalEntries.push(ed.currentJournalEntry);
        ed.journalIsNew = false;
        document.getElementById('deleteJournalBtn').hidden = false;
      } else {
        ed.state.journalEntries[idx] = ed.currentJournalEntry;
      }
      ed.saveState();
    } else if (idx !== -1) {
      ed.state.journalEntries.splice(idx, 1);
      ed.saveState();
    }
  }

  function scheduleJournalAutosave() {
    clearTimeout(ed.journalSaveTimer);
    // Unlike the shoot form's notes fields (which are readonly and edited in
    // the expand modal), the journal body is typed straight into, so this is
    // the app's one genuinely long typing session. Same reasoning as
    // scheduleShootAutosave: a backstop, with blur and backgrounding both
    // saving immediately.
    ed.journalSaveTimer = setTimeout(autosaveJournal, 2000);
  }

  function saveJournalNow() {
    if (!ed.currentJournalEntry) return;
    clearTimeout(ed.journalSaveTimer);
    autosaveJournal();
  }

  document.getElementById('journalSubject').addEventListener('input', scheduleJournalAutosave);
  document.getElementById('journalBody').addEventListener('input', scheduleJournalAutosave);
  document.getElementById('journalSubject').addEventListener('blur', saveJournalNow);
  document.getElementById('journalBody').addEventListener('blur', saveJournalNow);
};
;

// ---- pages/journal/entry-page.js ----
// An entry open: writing it or reading it; opening, closing and deleting it.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addJournalEntryPage = function addJournalEntryPage(ed) {
  Object.assign(ed, { clearOpenJournalMarker, openJournalModal, closeJournalModal });
  const journalModalOverlay = document.getElementById('journalModalOverlay'); ed.journalModalOverlay = journalModalOverlay;
  const OPEN_JOURNAL_KEY = 'dailies_open_journal_entry'; ed.OPEN_JOURNAL_KEY = OPEN_JOURNAL_KEY;

  function setOpenJournalMarker(id) {
    try { localStorage.setItem(OPEN_JOURNAL_KEY, id); } catch (e) {}
  }

  function clearOpenJournalMarker() {
    try { localStorage.removeItem(OPEN_JOURNAL_KEY); } catch (e) {}
  }

  // The full typing setup (title/body/hashtags/photos) — reachable directly
  // for a brand-new entry, or via the Edit button on an existing standalone
  // one.
  function showJournalEditMode() {
    ed.journalMode = 'edit';
    document.getElementById('journalSubject').value = ed.currentJournalEntry.title;
    document.getElementById('journalBody').value = ed.currentJournalEntry.body;
    ed.currentJournalTags = [...ed.currentJournalEntry.tags];
    ed.renderJournalTagsChips();
    ed.renderJournalTagsSuggestions();
    ed.journalTagsInput.value = '';
    document.getElementById('deleteJournalBtn').hidden = ed.journalIsNew;
    ed.renderJournalImages();
    document.getElementById('journalViewMode').hidden = true;
    document.getElementById('journalForm').hidden = false;
  }

  // A read-only popup of the saved entry — no textboxes, no editing
  // mechanics — until the Edit button switches back to edit mode.
  function showJournalViewMode() {
    ed.journalMode = 'view';
    const e = ed.currentJournalEntry;
    document.getElementById('journalViewTitle').textContent = e.title || 'Untitled entry';
    document.getElementById('journalViewDate').textContent = ed.prettyDate(e.createdAt);
    const tagsEl = document.getElementById('journalViewTags');
    tagsEl.innerHTML = (e.tags || []).map(t => `<span class="beat-chip view-only">${ed.escapeHtml(t)}</span>`).join('');
    tagsEl.hidden = !(e.tags && e.tags.length);
    document.getElementById('journalViewBody').textContent = e.body || '';
    document.getElementById('journalViewLinkedHint').hidden = !e.sourceShootId;
    document.getElementById('deleteJournalViewBtn').hidden = ed.journalIsNew;
    document.getElementById('journalViewDoneBtn').textContent = ed.pickRandomSaveMessage();
    ed.renderJournalViewImages();
    document.getElementById('journalForm').hidden = true;
    document.getElementById('journalViewMode').hidden = false;
  }

  function openJournalModal(id, mode) {
    const existing = id ? ed.state.journalEntries.find(x => x.id === id) : null;
    ed.journalIsNew = !existing;
    ed.currentJournalEntry = existing || { id: ed.uid(), title: '', body: '', tags: [], createdAt: ed.todayStr() };
    setOpenJournalMarker(ed.currentJournalEntry.id);
    ed.journalHasImages = false;

    // A brand-new entry starts in edit mode (nothing to view yet), as does one
    // opened straight from the Reflections list, where the body is already read
    // inline. Everything else opens read-only. Auto-compiled shoot reflections
    // never get edit mode here at all — editing them routes back to the shoot —
    // so the sourceShootId guard holds even if a caller asks for it.
    if (ed.journalIsNew || (mode === 'edit' && !ed.currentJournalEntry.sourceShootId)) showJournalEditMode();
    else showJournalViewMode();

    journalModalOverlay.hidden = false;
  }

  // Auto-compiled entries never edit in place — "editing" always hands off
  // to the shoot's own reflection fields instead, so the two stay in sync.
  async function revisitLinkedJournalEntry() {
    const entry = ed.currentJournalEntry;
    const shootId = entry.sourceShootId;
    const ok = await ed.askConfirm({
      title: 'Revisit this shoot?',
      text: "This entry is written from the shoot's reflection, so that's where it's changed.",
      confirmLabel: 'Go to shoot',
      cancelLabel: 'Stay here',
    });
    // Still the entry that asked (the popup sits over it, so it should be).
    if (!ok || ed.currentJournalEntry !== entry) return;
    closeJournalModal();
    ed.openPostShootJournalPrompt(shootId);
  }

  document.getElementById('journalViewBody').addEventListener('click', () => {
    if (ed.currentJournalEntry && ed.currentJournalEntry.sourceShootId) revisitLinkedJournalEntry();
  });

  document.getElementById('editJournalBtn').addEventListener('click', () => {
    if (ed.currentJournalEntry && ed.currentJournalEntry.sourceShootId) revisitLinkedJournalEntry();
    else showJournalEditMode();
  });

  function closeJournalModal() {
    clearTimeout(ed.journalSaveTimer);
    ed.autosaveJournal();
    clearOpenJournalMarker();
    journalModalOverlay.hidden = true;
    ed.currentJournalEntry = null;
    ed.renderJournal();
  }

  document.getElementById('addJournalBtn').addEventListener('click', () => openJournalModal(null));

  // Saving no longer closes the modal — it drops back to the read-only view
  // of what was just written, right in the same popup. An entry that ends
  // up with no real content (autosave already deletes it) just closes.
  document.getElementById('saveJournalBtn').addEventListener('click', () => {
    clearTimeout(ed.journalSaveTimer);
    ed.autosaveJournal();
    const e = ed.currentJournalEntry;
    const hasContent = e && (ed.hasText(e.title) || ed.hasText(e.body) || e.tags.length > 0 || ed.journalHasImages);
    if (hasContent) showJournalViewMode();
    else closeJournalModal();
  });

  async function deleteCurrentJournalEntry() {
    const entry = ed.currentJournalEntry;
    if (!entry) return;
    if (!(await ed.askDeleteJournalEntry()) || ed.currentJournalEntry !== entry) return;
    // Linked entries share the shoot's own final-images store — only
    // standalone entries own a dedicated image key to clean up here.
    if (!ed.currentJournalEntry.sourceShootId) {
      ed.idbDeleteImages(ed.journalImagesKey(ed.currentJournalEntry.id)).catch(() => {});
    }
    ed.state.journalEntries = ed.state.journalEntries.filter(x => x.id !== ed.currentJournalEntry.id);
    ed.saveState();
    clearTimeout(ed.journalSaveTimer);
    clearOpenJournalMarker();
    journalModalOverlay.hidden = true;
    ed.currentJournalEntry = null;
    ed.renderJournal();
  }

  document.getElementById('deleteJournalBtn').addEventListener('click', deleteCurrentJournalEntry);
  document.getElementById('deleteJournalViewBtn').addEventListener('click', deleteCurrentJournalEntry);
  document.getElementById('journalViewDoneBtn').addEventListener('click', closeJournalModal);

  journalModalOverlay.addEventListener('click', (e) => {
    if (e.target === journalModalOverlay) closeJournalModal();
  });
};
;

// ---- pages/journal/starting-prompt.js ----
// Picking a starting prompt for an entry.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addJournalStartingPrompt = function addJournalStartingPrompt(ed) {
  // ---------- Journal starting-prompt picker ----------
  // Offers a random prompt from JOURNAL_PROMPTS; accepting inserts it in
  // brackets at the top of the entry body for the user to write underneath.
  function pickRandomJournalPrompt(excludeText) {
    if (ed.JOURNAL_PROMPTS.length <= 1) return ed.JOURNAL_PROMPTS[0];
    let p;
    do { p = ed.JOURNAL_PROMPTS[Math.floor(Math.random() * ed.JOURNAL_PROMPTS.length)]; } while (p === excludeText);
    return p;
  }

  function showRandomJournalPrompt() {
    ed.journalPromptOffered = pickRandomJournalPrompt(ed.journalPromptOffered);
    document.getElementById('journalPromptText').textContent = ed.journalPromptOffered;
    document.getElementById('journalPromptOverlay').hidden = false;
  }

  document.getElementById('journalPromptBtn').addEventListener('click', showRandomJournalPrompt);
  document.getElementById('journalPromptAnotherBtn').addEventListener('click', showRandomJournalPrompt);

  document.getElementById('journalPromptAcceptBtn').addEventListener('click', () => {
    document.getElementById('journalPromptOverlay').hidden = true;
    if (!ed.journalPromptOffered) return;
    const body = document.getElementById('journalBody');
    const prefix = `[${ed.journalPromptOffered}]\n\n`;
    body.value = prefix + body.value;
    body.focus();
    body.setSelectionRange(prefix.length, prefix.length);
    ed.scheduleJournalAutosave();
  });

  document.getElementById('journalPromptOverlay').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) e.currentTarget.hidden = true;
  });
};
;

// ---- pages/shoot/framework-tags.js ----
// Framework tags on the shoot page.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootFrameworkTags = function addShootFrameworkTags(ed) {
  Object.assign(ed, { renderShootFrameworkTags, syncShootFrameworkTags });
  // ---------- Framework tags (rendered inside the shoot modal) ----------
  // Every framework-tag checkbox container in the Visuals section, in DOM
  // order — Visual Language renders early (before References/Mood board);
  // any custom frameworks a user adds via Manage render later. Anything that
  // needs to touch "all framework checkboxes" regardless of which container
  // they landed in (autosave gathering, the auto-advance-focus listener)
  // reads this list rather than hardcoding a single id.
  const FRAMEWORK_TAG_CONTAINER_IDS = ['frameworkTagsContainerEarly', 'frameworkTagsContainer']; ed.FRAMEWORK_TAG_CONTAINER_IDS = FRAMEWORK_TAG_CONTAINER_IDS;
  const FRAMEWORK_TAG_CHECKBOX_SELECTOR = FRAMEWORK_TAG_CONTAINER_IDS.map(id => `#${id} input[type="checkbox"]`).join(', ');
  // NOT `FRAMEWORK_TAG_CHECKBOX_SELECTOR + ':checked'` — appending to a
  // comma-joined selector only scopes to the LAST item in the list ("all of A,
  // checked B" rather than "checked in either"), which silently pulled in
  // every Visual Language checkbox regardless of state. Each part needs its
  // own suffix.
  const FRAMEWORK_TAG_CHECKED_SELECTOR = FRAMEWORK_TAG_CONTAINER_IDS.map(id => `#${id} input[type="checkbox"]:checked`).join(', '); ed.FRAMEWORK_TAG_CHECKED_SELECTOR = FRAMEWORK_TAG_CHECKED_SELECTOR;

  function renderFrameworkTagGroup(container, frameworks, selectedTags) {
    container.innerHTML = frameworks.map(fw => {
      return `
        <div class="framework-subsection">
          <h4 class="subsection-heading framework-heading" data-fw-id="${fw.id}">${ed.escapeHtml(fw.name)}</h4>
          <div class="framework-subsection-body" data-fw-body="${fw.id}">
            <div class="tag-group">
              ${fw.tags.map(tag => {
                const entry = selectedTags.find(t => t.frameworkId === fw.id && t.tag === tag);
                return `<label class="tag-check"><input type="checkbox" data-fw="${fw.id}" value="${ed.escapeHtml(tag)}" ${entry ? 'checked' : ''} /> ${ed.escapeHtml(tag)}</label>`;
              }).join('')}
            </div>
          </div>
        </div>
      `;
    }).join('');
  }

  // Visual Language renders as its own smaller subsection nested
  // under Visuals (same visual language as Shot list), in its own early
  // container so References/Mood board can sit between it and everything
  // else. Any custom frameworks a user adds via Manage render into the later
  // container. Lighting setups is its own standalone section further down —
  // no longer nested under a framework at all (see the Lighting removal in
  // migrateFrameworks/loadState).
  function renderShootFrameworkTags(shoot) {
    const earlyContainer = document.getElementById('frameworkTagsContainerEarly');
    const container = document.getElementById('frameworkTagsContainer');

    const selectedTags = shoot ? (shoot.frameworkTags || []) : [];
    const visualLanguageFws = ed.state.frameworks.filter(fw => fw.name === 'Visual Language');
    const restFws = ed.state.frameworks.filter(fw => fw.name !== 'Visual Language');
    renderFrameworkTagGroup(earlyContainer, visualLanguageFws, selectedTags);
    renderFrameworkTagGroup(container, restFws, selectedTags);
    // Empty once Lighting's gone, unless a custom framework was added via
    // Manage — hidden rather than left as a stray gap (see the margin-top
    // this container gets further down in Visuals).
    container.hidden = restFws.length === 0;
  }

  function syncShootFrameworkTags() {
    if (!ed.shootModalOverlay.hidden) {
      const s = ed.editingShootId ? ed.state.shoots.find(x => x.id === ed.editingShootId) : null;
      renderShootFrameworkTags(s);
    }
  }

  // Checking a tag auto-advances focus to the next checkbox so a run of
  // taps can march down the list without re-aiming each time. Attached to
  // each framework container separately (rather than delegated from a shared
  // ancestor) so it can't also catch unrelated checkboxes — the mood board
  // "complete?" box sits between the two in the DOM now.
  FRAMEWORK_TAG_CONTAINER_IDS.forEach(id => {
    document.getElementById(id).addEventListener('change', (e) => {
      if (e.target.type !== 'checkbox' || !e.target.checked) return;
      const all = [...document.querySelectorAll(FRAMEWORK_TAG_CHECKBOX_SELECTOR)];
      const next = all[all.indexOf(e.target) + 1];
      if (next) next.focus();
    });
  });
};
;

// ---- pages/shoot/known-contacts.js ----
// Looking up a handle among the talents and team members you know.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootKnownContacts = function addShootKnownContacts(ed) {
  Object.assign(ed, { lookupBestContactHandle });
  // ---------- Known-contact handle lookup (talents + team members) ----------
  // Scans every shoot's talents/team members for a name match and returns
  // whatever handle(s) were saved for them last time — so a returning
  // client or a repeat team member's handle doesn't have to be retyped.
  // Rebuilt fresh on every lookup (simple over clever: this app's shoot
  // count never gets remotely large enough for that to matter).
  function buildContactHandleRegistry() {
    const registry = new Map(); // name (trimmed, lowercased) -> Map(platform -> handle)
    function record(name, platform, handle) {
      const key = (name || '').trim().toLowerCase();
      if (!key || !ed.hasText(handle)) return;
      if (!registry.has(key)) registry.set(key, new Map());
      registry.get(key).set(platform || 'instagram', handle.trim());
    }
    ed.state.shoots.forEach(s => {
      (s.talents || []).forEach(t => {
        (t.socialHandles || []).forEach(sh => record(t.name, sh.platform, sh.handle));
      });
      (s.teamMembers || []).forEach(tm => record(tm.name, tm.socialPlatform, tm.socialHandle));
    });
    return registry;
  }

  function lookupContactHandles(name) {
    const key = (name || '').trim().toLowerCase();
    if (!key) return [];
    const entry = buildContactHandleRegistry().get(key);
    if (!entry) return [];
    return Array.from(entry.entries()).map(([platform, handle]) => ({ platform, handle }));
  }

  // Team members only have room for one handle — prefer instagram (the
  // default platform) if the contact has one, otherwise whatever's on file.
  function lookupBestContactHandle(name) {
    const matches = lookupContactHandles(name);
    if (!matches.length) return null;
    return matches.find(m => m.platform === 'instagram') || matches[0];
  }
};
;

// ---- pages/shoot/talents.js ----
// Talents on the shoot page, and what shows under each.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootTalents = function addShootTalents(ed) {
  Object.assign(ed, { renderPastLessons });
  // ---------- Talents (dynamic list, right under Title) ----------
  // Each talent renders as a compact read-only summary card — name, and
  // handles as plain text — with an Edit button that reopens the same popup
  // used to add one, prefilled (see openTalentModal/talentModalDraft below).
  // Mirrors the Location popup's pattern: nothing commits to currentTalents
  // until Save is tapped, so canceling out of an edit throws nothing away.
  ed.currentTalents = [];

  // ---------- Under a shoot's talent: last time with them ----------
  // The "Lessons for next time" from other shoots with any of the same people
  // (newest first, up to three; a shoot's later days share their lessons, so
  // each one shows once), so planning starts from what was learned before.
  function renderPastLessons() {
    const box = document.getElementById('pastLessons');
    const norm = n => (n || '').trim().replace(/\s+/g, ' ').toLowerCase();
    const names = new Map();
    ed.currentTalents.forEach(t => { if (ed.hasText(t.name)) names.set(norm(t.name), t.name.trim()); });
    const seen = new Set();
    const shown = !names.size ? [] : ed.state.shoots
      .filter(s => s.id !== ed.editingShootId && ed.hasText(s.lessonsLearned) && (s.talents || []).some(t => names.has(norm(t.name))))
      .sort((a, b) => (b.date || '').localeCompare(a.date || ''))
      .filter(s => { const k = s.lessonsLearned.trim(); if (seen.has(k)) return false; seen.add(k); return true; })
      .slice(0, 3);
    box.hidden = !shown.length;
    if (!shown.length) { box.innerHTML = ''; return; }
    const who = [...new Set(shown.flatMap(s => (s.talents || []).map(t => norm(t.name)).filter(n => names.has(n))))].map(n => names.get(n));
    box.innerHTML = `<p class="team-question">Last time with ${ed.escapeHtml(ed.joinWithAnd(who))}</p>` + shown.map(s => `
      <div class="past-lesson">
        <span class="past-lesson-head">${ed.escapeHtml(ed.hasText(s.title) ? s.title.trim() : ed.shootDisplayName(s))}${s.date ? ` · ${ed.escapeHtml(ed.prettyDate(s.date))}` : ''}</span>
        <span class="past-lesson-text">${ed.escapeHtml(s.lessonsLearned.trim())}</span>
      </div>`).join('');
  }
};
;

// ---- pages/shoot/overthoughts-notes.js ----
// Notes about this shoot, written in Overthoughts.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootOverthoughtsNotes = function addShootOverthoughtsNotes(ed) {
  Object.assign(ed, { renderShootNotes, renderTalents });
  // ---------- Notes about this shoot, written in Overthoughts ----------
  // Inside Documenting Fictions an Overthoughts entry can say which shoot
  // it's about: it shows here, read only, and opens in Overthoughts. Nothing
  // goes the other way: The Eye never writes to Overthoughts.
  function renderShootNotes(shootId) {
    const box = document.getElementById('shootNotes');
    box.hidden = true;
    box.innerHTML = '';
    const D = window.DFData;
    if (!shootId || !D || !D.inSuite()) return;
    const firstLine = t => (t || '').split('\n').map(l => l.trim()).find(Boolean) || 'Untitled entry';
    D.overthoughts().then(db => D.rows(db, 'entries')).then(rows => {
      if (ed.editingShootId !== shootId) return;
      const notes = rows.map(([, e]) => e)
        .filter(e => e && e.shootId === shootId && e.kind !== 'reflection' && e.from !== 'the-eye' && (ed.hasText(e.title) || ed.hasText(e.body) || ed.hasText(e.takeaway)))
        .sort((a, b) => (b.date || '').localeCompare(a.date || ''))
        .slice(0, 5);
      if (!notes.length) return;
      box.innerHTML = '<p class="team-question">Notes in Overthoughts</p>' + notes.map(e => `
        <a class="past-lesson past-lesson-link" href="${ed.escapeHtml(D.notebookUrl('overthoughts', { entry: e.id }) || '#')}">
          <span class="past-lesson-head">${ed.escapeHtml(ed.hasText(e.title) ? e.title.trim() : firstLine(e.body))}${e.date ? ` · ${ed.escapeHtml(ed.prettyDate(e.date))}` : ''}</span>
          ${ed.hasText(e.takeaway) ? `<span class="past-lesson-text">${ed.escapeHtml(e.takeaway.trim())}</span>` : ''}
        </a>`).join('');
      box.hidden = false;
    }).catch(() => {});
  }

  function renderTalents() {
    ed.updateShootRunningHead();
    ed.renderPastLessons();
    const container = document.getElementById('talentsList');
    container.innerHTML = ed.currentTalents.map((talent, idx) => {
      const handles = (talent.socialHandles || []).filter(sh => ed.hasText(sh.handle));
      return `
      <div class="team-member-card talent-summary-card" data-idx="${idx}">
        <div class="talent-summary-heading">
          ${talent.photo ? `<img src="${talent.photo}" alt="" class="talent-summary-photo" />` : ''}
          <span class="talent-summary-name">${ed.escapeHtml(ed.hasText(talent.name) ? talent.name : `Talent ${idx + 1}`)}</span>
        </div>
        ${handles.length ? `
          <div class="talent-summary-handles">
            ${handles.map(sh => {
              const entry = ed.SOCIAL_PLATFORM_OPTIONS.find(([val]) => val === sh.platform);
              return `<span>${ed.escapeHtml(entry ? entry[1] : 'Other')}: ${ed.escapeHtml(sh.handle)}</span>`;
            }).join('')}
          </div>
        ` : ''}
        <button type="button" class="talent-summary-delete" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
      </div>
    `;
    }).join('');

    // The whole card is the "edit" affordance now — no separate button needed.
    container.querySelectorAll('.talent-summary-card').forEach(card => {
      card.addEventListener('click', () => ed.openTalentModal(Number(card.dataset.idx)));
    });
    container.querySelectorAll('.talent-summary-delete').forEach(btn => {
      btn.addEventListener('click', async (ev) => {
        // The card itself opens the edit popup, so the delete "x" has to stop
        // the click here or it also reopens a popup for the talent it just removed.
        // Stopped before the await below, while the click is still on its way.
        ev.stopPropagation();
        const idx = Number(btn.dataset.idx);
        const talent = ed.currentTalents[idx];
        if (!talent) return;
        const shootId = ed.currentShootId;
        // Removing a talent also throws away their handles and photo, so it
        // asks first rather than vanishing on a mis-tap.
        const who = ed.hasText(talent.name) ? talent.name.trim() : `Talent ${idx + 1}`;
        const ok = await ed.askConfirm({
          title: `Remove ${who} from this shoot?`,
          text: 'Their handles and photo will be removed too.',
          confirmLabel: 'Remove',
          cancelLabel: 'Keep them',
          danger: true,
        });
        if (!ok || ed.currentShootId !== shootId) return;
        // Found again by the talent itself, in case the list moved meanwhile.
        const at = ed.currentTalents.indexOf(talent);
        if (at === -1) return;
        if (ed.currentShootId && talent.id) ed.idbDeleteImages(ed.talentPhotoKey(ed.currentShootId, talent.id)).catch(() => {});
        ed.currentTalents.splice(at, 1);
        renderTalents();
        ed.scheduleShootAutosave();
      });
    });
  }

  document.getElementById('addTalentBtn').addEventListener('click', () => ed.openTalentModal(null));
};
;

// ---- pages/shoot/past-talents.js ----
// Past talents: the list to pick from, and Manage talents.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootPastTalents = function addShootPastTalents(ed) {
  Object.assign(ed, { refreshPastTalentsSelect });
  // ---------- Talent popup (name/handles/photo + a "returning talent" picker) ----------
  // talentModalTargetIdx: index into currentTalents being edited, or null
  // while adding a new one. talentModalDraft holds the in-progress edits —
  // nothing in currentTalents changes until Save (see saveTalentModalBtn).
  ed.talentModalTargetIdx = null;
  ed.talentModalDraft = null;
  ed.pastTalentSamples = [];

  // Every distinct past talent name, ranked: talents who were the FIRST
  // (lead) name on 2+ shoots first, then talents who were lead on exactly
  // one shoot, then everyone who only ever appeared as a secondary/tertiary
  // talent — alphabetical within each tier. The sample pulled in for each
  // name (handles/photo) is whichever shoot used it most recently, same
  // "most recent wins" reasoning as getLastLocationDirections below.
  function getAllPastTalents() {
    const leadCounts = {};
    const sampleDates = {};
    const samples = {};
    const dismissed = new Set(ed.state.dismissedTalentKeys);
    ed.state.shoots.forEach(s => {
      (s.talents || []).forEach((t, i) => {
        if (!ed.hasText(t.name)) return;
        const key = t.name.trim().toLowerCase();
        if (dismissed.has(key)) return;
        if (i === 0) leadCounts[key] = (leadCounts[key] || 0) + 1;
        const d = s.date || '';
        if (!(key in sampleDates) || d > sampleDates[key]) {
          sampleDates[key] = d;
          samples[key] = t;
        }
      });
    });
    return Object.keys(samples)
      .sort((a, b) => {
        const aLead = leadCounts[a] || 0;
        const bLead = leadCounts[b] || 0;
        const tier = n => (n >= 2 ? 0 : n === 1 ? 1 : 2);
        const tierDiff = tier(aLead) - tier(bLead);
        return tierDiff || samples[a].name.localeCompare(samples[b].name);
      })
      .map(key => samples[key]);
  }

  function refreshPastTalentsSelect() {
    ed.pastTalentSamples = getAllPastTalents();
    const select = document.getElementById('pastTalentsSelect');
    select.innerHTML = '<option value="">Select a past talent…</option>'
      + ed.pastTalentSamples.map((t, i) => `<option value="${i}">${ed.escapeHtml(t.name)}</option>`).join('')
      + '<option value="__manage__">Manage saved…</option>';
  }

  document.getElementById('pastTalentsSelect').addEventListener('change', (e) => {
    if (e.target.value === '__manage__') {
      e.target.value = '';
      openManageTalentsModal();
      return;
    }
    if (e.target.value === '') return;
    const t = ed.pastTalentSamples[Number(e.target.value)];
    if (!t || !ed.talentModalDraft) return;
    ed.talentModalDraft.name = t.name || '';
    ed.talentModalDraft.socialHandles = (t.socialHandles || []).map(sh => ({ ...sh }));
    ed.talentModalDraft.photo = t.photo || '';
    // This card now shows someone else, so its own photo is replaced outright
    // (even by none) — but that's not a request to strip the photo off that
    // person's other shoots, and any earlier Remove press no longer applies.
    ed.talentModalDraft.photoRemoved = false;
    ed.talentModalDraft.photoSwapped = true;
    // Picking a returning talent links this draft to their identity (by
    // name, same matching getAllPastTalents already uses) — saveTalentModalBtn
    // uses this to propagate any edits back to every other shoot's copy of
    // the same person instead of leaving them out of sync.
    ed.talentModalDraft._matchName = t.name || '';
    ed.fillTalentModalForm();
  });

  // Same non-destructive "dismiss" pattern as Manage Locations — deleting
  // here only hides a name from future quick-picks (dismissedTalentKeys),
  // it never touches any shoot's own talents array or the profile-sync
  // matching saveTalentModalBtn does by name.
  function renderManageTalentsList() {
    const samples = getAllPastTalents();
    const container = document.getElementById('manageTalentsList');
    if (!samples.length) {
      container.innerHTML = '<p class="empty-hint">No saved talents yet.</p>';
      return;
    }
    container.innerHTML = samples.map((t, idx) => `
      <div class="manage-location-row">
        <span>${ed.escapeHtml(t.name)}</span>
        <button type="button" class="delete-manage-location" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
      </div>
    `).join('');
    container.querySelectorAll('.delete-manage-location').forEach(btn => {
      btn.addEventListener('click', () => {
        const t = samples[Number(btn.dataset.idx)];
        if (!t) return;
        const key = t.name.trim().toLowerCase();
        if (!ed.state.dismissedTalentKeys.includes(key)) ed.state.dismissedTalentKeys.push(key);
        ed.saveState();
        renderManageTalentsList();
        // The Talent modal's dropdown is still open underneath, so it has
        // to drop the deleted entry now rather than on next open.
        refreshPastTalentsSelect();
      });
    });
  }

  function openManageTalentsModal() {
    renderManageTalentsList();
    document.getElementById('manageTalentsOverlay').hidden = false;
  }
};
;

// ---- pages/shoot/talent-popup.js ----
// The talent popup: name, handles and photo.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootTalentPopup = function addShootTalentPopup(ed) {
  Object.assign(ed, { renderTalentModalPhoto, fillTalentModalForm, openTalentModal });
  function renderTalentModalHandles() {
    const container = document.getElementById('talentModalHandlesList');
    container.innerHTML = ed.talentModalDraft.socialHandles.map((sh, shIdx) => `
      <div class="social-handle-row">
        <select class="social-handle-platform" data-handle-idx="${shIdx}">
          ${ed.SOCIAL_PLATFORM_OPTIONS.map(([val, label]) => `<option value="${val}" ${sh.platform === val ? 'selected' : ''}>${label}</option>`).join('')}
        </select>
        <input type="text" class="social-handle-input" data-handle-idx="${shIdx}" placeholder="@handle" value="${ed.escapeHtml(sh.handle || '@')}" />
        <button type="button" class="delete-social-handle" data-handle-idx="${shIdx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
      </div>
    `).join('');
    container.querySelectorAll('.social-handle-platform').forEach(sel => {
      sel.addEventListener('change', () => {
        ed.talentModalDraft.socialHandles[Number(sel.dataset.handleIdx)].platform = sel.value;
      });
    });
    container.querySelectorAll('.social-handle-input').forEach(input => {
      input.addEventListener('input', () => {
        ed.talentModalDraft.socialHandles[Number(input.dataset.handleIdx)].handle = input.value;
      });
    });
    container.querySelectorAll('.delete-social-handle').forEach(btn => {
      btn.addEventListener('click', () => {
        ed.talentModalDraft.socialHandles.splice(Number(btn.dataset.handleIdx), 1);
        renderTalentModalHandles();
      });
    });
  }

  document.getElementById('talentModalAddHandleBtn').addEventListener('click', () => {
    ed.talentModalDraft.socialHandles.push({ platform: 'instagram', handle: '' });
    renderTalentModalHandles();
  });

  function renderTalentModalPhoto() {
    document.getElementById('talentModalPhotoBtn').textContent = ed.talentModalDraft.photo ? 'Change talent photo' : '+ Add talent photo';
    const wrap = document.getElementById('talentModalPhotoWrap');
    wrap.innerHTML = ed.talentModalDraft.photo ? `
      <div class="talent-photo-wrap">
        <div class="moodboard-thumb talent-photo-thumb">
          <img src="${ed.talentModalDraft.photo}" alt="" id="talentModalPhotoImg" />
        </div>
        <button type="button" class="manage-link" id="talentModalPhotoRemoveBtn">Remove photo</button>
      </div>
    ` : '';
    const img = document.getElementById('talentModalPhotoImg');
    if (img) img.addEventListener('click', () => ed.openImageViewer([{ src: ed.talentModalDraft.photo, caption: '' }], 0, null, null, false));
    const removeBtn = document.getElementById('talentModalPhotoRemoveBtn');
    if (removeBtn) removeBtn.addEventListener('click', () => {
      ed.talentModalDraft.photo = '';
      // The one thing that means "this person has no photo now" — a draft that
      // merely doesn't have one (never added, or not loaded yet) must not be
      // taken for it (see saveTalentModalBtn).
      ed.talentModalDraft.photoRemoved = true;
      renderTalentModalPhoto();
    });
  }

  document.getElementById('talentModalPhotoBtn').addEventListener('click', () => {
    document.getElementById('talentPhotoFileInput').click();
  });

  document.getElementById('talentPhotoFileInput').addEventListener('change', (e) => {
    const file = e.target.files[0];
    e.target.value = '';
    if (!file || !ed.talentModalDraft) return;
    ed.resizeImageFile(file, 1280, 0.72).then(dataUrl => {
      ed.openProjectPhotoCrop(dataUrl, 'talent');
    }).catch(() => {});
  });

  function fillTalentModalForm() {
    document.getElementById('talentModalNameInput').value = ed.talentModalDraft.name || '';
    renderTalentModalHandles();
    renderTalentModalPhoto();
  }

  function openTalentModal(idx) {
    ed.talentModalTargetIdx = (idx === null || idx === undefined) ? null : idx;
    const existing = ed.talentModalTargetIdx !== null ? ed.currentTalents[ed.talentModalTargetIdx] : null;
    ed.talentModalDraft = existing
      ? { id: existing.id, name: existing.name || '', socialHandles: (existing.socialHandles || []).map(sh => ({ ...sh })), photo: existing.photo || '' }
      : { id: ed.uid(), name: '', socialHandles: [], photo: '' };
    // Editing someone already named (whether typed fresh earlier or picked
    // from "returning talent" on a past visit) still counts as their
    // identity — an edit here should propagate to their other shoots too,
    // not just to picks made in this exact session. See saveTalentModalBtn.
    ed.talentModalDraft._matchName = ed.talentModalDraft.name || '';
    ed.refreshPastTalentsSelect();
    fillTalentModalForm();
    document.getElementById('talentModalOverlay').hidden = false;
  }

  document.getElementById('talentModalNameInput').addEventListener('input', (e) => {
    ed.talentModalDraft.name = e.target.value;
  });

  document.getElementById('saveTalentModalBtn').addEventListener('click', () => {
    const draft = ed.talentModalDraft;
    draft.name = document.getElementById('talentModalNameInput').value.trim();
    draft.socialHandles = draft.socialHandles.map(sh => ({ ...sh, handle: ed.normalizeSocialHandle(sh.handle) }));
    const oldPhoto = ed.talentModalTargetIdx !== null ? (ed.currentTalents[ed.talentModalTargetIdx].photo || '') : '';
    const photoRemoved = !!draft.photoRemoved;
    const photoSwapped = !!draft.photoSwapped;
    delete draft.photoRemoved;
    delete draft.photoSwapped;
    // A draft with no photo only means "no photo" if the user said so (Remove,
    // or picking a different person). Otherwise it's empty because the photo
    // simply hadn't reached memory when the popup opened, and saving it must
    // not turn that into a deletion.
    if (!draft.photo && oldPhoto && !photoRemoved && !photoSwapped) draft.photo = oldPhoto;

    if (ed.talentModalTargetIdx !== null) ed.currentTalents[ed.talentModalTargetIdx] = draft;
    else ed.currentTalents.push(draft);

    if (ed.currentShootId) {
      if (draft.photo) ed.savePhotoToIdb(ed.talentPhotoKey(ed.currentShootId, draft.id), draft.photo).catch(() => {});
      else if (oldPhoto) ed.idbDeleteImages(ed.talentPhotoKey(ed.currentShootId, draft.id)).catch(() => {});
    }
    // With no mood board or final images yet, nothing has claimed the cover
    // (those paths auto-set it from their first photo) — so a talent photo
    // becomes the shoot's cover rather than leaving the bubble blank. Both
    // boxes are 4:5, so it drops in without any odd object-fit cropping.
    if (draft.photo && !ed.pendingProjectPhoto) {
      ed.pendingProjectPhoto = draft.photo;
      const coverShootId = ed.currentShootId;
      if (coverShootId) {
        ed.savePhotoToIdb(ed.projectPhotoKey(coverShootId), draft.photo).catch(() => {})
          .then(() => ed.onShootImagesChanged(coverShootId, { cover: true }));
      }
    }

    // A talent picked from "returning talent" (or reopened from a card that
    // was itself picked that way once) is the same person everywhere they
    // appear — a handle added, a photo added, or a name fixed here should
    // update every other shoot's copy too, rather than leaving those behind
    // as stale duplicates of who they used to be. Matched by name, same as
    // getAllPastTalents groups them; matches on THIS shoot are left alone
    // since the block above already wrote the one being edited.
    const matchName = (draft._matchName || '').trim().toLowerCase();
    delete draft._matchName;
    if (matchName) {
      ed.state.shoots.forEach(s => {
        if (s.id === ed.currentShootId) return;
        (s.talents || []).forEach(t => {
          if ((t.name || '').trim().toLowerCase() !== matchName) return;
          const oldTalentPhoto = t.photo || '';
          t.name = draft.name;
          t.socialHandles = draft.socialHandles.map(sh => ({ ...sh }));
          if (draft.photo) {
            t.photo = draft.photo;
            ed.savePhotoToIdb(ed.talentPhotoKey(s.id, t.id), draft.photo).catch(() => {});
          } else if (photoRemoved) {
            t.photo = '';
            if (oldTalentPhoto) ed.idbDeleteImages(ed.talentPhotoKey(s.id, t.id)).catch(() => {});
          }
          // Otherwise this copy simply has no photo to share, which says
          // nothing about the other shoots' — their photo and stored image
          // are left alone. (Saving a photo-less copy used to permanently
          // delete every other copy's photo.)
        });
      });
      // The open shoot's own copy is committed in the same save, so a
      // multi-day lead and the days following it change together — saved
      // apart, the following days would look edited by hand and stop
      // mirroring (see syncProjectMirrors).
      clearTimeout(ed.shootSaveTimer);
      if (!ed.autosaveShoot()) ed.saveState();
      ed.renderAll();
    }

    document.getElementById('talentModalOverlay').hidden = true;
    ed.talentModalDraft = null;
    ed.renderTalents();
    ed.scheduleShootAutosave();
  });
};
;

// ---- pages/shoot/team.js ----
// Team members on the shoot page.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootTeam = function addShootTeam(ed) {
  Object.assign(ed, { renderTeamMembers });
  // ---------- Team members (popup, mirrors the Talent popup pattern) ----------
  // Each member renders as a read-only summary card — role, name, and handle
  // as plain text — with the card itself reopening the same popup used to
  // add one, prefilled (see openTeamMemberModal/teamMemberModalDraft below).
  // Nothing commits to currentTeamMembers until Save is tapped.
  ed.currentTeamMembers = [];

  function renderTeamMembers() {
    const container = document.getElementById('teamMembersList');
    container.innerHTML = ed.currentTeamMembers.map((tm, idx) => {
      const roleLabel = (ed.TEAM_ROLE_OPTIONS.find(([val]) => val === tm.role) || [null, 'Other'])[1];
      const platformLabel = (ed.SOCIAL_PLATFORM_OPTIONS.find(([val]) => val === tm.socialPlatform) || [null, 'Other'])[1];
      return `
      <div class="team-member-card team-member-summary-card" data-idx="${idx}">
        <div class="talent-summary-heading">
          <span class="talent-summary-name">${ed.escapeHtml(ed.hasText(tm.name) ? tm.name : `Team member ${idx + 1}`)}</span>
        </div>
        <div class="talent-summary-handles">
          <span>${ed.escapeHtml(roleLabel)}</span>
          ${ed.hasText(tm.socialHandle) ? `<span>${ed.escapeHtml(platformLabel)}: ${ed.escapeHtml(tm.socialHandle)}</span>` : ''}
        </div>
        <button type="button" class="talent-summary-delete" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
      </div>
    `;
    }).join('');

    // The whole card is the "edit" affordance — no separate button needed.
    container.querySelectorAll('.team-member-summary-card').forEach(card => {
      card.addEventListener('click', () => ed.openTeamMemberModal(Number(card.dataset.idx)));
    });
    container.querySelectorAll('.talent-summary-delete').forEach(btn => {
      btn.addEventListener('click', (ev) => {
        // The card itself opens the edit popup, so the delete "x" has to stop
        // the click here or it also reopens a popup for the member it just removed.
        ev.stopPropagation();
        const idx = Number(btn.dataset.idx);
        const [removed] = ed.currentTeamMembers.splice(idx, 1);
        renderTeamMembers();
        ed.scheduleShootAutosave();
        // Gone straight away (no asking), with a few seconds to take it back.
        if (removed) {
          const shootId = ed.currentShootId;
          const following = ed.followingAtRemoval(shootId);
          ed.showUndoToast('Team member removed', () => ed.restoreRemovedShootItem(shootId, 'teamMembers', idx, removed, following));
        }
      });
    });
  }

  document.getElementById('addTeamMemberBtn').addEventListener('click', () => ed.openTeamMemberModal(null));
};
;

// ---- pages/shoot/team-member-popup.js ----
// The team member popup: name, role and handle, or someone from before.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootTeamMemberPopup = function addShootTeamMemberPopup(ed) {
  Object.assign(ed, { openTeamMemberModal, getTeamRequiredChoice, setTeamRequiredChoice });
  // ---------- Team member popup (name/role/handle + a "returning member" picker) ----------
  // The member being edited (null when adding one) — the member itself, not
  // its place in the list: an Undo of a removal can put someone back in
  // front of them while the popup's open, and Save must still land on them.
  let teamMemberModalTarget = null;
  let teamMemberModalDraft = null;
  let pastTeamMemberSamples = [];

  // Every distinct past team member name, ranked by how many past shoots
  // they've worked (most-used first, alphabetical within a tie) — same
  // "returning contact" idea as past locations, just counted by name
  // instead of by location key. The sample pulled in for each name is
  // whichever shoot used it most recently. A solo shoot's team list is kept
  // but hidden (see updateTeamRequiredUI), so it doesn't count here.
  function getAllPastTeamMembers() {
    const counts = {};
    const sampleDates = {};
    const samples = {};
    const dismissed = new Set(ed.state.dismissedTeamMemberKeys);
    ed.state.shoots.forEach(s => {
      if (s.teamRequired !== 'yes') return;
      (s.teamMembers || []).forEach(tm => {
        if (!ed.hasText(tm.name)) return;
        const key = tm.name.trim().toLowerCase();
        if (dismissed.has(key)) return;
        counts[key] = (counts[key] || 0) + 1;
        const d = s.date || '';
        if (!(key in sampleDates) || d > sampleDates[key]) {
          sampleDates[key] = d;
          samples[key] = tm;
        }
      });
    });
    return Object.keys(counts)
      .sort((a, b) => counts[b] - counts[a] || samples[a].name.localeCompare(samples[b].name))
      .map(key => samples[key]);
  }

  // Static option lists — populated once rather than per-render, since
  // (unlike the old inline repeater) this modal isn't rebuilt every time
  // a team member is added or edited.
  document.getElementById('teamMemberModalRoleSelect').innerHTML =
    ed.TEAM_ROLE_OPTIONS.map(([val, label]) => `<option value="${val}">${label}</option>`).join('');
  document.getElementById('teamMemberModalSocialPlatform').innerHTML =
    ed.SOCIAL_PLATFORM_OPTIONS.map(([val, label]) => `<option value="${val}">${label}</option>`).join('');

  function refreshPastTeamMembersSelect() {
    pastTeamMemberSamples = getAllPastTeamMembers();
    const select = document.getElementById('pastTeamMembersSelect');
    select.innerHTML = '<option value="">Select a past team member…</option>'
      + pastTeamMemberSamples.map((tm, i) => `<option value="${i}">${ed.escapeHtml(tm.name)}</option>`).join('')
      + '<option value="__manage__">Manage saved…</option>';
  }

  document.getElementById('pastTeamMembersSelect').addEventListener('change', (e) => {
    if (e.target.value === '__manage__') {
      e.target.value = '';
      openManageTeamMembersModal();
      return;
    }
    if (e.target.value === '') return;
    const tm = pastTeamMemberSamples[Number(e.target.value)];
    if (!tm || !teamMemberModalDraft) return;
    teamMemberModalDraft.role = tm.role || 'makeup_artist';
    teamMemberModalDraft.name = tm.name || '';
    teamMemberModalDraft.socialPlatform = tm.socialPlatform || 'instagram';
    teamMemberModalDraft.socialHandle = tm.socialHandle || '';
    fillTeamMemberModalForm();
  });

  // Same non-destructive "dismiss" pattern as Manage Locations — deleting
  // here only hides a name from future quick-picks (dismissedTeamMemberKeys),
  // it never touches any shoot's own teamMembers array.
  function renderManageTeamMembersList() {
    const samples = getAllPastTeamMembers();
    const container = document.getElementById('manageTeamMembersList');
    if (!samples.length) {
      container.innerHTML = '<p class="empty-hint">No saved team members yet.</p>';
      return;
    }
    container.innerHTML = samples.map((tm, idx) => `
      <div class="manage-location-row">
        <span>${ed.escapeHtml(tm.name)}</span>
        <button type="button" class="delete-manage-location" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
      </div>
    `).join('');
    container.querySelectorAll('.delete-manage-location').forEach(btn => {
      btn.addEventListener('click', () => {
        const tm = samples[Number(btn.dataset.idx)];
        if (!tm) return;
        const key = tm.name.trim().toLowerCase();
        if (!ed.state.dismissedTeamMemberKeys.includes(key)) ed.state.dismissedTeamMemberKeys.push(key);
        ed.saveState();
        renderManageTeamMembersList();
        // The Team member modal's dropdown is still open underneath, so it
        // has to drop the deleted entry now rather than on next open.
        refreshPastTeamMembersSelect();
      });
    });
  }

  function openManageTeamMembersModal() {
    renderManageTeamMembersList();
    document.getElementById('manageTeamMembersOverlay').hidden = false;
  }

  function fillTeamMemberModalForm() {
    document.getElementById('teamMemberModalRoleSelect').value = teamMemberModalDraft.role || 'makeup_artist';
    document.getElementById('teamMemberModalNameInput').value = teamMemberModalDraft.name || '';
    document.getElementById('teamMemberModalSocialPlatform').value = teamMemberModalDraft.socialPlatform || 'instagram';
    document.getElementById('teamMemberModalSocialInput').value = teamMemberModalDraft.socialHandle || '@';
  }

  function openTeamMemberModal(idx) {
    const existing = (idx === null || idx === undefined) ? null : (ed.currentTeamMembers[idx] || null);
    teamMemberModalTarget = existing;
    teamMemberModalDraft = existing
      ? { ...existing }
      : { role: 'makeup_artist', name: '', socialPlatform: 'instagram', socialHandle: '' };
    refreshPastTeamMembersSelect();
    fillTeamMemberModalForm();
    document.getElementById('teamMemberModalOverlay').hidden = false;
  }

  document.getElementById('teamMemberModalRoleSelect').addEventListener('change', (e) => {
    teamMemberModalDraft.role = e.target.value;
  });

  document.getElementById('teamMemberModalNameInput').addEventListener('input', (e) => {
    teamMemberModalDraft.name = e.target.value;
  });

  // Same auto-fill as before the popup redesign: leaving the name field
  // having typed a known contact's name fills in whatever handle was saved
  // for them last time, unless one's already been typed here.
  document.getElementById('teamMemberModalNameInput').addEventListener('blur', () => {
    const draft = teamMemberModalDraft;
    if (!draft || ed.hasText(draft.socialHandle)) return;
    const match = ed.lookupBestContactHandle(draft.name);
    if (!match) return;
    draft.socialPlatform = match.platform;
    draft.socialHandle = match.handle;
    fillTeamMemberModalForm();
  });

  document.getElementById('teamMemberModalSocialPlatform').addEventListener('change', (e) => {
    teamMemberModalDraft.socialPlatform = e.target.value;
  });

  document.getElementById('teamMemberModalSocialInput').addEventListener('input', (e) => {
    teamMemberModalDraft.socialHandle = e.target.value;
  });

  document.getElementById('saveTeamMemberModalBtn').addEventListener('click', () => {
    const draft = teamMemberModalDraft;
    draft.name = document.getElementById('teamMemberModalNameInput').value.trim();
    draft.socialHandle = ed.normalizeSocialHandle(draft.socialHandle);

    // Found again by the member itself, in case the list moved meanwhile.
    const at = teamMemberModalTarget ? ed.currentTeamMembers.indexOf(teamMemberModalTarget) : -1;
    if (at !== -1) ed.currentTeamMembers[at] = draft;
    else ed.currentTeamMembers.push(draft);

    document.getElementById('teamMemberModalOverlay').hidden = true;
    teamMemberModalDraft = null;
    teamMemberModalTarget = null;
    ed.renderTeamMembers();
    ed.scheduleShootAutosave();
  });

  // "Requires team?" is two named buttons, "Just me" / "With a team", rather
  // than a pair of Yes/No tick boxes. The answer is still saved as
  // teamRequired 'no'/'yes' ('' while neither's been picked), read straight
  // off whichever button is showing as picked.
  const TEAM_REQUIRED_CHOICES = [['teamRequiredNoBtn', 'no'], ['teamRequiredYesBtn', 'yes']];

  function getTeamRequiredChoice() {
    const picked = TEAM_REQUIRED_CHOICES.find(([id]) => document.getElementById(id).classList.contains('active'));
    return picked ? picked[1] : '';
  }

  function setTeamRequiredChoice(value) {
    TEAM_REQUIRED_CHOICES.forEach(([id, choice]) => {
      const btn = document.getElementById(id);
      btn.classList.toggle('active', value === choice);
      btn.setAttribute('aria-pressed', value === choice ? 'true' : 'false');
    });
    updateTeamRequiredUI();
  }

  // Switching to "Just me" only HIDES the team list and Directions for team —
  // both are kept, and come straight back with "With a team". Everything that
  // shows or counts a team (PDFs, Stats, Pending labels...) checks
  // teamRequired === 'yes' for the same reason, and directionFieldApplies
  // leaves Directions for team out of Shoot mode and the PDFs on a solo shoot.
  function updateTeamRequiredUI() {
    const choice = getTeamRequiredChoice();
    document.getElementById('teamDetailsBlock').hidden = choice !== 'yes';
    document.getElementById('teamFinalizedNote').hidden = choice !== 'no';
    const directionsField = document.getElementById('shootTeamDirectionsField');
    directionsField.hidden = choice === 'no';
    // Back from "Just me": the kept directions were last measured while
    // hidden (zero height), so they're sized to their text again now.
    if (!directionsField.hidden) ed.syncFieldFilledState(document.getElementById('shootTeamDirections'));
  }

  // Buttons fire no input/change event of their own, so each saves itself
  // (scheduleShootAutosave also refreshes the new-shoot guide, whose Team
  // slide borrows this whole block). Tapping the one already picked keeps it.
  TEAM_REQUIRED_CHOICES.forEach(([id, choice]) => {
    document.getElementById(id).addEventListener('click', () => {
      if (getTeamRequiredChoice() === choice) return;
      setTeamRequiredChoice(choice);
      ed.scheduleShootAutosave();
    });
  });
};
;

// ---- pages/shoot/shoot-fields.js ----
// The shoot page's fields: growing text boxes, filled fields, and putting back what was removed.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootFields = function addShootFields(ed) {
  Object.assign(ed, { autoSizeTextarea, autoSizeAllListTextareas, isBoxSheddingField, syncFieldFilledState, syncAllShootFormFields, shootListScroller, restoreAfterListReorder, restoreRemovedShootItem, followingAtRemoval });
  // ---------- Shot list (checklist inside Shoot-day notes) ----------
  // Checked items stay in the underlying array in their original order —
  // renderShotList() just displays unchecked-first, checked-last, so
  // unchecking an item returns it to its original spot automatically.
  ed.currentShotList = [];

  // Shots and lighting setups read as lines of writing rather than boxes, so
  // each row is sized to exactly the text in it instead of a fixed slab of
  // empty field.
  //
  // scrollHeight is content + padding but NOT border, while `* { box-sizing:
  // border-box }` makes an assigned height cover content + padding + border.
  // Assigning scrollHeight straight across therefore lands the box short by the
  // border width and shaves the last line — so the borders get added back.
  //
  // scrollHeight is also 0 while the row is hidden (no layout), and assigning
  // that would flatten it to nothing; a zero measurement is skipped so the row
  // keeps its one-line default until something visible re-runs this.
  function autoSizeTextarea(el) {
    el.style.height = 'auto';
    if (!el.scrollHeight) return;
    const cs = getComputedStyle(el);
    const borders = parseFloat(cs.borderTopWidth) + parseFloat(cs.borderBottomWidth);
    el.style.height = (el.scrollHeight + borders) + 'px';
  }

  // #shootModeShotList included here too — openShootMode's own re-measure
  // pass calls this function expecting it to cover Shoot Mode's shot rows
  // as well as the main form's; it silently didn't, since this selector
  // never named that list, leaving a shot with wrapped text visibly
  // clipped to one line the moment you entered Shoot Mode (correcting
  // itself only once you typed in it, which re-triggers sizing via the
  // row's own input listener).
  function autoSizeAllListTextareas() {
    document.querySelectorAll('#shotListItems .shot-text, #lightingSetupsItems .lighting-setup-description, #shootModeShotList .shot-text, #shootModeShootingNotes')
      .forEach(autoSizeTextarea);
  }

  // A field with something in it should read as what you wrote, not as an input
  // still waiting for you — the same treatment the shot list got. An EMPTY field
  // keeps its box, because the box is the thing that says "put something here";
  // a filled one keeps a rule underneath, which is what says "tap to change it".
  //
  // Only free-text fields qualify. Date, time and select are pickers: stripping
  // their frame would read as broken rather than as written-in, and there's no
  // typing to reveal. The shot rows are skipped too — they already carry this
  // look permanently via .shot-text, and their own renderer sizes them. The
  // lighting fields (no .shot-text) do qualify, which is why their renderer
  // re-syncs them itself after rebuilding.
  function isBoxSheddingField(el) {
    if (el.classList.contains('shot-text')) return false;
    if (el.tagName === 'TEXTAREA') return true;
    return el.tagName === 'INPUT' && (!el.type || el.type === 'text');
  }

  function syncFieldFilledState(el) {
    if (!el || !el.tagName || !isBoxSheddingField(el)) return;
    const filled = !!el.value.trim();
    el.classList.toggle('is-filled', filled);
    if (el.tagName !== 'TEXTAREA') return;
    // Filled: shrink to the text, so losing the box doesn't leave a tall band of
    // empty ruled space. Empty: hand the height back to the rows attribute.
    if (filled) autoSizeTextarea(el);
    else el.style.height = '';
  }

  function syncAllShootFormFields() {
    document.querySelectorAll('#shootForm input, #shootForm textarea').forEach(syncFieldFilledState);
  }

  // What a list inside the shoot form actually scrolls in: the new-shoot
  // wizard's card body while the list is borrowed onto one of its slides
  // (see SHOOT_WIZARD_STEPS), the shoot modal itself the rest of the time.
  // Saving/restoring the modal's scroll for a list that's in the card would
  // leave the card free to lurch on every re-render.
  function shootListScroller(container) {
    return (container && container.closest('#shootWizardBody')) || ed.shootModalOverlay.querySelector('.modal');
  }

  // Ticking a checkbox re-renders its whole list, because checked items sort to
  // the bottom — which destroys the very node that was tapped. Left alone the
  // browser drops focus and the modal lurches hundreds of pixels: measured at
  // 3399 -> 2621 on a shoot with a couple of setups.
  //
  // Restoring inside the change handler isn't enough on its own — the click's
  // own default processing runs after the handler and undoes it — so the same
  // restore is repeated on the next frame, which is the first moment nothing
  // else is still touching scroll or focus. preventScroll keeps the view still
  // while focus follows the item down to its new position.
  function restoreAfterListReorder(container, checkIdx, savedScrollTop) {
    const apply = () => {
      const scroller = shootListScroller(container);
      if (scroller && savedScrollTop !== undefined) scroller.scrollTop = savedScrollTop;
      if (checkIdx === undefined) return;
      const cb = container.querySelector(`.shot-check[data-idx="${checkIdx}"]`);
      if (cb) cb.focus({ preventScroll: true });
    };
    apply();
    requestAnimationFrame(apply);
  }

  // Undo (showUndoToast) for the quick removals that don't ask first — a
  // shot, a lighting setup, a team member: the item goes back where it was.
  // While that shoot's page is open, into the page's own working list,
  // re-rendered and saved the same way the × was; otherwise (Shoot mode, or
  // the page closed within the toast's few seconds) straight into the saved
  // shoot, the way Shoot mode's own edits are, so Undo never quietly does
  // nothing. A spot past the end (the list got shorter since) is the end.
  //
  // `following` (from followingAtRemoval, for a team member or lighting
  // setup) says the shoot was a day following its project's lead when the
  // item was taken out. Those lists are mirrored, so the removal made the
  // day its own (syncProjectMirrors); taking it back puts the day back to
  // following, if it now matches the lead again (reattachDayIfMatchingLead).
  function restoreRemovedShootItem(shootId, listKey, idx, item, following) {
    if (!ed.shootModalOverlay.hidden && ed.currentShootId === shootId) {
      const [list, render] = {
        shotList: [ed.currentShotList, ed.renderShotList],
        lightingSetups: [ed.currentLightingSetups, ed.renderLightingSetups],
        teamMembers: [ed.currentTeamMembers, ed.renderTeamMembers],
      }[listKey];
      list.splice(Math.min(idx, list.length), 0, item);
      render();
      ed.scheduleShootAutosave();
      if (following) {
        // Saved straight away rather than in a moment, so the check below
        // compares the day as it now is.
        ed.saveShootNow();
        reattachDayIfMatchingLead(shootId, following);
      }
      return;
    }
    // Another shoot's page is open: it's committed first, so its own
    // pending edits count against it (and make it its own, if they do)
    // before anything below is mirrored onto it.
    const openOtherId = !ed.shootModalOverlay.hidden && ed.currentShootId ? ed.currentShootId : null;
    if (openOtherId) ed.saveShootNow();
    const shoot = ed.state.shoots.find(s => s.id === shootId);
    if (!shoot) return;
    if (!Array.isArray(shoot[listKey])) shoot[listKey] = [];
    shoot[listKey].splice(Math.min(idx, shoot[listKey].length), 0, item);
    ed.saveState();
    if (following) reattachDayIfMatchingLead(shootId, following);
    // The open page is a day following this one: the save above mirrored
    // the item back onto its saved copy, so it goes back into the page's
    // own list too, at the same spot — or the page, still showing the list
    // without it, would save that over the mirror and make the day its own.
    // Spliced in rather than the whole list reloaded, so the rest of the
    // page (folded setups, a team member popup that's open) stays as it is.
    const openDay = openOtherId && (listKey === 'lightingSetups' || listKey === 'teamMembers')
      ? ed.state.shoots.find(s => s.id === openOtherId) : null;
    const openLead = openDay && openDay.followsLead ? ed.projectLeadOf(ed.findProject(openDay.projectId)) : null;
    if (openLead && openLead.id === shootId) {
      const isSetups = listKey === 'lightingSetups';
      const working = isSetups ? ed.currentLightingSetups : ed.currentTeamMembers;
      // A copy (a setup with an id of its own, as the mirror gives it), so
      // the two days never share one object.
      working.splice(Math.min(idx, working.length), 0, isSetups ? { ...item, id: ed.uid() } : { ...item });
      // Shouldn't differ (the day matched its lead), but if it somehow
      // does, the saved list as it now stands is the one to show.
      if (ed.mirrorSignature({ ...openDay, [listKey]: working }) !== ed.mirrorSignature(openDay)) {
        working.splice(0, working.length, ...(openDay[listKey] || []).map(x => ({ ...x })));
      }
      if (isSetups) ed.renderLightingSetups(); else ed.renderTeamMembers();
      ed.scheduleShootAutosave();
    }
    if (listKey === 'shotList' && !ed.shootModeOverlay.hidden && ed.getShootModeShootId() === shootId) ed.renderShootModeShots(shoot);
    ed.renderAll();
  }

  // Taken at the moment of a quick removal, for restoreRemovedShootItem: for
  // a day of a multi-day project that's following its lead, which project
  // and when — null for anything else.
  function followingAtRemoval(shootId) {
    const s = ed.state.shoots.find(x => x.id === shootId);
    return s && s.followsLead && s.projectId ? { projectId: s.projectId, at: Date.now() } : null;
  }

  // After an Undo on a day that was following its lead when the item was
  // removed (`following`, from followingAtRemoval): if the removal made it
  // its own and it now matches the lead again, it follows again, as if the
  // removal never happened. Left as it is when it's following already, has
  // moved project, or its own or the lead's photos were changed by hand
  // since (shootImagesChangedAt) — those aren't in the signature, and the
  // day's would be replaced by the lead's next change.
  function reattachDayIfMatchingLead(shootId, following) {
    const day = ed.state.shoots.find(s => s.id === shootId);
    if (!day || day.followsLead || day.projectId !== following.projectId) return;
    const lead = ed.projectLeadOf(ed.findProject(following.projectId));
    if (!lead || lead.id === day.id) return;
    if ([day.id, lead.id].some(id => (ed.shootImagesChangedAt.get(id) || 0) >= following.at)) return;
    const sig = ed.mirrorSignature(day);
    if (sig !== ed.mirrorSignature(lead)) return;
    day.followsLead = true;
    day.mirrorSig = sig;
    ed.saveState();
    if (!ed.shootModalOverlay.hidden && ed.currentShootId === day.id) ed.updateMultiDayRow();
  }
};
;

// ---- pages/shoot/shot-list.js ----
// The shot list: its rows, stars and dragging.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootShotList = function addShootShotList(ed) {
  Object.assign(ed, { shotStarButtonHtml, toggleShotStar, renderShotList });
  // A shot's must-have star, between its text and its × on both shot lists
  // (the shoot page's and Shoot mode's): the × button's own circle, with a
  // navy star that fills yellow once the shot is a must-have. Stored as
  // `starred: true` on the item, and left off rather than false.
  function shotStarButtonHtml(item, idx) {
    return `<button type="button" class="star-shot${item.starred ? ' starred' : ''}" data-idx="${idx}" aria-label="Must-have shot" aria-pressed="${item.starred ? 'true' : 'false'}"><svg class="star-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.5l2.9 5.9 6.6 1-4.75 4.6 1.1 6.5L12 17.4l-5.85 3.1 1.1-6.5L2.5 9.4l6.6-1z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/></svg></button>`;
  }

  // Flips a shot's star in place (no re-render, so nothing jumps), and
  // returns whether it's starred now.
  function toggleShotStar(item, btn) {
    if (item.starred) delete item.starred;
    else item.starred = true;
    btn.classList.toggle('starred', !!item.starred);
    btn.setAttribute('aria-pressed', item.starred ? 'true' : 'false');
    return !!item.starred;
  }

  function renderShotList(focusIdx, refocusCheckIdx) {
    const container = document.getElementById('shotListItems');
    const scroller = ed.shootListScroller(container);
    const savedScrollTop = refocusCheckIdx === undefined || !scroller ? undefined : scroller.scrollTop;
    const indexed = ed.currentShotList.map((item, idx) => ({ ...item, idx }));
    const ordered = indexed.filter(i => !i.checked).concat(indexed.filter(i => i.checked));
    container.innerHTML = ordered.map(item => `
      <div class="shot-list-row${item.checked ? ' shot-checked' : ''}" data-idx="${item.idx}">
        <button type="button" class="shot-drag-handle" aria-label="Drag to reorder shot" tabindex="-1">&#8942;</button>
        <input type="checkbox" class="shot-check" data-idx="${item.idx}" ${item.checked ? 'checked' : ''} />
        <textarea class="shot-text" data-idx="${item.idx}" rows="1" placeholder="Describe the shot">${ed.escapeHtml(item.text || '')}</textarea>
        ${shotStarButtonHtml(item, item.idx)}
        <button type="button" class="delete-shot" data-idx="${item.idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
      </div>
    `).join('');

    // A button fires none of the form's own autosave events, so it asks.
    container.querySelectorAll('.star-shot').forEach(btn => {
      btn.addEventListener('click', () => {
        toggleShotStar(ed.currentShotList[Number(btn.dataset.idx)], btn);
        ed.scheduleShootAutosave();
      });
    });
    container.querySelectorAll('.shot-check').forEach(cb => {
      cb.addEventListener('change', () => {
        const idx = Number(cb.dataset.idx);
        ed.currentShotList[idx].checked = cb.checked;
        renderShotList(undefined, idx);
        ed.scheduleShootAutosave();
      });
    });
    container.querySelectorAll('.shot-text').forEach(textarea => {
      ed.autoSizeTextarea(textarea);
      textarea.addEventListener('input', () => {
        ed.currentShotList[Number(textarea.dataset.idx)].text = textarea.value;
        ed.autoSizeTextarea(textarea);
        ed.scheduleShootAutosave();
      });
      textarea.addEventListener('keydown', (e) => {
        if (e.key !== 'Enter') return;
        e.preventDefault();
        const idx = Number(textarea.dataset.idx);
        ed.currentShotList[idx].text = textarea.value;
        // If the row right after is already a blank one — e.g. it was just
        // created by an earlier Enter, and the user tapped back up to fix
        // something above it rather than typing into it — reuse that one
        // instead of stacking a second blank row on top of it.
        const next = ed.currentShotList[idx + 1];
        if (!next || ed.hasText(next.text)) {
          ed.currentShotList.splice(idx + 1, 0, { text: '', checked: false });
        }
        renderShotList(idx + 1);
        ed.scheduleShootAutosave();
      });
    });
    container.querySelectorAll('.delete-shot').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = Number(btn.dataset.idx);
        const [removed] = ed.currentShotList.splice(idx, 1);
        renderShotList();
        ed.scheduleShootAutosave();
        // An empty row has nothing to take back, so no toast for it.
        if (removed && ed.hasText(removed.text)) {
          const shootId = ed.currentShootId;
          ed.showUndoToast('Shot removed', () => ed.restoreRemovedShootItem(shootId, 'shotList', idx, removed));
        }
      });
    });
    container.querySelectorAll('.shot-drag-handle').forEach(handle => {
      wireShotDragHandle(handle, container);
    });

    if (focusIdx !== undefined) {
      const focusInput = container.querySelector(`.shot-text[data-idx="${focusIdx}"]`);
      if (focusInput) {
        focusInput.focus();
        // A row added via Enter can land low enough in this scrolling form
        // to come up right against the sticky Save bar fixed below it (or
        // the iOS keyboard) — the browser's own scroll-into-view-on-focus
        // doesn't know either is there and won't leave them any clearance.
        // Centering it ourselves guarantees a clear look at what's being
        // typed instead of a sliver hidden behind either one. Same fix as
        // Shoot Mode's own shot list — see renderShootModeShots.
        focusInput.scrollIntoView({ block: 'center' });
        if (window.visualViewport) {
          window.visualViewport.addEventListener(
            'resize',
            () => focusInput.scrollIntoView({ block: 'center' }),
            { once: true }
          );
        }
      }
    }
    ed.restoreAfterListReorder(container, refocusCheckIdx, savedScrollTop);
  }

  // Press-and-hold reorder for shot rows. Dragging is restricted to rows
  // within the same checked/unchecked bucket, since renderShotList always
  // displays unchecked-first/checked-last — letting a drag cross that
  // boundary would just get silently undone by the next render.
  function wireShotDragHandle(handle, container) {
    handle.addEventListener('pointerdown', (e) => {
      if (e.button !== undefined && e.button !== 0) return;
      e.preventDefault();
      const row = handle.closest('.shot-list-row');
      if (!row) return;
      const pointerId = e.pointerId;
      const bucketSelector = row.classList.contains('shot-checked')
        ? '.shot-list-row.shot-checked'
        : '.shot-list-row:not(.shot-checked)';

      // The bucket's total span stays constant for the whole drag (reordering
      // same rows doesn't change how much vertical space they occupy), so
      // these bounds are captured once, before any transform, and used to
      // keep the dragged row from drifting past its own bucket — e.g. below
      // the last shot and on top of the "+ Add shot" button.
      const bucketRects = Array.from(container.querySelectorAll(bucketSelector)).map(r => r.getBoundingClientRect());
      const bucketTop = Math.min(...bucketRects.map(r => r.top));
      const bucketBottom = Math.max(...bucketRects.map(r => r.bottom));

      let baseClientY = e.clientY;
      let baseTranslateY = 0;
      let appliedTransform = 0;
      row.classList.add('shot-dragging');
      if (navigator.vibrate) navigator.vibrate(15);
      // iOS Safari has no Vibration API at all, so this pulse is the only
      // "felt" grab feedback that actually reaches an iPhone — a quick
      // scale/color flash on the handle itself, right under the finger.
      handle.classList.add('shot-drag-pulse');
      handle.addEventListener('animationend', () => {
        handle.classList.remove('shot-drag-pulse');
      }, { once: true });
      try { handle.setPointerCapture(e.pointerId); } catch (err) { /* capture is a nice-to-have, not required */ }

      function onMove(ev) {
        if (ev.pointerId !== pointerId) return;
        const rawRect = row.getBoundingClientRect();
        const layoutTop = rawRect.top - appliedTransform;
        const rowHeight = rawRect.height;
        const minDy = bucketTop - layoutTop;
        const maxDy = (bucketBottom - rowHeight) - layoutTop;
        const proposedDy = baseTranslateY + (ev.clientY - baseClientY);
        const dy = Math.min(maxDy, Math.max(minDy, proposedDy));

        row.style.transform = `translateY(${dy}px)`;
        appliedTransform = dy;

        // A fast flick can carry the row's center past more than one
        // neighbor between two pointermove events — checking just the
        // immediate neighbor once per event let the dragged row's visual
        // position (driven directly by the finger, above) outrun its actual
        // slot in the list, landing on top of rows it hadn't swapped past
        // yet. Loop until neither neighbor qualifies, so the DOM order
        // always catches up to wherever the transform already put it.
        const before = row.getBoundingClientRect();
        let swapped = false;
        while (true) {
          const rows = Array.from(container.querySelectorAll(bucketSelector));
          const idx = rows.indexOf(row);
          const rowRect = row.getBoundingClientRect();
          const rowCenter = rowRect.top + rowRect.height / 2;
          const next = rows[idx + 1];
          const prev = rows[idx - 1];

          let neighbor = null;
          let insertBeforeRow = false;
          if (next) {
            const nextRect = next.getBoundingClientRect();
            // >= (not >): the bucket-bounds clamp above can cap the dragged
            // row's center at exactly the last slot's center, so a strict ">"
            // would make the final swap unreachable.
            if (rowCenter >= nextRect.top + nextRect.height / 2) neighbor = next;
          }
          if (!neighbor && prev) {
            const prevRect = prev.getBoundingClientRect();
            if (rowCenter <= prevRect.top + prevRect.height / 2) { neighbor = prev; insertBeforeRow = true; }
          }
          if (!neighbor) break;

          if (insertBeforeRow) container.insertBefore(row, neighbor);
          else container.insertBefore(neighbor, row);
          swapped = true;
        }
        if (!swapped) return;

        row.style.transform = 'none';
        const after = row.getBoundingClientRect();
        baseTranslateY = before.top - after.top;
        baseClientY = ev.clientY;
        row.style.transform = `translateY(${baseTranslateY}px)`;
        appliedTransform = baseTranslateY;
      }

      function onEnd(ev) {
        if (ev && ev.pointerId !== undefined && ev.pointerId !== pointerId) return;
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onEnd);
        window.removeEventListener('pointercancel', onEnd);
        row.classList.remove('shot-dragging');
        row.style.transform = '';
        const rows = Array.from(container.querySelectorAll('.shot-list-row'));
        ed.currentShotList = rows.map(r => ed.currentShotList[Number(r.dataset.idx)]);
        renderShotList();
        ed.scheduleShootAutosave();
      }

      // Listening on window (not the handle) means tracking survives even
      // if the row hits its bucket clamp and stops moving while the finger
      // keeps going — hit-testing on a now-stationary handle would miss
      // the finger and silently stop delivering events, leaving the row
      // stuck mid-drag with no pointerup ever arriving to release it.
      // setPointerCapture above is kept too, as a belt-and-suspenders
      // targeting hint, but window is what makes this actually reliable.
      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onEnd);
      window.addEventListener('pointercancel', onEnd);
    });
  }

  document.getElementById('addShotBtn').addEventListener('click', () => {
    ed.currentShotList.push({ text: '', checked: false });
    renderShotList(ed.currentShotList.length - 1);
    ed.scheduleShootAutosave();
  });
};
;

// ---- components/drag-reorder.js ----
// Dragging to reorder lists whose rows differ in height.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addDragReorder = function addDragReorder(ed) {
  Object.assign(ed, { wireRowDragReorder });
  // ---------- Drag-to-reorder for lists of rows that differ in height ----------
  // Same press-and-drag feel as the shot list, but built for rows of very
  // different heights (a collapsed lighting setup is ~46px, an open one a few
  // hundred), which the shot list's version isn't:
  //   - 'edge' crossing: the dragged row's leading edge against the
  //     neighbour's midline. Comparing centres can't reach the end slots once
  //     the clamp stops a tall row's centre short of a short neighbour's.
  //   - the scroller auto-scrolls near its visible edge, and any scroll is
  //     folded into the drag so the row stays under the finger.
  //   - the transform is re-derived right after every swap, so moving past
  //     several neighbours in one go can't over-swap.
  //   - the neighbour hops over the dragged row, so the dragged node is never
  //     detached (it keeps its pointer capture).
  //   - a drop that changes nothing commits nothing: no re-render, no save.
  const DRAG_SWAP_BIAS = 6;         // px past a neighbour's midline before a swap (stops flip-flopping at the boundary)
  const DRAG_EDGE_ZONE = 56;        // px inside the scroller's visible edge where auto-scroll starts
  const DRAG_MAX_SCROLL_STEP = 14;  // px per 16ms tick at the very edge
  const DRAG_EDGE_INTENT = 12;      // px a grab inside an edge zone must move toward that edge before it scrolls

  // opts: { container, rowSelector, draggingClass, scroll?: { el, bounds() -> {top, bottom} },
  //         onStart?(row), onCommit(rowsInNewDomOrder) }. Rows must be direct children of container.
  function wireRowDragReorder(handle, opts) {
    const { container, rowSelector, draggingClass, scroll, onStart, onCommit } = opts;
    // Android's long-press would otherwise raise a context menu and cancel the pointer mid-grab.
    handle.addEventListener('contextmenu', (e) => e.preventDefault());
    handle.addEventListener('pointerdown', (e) => {
      if (e.button !== undefined && e.button !== 0) return;
      e.preventDefault();
      const row = handle.closest(rowSelector);
      if (!row || container.querySelector('.' + draggingClass)) return; // one drag at a time
      const pointerId = e.pointerId;
      if (onStart) onStart(row); // before any measuring: it may blur a field / close a dropdown

      const startRows = Array.from(container.querySelectorAll(rowSelector));
      const startRects = startRows.map(r => r.getBoundingClientRect());
      const limitTop0 = Math.min(...startRects.map(r => r.top));
      const limitBottom0 = Math.max(...startRects.map(r => r.bottom));

      const scrollEl = scroll ? scroll.el : null;
      const scrollStart = scrollEl ? scrollEl.scrollTop : 0;
      let lastScrollTop = scrollStart;
      // Chrome's scroll anchoring can nudge scrollTop when two rows of different heights swap.
      const prevOverflowAnchor = scrollEl ? scrollEl.style.overflowAnchor : '';
      if (scrollEl) scrollEl.style.overflowAnchor = 'none';

      const startClientY = e.clientY;
      let lastClientY = e.clientY;
      let baseClientY = e.clientY;
      let baseTranslateY = 0;
      let appliedTransform = 0;
      let armed = false; // auto-scroll only once the finger has actually moved a few px
      // Each edge arms separately. A card grabbed while it's already inside an
      // edge zone (common: the first card sits right under the sticky header)
      // must not start scrolling toward that edge just because the finger
      // drifted — it arms once the finger has been clear of the zone, or has
      // deliberately moved toward the edge from where it grabbed.
      let topArmed = true;
      let bottomArmed = true;
      if (scroll) {
        const b0 = scroll.bounds();
        topArmed = e.clientY >= b0.top + DRAG_EDGE_ZONE;
        bottomArmed = e.clientY <= b0.bottom - DRAG_EDGE_ZONE;
      }

      row.classList.add(draggingClass);
      if (navigator.vibrate) navigator.vibrate(15);
      handle.classList.add('shot-drag-pulse');
      handle.addEventListener('animationend', () => handle.classList.remove('shot-drag-pulse'), { once: true });
      try { handle.setPointerCapture(pointerId); } catch (err) { /* capture is a nice-to-have, not required */ }

      function update(clientY) {
        // Anything that scrolled the scroller since the last pass (our
        // auto-scroll, a wheel, the browser) moved the row's layout slot
        // under a stationary finger: fold it into the baseline.
        if (scrollEl && scrollEl.scrollTop !== lastScrollTop) {
          baseTranslateY += scrollEl.scrollTop - lastScrollTop;
          lastScrollTop = scrollEl.scrollTop;
        }
        const scrolled = scrollEl ? scrollEl.scrollTop - scrollStart : 0;
        const raw = row.getBoundingClientRect();
        const layoutTop = raw.top - appliedTransform;
        const minDy = (limitTop0 - scrolled) - layoutTop;
        const maxDy = (limitBottom0 - scrolled - raw.height) - layoutTop;
        const dy = Math.min(maxDy, Math.max(minDy, baseTranslateY + (clientY - baseClientY)));
        row.style.transform = `translateY(${dy}px)`;
        appliedTransform = dy;

        for (let guard = 0; guard < 100; guard++) {
          const rows = Array.from(container.querySelectorAll(rowSelector));
          const i = rows.indexOf(row);
          const r = row.getBoundingClientRect();
          const next = rows[i + 1];
          const prev = rows[i - 1];
          let neighbor = null;
          let neighborIsPrev = false;
          if (next) {
            const n = next.getBoundingClientRect();
            // >= (not >): the clamp can park the leading edge exactly on the last slot's midline.
            if (r.bottom - DRAG_SWAP_BIAS >= n.top + n.height / 2) neighbor = next;
          }
          if (!neighbor && prev) {
            const pr = prev.getBoundingClientRect();
            if (r.top + DRAG_SWAP_BIAS <= pr.top + pr.height / 2) { neighbor = prev; neighborIsPrev = true; }
          }
          if (!neighbor) break;

          const visualTop = r.top;
          // Move the NEIGHBOUR over the dragged row, never the dragged row itself.
          if (neighborIsPrev) container.insertBefore(neighbor, row.nextSibling);
          else container.insertBefore(neighbor, row);
          // The swap shifted the row's layout slot; re-derive the transform
          // now so the next pass sees the row exactly where the finger left it.
          row.style.transform = 'none';
          baseTranslateY = visualTop - row.getBoundingClientRect().top;
          baseClientY = clientY;
          row.style.transform = `translateY(${baseTranslateY}px)`;
          appliedTransform = baseTranslateY;
        }
      }

      function onMove(ev) {
        if (ev.pointerId !== pointerId) return;
        lastClientY = ev.clientY;
        if (!armed && Math.abs(ev.clientY - startClientY) > 4) armed = true;
        update(ev.clientY);
      }

      // setInterval, not rAF: rAF doesn't fire in a backgrounded test tab.
      let scrollTimer = null;
      if (scrollEl) {
        scrollTimer = setInterval(() => {
          const { top, bottom } = scroll.bounds();
          if (!topArmed && (lastClientY >= top + DRAG_EDGE_ZONE || startClientY - lastClientY >= DRAG_EDGE_INTENT)) topArmed = true;
          if (!bottomArmed && (lastClientY <= bottom - DRAG_EDGE_ZONE || lastClientY - startClientY >= DRAG_EDGE_INTENT)) bottomArmed = true;
          let step = 0;
          if (armed) {
            if (topArmed && lastClientY < top + DRAG_EDGE_ZONE) {
              step = -DRAG_MAX_SCROLL_STEP * Math.min(1, (top + DRAG_EDGE_ZONE - lastClientY) / DRAG_EDGE_ZONE);
            } else if (bottomArmed && lastClientY > bottom - DRAG_EDGE_ZONE) {
              step = DRAG_MAX_SCROLL_STEP * Math.min(1, (lastClientY - (bottom - DRAG_EDGE_ZONE)) / DRAG_EDGE_ZONE);
            }
          }
          if (step) scrollEl.scrollTop += Math.sign(step) * Math.max(1, Math.round(Math.abs(step)));
          if (scrollEl.scrollTop !== lastScrollTop) update(lastClientY);
        }, 16);
      }

      function onEnd(ev) {
        if (ev && ev.pointerId !== undefined && ev.pointerId !== pointerId) return;
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onEnd);
        window.removeEventListener('pointercancel', onEnd);
        clearInterval(scrollTimer);
        row.classList.remove(draggingClass);
        row.style.transform = '';
        const endRows = Array.from(container.querySelectorAll(rowSelector));
        const changed = endRows.some((r, i) => r !== startRows[i]);
        try {
          if (changed) onCommit(endRows);
        } finally {
          if (scrollEl) scrollEl.style.overflowAnchor = prevOverflowAnchor;
        }
      }

      // window, not the handle: once the row hits its clamp it stops being
      // under the finger, and hit-testing a stationary handle would miss it.
      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onEnd);
      window.addEventListener('pointercancel', onEnd);
    });
  }
};
;

// ---- pages/shoot/lighting-suggestions.js ----
// Lighting setups: past setups suggested as you type.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootLightingSuggestions = function addShootLightingSuggestions(ed) {
  Object.assign(ed, { getPastLightingSetups, updateLightingSetupSuggestions, hasOtherShootLightingSetups, setLightingBrowseExpanded, toggleLightingBrowse, hideLightingSuggestionBox });
  // ---------- Lighting setups (nested bubble cards, in Visuals) ----------
  // Collapsible outlined card per setup (same visual pattern Talent used to
  // use before its own popup redesign) instead of the old single-field
  // checklist — each setup gets a name (the card's heading), plus
  // characteristics and a longer description.
  ed.currentLightingSetups = [];

  // Grouped by name across every shoot's lightingSetups, most-recent shoot's
  // version winning ties — same "most recent wins" shape as
  // getAllPastTalents/getLastLocationDirections, just without lead-count
  // tiering since setups aren't ranked, only deduped. `excludeId` leaves one
  // setup out BEFORE the grouping (a card's own, see
  // updateLightingSetupSuggestions), so a same-named setup from another shoot
  // still gets listed instead of losing to the card's own newer copy.
  function getPastLightingSetups(excludeId) {
    const sampleDates = {};
    const samples = {};
    const dismissed = new Set(ed.state.dismissedLightingSetupKeys);
    ed.state.shoots.forEach(s => {
      (s.lightingSetups || []).forEach(item => {
        if (!ed.hasText(item.name)) return;
        if (excludeId && item.id === excludeId) return;
        const key = item.name.trim().toLowerCase();
        if (dismissed.has(key)) return;
        const d = s.date || '';
        if (!(key in sampleDates) || d > sampleDates[key]) {
          sampleDates[key] = d;
          samples[key] = item;
        }
      });
    });
    return Object.keys(samples)
      .sort((a, b) => samples[a].name.localeCompare(samples[b].name))
      .map(key => samples[key]);
  }

  // Typing (or just tapping into) a setup's name shows past setups sharing
  // this shoot's Visuals-section styling as a dropdown under the field —
  // picking one COPIES its name/characteristics/description in, a one-time
  // fill rather than the Talent popup's ongoing cross-shoot sync. Lighting
  // setups are far more likely than a person's identity to legitimately
  // vary shoot to shoot under the same name (a different room, different
  // gear), so silently keeping every past "Rembrandt lighting" in sync
  // would rewrite descriptions the user never touched. Returns whether the
  // dropdown ended up open (there was something to show). `browseAll` lists
  // every saved setup whatever the name says (the guide's chevron).
  function updateLightingSetupSuggestions(idx, input, browseAll = false) {
    const wrap = input.closest('.lighting-setup-name-wrap');
    const box = wrap.querySelector('.lighting-setup-suggestions');
    const card = input.closest('.lighting-setup-card');
    const query = browseAll ? '' : input.value.trim().toLowerCase();
    // Its own id left out: autosave can land mid-typing, which briefly puts
    // THIS setup's own in-progress name into state.shoots — it would then
    // suggest itself back to whoever's still typing it.
    const matches = getPastLightingSetups(ed.currentLightingSetups[idx].id)
      .filter(item => !query || item.name.toLowerCase().includes(query));
    if (!matches.length) {
      box.hidden = true;
      card.classList.remove('lighting-setup-suggestions-open');
      setLightingBrowseExpanded(card, false);
      return false;
    }
    // Manage leads the list, and every match is listed (the box scrolls past
    // its max-height) rather than a capped handful with Manage buried last.
    box.innerHTML = '<button type="button" class="lighting-setup-suggestion lighting-setup-suggestion-manage">Manage saved…</button>'
      + matches.map((item, i) => `
      <button type="button" class="lighting-setup-suggestion" data-idx="${idx}" data-match="${i}">${ed.escapeHtml(item.name)}</button>
    `).join('');
    box.querySelectorAll('.lighting-setup-suggestion:not(.lighting-setup-suggestion-manage)').forEach((btn, i) => {
      // mousedown (not click) fires before the field's blur, so the copy
      // lands before blur's own handler hides this dropdown out from
      // under it — preventDefault keeps focus on the field throughout.
      const pick = () => {
        const picked = matches[i];
        ed.currentLightingSetups[idx].name = picked.name || '';
        ed.currentLightingSetups[idx].characteristics = picked.characteristics || '';
        ed.currentLightingSetups[idx].description = picked.description || '';
        ed.renderLightingSetups();
        ed.scheduleShootAutosave();
      };
      btn.addEventListener('mousedown', (e) => {
        e.preventDefault();
        pick();
      });
      // Enter/Space on a row reached with Tab — the guide's keyboard-free
      // list stays open without its field focused — is a click with
      // detail 0. Taps and mouse clicks already picked on mousedown.
      btn.addEventListener('click', (e) => { if (e.detail === 0) pick(); });
    });
    const manageBtn = box.querySelector('.lighting-setup-suggestion-manage');
    const openManage = () => {
      // From a list with nobody typing in its name (the guide's keyboard-
      // free one), the list comes back when Manage closes (see below).
      manageLightingReturn = document.activeElement === input ? null : input;
      ed.openManageLightingSetupsModal();
    };
    manageBtn.addEventListener('mousedown', (e) => {
      e.preventDefault();
      openManage();
    });
    manageBtn.addEventListener('click', (e) => { if (e.detail === 0) openManage(); });
    box.hidden = false;
    card.classList.add('lighting-setup-suggestions-open');
    setLightingBrowseExpanded(card, true);
    return true;
  }

  // Setups saved on OTHER shoots: what the guide's keyboard-free list is
  // for. This shoot's own cards land in state.shoots too once autosave runs,
  // and on a multi-day shoot the days following it get copies of them (see
  // syncProjectMirrors), so counting either would flip + Add's behavior a
  // couple of seconds into typing the first setup.
  function hasOtherShootLightingSetups() {
    const mine = new Set([ed.currentShootId]);
    const me = ed.state.shoots.find(s => s.id === ed.currentShootId);
    const project = (me && me.projectId && ed.findProject(me.projectId))
      || (ed.state.projects || []).find(p => p.leadShootId === ed.currentShootId);
    const lead = ed.projectLeadOf(project);
    if (lead && (lead.id === ed.currentShootId || (me && me.followsLead))) {
      mine.add(lead.id);
      ed.projectFollowers(project, lead).forEach(day => mine.add(day.id));
    }
    const dismissed = new Set(ed.state.dismissedLightingSetupKeys);
    return ed.state.shoots.some(s => !mine.has(s.id) && (s.lightingSetups || [])
      .some(item => ed.hasText(item.name) && !dismissed.has(item.name.trim().toLowerCase())));
  }

  function setLightingBrowseExpanded(card, open) {
    const toggle = card && card.querySelector('.lighting-setup-browse-toggle');
    if (toggle) toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  }

  // On the guide each card's bar has a chevron (where the page has its fold
  // arrow) that shows the saved list without the keyboard: after a stray
  // tap closed it, or to swap a picked setup for another. Tapped while any
  // field is being typed in, it puts the keyboard away (iOS doesn't blur a
  // field when a button's tapped; the blur also closes another card's list)
  // and lists them all.
  function toggleLightingBrowse(btn) {
    const card = btn.closest('.lighting-setup-card');
    const input = card.querySelector('.lighting-setup-name');
    const box = card.querySelector('.lighting-setup-suggestions');
    if (!box.hidden && document.activeElement !== input) {
      hideLightingSuggestionBox(box);
      return;
    }
    const active = document.activeElement;
    if (active && active.matches('input, textarea, select')) active.blur();
    updateLightingSetupSuggestions(Number(input.dataset.idx), input, true);
  }

  function syncLightingBrowseToggles() {
    const show = hasOtherShootLightingSetups();
    document.querySelectorAll('#lightingSetupsItems .lighting-setup-browse-toggle').forEach(btn => { btn.hidden = !show; });
  }

  // On the new-shoot guide the saved list opens without its name field
  // being focused (the + Add handler, the chevron), so there's no blur to
  // close it: a tap anywhere outside that card's bar and its list does.
  // Only a real tap: a drag that scrolls the slide leaves it open (touch
  // scrolling sends pointercancel; a mouse drag moves too far), and so does
  // a touch that just stops a flick's glide (iOS sends no pointercancel for
  // that, but the slide was still scrolling a moment before). Taps in the
  // Manage popup opened from the list don't count either. A list whose own
  // field has focus is left to that field's blur, as before.
  let lightingTapOutside = null;
  ed.lastScrollAt = 0;
  document.addEventListener('scroll', () => { ed.lastScrollAt = performance.now(); }, { capture: true, passive: true });
  function unfocusedLightingSuggestions() {
    return [...document.querySelectorAll('#lightingSetupsItems .lighting-setup-suggestions:not([hidden])')]
      .filter(box => document.activeElement !== box.closest('.lighting-setup-name-wrap').querySelector('.lighting-setup-name'));
  }
  function hideLightingSuggestionBox(box) {
    box.hidden = true;
    const card = box.closest('.lighting-setup-card');
    if (card) {
      card.classList.remove('lighting-setup-suggestions-open');
      setLightingBrowseExpanded(card, false);
    }
  }
  document.addEventListener('pointerdown', (e) => {
    lightingTapOutside = null;
    if (!(e.target instanceof Element) || performance.now() - ed.lastScrollAt < 150 || e.target.closest('#manageLightingSetupsOverlay')) return;
    const boxes = unfocusedLightingSuggestions().filter(box => !box.closest('.lighting-setup-card-bar').contains(e.target));
    if (boxes.length) lightingTapOutside = { boxes, x: e.clientX, y: e.clientY };
  }, true);
  document.addEventListener('pointercancel', () => { lightingTapOutside = null; }, true);
  document.addEventListener('pointerup', (e) => {
    const tap = lightingTapOutside;
    lightingTapOutside = null;
    if (tap && Math.hypot(e.clientX - tap.x, e.clientY - tap.y) < 10) tap.boxes.forEach(hideLightingSuggestionBox);
  }, true);
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') unfocusedLightingSuggestions().forEach(hideLightingSuggestionBox);
  });

  // The name field of the keyboard-free list Manage was opened from (set by
  // its "Manage saved…" row). Every way of closing Manage just hides it, so
  // that's watched: the list comes back, freshly built, unless the card's
  // gone or a field is being typed in by then. The chevrons are re-checked
  // too, in case every saved setup was just removed.
  let manageLightingReturn = null;
  new MutationObserver(() => {
    if (!document.getElementById('manageLightingSetupsOverlay').hidden) return;
    const input = manageLightingReturn;
    manageLightingReturn = null;
    syncLightingBrowseToggles();
    const active = document.activeElement;
    if (input && input.isConnected && !(active && active.matches('input, textarea, select'))) {
      updateLightingSetupSuggestions(Number(input.dataset.idx), input, true);
    }
  }).observe(document.getElementById('manageLightingSetupsOverlay'), { attributes: true, attributeFilter: ['hidden'] });
};
;

// ---- pages/shoot/lighting.js ----
// Lighting setups: Manage, dragging, and the cards themselves.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootLighting = function addShootLighting(ed) {
  Object.assign(ed, { openManageLightingSetupsModal, renderLightingSetups });
  // Same non-destructive "dismiss" pattern as Manage Locations — deleting
  // here only hides a name from future suggestions (dismissedLightingSetup-
  // Keys), it never touches any shoot's own lightingSetups array.
  function renderManageLightingSetupsList() {
    const samples = ed.getPastLightingSetups();
    const container = document.getElementById('manageLightingSetupsList');
    if (!samples.length) {
      container.innerHTML = '<p class="empty-hint">No saved lighting setups yet.</p>';
      return;
    }
    container.innerHTML = samples.map((item, idx) => `
      <div class="manage-location-row">
        <span>${ed.escapeHtml(item.name)}</span>
        <button type="button" class="delete-manage-location" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
      </div>
    `).join('');
    container.querySelectorAll('.delete-manage-location').forEach(btn => {
      btn.addEventListener('click', () => {
        const item = samples[Number(btn.dataset.idx)];
        if (!item) return;
        const key = item.name.trim().toLowerCase();
        if (!ed.state.dismissedLightingSetupKeys.includes(key)) ed.state.dismissedLightingSetupKeys.push(key);
        ed.saveState();
        renderManageLightingSetupsList();
        // Unlike the other three "manage saved" lists, this one opens from a
        // dropdown rather than a persistent select still sitting open behind
        // it — and that dropdown is still showing whatever it last rendered,
        // dismissed entry and all (a typeahead's field never lost focus, see
        // updateLightingSetupSuggestions' preventDefault; the guide's
        // keyboard-free list has no field focused at all). Hiding it here
        // avoids a stale delete offer; it rebuilds on the field's next
        // input/focus, or when Manage closes for the keyboard-free one.
        document.querySelectorAll('#lightingSetupsItems .lighting-setup-suggestions').forEach(ed.hideLightingSuggestionBox);
      });
    });
  }

  function openManageLightingSetupsModal() {
    renderManageLightingSetupsList();
    document.getElementById('manageLightingSetupsOverlay').hidden = false;
  }

  function closeLightingSuggestions() {
    document.querySelectorAll('#lightingSetupsItems .lighting-setup-suggestions').forEach(box => { box.hidden = true; });
    document.querySelectorAll('#lightingSetupsItems .lighting-setup-suggestions-open')
      .forEach(card => card.classList.remove('lighting-setup-suggestions-open'));
    document.querySelectorAll('#lightingSetupsItems .lighting-setup-card').forEach(card => ed.setLightingBrowseExpanded(card, false));
  }

  // The part of the modal a dragged card can actually be seen in: below the
  // sticky header, above the sticky Save bar, and above the iOS keyboard.
  function lightingDragScrollBounds(modalEl) {
    const m = modalEl.getBoundingClientRect();
    const header = modalEl.querySelector('.shoot-modal-header');
    const actions = modalEl.querySelector('.modal-actions');
    const vv = window.visualViewport;
    return {
      top: Math.max(m.top, header ? header.getBoundingClientRect().bottom : m.top),
      bottom: Math.min(m.bottom, actions && actions.offsetParent ? actions.getBoundingClientRect().top : m.bottom, vv ? vv.offsetTop + vv.height : m.bottom),
    };
  }

  // The same, for a lighting list borrowed onto a new-shoot wizard slide:
  // the card body's own visible box, still capped above the iOS keyboard.
  function wizardBodyDragBounds(body) {
    const r = body.getBoundingClientRect();
    const vv = window.visualViewport;
    return {
      top: r.top,
      bottom: Math.min(r.bottom, vv ? vv.offsetTop + vv.height : r.bottom),
    };
  }

  function commitLightingReorder(cards) {
    // The modal was closed mid-drag: closeShootModal already saved the old order.
    if (ed.shootModalOverlay.hidden) return;
    const container = document.getElementById('lightingSetupsItems');
    const scroller = ed.shootListScroller(container);
    const savedScrollTop = scroller ? scroller.scrollTop : undefined;
    // Each card's data-idx is its PRE-drag index (renderLightingSetups stamps
    // it), so DOM order maps straight back onto the array. The SAME setup
    // objects are reused, so every id (and the collapsed state keyed by it)
    // follows its card.
    const reordered = cards.map(c => ed.currentLightingSetups[Number(c.dataset.idx)]);
    if (reordered.length === ed.currentLightingSetups.length && reordered.every(Boolean)) {
      ed.currentLightingSetups = reordered;
      // Reordering fires no input event, so nothing else would save it.
      ed.scheduleShootAutosave();
    }
    // Renumbers data-idx and the "Setup N" placeholders, and re-binds the
    // handlers that captured their index at render time.
    renderLightingSetups();
    ed.restoreAfterListReorder(container, undefined, savedScrollTop);
  }

  function wireLightingDragHandle(handle) {
    const container = document.getElementById('lightingSetupsItems');
    const modalEl = ed.shootModalOverlay.querySelector('.modal');
    ed.wireRowDragReorder(handle, {
      container,
      rowSelector: '.lighting-setup-card',
      draggingClass: 'lighting-dragging',
      // Getters rather than fixed values: the list may be on the page
      // (scrolling in the modal, between its sticky header and Save bar) or
      // borrowed onto a new-shoot wizard slide (scrolling in the card), and
      // wireRowDragReorder reads `el` on every grab and bounds() every tick.
      // Left pointing at the modal, a drag in the card would auto-scroll the
      // covered page behind it and fold that scroll into the dragged row.
      scroll: {
        get el() { return ed.shootListScroller(container); },
        bounds: () => {
          const wizardBody = container.closest('#shootWizardBody');
          return wizardBody ? wizardBodyDragBounds(wizardBody) : lightingDragScrollBounds(modalEl);
        },
      },
      onStart: () => {
        // On iOS tapping a button never blurs a focused field, and a swap
        // would move that field mid-drag (dropping the keyboard at a random
        // moment) — so blur it now, which also hides its open suggestions.
        const active = document.activeElement;
        if (active && active !== document.body && container.contains(active)) active.blur();
        closeLightingSuggestions();
      },
      onCommit: commitLightingReorder,
    });
  }

  function renderLightingSetups() {
    const container = document.getElementById('lightingSetupsItems');
    const inWizard = !!container.closest('#shootWizard');
    // On the wizard's Lighting setups slide each card's bar has the saved-list
    // chevron (see toggleLightingBrowse), shown only when other shoots have
    // setups saved.
    const browseSaved = inWizard && ed.hasOtherShootLightingSetups();
    container.innerHTML = ed.currentLightingSetups.map((item, idx) => {
      return `
      <div class="team-member-card lighting-setup-card" data-idx="${idx}">
        <div class="lighting-setup-card-bar">
          <button type="button" class="shot-drag-handle lighting-drag-handle" aria-label="Drag to reorder lighting setup" tabindex="-1">&#8942;</button>
          <div class="lighting-setup-name-wrap">
            <input type="text" class="lighting-setup-name" data-idx="${idx}" placeholder="Setup ${idx + 1}" aria-label="Lighting setup ${idx + 1} name" value="${ed.escapeHtml(item.name || '')}" autocomplete="off" />
            <div class="lighting-setup-suggestions" hidden></div>
          </div>
          ${inWizard ? `<button type="button" class="lighting-setup-collapse-toggle lighting-setup-browse-toggle" data-idx="${idx}" aria-label="Show saved lighting setups" aria-expanded="false"${browseSaved ? '' : ' hidden'}>
            ${ed.COLLAPSE_ARROW_SVG}
          </button>` : ''}
          <button type="button" class="delete-lighting-setup" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
        </div>
        <div class="lighting-setup-card-body">
          <input type="text" class="lighting-setup-characteristics" data-idx="${idx}" placeholder="mood, quality, style, etc." aria-label="Characteristics" value="${ed.escapeHtml(item.characteristics || '')}" />
          <textarea class="lighting-setup-description" data-idx="${idx}" rows="2" placeholder="Describe the setup." aria-label="Description">${ed.escapeHtml(item.description || '')}</textarea>
        </div>
      </div>
    `;
    }).join('');

    container.querySelectorAll('.lighting-setup-description').forEach(ed.autoSizeTextarea);

    container.querySelectorAll('.lighting-setup-browse-toggle').forEach(btn => {
      btn.addEventListener('click', () => ed.toggleLightingBrowse(btn));
    });
    container.querySelectorAll('.delete-lighting-setup').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = Number(btn.dataset.idx);
        const [removed] = ed.currentLightingSetups.splice(idx, 1);
        renderLightingSetups();
        ed.scheduleShootAutosave();
        // Same as a shot: a never-filled-in card has nothing to take back.
        if (removed && (ed.hasText(removed.name) || ed.hasText(removed.characteristics) || ed.hasText(removed.description))) {
          const shootId = ed.currentShootId;
          const following = ed.followingAtRemoval(shootId);
          ed.showUndoToast('Lighting setup removed', () => ed.restoreRemovedShootItem(shootId, 'lightingSetups', idx, removed, following));
        }
      });
    });
    container.querySelectorAll('.lighting-setup-name').forEach(input => {
      const idx = Number(input.dataset.idx);
      input.addEventListener('input', () => {
        ed.currentLightingSetups[idx].name = input.value;
        ed.updateLightingSetupSuggestions(idx, input);
      });
      // Focusing an empty field browses every past setup, same as tapping
      // open the Returning talent/team-member select — you shouldn't have
      // to already remember a name to find it.
      input.addEventListener('focus', () => ed.updateLightingSetupSuggestions(idx, input));
      input.addEventListener('blur', () => {
        input.closest('.lighting-setup-name-wrap').querySelector('.lighting-setup-suggestions').hidden = true;
        input.closest('.lighting-setup-card').classList.remove('lighting-setup-suggestions-open');
        ed.setLightingBrowseExpanded(input.closest('.lighting-setup-card'), false);
      });
      input.addEventListener('keydown', (e) => {
        if (e.key !== 'Enter') return;
        e.preventDefault();
        input.blur();
      });
    });
    container.querySelectorAll('.lighting-setup-characteristics').forEach(input => {
      input.addEventListener('input', () => {
        ed.currentLightingSetups[Number(input.dataset.idx)].characteristics = input.value;
      });
    });
    container.querySelectorAll('.lighting-setup-description').forEach(textarea => {
      textarea.addEventListener('input', () => {
        ed.currentLightingSetups[Number(textarea.dataset.idx)].description = textarea.value;
        ed.autoSizeTextarea(textarea);
      });
    });
    container.querySelectorAll('.lighting-drag-handle').forEach(wireLightingDragHandle);
    // The fields were just rebuilt, so they have no .is-filled class until
    // something re-syncs them (renderReferences does the same) — otherwise
    // every re-render, a reorder included, made filled fields look empty.
    // Only these fields: re-measuring every textarea in the form would briefly
    // shrink the long note boxes and could clamp the modal's scroll position.
    container.querySelectorAll('input, textarea').forEach(ed.syncFieldFilledState);
  }

  document.getElementById('addLightingSetupBtn').addEventListener('click', () => {
    ed.currentLightingSetups.push({ id: ed.uid(), name: '', characteristics: '', description: '' });
    renderLightingSetups();
    // Same reasoning as +Add talent — focus the new card's name field so the
    // keyboard opens on the right box and the browser scrolls it into view.
    const cards = document.querySelectorAll('#lightingSetupsItems .lighting-setup-card');
    const newField = cards.length ? cards[cards.length - 1].querySelector('.lighting-setup-name') : null;
    if (newField && newField.closest('#shootWizard') && ed.hasOtherShootLightingSetups() && ed.updateLightingSetupSuggestions(cards.length - 1, newField)) {
      // Except on the new-shoot guide when other shoots have setups saved:
      // there the new card opens on that list with its name left unfocused,
      // so no keyboard comes up over it — picking an old setup never needs
      // one (the user's call, 2026-11-10). Tapping the name still types a
      // new one; the bar's chevron brings the list back without the
      // keyboard. The list closes on a tap outside it.
      const active = document.activeElement;
      if (active && active.matches('input, textarea, select')) active.blur();
      newField.closest('.lighting-setup-name-wrap').querySelector('.lighting-setup-suggestions')
        .scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    } else if (newField) {
      newField.scrollIntoView({ block: 'center', behavior: 'smooth' });
      newField.focus();
    }
    ed.scheduleShootAutosave();
  });
};
;

// ---- pages/shoot/location.js ----
// The location popup: name, street, city, zip and country, or a past location.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootLocation = function addShootLocation(ed) {
  Object.assign(ed, { updateLocationBtnDisplay });
  // ---------- Location (popup with name/street/city/zip/country + past locations) ----------
  ed.currentShootLocation = { name: '', street: '', city: '', state: '', zip: '', country: '' };
  ed.pastLocationSamples = [];

  function updateLocationBtnDisplay() {
    const btn = document.getElementById('shootLocationBtn');
    const loc = ed.currentShootLocation;
    // Country alone doesn't count as real content — it's just the
    // pre-filled default (see state.defaultCountry), not something the
    // user actually entered, so it shouldn't show up as a location preview.
    const hasRealContent = ed.hasText(loc.name) || ed.hasText(loc.street) || ed.hasText(loc.city) || ed.hasText(loc.state) || ed.hasText(loc.zip);
    const display = hasRealContent ? ed.formatLocationDisplay(loc) : '';
    btn.textContent = display || 'Tap to add location';
    btn.classList.toggle('has-value', !!display);
  }

  // Most recently used locations first: each ranks by the latest shoot date
  // it's been used for (an undated shoot that's still being planned counts
  // as today), ties broken alphabetically so the order stays stable rather
  // than reflecting shoot-creation order.
  function getAllPastLocations() {
    const latest = {};
    const samples = {};
    const dismissed = new Set(ed.state.dismissedLocationKeys);
    const today = ed.todayStr();
    ed.state.shoots.forEach(s => {
      // A country on its own is just the pre-filled default, not a location
      // anyone picked (same rule as updateLocationBtnDisplay).
      const loc = s.location;
      if (!loc || !['name', 'street', 'city', 'state', 'zip'].some(k => ed.hasText(loc[k]))) return;
      const key = ed.locationKey(loc);
      if (dismissed.has(key)) return;
      // Only a shoot still being planned counts its missing date as today: a
      // canceled/postponed one's kept date is only the original plan
      // (scheduledShootDate leaves it out), so it ranks last.
      const live = !s.archived && s.status !== 'canceled' && s.status !== 'rescheduled';
      const when = ed.scheduledShootDate(s) || (live ? today : '');
      if (!(key in latest) || when >= latest[key]) {
        latest[key] = when;
        samples[key] = s.location;
      }
    });
    return Object.keys(latest)
      .sort((a, b) => latest[b].localeCompare(latest[a]) || ed.formatLocationDisplay(samples[a]).localeCompare(ed.formatLocationDisplay(samples[b])))
      .map(key => samples[key]);
  }

  // Whatever directions were entered the most recent time this exact
  // location was shot at (by shoot date; undated shoots sort last so they
  // only win if nothing else has directions on file) — lets picking a
  // known location bring its directions along automatically.
  function getLastLocationDirections(loc) {
    const key = ed.locationKey(loc);
    const matches = ed.state.shoots.filter(s => s.location && ed.locationKey(s.location) === key && ed.hasText(s.locationDirections));
    if (!matches.length) return '';
    matches.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    return matches[0].locationDirections;
  }

  function fillLocationForm(loc) {
    document.getElementById('locationNameInput').value = loc.name || '';
    document.getElementById('locationStreetInput').value = loc.street || '';
    document.getElementById('locationCityInput').value = loc.city || '';
    document.getElementById('locationStateInput').value = loc.state || '';
    document.getElementById('locationZipInput').value = loc.zip || '';
    document.getElementById('locationCountryInput').value = loc.country || '';
  }

  // Rebuilt rather than built once, because deleting from "Manage locations…"
  // changes what belongs in this list while the Location modal is still open
  // behind it. Without a refresh you'd come back to a dropdown still offering
  // locations you just removed, until you closed and reopened the modal.
  function refreshPastLocationsSelect() {
    ed.pastLocationSamples = getAllPastLocations();
    const select = document.getElementById('pastLocationsSelect');
    select.innerHTML = '<option value="">Select a past location…</option>'
      + ed.pastLocationSamples.map((loc, i) => `<option value="${i}">${ed.escapeHtml(ed.formatLocationDisplay(loc))}</option>`).join('')
      + '<option value="__manage__">Manage locations…</option>';
  }

  function openLocationModal() {
    fillLocationForm(ed.currentShootLocation);
    refreshPastLocationsSelect();
    document.getElementById('locationModalOverlay').hidden = false;
  }

  document.getElementById('shootLocationBtn').addEventListener('click', openLocationModal);

  document.getElementById('pastLocationsSelect').addEventListener('change', (e) => {
    if (e.target.value === '__manage__') {
      e.target.value = '';
      openManageLocationsModal();
      return;
    }
    if (e.target.value === '') return;
    const loc = ed.pastLocationSamples[Number(e.target.value)];
    if (loc) fillLocationForm(loc);
  });

  // State / region is optional, like every other line here: plenty of places
  // have none (or none anyone writes), and a studio name on its own is a
  // perfectly good location. Everything that reads a location already skips
  // a blank part — formatLocationDisplay leaves it out of the line, and the
  // past-locations key just has an empty slot for it.
  document.getElementById('saveLocationBtn').addEventListener('click', () => {
    const newLocation = {
      name: document.getElementById('locationNameInput').value.trim(),
      street: document.getElementById('locationStreetInput').value.trim(),
      city: document.getElementById('locationCityInput').value.trim(),
      state: document.getElementById('locationStateInput').value.trim(),
      zip: document.getElementById('locationZipInput').value.trim(),
      country: document.getElementById('locationCountryInput').value,
    };
    const oldKey = ed.locationKey(ed.currentShootLocation);
    const isChange = ed.locationKey(newLocation) !== oldKey;
    ed.currentShootLocation = newLocation;
    updateLocationBtnDisplay();
    // Only autofill on an actual change — re-saving the same location
    // shouldn't clobber directions the user may have just edited by hand.
    if (isChange && !ed.isLocationBlank(newLocation)) {
      const lastDirections = getLastLocationDirections(newLocation);
      if (lastDirections) document.getElementById('shootLocationDirections').value = lastDirections;
    }
    // Remember whichever country gets set the first time ever — most
    // photographers mostly work in one country, so pre-filling it for every
    // new shoot going forward saves a repetitive pick.
    if (newLocation.country && !ed.state.defaultCountry) ed.state.defaultCountry = newLocation.country;
    document.getElementById('locationModalOverlay').hidden = true;
    ed.scheduleShootAutosave();
  });

  function renderManageLocationsList() {
    const samples = getAllPastLocations();
    const container = document.getElementById('manageLocationsList');
    if (!samples.length) {
      container.innerHTML = '<p class="empty-hint">No saved locations yet.</p>';
      return;
    }
    container.innerHTML = samples.map((loc, idx) => `
      <div class="manage-location-row">
        <span>${ed.escapeHtml(ed.formatLocationDisplay(loc))}</span>
        <button type="button" class="delete-manage-location" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
      </div>
    `).join('');
    container.querySelectorAll('.delete-manage-location').forEach(btn => {
      btn.addEventListener('click', () => {
        const loc = samples[Number(btn.dataset.idx)];
        if (!loc) return;
        const key = ed.locationKey(loc);
        if (!ed.state.dismissedLocationKeys.includes(key)) ed.state.dismissedLocationKeys.push(key);
        ed.saveState();
        renderManageLocationsList();
        // The Location modal's dropdown is still sitting open underneath, so it
        // has to drop the deleted entry now rather than on next open.
        refreshPastLocationsSelect();
      });
    });
  }

  function openManageLocationsModal() {
    renderManageLocationsList();
    document.getElementById('manageLocationsOverlay').hidden = false;
  }
};
;

// ---- pages/shoot/references.js ----
// References: the list of links.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootReferences = function addShootReferences(ed) {
  Object.assign(ed, { renderReferences });
  // ---------- References (dynamic list of external links) ----------
  ed.currentReferences = [];

  function renderReferences() {
    const container = document.getElementById('referencesList');
    container.innerHTML = ed.currentReferences.map((url, idx) => `
      <div class="reference-row">
        <input type="text" class="reference-input" data-idx="${idx}" value="${ed.escapeHtml(url)}" placeholder="https://…" />
        <button type="button" class="reference-open" data-idx="${idx}" aria-label="Open link">&#8599;</button>
        <button type="button" class="delete-reference" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
      </div>
    `).join('');

    container.querySelectorAll('.reference-input').forEach(input => {
      input.addEventListener('input', () => {
        ed.currentReferences[Number(input.dataset.idx)] = input.value;
      });
    });
    container.querySelectorAll('.reference-open').forEach(btn => {
      btn.addEventListener('click', () => {
        const url = (ed.currentReferences[Number(btn.dataset.idx)] || '').trim();
        if (!url) return;
        window.open(/^https?:\/\//i.test(url) ? url : `https://${url}`, '_blank', 'noopener');
      });
    });
    container.querySelectorAll('.delete-reference').forEach(btn => {
      btn.addEventListener('click', () => {
        ed.currentReferences.splice(Number(btn.dataset.idx), 1);
        renderReferences();
        ed.scheduleShootAutosave();
      });
    });
    ed.syncAllShootFormFields();
  }

  document.getElementById('addReferenceBtn').addEventListener('click', () => {
    ed.currentReferences.push('');
    renderReferences();
    ed.scheduleShootAutosave();
  });
};
;

// ---- pages/shoot/time-range.js ----
// The time range (the end time starts 2 hours after the start).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootTimeRange = function addShootTimeRange(ed) {
  // ---------- Time range (default end time to 2h after start) ----------
  // The step="1800" attribute keeps a native wheel/spinner picker to :00/:30
  // stops, but a typed-in value (desktop keyboard entry, or a pasted value)
  // can still land off-step — rounding here on commit guarantees the shoot
  // never actually saves an odd time like 2:43 regardless of how it was entered.
  function roundToNearestHalfHour(timeStr) {
    const [h, m] = timeStr.split(':').map(Number);
    const totalMinutes = ((Math.round((h * 60 + m) / 30) * 30) + 1440) % 1440;
    return `${String(Math.floor(totalMinutes / 60)).padStart(2, '0')}:${String(totalMinutes % 60).padStart(2, '0')}`;
  }

  document.getElementById('shootStartTime').addEventListener('change', () => {
    const startInput = document.getElementById('shootStartTime');
    const endInput = document.getElementById('shootEndTime');
    if (!startInput.value) return;
    startInput.value = roundToNearestHalfHour(startInput.value);
    const [h, m] = startInput.value.split(':').map(Number);
    const endH = (h + 2) % 24;
    endInput.value = `${String(endH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  });

  document.getElementById('shootEndTime').addEventListener('change', () => {
    const endInput = document.getElementById('shootEndTime');
    if (!endInput.value) return;
    endInput.value = roundToNearestHalfHour(endInput.value);
  });

  // Video-only call times (crew/talent) snap to :00/:30 the same way.
  ['shootCrewCallTime', 'shootTalentCallTime'].forEach(id => {
    document.getElementById(id).addEventListener('change', () => {
      const input = document.getElementById(id);
      if (!input.value) return;
      input.value = roundToNearestHalfHour(input.value);
    });
  });
};
;

// ---- pages/shoot/concept-fields.js ----
// The concept fields, which differ for story and for commercial shoots.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootConceptFields = function addShootConceptFields(ed) {
  Object.assign(ed, { categoryHasConcept, directionFieldApplies, updateCategoryTierUI, updateVideoCategoryUI, onShootSectionRevealed });
  // ---------- Tiered concept fields (narrative vs commercial categories) ----------
  const COMMERCIAL_TIER_CATEGORIES = ['commercial', 'video', 'lighting_test', 'headshot', 'event'];
  // Events don't plan a concept or an elevator pitch at all.
  const NO_CONCEPT_CATEGORIES = ['event'];

  function categoryHasStoryFields(category) {
    return !COMMERCIAL_TIER_CATEGORIES.includes(category || '');
  }

  function categoryHasConcept(category) {
    return !NO_CONCEPT_CATEGORIES.includes(category || '');
  }

  // Whether a Direction field belongs to this shoot's kind — the same rule
  // the page shows/hides them by (below), for the places that list them
  // from the saved shoot instead: Shoot mode's Direction review and the PDFs.
  function directionFieldApplies(shoot, key) {
    if (key === 'premise' || key === 'elevatorPitch') return categoryHasConcept(shoot.category);
    if (key === 'character' || key === 'worldNotes') return categoryHasStoryFields(shoot.category);
    // Hidden on a "Just me" shoot (see updateTeamRequiredUI); still shown
    // while the team question hasn't been answered.
    if (key === 'teamDirections') return shoot.teamRequired !== 'no';
    return true;
  }

  function updateCategoryTierUI() {
    const category = document.getElementById('shootCategory').value;
    const isCommercialTier = !categoryHasStoryFields(category);
    document.getElementById('narrativeFieldsBlock').hidden = isCommercialTier;
    document.getElementById('shootPremiseLabelText').textContent = isCommercialTier ? 'Concept (if applicable)' : 'Concept';
    // No Concept, Elevator pitch or concept helper (which only writes
    // those) for events. Hiding never clears them, same as the rest.
    const hasConcept = categoryHasConcept(category);
    document.getElementById('shootPremiseField').hidden = !hasConcept;
    document.getElementById('shootElevatorPitchField').hidden = !hasConcept;
    document.getElementById('conceptHelperBtn').hidden = !hasConcept;
    // Video-only fields: Deliverables (Direction) and Crew/Talent call times
    // (Logistics). Hiding never clears them, so flipping away from Video and
    // back keeps whatever was filled in.
    const isVideo = ed.isVideoCategory(category);
    const deliverablesBlock = document.getElementById('videoDeliverablesBlock');
    deliverablesBlock.hidden = !isVideo;
    document.getElementById('videoCallTimesRow').hidden = !isVideo;
    if (isVideo) deliverablesBlock.querySelectorAll('input, textarea').forEach(ed.syncFieldFilledState);
  }

  document.getElementById('shootCategory').addEventListener('change', updateCategoryTierUI);

  // Video swaps "Mood board" for "Storyboard" and has no Final images (the
  // section's hidden, never cleared — flipping back to a photo category
  // brings any images uploaded before the switch right back).
  function updateVideoCategoryUI() {
    const category = document.getElementById('shootCategory').value;
    document.getElementById('moodboardSectionLabel').textContent = ed.moodboardTerm(category);
    ed.updateMoodboardCompleteLabel();
    document.getElementById('finalImagesSection').hidden = ed.isVideoCategory(category);
  }

  document.getElementById('shootCategory').addEventListener('change', updateVideoCategoryUI);

  // Direction no longer waits behind "select a category to continue" on a new
  // shoot: Shoot goals and the rest are there from the start. With no
  // category yet it shows the full set (the same as an existing shoot with
  // none), and picking one later only hides what doesn't apply, never
  // clearing it (updateCategoryTierUI).

  // A section's auto-sized boxes measure zero while it's hidden and keep their
  // rows-default size, so whatever reveals one measures them again on screen.
  function onShootSectionRevealed(bodyId) {
    if (bodyId === 'shotListBody' || bodyId === 'lightingSetupsBody') ed.autoSizeAllListTextareas();
    const body = document.getElementById(bodyId);
    if (body) body.querySelectorAll('textarea').forEach(ed.syncFieldFilledState);
  }
};
;

// ---- pages/shoot/expand-field.js ----
// Expanding a notes field to the whole screen.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootExpandField = function addShootExpandField(ed) {
  Object.assign(ed, { openExpandField });
  // ---------- Expand field (every notes-style textarea in the shoot form) ----------
  // These fields are readonly on the small form; tapping one opens a bigger
  // writing surface in a modal instead of typing directly in the compressed box.
  const EXPAND_FIELD_LABELS = {
    shootCharacter: 'Character/Personality',
    shootWorldNotes: 'World-building notes',
    shootGoals: 'Shoot goals',
    shootElevatorPitch: 'Elevator pitch',
    shootWentRight: 'What went right',
    shootCouldBeBetter: "What could've gone better",
    shootLessonsLearned: 'Lessons for next time',
    shootTalentDirections: 'Directions for talent',
    shootTeamDirections: 'Directions for team',
    shootShootingNotes: 'Shooting notes',
    shootLocationDirections: 'Location directions',
    shootDeliverables: 'Deliverables',
  };
  let expandFieldOnSave = null;

  function expandFieldLabel(fieldId) {
    if (fieldId === 'shootPremise') return document.getElementById('shootPremiseLabelText').textContent;
    return EXPAND_FIELD_LABELS[fieldId] || '';
  }

  // Accepts either a field id (the main form's own readonly fields — reads
  // label/value/placeholder/maxLength off that field, and writes back +
  // re-dispatches 'input' so the field's own listener persists it) or a
  // {title, value, placeholder, maxLength, onSave} config for callers with
  // no backing DOM field to read from, like Shoot Mode's Quick review —
  // those write straight to the shoot object themselves, same as
  // everything else in Shoot Mode does.
  function openExpandField(fieldIdOrConfig) {
    let config;
    if (typeof fieldIdOrConfig === 'string') {
      const field = document.getElementById(fieldIdOrConfig);
      config = {
        title: expandFieldLabel(fieldIdOrConfig),
        value: field.value,
        placeholder: field.placeholder,
        maxLength: field.maxLength,
        onSave: (newValue) => {
          field.value = newValue;
          // The readonly field is what's visible on the main form once this
          // popup closes — it should always read from the start of what was
          // written, not wherever the popup's own cursor/scroll happened to
          // be sitting.
          field.scrollTop = 0;
          field.dispatchEvent(new Event('input', { bubbles: true }));
        },
      };
    } else {
      config = fieldIdOrConfig;
    }
    // A shoot page's own field: written out at the page's (bigger) size.
    document.getElementById('expandFieldOverlay').classList.toggle('from-page', typeof fieldIdOrConfig === 'string');
    expandFieldOnSave = config.onSave;
    document.getElementById('expandFieldTitle').textContent = config.title;
    const textarea = document.getElementById('expandFieldTextarea');
    textarea.value = config.value || '';
    textarea.maxLength = config.maxLength || 2000;
    textarea.placeholder = config.placeholder || '';
    document.getElementById('expandFieldOverlay').hidden = false;
    // Deferred a frame: focusing (which opens the keyboard) in the same tick
    // as un-hiding gives the browser no chance to lay out the now-visible
    // modal first, which is one way the keyboard-open/scroll-into-view
    // behavior it triggers can end up positioning this popup off-screen.
    requestAnimationFrame(() => textarea.focus());
  }

  function closeExpandField() {
    document.getElementById('expandFieldOverlay').hidden = true;
    expandFieldOnSave = null;
    ed.queueShootBreak(250);
  }

  document.getElementById('expandFieldTextarea').addEventListener('input', () => {
    if (expandFieldOnSave) expandFieldOnSave(document.getElementById('expandFieldTextarea').value);
  });

  document.getElementById('expandFieldCloseBtn').addEventListener('click', closeExpandField);
  document.getElementById('expandFieldOkBtn').addEventListener('click', closeExpandField);
  document.getElementById('expandFieldOverlay').addEventListener('click', (e) => {
    if (e.target === document.getElementById('expandFieldOverlay')) closeExpandField();
  });

  [
    'shootPremise', 'shootCharacter', 'shootWorldNotes', 'shootGoals',
    'shootElevatorPitch',
    'shootWentRight', 'shootCouldBeBetter', 'shootLessonsLearned',
    'shootTalentDirections', 'shootTeamDirections', 'shootLocationDirections',
    'shootShootingNotes', 'shootDeliverables',
  ].forEach(fieldId => {
    document.getElementById(fieldId).addEventListener('click', (e) => {
      // Not readonly right now = borrowed onto a new-shoot wizard slide,
      // which has the room to type in place (see moveBlockIntoShootWizard).
      if (!e.currentTarget.readOnly) return;
      openExpandField(fieldId);
    });
  });
};
;

// ---- pages/shoot/after-status.js ----
// When the status changes: the reflection opens once it's shot, and what's asked next.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootAfterStatus = function addShootAfterStatus(ed) {
  Object.assign(ed, { isPostCaptureStatus, shootPageOpenOn, runStatusFollowUps, showPostShootContentExpanded, openShootPageAtReflection });
  // ---------- Post-shoot reflection (gated behind captured-or-later status) ----------
  ed.previousStatusValue = 'prospect';
  // The open shoot's offScheduleDate (see isOriginalPlanDate), kept with the
  // form like its other fields: loaded by openShootModal, noted by the
  // status button and saved by gatherShootFormData. undefined when it has
  // none.
  ed.currentOffScheduleDate = undefined;
  // The status swap the last category flip made ({ from, to }), so flipping
  // the category straight back restores the original status (a mis-tap on
  // the category dropdown stays lossless). Reset per modal open.
  ed.categoryRemap = null;

  function isPostCaptureStatus(status) {
    // Postponed (key: rescheduled)/canceled are an off-track branch, not a step further along
    // the capture pipeline, regardless of where they sit in STATUS_LABELS.
    // Must agree with POST_CAPTURE_STATUSES; the video edit keys sit between
    // captured and delivered in STATUS_LABELS for this reason.
    if (status === 'rescheduled' || status === 'canceled') return false;
    const order = Object.keys(ed.STATUS_LABELS);
    return order.indexOf(status) >= order.indexOf('captured');
  }

  // ---------- After a status change: the reflection and deadline prompts ----------
  // Whichever way a status changes — the shoot page's status button, a row's
  // ⋮ > Change status, or "Done shooting" — the same follow-ups come next,
  // from runStatusFollowUps: moving into Captured or later offers the
  // post-shoot reflection, and moving into the edit without a deadline asks
  // for one, chained after the reflection prompt when both apply so the two
  // never show stacked. Both prompts remember which shoot they're about, so
  // they work from a row too, with that shoot's page closed: there they read
  // and write the saved shoot, and "Reflect now" opens its page.

  // Whether the shoot page is open on this shoot right now — its form, not
  // the saved shoot, is then where its status, deadline and reflection are.
  function shootPageOpenOn(shootId) {
    return !!shootId && !ed.shootModalOverlay.hidden && ed.currentShootId === shootId;
  }

  function shootHasReflection(shootId) {
    if (shootPageOpenOn(shootId)) {
      return ['shootWentRight', 'shootCouldBeBetter', 'shootLessonsLearned'].some(ed.shootFieldHasText);
    }
    const s = ed.state.shoots.find(x => x.id === shootId);
    return !!s && (ed.hasText(s.whatWentRight) || ed.hasText(s.couldBeBetter) || ed.hasText(s.lessonsLearned));
  }

  function runStatusFollowUps(shootId, oldStatus, newStatus) {
    if (isPostCaptureStatus(newStatus) && !isPostCaptureStatus(oldStatus)) {
      // A reflection written before the shoot stepped back a status (it's
      // only ever hidden then, never cleared) just comes back into view —
      // no asking again for what's already there.
      if (!shootHasReflection(shootId)) {
        openPostShootPrompt(shootId);
        return;
      }
      if (shootPageOpenOn(shootId)) {
        document.getElementById('postShootContent').hidden = false;
        // Its answers were measured while hidden (zero height, so they kept
        // their rows size and a longer one reads cut off): measured again
        // now they're on screen.
        ed.onShootSectionRevealed('postShootBody');
        ed.updateShootModalJumpMenuVisibility();
      }
    }
    // Only on entering the edit bucket: a video stepping Rough cut ->
    // Client review -> Revisions shouldn't re-ask at every step.
    if (ed.isInTheEditStatus(newStatus) && !ed.isInTheEditStatus(oldStatus)) ed.maybeOpenDeadlinePrompt(shootId);
  }

  // The shoot the reflection prompt is about.
  let postShootPromptShootId = null;

  function openPostShootPrompt(shootId) {
    postShootPromptShootId = shootId;
    document.getElementById('postShootPromptText').textContent = 'Complete post shoot reflection?';
    document.getElementById('postShootPromptActions').hidden = false;
    document.getElementById('postShootPromptWalkBtn').hidden = false;
    document.getElementById('postShootPromptDismissBtn').hidden = true;
    document.getElementById('postShootPromptOverlay').hidden = false;
    // "Reflect now" doesn't fit half the row on a phone: stack, don't wrap.
    ed.fitButtonPair(document.getElementById('postShootPromptActions'));
  }

  // Reveals the Post-shoot Reflection section.
  function showPostShootContentExpanded() {
    const content = document.getElementById('postShootContent');
    content.hidden = false;
    // Sized now it's on screen: its boxes were measured while hidden and
    // would stay cut off at three lines.
    ed.onShootSectionRevealed('postShootBody');
    return content;
  }

  // Opens a shoot, from a row, already on its Reflection page.
  function openShootPageAtReflection(shootId) {
    if (!ed.state.shoots.some(x => x.id === shootId)) return false;
    ed.openShootModal(shootId);
    showPostShootContentExpanded();
    ed.showShootPage('postShootHeading');
    ed.updateShootModalJumpMenuVisibility();
    return true;
  }

  // "Reflect now": straight to the Reflection page of that shoot.
  function goToPostShootReflection(shootId) {
    if (!shootPageOpenOn(shootId)) return openShootPageAtReflection(shootId);
    // From the new-shoot wizard's first slide (a shoot being logged after
    // the fact) this means "take me to the reflection now" — close the
    // wizard first so the page turns behind nothing.
    if (ed.shootWizardActive) ed.endShootWizard();
    showPostShootContentExpanded();
    ed.showShootPage('postShootHeading', { turn: true });
    ed.updateShootModalJumpMenuVisibility();
    return true;
  }

  document.getElementById('postShootPromptYesBtn').addEventListener('click', () => {
    const shootId = postShootPromptShootId;
    document.getElementById('postShootPromptOverlay').hidden = true;
    goToPostShootReflection(shootId);
    ed.maybeOpenDeadlinePrompt(shootId);
  });

  // "Walk me through it": the same, then the reflection helper's questions
  // straight away. The deadline prompt, when it applies, waits until the
  // helper closes rather than stacking over it.
  document.getElementById('postShootPromptWalkBtn').addEventListener('click', () => {
    const shootId = postShootPromptShootId;
    document.getElementById('postShootPromptOverlay').hidden = true;
    if (!goToPostShootReflection(shootId)) return;
    ed.openReflectHelper();
    ed.reflectHelper.onClose = () => ed.maybeOpenDeadlinePrompt(shootId);
  });

  document.getElementById('postShootPromptLaterBtn').addEventListener('click', () => {
    if (shootPageOpenOn(postShootPromptShootId)) {
      showPostShootContentExpanded();
      ed.updateShootModalJumpMenuVisibility();
    }
    document.getElementById('postShootPromptText').textContent = "the post-shoot reflection questions will be on the Reflection page of this shoot whenever you're ready.";
    document.getElementById('postShootPromptActions').hidden = true;
    document.getElementById('postShootPromptWalkBtn').hidden = true;
    document.getElementById('postShootPromptDismissBtn').hidden = false;
  });

  document.getElementById('postShootPromptDismissBtn').addEventListener('click', () => {
    document.getElementById('postShootPromptOverlay').hidden = true;
    ed.maybeOpenDeadlinePrompt(postShootPromptShootId);
  });
};
;

// ---- pages/shoot/deadline-prompt.js ----
// The prompt to add a deadline, once a shoot is in the edit.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootDeadlinePrompt = function addShootDeadlinePrompt(ed) {
  Object.assign(ed, { maybeOpenDeadlinePrompt, updateEnterShootModeBtnVisibility });
  // ---------- Add deadline prompt (shown once a shoot moves into the edit —
  // Editing, or any of a video's Rough cut/Client review/Revisions — without
  // a deadline set yet — chained after the post-shoot reflection
  // prompt when both apply, e.g. a shoot logged retroactively straight into
  // "editing", so the two never show stacked on top of each other). ----------
  let deadlinePromptShootId = null;

  function openDeadlinePrompt(shootId) {
    deadlinePromptShootId = shootId;
    document.getElementById('deadlinePromptDateInput').value = '';
    // "Set deadline" waits for a date — it used to just close with none.
    document.getElementById('deadlinePromptOkBtn').disabled = true;
    document.getElementById('deadlinePromptOverlay').hidden = false;
    ed.fitButtonPair(document.getElementById('deadlinePromptActions'));
  }

  function maybeOpenDeadlinePrompt(shootId) {
    let status = '';
    let deadline = '';
    if (ed.shootPageOpenOn(shootId)) {
      status = document.getElementById('shootStatus').value;
      deadline = document.getElementById('shootDeadline').value;
    } else {
      const s = ed.state.shoots.find(x => x.id === shootId);
      if (!s) return;
      status = s.status;
      deadline = s.deadline;
    }
    if (ed.isInTheEditStatus(status) && !ed.hasText(deadline)) openDeadlinePrompt(shootId);
  }

  ['input', 'change'].forEach(type => {
    document.getElementById('deadlinePromptDateInput').addEventListener(type, (e) => {
      document.getElementById('deadlinePromptOkBtn').disabled = !e.target.value;
    });
  });

  document.getElementById('deadlinePromptOkBtn').addEventListener('click', () => {
    const dateValue = document.getElementById('deadlinePromptDateInput').value;
    if (!dateValue) return;
    const shootId = deadlinePromptShootId;
    document.getElementById('deadlinePromptOverlay').hidden = true;
    if (ed.shootPageOpenOn(shootId)) {
      document.getElementById('shootDeadline').value = dateValue;
      ed.scheduleShootAutosave();
      return;
    }
    // Asked from a row, with the page closed: same write as the ⋮ menu's
    // own deadline option (saveDeadlineOption).
    const idx = ed.state.shoots.findIndex(x => x.id === shootId);
    if (idx === -1) return;
    ed.state.shoots[idx] = { ...ed.state.shoots[idx], deadline: dateValue };
    ed.saveState();
    ed.renderAll();
  });

  document.getElementById('deadlinePromptNotNowBtn').addEventListener('click', () => {
    document.getElementById('deadlinePromptOverlay').hidden = true;
    ed.showToast('You can add a deadline anytime from Basic Info.');
  });

  // Shoot mode only makes sense once a shoot has a shot list and mood board
  // worth working from and a day it's actually happening — "Shoot ready" is the
  // one status that means both. Re-run on every status change (not just on
  // load), since flipping the swatch while the modal is open is the normal way
  // a shoot reaches that status in the first place. An archived shoot gets
  // Archive mode's button in this exact same spot instead — the two are
  // mutually exclusive, so Shoot mode is also hidden once archived even on
  // the off chance a shoot got archived without ever reaching "Shoot ready".
  function updateEnterShootModeBtnVisibility() {
    const status = document.getElementById('shootStatus').value;
    const shoot = ed.editingShootId ? ed.state.shoots.find(s => s.id === ed.editingShootId) : null;
    const isArchived = !!(shoot && shoot.archived);
    document.getElementById('enterShootModeBtn').hidden = !ed.editingShootId || isArchived || status !== 'waiting_to_shoot';
    document.getElementById('enterArchiveModeBtn').hidden = !ed.editingShootId || !isArchived;
  }

  document.getElementById('shootStatus').addEventListener('change', (e) => {
    const newValue = e.target.value;
    const oldValue = ed.previousStatusValue;
    ed.previousStatusValue = newValue;
    // The same note applyStatusChange makes: going Postponed/Canceled marks
    // the date on the page right now as the plan that fell through.
    ed.currentOffScheduleDate = ed.isOffScheduleShoot({ status: newValue })
      ? document.getElementById('shootDate').value
      : undefined;

    // Nothing is cleared on the way: a Postponed (key: rescheduled) or
    // Canceled shoot keeps its date and times (lists show them as the
    // original plan, see isOffScheduleShoot), and stepping back from
    // Captured only hides the Reflection — its answers are kept, and come
    // back with the status. The form-level change listener saves it all.
    if (!ed.isPostCaptureStatus(newValue)) {
      document.getElementById('postShootContent').hidden = true;
      ed.updateShootModalJumpMenuVisibility();
    }
    ed.runStatusFollowUps(ed.currentShootId, oldValue, newValue);

    const isArchived = !document.getElementById('unarchiveShootBtn').hidden;
    document.getElementById('completeShootBtn').hidden = !ed.editingShootId || isArchived || document.getElementById('shootStatus').value !== 'delivered';
    ed.updateMoodboardCompleteVisibility();
    ed.updateStatusSwatchDisplay();
    updateEnterShootModeBtnVisibility();
  });
};
;

// ---- pages/shoot/status-options.js ----
// Which statuses a kind of shoot offers (video has its own edit steps).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootStatusOptions = function addShootStatusOptions(ed) {
  Object.assign(ed, { updateMoodboardCompleteLabel, updateMoodboardCompleteVisibility });
  // ---------- Category -> status options (video has its own edit steps) ----------
  // Flipping a shoot to or from Video rebuilds the status select for the new
  // category and swaps a category-specific status for its nearest equivalent
  // (Waiting for selects/Editing -> Rough cut; Rough cut/Client review/
  // Revisions -> Editing), so the select never goes blank. Both sides of
  // every swap are post-capture, so no reflection prompt/confirm is involved.
  // Flipping straight back restores the original status (see categoryRemap).
  function syncStatusSelectToCategory() {
    const category = document.getElementById('shootCategory').value;
    const current = document.getElementById('shootStatus').value || ed.previousStatusValue || 'prospect';
    // Looked up fresh: autosaveShoot replaces the shoot object on every save.
    const live = ed.state.shoots.find(x => x.id === ed.currentShootId);
    let next = ed.remapStatusForCategory(current, category);
    if (ed.categoryRemap && current === ed.categoryRemap.to && ed.remapStatusForCategory(ed.categoryRemap.from, category) === ed.categoryRemap.from) {
      next = ed.categoryRemap.from;
      // The flip's save may have stamped an edit-start date (Waiting for
      // selects -> Rough cut counts as entering the edit). Flipping straight
      // back puts it back how it was, so a mis-tap doesn't start the weekly
      // editing check-in clock early. The next autosave writes it.
      if (live) {
        if (ed.categoryRemap.editingAt) live.editingAt = ed.categoryRemap.editingAt;
        else delete live.editingAt;
      }
    }
    if (next !== current) ed.categoryRemap = { from: current, to: next, editingAt: live ? live.editingAt : undefined };
    ed.renderShootStatusSelectOptions(category, next);
    ed.previousStatusValue = next;
    ed.updateStatusSwatchDisplay();
  }

  document.getElementById('shootCategory').addEventListener('change', syncStatusSelectToCategory);

  function updateMoodboardCompleteLabel() {
    const checked = document.getElementById('shootMoodboardComplete').checked;
    const term = ed.moodboardTerm(document.getElementById('shootCategory').value);
    document.getElementById('moodboardCompleteLabel').textContent = `${term} complete or not required${checked ? '' : '?'}`;
  }

  // Past capture, the mood board is moot — hide the checkbox entirely rather
  // than let it keep tracking a value nobody's looking at anymore. Same for
  // canceled/postponed (key: rescheduled), an off-track branch rather than a step further
  // along (isPostCaptureStatus alone doesn't cover those — see its own
  // comment). The value itself is never touched here, so reverting to an
  // earlier status brings the row (and whatever it was actually set to)
  // right back.
  function updateMoodboardCompleteVisibility() {
    const status = document.getElementById('shootStatus').value;
    document.getElementById('moodboardCompleteRow').hidden =
      ed.isPostCaptureStatus(status) || status === 'canceled' || status === 'rescheduled';
  }

  document.getElementById('shootMoodboardComplete').addEventListener('change', updateMoodboardCompleteLabel);
};
;

// ---- pages/shoot/shoot-page.js ----
// The shoot page.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootPage = function addShootPage(ed) {
  // ---------- Shoot modal ----------
  const shootModalOverlay = document.getElementById('shootModalOverlay'); ed.shootModalOverlay = shootModalOverlay;
  const shootForm = document.getElementById('shootForm'); ed.shootForm = shootForm;
  ed.editingShootId = null;
  ed.currentShootId = null;
  ed.pendingProjectPhoto = null;
  ed.shootHasImages = false;
  ed.shootSaveTimer = null;
  ed.shootModalBaseTitle = '';
  // New-shoot planning wizard (see SHOOT_WIZARD_STEPS). Tracked by its own
  // flag rather than by editingShootId === null: Multi-day's "Create days"
  // saves a brand-new draft mid-wizard, which flips that to the shoot's id.
  ed.shootWizardActive = false;
  ed.shootWizardStepKey = null;
  ed.shootWizardAgain = false;       // opened from the ⋯ menu's "Guide me through this shoot"
  ed.shootWizardMoved = [];          // { el, placeholder, unlocked, wasInert } per borrowed block
  ed.shootWizardPendingId = null;    // shoot a queued wizard is waiting to open over
  ed.shootWizardStartTimer = null;
  ed.shootWizardViewportMaxH = 0;    // tallest visible height seen this run — the keyboard yardstick

  // The one canonical list of top-level sections in the form, in on-page
  // order: the notebook's pages and the guided tour.
  const SHOOT_MODAL_SECTIONS = [
    { id: 'basicInfoHeading', label: 'Basic Info' },
    { id: 'logisticsHeading', label: 'Logistics' },
    { id: 'teamHeading', label: 'Team' },
    { id: 'directionHeading', label: 'Direction' },
    { id: 'visualsHeading', label: 'Visuals' },
    { id: 'shotListHeading', label: 'Shot list' },
    { id: 'postShootHeading', label: 'Reflection' },
  ]; ed.SHOOT_MODAL_SECTIONS = SHOOT_MODAL_SECTIONS;
};
;

// ---- pages/shoot/title-jump.js ----
// The title's jump menu, and keeping it in step with the scrolling.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootTitleJump = function addShootTitleJump(ed) {
  Object.assign(ed, { updateShootModalJumpMenuVisibility, closeShootModalJumpMenu });
  // ---- Title jump menu + scrollspy ----
  const shootModalTitleBtn = document.getElementById('shootModalTitleBtn');
  const shootModalJumpMenu = document.getElementById('shootModalJumpMenu');

  // Post-shoot Reflection is the only section that can be entirely absent
  // from the form (pre-capture shoots), so its jump-menu item has to track
  // that same visibility rather than always being offered.
  function updateShootModalJumpMenuVisibility() {
    document.getElementById('jumpToPostShootItem').hidden = document.getElementById('postShootContent').hidden;
  }

  function closeShootModalJumpMenu() {
    shootModalJumpMenu.hidden = true;
    shootModalTitleBtn.classList.remove('open');
  }

  shootModalTitleBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    const willOpen = shootModalJumpMenu.hidden;
    shootModalJumpMenu.hidden = !willOpen;
    shootModalTitleBtn.classList.toggle('open', willOpen);
  });

  shootModalJumpMenu.addEventListener('click', (e) => {
    const item = e.target.closest('.modal-title-jump-item');
    if (!item) return;
    closeShootModalJumpMenu();
    // Basic Info is the very first section, with the shoot-mode button and
    // the folder-tab decoration sitting above its heading — scrollIntoView
    // on the heading itself stops right at its own top edge, leaving that
    // bit still scrolled past. Scrolling the modal to 0 always reaches the
    // true top of the page instead.
    if (item.dataset.jump === 'basicInfoHeading') {
      ed.shootModalOverlay.querySelector('.modal').scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    const target = document.getElementById(item.dataset.jump);
    if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });

  document.addEventListener('click', (e) => {
    if (shootModalJumpMenu.hidden) return;
    if (!shootModalJumpMenu.contains(e.target) && !shootModalTitleBtn.contains(e.target)) {
      closeShootModalJumpMenu();
    }
  });
};
;

// ---- pages/shoot/chapter-pages.js ----
// A shoot as a chapter: its pages, and where they break.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootChapterPages = function addShootChapterPages(ed) {
  Object.assign(ed, { typingNow, shootFlatPages, drawShootSub, breakShootPages, noteShootChanges, queueShootBreak, availableShootPages, drawShootPageNumber, updateShootRunningHead });
  // ---------- A shoot as a chapter ----------
  // A shoot is one page that scrolls, its sections one under another. Which
  // section is at the top of the page is kept (shootPageId) for coming back
  // to it. The form's direct children are listed by section (shootPageEls).
  const shootPageEls = (() => {
    const ids = ed.SHOOT_MODAL_SECTIONS.map(sec => sec.id);
    const els = [];
    let page = null;
    [...ed.shootForm.children].forEach(el => {
      if (el.id === 'postShootContent') { els.push({ el, page: 'postShootHeading' }); page = null; return; }
      if (ids.includes(el.id)) page = el.id;
      if (page && !el.classList.contains('folder-tab-deco') && el.id !== 'deleteShootBtn' && !el.classList.contains('modal-actions') && el.id !== 'shootWizard') els.push({ el, page });
    });
    return els;
  })(); ed.shootPageEls = shootPageEls;
  const shootPageMemory = {}; ed.shootPageMemory = shootPageMemory;
  ed.shootPageId = 'basicInfoHeading';
  // A section runs over as many pages as it needs. Inside a shoot the breaks
  // fall between whole blocks: a list stays in one piece so it can be dragged
  // and typed in, and one taller than a page scrolls on a page of its own.
  ed.shootSub = 0;
  ed.shootFlows = null;
  ed.shootBreakWatch = null;
  let shootBreakTimer = null;
  ed.shootBreakChanged = []; // what's changed since the pages were last broken
  ed.shootWanted = null; // the page a shoot reopens on, held until its photos are in
  ed.shootOpening = null; // set while a shoot that's just opened waits for its photos
  const SHOOT_PAGE_BODIES = {
    basicInfoHeading: 'basicInfoBody',
    logisticsHeading: 'logisticsBody',
    teamHeading: 'teamBody',
    directionHeading: 'directionBody',
    visualsHeading: 'visualsBody',
    shotListHeading: 'shotListBody',
    postShootHeading: 'postShootBody',
  };
  const SHOOT_BLOCKS_INSIDE = '#formSection2, #narrativeFieldsBlock, #videoDeliverablesBlock, #frameworkTagsContainerEarly, #frameworkTagsContainer';
  const SHOOT_STAYS_WITH_NEXT = '.form-section-label-row, #conceptHelperBtn, #reflectHelperBtn';
  const SHOOT_STAYS_WITH_LAST = '#multiDayRow, #addShotBtn';

  function typingNow() {
    const el = document.activeElement;
    return !!el && (el.isContentEditable || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT'
      || (el.tagName === 'INPUT' && !['checkbox', 'radio', 'button', 'file'].includes(el.type)));
  }

  function shootFlowAtoms(body) {
    const atoms = [];
    let glue = false;
    const walk = (parent) => [...parent.children].forEach((el) => {
      if (el.hidden || !el.getBoundingClientRect().height) return;
      if (el.matches(SHOOT_BLOCKS_INSIDE)) { walk(el); return; }
      const last = atoms[atoms.length - 1];
      if (last && (glue || el.matches(SHOOT_STAYS_WITH_LAST))) last.also.push(el);
      else atoms.push({ el, also: [], heads: [] });
      glue = el.matches(SHOOT_STAYS_WITH_NEXT);
    });
    walk(body);
    return atoms;
  }

  function shootFlatPages() {
    const flat = [];
    availableShootPages().forEach(({ id }) => {
      const flow = ed.shootFlows && ed.shootFlows[id];
      const count = (flow && flow.pages.length) || 1;
      for (let sub = 0; sub < count; sub++) flat.push({ id, sub });
    });
    return flat;
  }

  function drawShootSub() {
    if (ed.shootWizardActive || ed.shootWizardPendingId) return;
    const flow = ed.shootFlows && ed.shootFlows[ed.shootPageId];
    if (!flow || !flow.pages.length) { ed.shootSub = 0; return; }
    ed.shootSub = Math.max(0, Math.min(ed.shootSub, flow.pages.length - 1));
    ed.drawFlowPage(flow, ed.shootSub);
    if (ed.currentShootId && !ed.shootWanted) shootPageMemory[ed.currentShootId] = { id: ed.shootPageId, sub: ed.shootSub };
  }

  // All in one go, before anything's painted. Holds off while a field is
  // being typed in, a row's being dragged or the new-shoot steps are up.
  function breakShootPages() {
    if (ed.shootModalOverlay.hidden || ed.shootWizardActive || ed.shootWizardPendingId || typingNow()) return;
    if (!document.getElementById('expandFieldOverlay').hidden) return;
    if (ed.shootForm.querySelector('.shot-dragging, .lighting-dragging')) return;
    const modal = ed.shootModalOverlay.querySelector('.modal');
    const scrolled = modal.scrollTop;
    modal.scrollTop = 0;
    const oldFlow = ed.shootFlows && ed.shootFlows[ed.shootPageId];
    const oldPage = oldFlow && oldFlow.pages[ed.shootSub];
    if (ed.shootBreakWatch) noteShootChanges(ed.shootBreakWatch.takeRecords());
    const atomHolds = (a, node) => [a.el, ...a.also].some(el => el.contains(node));
    // Stay with the block that just changed on this page: if it has grown
    // over onto the next one, the page turns with it. Otherwise stay with
    // what the page started with.
    const changedHere = oldPage ? ed.shootBreakChanged.filter(node => oldPage.atoms.some(a => atomHolds(a, node))) : [];
    const follow = changedHere.length ? changedHere[changedHere.length - 1] : oldPage ? oldPage.atoms[0].el : null;
    ed.shootBreakChanged = [];
    ed.shootForm.querySelectorAll('.pg-off, .pg-first').forEach(el => el.classList.remove('pg-off', 'pg-first'));
    shootPageEls.forEach(({ el }) => el.classList.remove('nb-off'));
    ed.autoSizeAllListTextareas();
    ed.syncAllShootFormFields();
    const flows = {};
    availableShootPages().forEach(({ id }) => {
      flows[id] = ed.buildFlow(document.getElementById(SHOOT_PAGE_BODIES[id]), shootFlowAtoms);
    });
    ed.shootFlows = flows;
    const flow = ed.shootFlows[ed.shootPageId];
    // An edit on this page outranks the remembered page.
    if (changedHere.length) ed.shootWanted = null;
    if (ed.shootWanted && ed.shootWanted.id === ed.shootPageId) ed.shootSub = ed.shootWanted.sub;
    else {
      const found = follow && flow ? flow.pages.findIndex(p => p.atoms.some(a => atomHolds(a, follow))) : -1;
      if (found >= 0) ed.shootSub = found;
    }
    if (!ed.shootOpening) ed.shootWanted = null; // photos are in: this is the real page count
    drawShootSub();
    drawShootPageNumber();
    // Boxes hidden while the others were measured lost their height.
    ed.autoSizeAllListTextareas();
    ed.syncAllShootFormFields();
    modal.scrollTop = scrolled;
    if (ed.shootBreakWatch) ed.shootBreakWatch.takeRecords();
  }

  // A shoot's photos arriving as it opens aren't an edit to follow.
  function noteShootChanges(records) {
    records.forEach((r) => {
      if (!ed.shootOpening || !r.target.closest('#moodboardGrid, #finalImagesGrid')) ed.shootBreakChanged.push(r.target);
    });
  }

  function queueShootBreak(ms = 80) {
    clearTimeout(shootBreakTimer);
    shootBreakTimer = setTimeout(breakShootPages, ms);
  }

  function availableShootPages() {
    const reflection = !document.getElementById('postShootContent').hidden;
    return ed.SHOOT_MODAL_SECTIONS.filter(sec => sec.id !== 'postShootHeading' || reflection);
  }

  function drawShootPageNumber() {
    ed.queueLastPlace();
    const pages = shootFlatPages();
    const at = pages.findIndex(p => p.id === ed.shootPageId && p.sub === ed.shootSub);
    document.getElementById('nbPageFoot').textContent = `${at + 1} / ${pages.length}`;
    document.getElementById('nbPagePrev').disabled = at <= 0;
    document.getElementById('nbPageNext').disabled = at >= pages.length - 1;
  }

  // The running head: the shoot's name, written at the top of each page.
  function updateShootRunningHead() {
    document.getElementById('nbShootRun').textContent = ed.shootDisplayName({
      title: document.getElementById('shootTitle').value.trim(),
      talents: ed.currentTalents,
    });
  }
};
;

// ---- pages/shoot/chapter.js ----
// A shoot as a chapter: showing a page, and the bar and menus under it.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootChapter = function addShootChapter(ed) {
  Object.assign(ed, { shootPageCopy, showShootPage });
  // What's on this page, for the sheet that turns. The lists that are read
  // back when the shoot saves are found by id across the whole document, so
  // the copy's lose theirs (keeping how they're laid out) and can't be
  // mistaken for the real ones. Other ids stay: they carry the page's look,
  // and the real form comes first in the document.
  const SHOOT_READ_BACK_IDS = [...ed.FRAMEWORK_TAG_CONTAINER_IDS, 'shootAspectRatios', 'shotListItems', 'lightingSetupsItems'];
  function shootPageCopy() {
    return ed.pageCopy(ed.shootForm, (copy) => {
      copy.querySelectorAll(':scope > .nb-off, :scope > #shootWizard, :scope > #deleteShootBtn, :scope > .modal-actions').forEach(el => el.remove());
      SHOOT_READ_BACK_IDS.forEach(id => {
        const el = copy.querySelector(`#${id}`);
        if (!el) return;
        const { display, flexDirection, flexWrap, gap } = getComputedStyle(document.getElementById(id));
        Object.assign(el.style, { display, flexDirection, flexWrap, gap });
        el.removeAttribute('id');
      });
    });
  }

  // Scrolls to a section (the first one is the top of the page). opts.turn:
  // asked for by a tap, so it glides there.
  function showShootPage(id, opts = {}) {
    const pages = ed.availableShootPages();
    if (!pages.some(p => p.id === id)) {
      if (!opts.orFirst) return;
      id = pages[0].id;
    }
    ed.shootWanted = null;
    ed.shootPageId = id;
    ed.shootSub = 0;
    if (ed.currentShootId) ed.shootPageMemory[ed.currentShootId] = { id, sub: 0 };
    ed.shootPageEls.forEach(({ el }) => el.classList.remove('nb-off'));
    ed.drawShootSub();
    ed.drawShootPageNumber();
    ed.updateShootRunningHead();
    // Boxes that were out of sight may have measured nothing.
    ed.autoSizeAllListTextareas();
    ed.syncAllShootFormFields();
    const modal = ed.shootModalOverlay.querySelector('.modal');
    const head = document.getElementById(id);
    const top = id === pages[0].id || !head ? 0
      : modal.scrollTop + head.getBoundingClientRect().top - modal.getBoundingClientRect().top - parseFloat(getComputedStyle(modal).paddingTop);
    modal.scrollTo({ top: Math.max(0, top), behavior: opts.turn && ed.motionOk() ? 'smooth' : 'auto' });
    if (ed.shootBreakWatch) ed.shootBreakWatch.takeRecords();
  }

  // Scrolled by hand: the section at the top of the page is the one it's on.
  (function followShootScroll() {
    const modal = ed.shootModalOverlay.querySelector('.modal');
    let due = false;
    modal.addEventListener('scroll', () => {
      if (due) return;
      due = true;
      setTimeout(() => {
        due = false;
        if (ed.shootModalOverlay.hidden || ed.shootWizardActive || ed.shootWizardPendingId) return;
        const line = modal.getBoundingClientRect().top + modal.clientHeight / 3;
        let on = null;
        ed.availableShootPages().forEach(({ id }) => {
          const head = document.getElementById(id);
          if (head && head.getBoundingClientRect().top <= line) on = id;
        });
        on = on || ed.availableShootPages()[0].id;
        if (on === ed.shootPageId) return;
        ed.shootPageId = on;
        if (ed.currentShootId) ed.shootPageMemory[ed.currentShootId] = { id: on, sub: 0 };
        ed.drawShootPageNumber();
      }, 120);
    }, { passive: true });
  })();

  ed.shootForm.addEventListener('input', (e) => { if (e.target.id === 'shootTitle') ed.updateShootRunningHead(); });
  // Anything that adds to a page or takes from it breaks the pages again.
  ed.shootBreakWatch = new MutationObserver((records) => {
    ed.noteShootChanges(records);
    ed.queueShootBreak();
  });
  ed.shootBreakWatch.observe(ed.shootForm, { subtree: true, childList: true, attributes: true, attributeFilter: ['hidden'] });
  // Only a field that really changed is followed; helpers and the expand popup fire input too.
  ed.shootForm.addEventListener('input', (e) => {
    if (ed.shootBreakChanged[ed.shootBreakChanged.length - 1] !== e.target) ed.shootBreakChanged.push(e.target);
  });
  ed.shootForm.addEventListener('focusout', () => ed.queueShootBreak(250));
  // Reflection comes and goes with the status: the page count follows, and if its
  // page is the open one when it goes, the book falls back to the first page.
  new MutationObserver(() => {
    if (ed.shootModalOverlay.hidden) return;
    if (document.getElementById('postShootContent').hidden && ed.shootPageId === 'postShootHeading') showShootPage('basicInfoHeading');
    else { ed.queueShootBreak(); ed.drawShootPageNumber(); }
  }).observe(document.getElementById('postShootContent'), { attributes: true, attributeFilter: ['hidden'] });

  // The bottom bar stands in for the buttons that used to sit on the page.
  // They're still there (hidden) and still decide when they apply, so each
  // bar button simply follows its original.
  [
    ['nbBarShootMode', 'enterShootModeBtn'],
    ['nbBarComplete', 'completeShootBtn'],
    ['nbBarUnarchive', 'unarchiveShootBtn'],
  ].forEach(([barId, realId]) => {
    const barBtn = document.getElementById(barId);
    const real = document.getElementById(realId);
    const follow = () => { barBtn.hidden = real.hidden; };
    follow();
    new MutationObserver(follow).observe(real, { attributes: true, attributeFilter: ['hidden'] });
    barBtn.addEventListener('click', () => real.click());
  });
  document.getElementById('nbBarBack').addEventListener('click', () => {
    ed.shootModalOverlay.querySelector('[data-close="shoot"]').click();
  });
  (function setupShootMoreMenu() {
    const overlay = document.getElementById('shootMoreOverlay');
    const close = () => { overlay.hidden = true; };
    const share = document.getElementById('shareShootBtn');
    const del = document.getElementById('deleteShootBtn');
    document.getElementById('nbBarMore').addEventListener('click', () => {
      document.getElementById('shootMoreShareBtn').hidden = share.hidden;
      document.getElementById('shootMoreShareDivider').hidden = share.hidden;
      document.getElementById('shootMoreDeleteBtn').hidden = del.hidden;
      document.getElementById('shootMoreDeleteDivider').hidden = del.hidden;
      overlay.hidden = false;
    });
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
    document.getElementById('shootMoreCancelBtn').addEventListener('click', close);
    [['shootMoreGuideBtn', 'shootTourBtn'], ['shootMoreShareBtn', 'shareShootBtn'], ['shootMoreDeleteBtn', 'deleteShootBtn']].forEach(([menuId, realId]) => {
      document.getElementById(menuId).addEventListener('click', () => {
        close();
        document.getElementById(realId).click();
      });
    });
  })();
};
;

// ---- pages/new-shoot/wizard-steps.js ----
// The new-shoot guide ("Guide me through this shoot"): its steps.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addNewShootWizardSteps = function addNewShootWizardSteps(ed) {
  Object.assign(ed, { shootFieldHasText });
  // ---------- "Guide me through this shoot" ----------
  // In the shoot's ⋯ menu (setupShootMoreMenu): opens the new-shoot guide
  // again on the shoot that's open (user, 11-12), for when it was closed
  // early. The same steps from the first one, over what's already filled in.
  document.getElementById('shootTourBtn').addEventListener('click', () => {
    if (ed.shootWizardActive || ed.shootModalOverlay.hidden) return;
    ed.closeShootModalJumpMenu();
    ed.startShootWizard({ again: true });
  });

  // ---------- New-shoot planning wizard ----------
  // A brand-new shoot opens with a step-by-step popup over the dimmed page —
  // a few fields per slide, like an installer, instead of the whole form at
  // once. Each slide BORROWS the real field blocks from the page: they're
  // moved into the card (a comment node keeps their spot — it has no box, so
  // it adds no stray flex gap) and moved straight back when the slide changes
  // or the wizard closes. Whatever's typed therefore lands in the real form:
  // autosave, the talent/location/team popups, the mood board, Multi-day and
  // every category-driven show/hide work untouched, and the page is already
  // filled in when the wizard's done. Only openShootModal(null) starts it on
  // its own — existing shoots, "+ Add a day" copies and the rest never do —
  // and the ⋯ menu's "Guide me through this shoot" opens it again on any.
  //
  // The markup sits inside #shootForm on purpose (the form-level input/
  // change/focusout listeners and the #shootForm field styles keep applying
  // to borrowed blocks), and every popup a slide can open is a later
  // body-level overlay, so it stacks above the wizard with no z-index work.
  //
  // Slides run in this order, so reordering them is reordering this list.
  //   key        stable id; the current slide is tracked by key because a
  //              category change on slide 1 adds/removes slides around it
  //   title      string, or a function read on every render
  //   hint       optional — a line under the title (string or function)
  //   blocks()   the page elements to borrow, resolved from field ids while
  //              they're back in place on the page
  //   when()     optional — the slide is skipped (and not counted) if false
  //   enter()/leave() optional — after the blocks move in / after they're back

  // Shorthand for the step list: a field by id, or the block around it.
  function shootWizardBlock(fieldId, selector) {
    const el = document.getElementById(fieldId);
    if (!el) return null;
    return selector ? el.closest(selector) : el;
  }

  function shootFieldHasText(fieldId) {
    return ed.hasText(document.getElementById(fieldId).value);
  }

  const SHOOT_WIZARD_STEPS = [
    {
      key: 'basics',
      title: 'The basics',
      blocks: () => [
        shootWizardBlock('shootStatus', '.status-swatch-wrap'),
        shootWizardBlock('shootTitle', 'label'),
        shootWizardBlock('shootCategory', 'label'),
      ],
    },
    {
      key: 'talent',
      title: 'Talent',
      hint: "Who's in front of the camera? Add each person, with their handles and a photo if you have one.",
      blocks: () => [shootWizardBlock('addTalentBtn', '.talents-section')],
    },
    {
      key: 'when',
      title: 'Date & time',
      // Last day and the video call times keep showing/hiding themselves.
      blocks: () => [
        shootWizardBlock('shootDate', 'label'),
        shootWizardBlock('multiDayRow'),
        shootWizardBlock('multiDayLastDayLabel'),
        shootWizardBlock('shootStartTime', '.time-range-row'),
        shootWizardBlock('videoCallTimesRow'),
      ],
    },
    {
      key: 'location',
      title: 'Location',
      hint: "Where it's happening, and anything people need to know to find it.",
      blocks: () => [
        shootWizardBlock('shootLocationBtn', 'label'),
        shootWizardBlock('shootLocationDirections', 'label'),
      ],
    },
    {
      key: 'team',
      title: 'Team',
      hint: "Is anyone helping out? Add each person once you know who's on board.",
      blocks: () => [shootWizardBlock('teamBody')],
    },
    {
      key: 'goals',
      title: 'Goals',
      hint: () => (ed.isVideoCategory(document.getElementById('shootCategory').value)
        ? "Be concrete and specific with what you and everyone involved should hope to expect from the shoot, and what you're delivering at the end."
        : 'Be concrete and specific with what you and everyone involved should hope to expect from the shoot.'),
      blocks: () => [
        shootWizardBlock('shootGoals', 'label'),
        shootWizardBlock('videoDeliverablesBlock'),
      ],
      // "Last time" under the goals: the lessons from the newest finished
      // shoot of this same kind, if there's one (see showLastTimeNote).
      enter: () => ed.showGoalsLastTimeNote(),
      leave: () => ed.clearLastTimeNotes(document.getElementById('shootWizardBody')),
    },
    {
      key: 'idea',
      title: 'The idea',
      hint: 'The concept and a one-line pitch. The button below can ask you a few questions and fill this in from your answers.',
      blocks: () => [
        // "Need to think it through?" — walks through a few questions and
        // writes the concept and pitch (and, on narrative shoots, The
        // story's two boxes). Sits just above Concept on the page too.
        shootWizardBlock('conceptHelperBtn'),
        shootWizardBlock('shootPremise', 'label'),
        shootWizardBlock('shootElevatorPitch', 'label'),
      ],
      // Not for events, which have no concept or pitch (see
      // updateCategoryTierUI).
      when: () => ed.categoryHasConcept(document.getElementById('shootCategory').value),
    },
    {
      key: 'story',
      title: 'The story',
      hint: "Who the talent is being, and the world they're in.",
      blocks: () => [shootWizardBlock('narrativeFieldsBlock')],
      // Narrative categories only — the same switch that shows these fields
      // on the page (updateCategoryTierUI), where a blank category counts as
      // narrative too.
      when: () => !document.getElementById('narrativeFieldsBlock').hidden,
    },
    // Visual language isn't asked here (user, 11-12): its tags stay on the
    // shoot page. The mood board comes before References (user, 11-12).
    {
      key: 'moodboard',
      // Mood board or Storyboard, by category — same wording as the section.
      title: () => ed.moodboardTerm(document.getElementById('shootCategory').value),
      hint: () => {
        const term = ed.moodboardTerm(document.getElementById('shootCategory').value).toLowerCase();
        return document.getElementById('moodboardCompleteRow').hidden
          ? `Images that set the look. Add a few now, or come back to the ${term} later.`
          : `Images that set the look. Tick the box once the ${term} is done, or if this shoot doesn't need one.`;
      },
      // Anchored on the grid: Final images shares the .moodboard-section class.
      blocks: () => [shootWizardBlock('moodboardGrid', '.moodboard-section')],
    },
    {
      key: 'references',
      title: 'References',
      hint: "Anything you're drawing inspiration from. Add as many links as you like.",
      blocks: () => [shootWizardBlock('referencesList', '.references-block')],
    },
    {
      key: 'lighting',
      title: 'Lighting setups',
      hint: 'Plan the light you want, one setup at a time.',
      // The section's body only — its heading stays on the page with the
      // jump menu/scrollspy/tour anchors. Shown here even if folded there.
      blocks: () => [shootWizardBlock('lightingSetupsBody')],
      // Every setup card open while it's here (see renderLightingSetups).
      enter: () => ed.renderLightingSetups(),
      leave: () => ed.renderLightingSetups(),
    },
    {
      key: 'shotList',
      title: 'Shot list',
      hint: 'Every shot you want to come away with. Tap a line to write, and Enter starts the next one.',
      // Its own pieces rather than the whole section body: Directions for
      // talent/team live in the same section on the page but get their own
      // slide, right after this one.
      blocks: () => [
        shootWizardBlock('shotListItems'),
        shootWizardBlock('addShotBtn'),
        shootWizardBlock('shootShootingNotes', 'label'),
      ],
    },
    {
      key: 'directions',
      title: 'Directions',
      // On a "Just me" shoot (the Team slide's answer) Directions for team
      // stays hidden here like on the page (updateTeamRequiredUI), so the
      // hint only mentions the talent.
      hint: () => (ed.getTeamRequiredChoice() === 'no'
        ? "Notes for the day: what you'll ask of the talent."
        : "Notes for the day: what you'll ask of the talent, and what the team needs to know."),
      blocks: () => [
        shootWizardBlock('shootTalentDirections', 'label'),
        shootWizardBlock('shootTeamDirections', 'label'),
      ],
    },
    {
      key: 'deadline',
      title: 'Deadline',
      hint: "When everything's due, if there's a date to hit.",
      blocks: () => [shootWizardBlock('shootDeadline', 'label')],
    },
    {
      key: 'finish',
      title: 'All set',
      hint: 'Everything you filled in is already on the shoot page. Add to it or change it there anytime.',
      blocks: () => [],
    },
  ]; ed.SHOOT_WIZARD_STEPS = SHOOT_WIZARD_STEPS;
};
;

// ---- pages/new-shoot/wizard.js ----
// The new-shoot guide: going through its steps.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addNewShootWizard = function addNewShootWizard(ed) {
  Object.assign(ed, { adjacentShootWizardStep, blurShootWizardFocus, restoreShootWizardBlocks, refreshShootWizard, showShootWizardStep, syncShootWizardViewport, setShootPageInert, startShootWizard, queueShootWizard, startQueuedShootWizard });
  // The slides that currently apply (the one on screen always counts, so the
  // "Step x of y" line can never lose its own place).
  function shootWizardStepsInPlay() {
    return ed.SHOOT_WIZARD_STEPS.filter(step => step.key === ed.shootWizardStepKey || !step.when || step.when());
  }

  // The nearest slide that applies before (-1) or after (+1) the current
  // one, or null at either end. Re-evaluated every time, since slide 1's
  // category decides whether The story applies at all.
  function adjacentShootWizardStep(direction) {
    const from = ed.SHOOT_WIZARD_STEPS.findIndex(step => step.key === ed.shootWizardStepKey);
    for (let i = from + direction; i >= 0 && i < ed.SHOOT_WIZARD_STEPS.length; i += direction) {
      const step = ed.SHOOT_WIZARD_STEPS[i];
      if (!step.when || step.when()) return step;
    }
    return null;
  }

  // Before anything moves: a focused field that's moved loses focus without
  // a focusout (so without its saveShootNow), and iOS never blurs a field
  // when a button is tapped. Blurring also drops the keyboard/native picker.
  function blurShootWizardFocus() {
    const active = document.activeElement;
    if (active && active !== document.body && document.getElementById('shootWizard').contains(active)) active.blur();
  }

  function moveBlockIntoShootWizard(el, body) {
    if (!el || body.contains(el)) return;
    const placeholder = document.createComment('shoot-wizard');
    el.before(placeholder);
    [el, ...el.querySelectorAll('.pg-off, .pg-first')].forEach(node => node.classList.remove('pg-off', 'pg-first'));
    const record = { el, placeholder, unlocked: [], wasInert: el.inert };
    // A block that sits directly under #shootForm (Team, Shot list) was made
    // inert itself along with the rest of the covered page — it has to come
    // alive in the card, then go back to how it was on the page.
    el.inert = false;
    // On the page these open the expand popup instead of taking typing (see
    // its click guard); a slide has the room to type in place.
    el.querySelectorAll('textarea[readonly]').forEach(field => {
      field.readOnly = false;
      record.unlocked.push(field);
    });
    body.appendChild(el);
    ed.shootWizardMoved.push(record);
  }

  function restoreShootWizardBlocks() {
    ed.shootWizardMoved.forEach(({ el, placeholder, unlocked, wasInert }) => {
      unlocked.forEach(field => { field.readOnly = true; });
      el.inert = wasInert;
      if (placeholder.parentNode) placeholder.replaceWith(el);
    });
    ed.shootWizardMoved = [];
    const step = ed.SHOOT_WIZARD_STEPS.find(s => s.key === ed.shootWizardStepKey);
    if (step && step.leave) step.leave();
  }

  function renderShootWizardChrome() {
    const step = ed.SHOOT_WIZARD_STEPS.find(s => s.key === ed.shootWizardStepKey);
    if (!step) return;
    const inPlay = shootWizardStepsInPlay();
    const isLast = !adjacentShootWizardStep(1);
    document.getElementById('shootWizardStep').textContent = `Step ${inPlay.indexOf(step) + 1} of ${inPlay.length}`;
    document.getElementById('shootWizardTitle').textContent = typeof step.title === 'function' ? step.title() : step.title;
    const hintEl = document.getElementById('shootWizardHint');
    hintEl.textContent = (typeof step.hint === 'function' ? step.hint() : step.hint) || '';
    // A slide without a hint doesn't keep an empty line's spacing.
    hintEl.hidden = !hintEl.textContent;
    // No Back on the first slide, nor on the last: that one is just the
    // confirm button (see below).
    document.getElementById('shootWizardBackBtn').hidden = isLast || !adjacentShootWizardStep(-1);
    // Small "Don't show again" link, on the first slide only, and not when
    // the guide was asked for from the ⋯ menu.
    document.getElementById('shootWizardDontShowBtn').hidden = inPlay.indexOf(step) !== 0 || ed.shootWizardAgain;
    // Forward is always possible, filled in or not. On the last slide the
    // forward button is the shoot page's own Save — same varying text as the
    // page's button (picked when the shoot opened) — and the separate "Skip
    // to shoot page" row, on every other slide, steps aside.
    const nextBtn = document.getElementById('shootWizardNextBtn');
    nextBtn.textContent = isLast ? document.getElementById('saveShootBtn').textContent : 'Next';
    nextBtn.classList.toggle('shoot-wizard-save', isLast);
    document.getElementById('shootWizardExitRow').hidden = isLast;
  }

  // Run from scheduleShootAutosave on every change while the wizard's up.
  function refreshShootWizard() {
    renderShootWizardChrome();
    // Values written from code fire no input event, so they'd keep their
    // empty-field look on the slide — a picked location's remembered
    // directions, for one. Only fields whose look is actually out of step get
    // re-synced: re-measuring every box on each keystroke can briefly shrink
    // the card's content and knock its scroll position.
    document.querySelectorAll('#shootWizardBody input, #shootWizardBody textarea').forEach(el => {
      if (el !== document.activeElement && ed.isBoxSheddingField(el) && el.classList.contains('is-filled') !== ed.hasText(el.value)) ed.syncFieldFilledState(el);
    });
  }

  function showShootWizardStep(key) {
    const step = ed.SHOOT_WIZARD_STEPS.find(s => s.key === key);
    if (!step) return;
    blurShootWizardFocus();
    restoreShootWizardBlocks();
    ed.shootWizardStepKey = key;
    const body = document.getElementById('shootWizardBody');
    step.blocks().forEach(block => moveBlockIntoShootWizard(block, body));
    if (step.enter) step.enter();
    body.scrollTop = 0;
    renderShootWizardChrome();
    // Measured now, at the card's width, with the wizard already visible — a
    // hidden one would measure zero and leave every box at its rows default.
    body.querySelectorAll('input, textarea').forEach(ed.syncFieldFilledState);
    ed.autoSizeAllListTextareas();
    // The card, not a field: focusing a field on every slide would throw the
    // keyboard up over the slide before it's even been read.
    document.getElementById('shootWizardCard').focus({ preventScroll: true });
  }

  // Fits the wizard to the part of the screen that's actually visible, so
  // with the iOS keyboard up the card re-centres above it instead of sitting
  // behind it (iOS doesn't shrink the layout viewport). A visible height well
  // under the tallest seen this run means the keyboard's up: compact mode.
  function syncShootWizardViewport() {
    const wizard = document.getElementById('shootWizard');
    const vv = window.visualViewport;
    const height = vv ? vv.height : window.innerHeight;
    ed.shootWizardViewportMaxH = Math.max(ed.shootWizardViewportMaxH, height);
    if (vv) {
      wizard.style.setProperty('--wiz-vv-top', `${vv.offsetTop}px`);
      // With no keyboard up, the dim runs to the real bottom of the screen.
      const keyboardUp = height < ed.shootWizardViewportMaxH * 0.8;
      wizard.style.setProperty('--wiz-vv-h', `${keyboardUp ? vv.height : Math.min(vv.height + ed.screenGap, ed.screenHeightNow())}px`);
    }
    // Also compact outright on a short screen (an iPhone on its side), where
    // the full step line + hint + buttons alone would leave no room for fields.
    wizard.classList.toggle('shoot-wizard-compact', height < ed.shootWizardViewportMaxH * 0.8 || height < 560);
  }

  // The covered page can't take focus while the wizard's up. The wizard is
  // last in the form, so every page field comes before a slide's fields in
  // document order: iOS's keyboard ^/v arrows (or Tab) from a slide's first
  // field would land in a field hidden behind the dim and type into it
  // unseen, or reach Save/Delete/Shoot mode/the tour. Every popup a slide
  // opens is a body-level overlay, so none of them is affected.
  function setShootPageInert(on) {
    const modalEl = ed.shootModalOverlay.querySelector('.modal');
    [...modalEl.children, ...ed.shootForm.children, ed.shootModalOverlay.querySelector('.nb-page-foot'), ed.shootModalOverlay.querySelector('.nb-screen-tabs-shoot'), ed.shootModalOverlay.querySelector('.nb-shoot-bar')].forEach(el => {
      if (el !== ed.shootForm && el.id !== 'shootWizard') el.inert = on;
    });
  }

  function startShootWizard(opts) {
    const first = ed.SHOOT_WIZARD_STEPS.find(step => !step.when || step.when());
    if (!first) return;
    ed.shootWizardActive = true;
    ed.shootWizardAgain = !!(opts && opts.again);
    ed.shootWizardStepKey = null;
    ed.shootWizardViewportMaxH = 0;
    // Slide 1 explains the status button itself, so the one-time intro that
    // points at it "up top" is marked seen rather than stacking over the
    // wizard now, or turning up later to repeat it.
    try { localStorage.setItem(ed.STATUS_SWATCH_INTRO_KEY, '1'); } catch (err) { /* storage unavailable — nothing to remember it in */ }
    // The covered page holds still: only the card scrolls. Doesn't clip the
    // fixed wizard (its containing block is the viewport), and code can
    // still set scrollTop.
    ed.shootModalOverlay.querySelector('.modal').style.overflow = 'hidden';
    // The steps borrow blocks from the page: none may arrive hidden.
    ed.shootForm.querySelectorAll('.pg-off, .pg-first').forEach(el => el.classList.remove('pg-off', 'pg-first'));
    setShootPageInert(true);
    document.getElementById('shootWizard').hidden = false;
    syncShootWizardViewport();
    if (window.visualViewport) {
      window.visualViewport.addEventListener('resize', syncShootWizardViewport);
      window.visualViewport.addEventListener('scroll', syncShootWizardViewport);
    }
    showShootWizardStep(first.key);
  }

  // The shoot modal slides up on a transform for its first 0.2s, and while
  // that runs it's the containing block for anything position:fixed inside
  // it — a wizard shown straight away would sit inside the moving sheet,
  // clipped, then jump to full screen. So it waits for the slide-in's own
  // animationend (wired below), with a timer as the fallback for when none
  // comes: the overlay was already open, or the tab is in the background
  // (rAF and CSS animations stall there, timers don't).
  function queueShootWizard() {
    ed.shootWizardPendingId = ed.currentShootId;
    clearTimeout(ed.shootWizardStartTimer);
    ed.shootWizardStartTimer = setTimeout(startQueuedShootWizard, 320);
  }

  function startQueuedShootWizard() {
    const pendingId = ed.shootWizardPendingId;
    ed.shootWizardPendingId = null;
    clearTimeout(ed.shootWizardStartTimer);
    if (!pendingId || pendingId !== ed.currentShootId || ed.shootModalOverlay.hidden || ed.shootWizardActive) return;
    startShootWizard();
  }
};
;

// ---- pages/new-shoot/wizard-end.js ----
// The new-shoot guide: finishing or leaving it, and turning it on or off.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addNewShootWizardEnd = function addNewShootWizardEnd(ed) {
  Object.assign(ed, { endShootWizard, isNewShootGuideOn, setNewShootGuideOn });
  // Every way out: Done, "Skip to shoot page", the post-shoot prompt's Yes,
  // closeShootModal and openShootModal. Idempotent. `closing` skips the
  // landing-on-the-page work, since a close/reopen does its own next.
  function endShootWizard(opts) {
    const closing = !!(opts && opts.closing);
    ed.shootWizardPendingId = null;
    clearTimeout(ed.shootWizardStartTimer);
    if (!ed.shootWizardActive) return;
    closeLeaveShootWizardPrompt();
    ed.closeConceptHelper();
    ed.blurShootWizardFocus();
    ed.restoreShootWizardBlocks();
    ed.shootWizardActive = false;
    ed.shootWizardAgain = false;
    ed.shootWizardStepKey = null;
    const wizard = document.getElementById('shootWizard');
    wizard.hidden = true;
    wizard.classList.remove('shoot-wizard-compact');
    ed.setShootPageInert(false);
    if (window.visualViewport) {
      window.visualViewport.removeEventListener('resize', ed.syncShootWizardViewport);
      window.visualViewport.removeEventListener('scroll', ed.syncShootWizardViewport);
    }
    const modalEl = ed.shootModalOverlay.querySelector('.modal');
    modalEl.style.overflow = '';
    if (closing) return;
    // Everything was last measured at the card's width; the page is wider.
    ed.syncAllShootFormFields();
    ed.autoSizeAllListTextareas();
    // Instant, not smooth: smooth scrolling doesn't run in a background tab.
    modalEl.scrollTop = 0;
    ed.updateShootModalTitleFromScroll();
    ed.breakShootPages();
  }

  document.getElementById('shootWizardBackBtn').addEventListener('click', () => {
    if (!ed.shootWizardActive) return;
    const prev = ed.adjacentShootWizardStep(-1);
    if (prev) ed.showShootWizardStep(prev.key);
  });

  document.getElementById('shootWizardNextBtn').addEventListener('click', () => {
    if (!ed.shootWizardActive) return;
    const next = ed.adjacentShootWizardStep(1);
    if (next) ed.showShootWizardStep(next.key);
    // The last slide's button is Save: save and close, like the page's.
    else ed.closeShootModal();
  });

  // Leaving early always asks first — from "Skip to shoot page" or a tap on
  // the dim around the card. (Finishing on the last slide, or "Don't show
  // again", don't: those say what they do.)
  function askLeaveShootWizard() {
    if (!ed.shootWizardActive) return;
    document.getElementById('shootWizardLeaveOverlay').hidden = false;
  }

  function closeLeaveShootWizardPrompt() {
    document.getElementById('shootWizardLeaveOverlay').hidden = true;
  }

  document.getElementById('shootWizardExitBtn').addEventListener('click', askLeaveShootWizard);

  // Only a tap that both starts and ends on the dim: with a mouse, a text
  // selection dragged out past the card's edge also "clicks" the backdrop.
  let shootWizardPressOnBackdrop = false;
  document.getElementById('shootWizard').addEventListener('pointerdown', (e) => {
    shootWizardPressOnBackdrop = e.target === e.currentTarget;
  });
  document.getElementById('shootWizard').addEventListener('click', (e) => {
    if (e.target === e.currentTarget && shootWizardPressOnBackdrop) askLeaveShootWizard();
    shootWizardPressOnBackdrop = false;
  });

  document.getElementById('shootWizardLeaveStayBtn').addEventListener('click', closeLeaveShootWizardPrompt);

  document.getElementById('shootWizardLeaveGoBtn').addEventListener('click', () => {
    closeLeaveShootWizardPrompt();
    endShootWizard();
  });

  document.getElementById('shootWizardLeaveOverlay').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) closeLeaveShootWizardPrompt();
  });

  // On/off for the whole guide, remembered on this device. Turned off from
  // the first slide's "Don't show again", and back on (or off) from the App
  // options' New shoot guide switch.
  const NEW_SHOOT_GUIDE_OFF_KEY = 'dailies_new_shoot_guide_off_v1';

  function isNewShootGuideOn() {
    try { return localStorage.getItem(NEW_SHOOT_GUIDE_OFF_KEY) !== '1'; } catch (err) { return true; }
  }

  function setNewShootGuideOn(on) {
    try {
      if (on) localStorage.removeItem(NEW_SHOOT_GUIDE_OFF_KEY);
      else localStorage.setItem(NEW_SHOOT_GUIDE_OFF_KEY, '1');
    } catch (err) { /* storage unavailable — nothing to remember it in */ }
  }
};
;

// ---- pages/concept-helper/helper.js ----
// "Need to think it through?": the flow for this shoot, and its answers.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addConceptHelperHelper = function addConceptHelperHelper(ed) {
  Object.assign(ed, { conceptHelperCategory, conceptHelperCategoryLabel, conceptFlowFor, conceptHelperNode, conceptHelperDeeperStart, conceptHelperShownOutputs, fillConceptHelperOutputs, updateConceptHelperCount });
  // Lands on the shoot page with everything so far, then says where the
  // switch lives so the guide isn't gone for good by accident.
  // ---------- Concept helper ("Need to think it through?") ----------
  // From The idea slide and the Direction section: a short decision tree of
  // yes/no and short-answer questions, picked by the shoot's category
  // (CONCEPT_FLOWS), whose answers are dropped mad-lib style into a concept
  // and an elevator pitch at the end — plus Character/Personality and
  // World-building notes on shoots that have those boxes, if the user opts
  // into a few more questions. Each is editable, then either used to fill
  // the page's fields or left for the user to write their own.
  //
  // Flow format: { id, label, categories (keys; '' = no category yet),
  // start, nodes: [{ id, type: 'yesno'|'short', text, hint?, placeholder?,
  // key, yes/no (yesno: next id or 'END'), yesValue/noValue? (stored instead
  // of true/false), yesLabel/noLabel? (the buttons' text when the question
  // is a choice between two things rather than a yes or no), next (short),
  // categoryText? ({category: text}), section? ('deeper') }],
  // deeper?: [{ when, start }],
  // summaries: [{ when: {key: value}, template, pitch?, character?, world? }] }
  // — the first summary whose `when` all match is used. Templates: {key}
  // inserts an answer, {category} the shoot type, and [[ ... ]] is dropped
  // whole if any {key} in it is blank. pitch/character/world are lists of
  // templates (see conceptHelperPick). `deeper` is where the main questions
  // hand over, when they run out, to the opt-in Character/World ones
  // (section 'deeper': a yes/no gate keyed `deeper`, then its questions) —
  // only on shoots whose page shows those two boxes.
  ed.conceptHelper = null; // { flow, nodeId, history: [nodeId], answers: {nodeId: value}, ended }

  // The end screen's boxes, each filling the page field of the same name.
  // Each box is checked against its field's own limit, so a compiled text
  // that won't fit is caught there (see updateConceptHelperCount) rather
  // than cut off by the field.
  const CONCEPT_HELPER_OUTPUTS = [
    { key: 'concept', boxId: 'conceptHelperSummary', countId: 'conceptHelperCount', fieldId: 'shootPremise', label: 'Concept', fallbackMax: 300 },
    { key: 'character', boxId: 'conceptHelperCharacter', countId: 'conceptHelperCharacterCount', fieldId: 'shootCharacter', label: 'Character/Personality', fallbackMax: 1000 },
    { key: 'world', boxId: 'conceptHelperWorld', countId: 'conceptHelperWorldCount', fieldId: 'shootWorldNotes', label: 'World-building notes', fallbackMax: 1000 },
    { key: 'pitch', boxId: 'conceptHelperPitch', countId: 'conceptHelperPitchCount', fieldId: 'shootElevatorPitch', label: 'Elevator pitch', fallbackMax: 150 },
  ]; ed.CONCEPT_HELPER_OUTPUTS = CONCEPT_HELPER_OUTPUTS;
  const conceptHelperMax = (out) => document.getElementById(out.fieldId).maxLength || out.fallbackMax; ed.conceptHelperMax = conceptHelperMax;

  // The questions behind "Need to think it through?" — one flow per kind of
  // shoot (see the format notes above openConceptHelper), each leaning on
  // what that kind of shoot actually is: story vs vibe for narrative work,
  // the people and their relationship for engagements/family/maternity, a
  // theme rather than a plot for events (you don't control what happens),
  // message/audience/personality for brand work, and so on. '' in a flow's
  // categories = the one used before a category's been picked.
  const CONCEPT_FLOWS = window.EyeWords.conceptFlows; ed.CONCEPT_FLOWS = CONCEPT_FLOWS;


  function conceptHelperCategory() {
    return document.getElementById('shootCategory').value || '';
  }

  function conceptHelperCategoryLabel() {
    const cat = conceptHelperCategory();
    if (!cat || !ed.CATEGORY_LABELS[cat]) return 'shoot';
    // "editorial shoot", but "test shoot" rather than "test shoot shoot".
    const label = ed.CATEGORY_LABELS[cat].toLowerCase();
    return /\bshoot$/.test(label) ? label : `${label} shoot`;
  }

  function conceptFlowFor(category) {
    return CONCEPT_FLOWS.find(f => f.categories.includes(category))
      || CONCEPT_FLOWS.find(f => f.categories.includes(''))
      || CONCEPT_FLOWS[0];
  }

  function conceptHelperNode(id) {
    return ed.conceptHelper.flow.nodes.find(n => n.id === id) || null;
  }

  // Answers along the path actually taken (history + current), by key — so
  // an answer from a branch the user backed out of never leaks into the
  // summary.
  function conceptHelperAnswers() {
    const out = {};
    [...ed.conceptHelper.history, ed.conceptHelper.nodeId].forEach(id => {
      const node = id && conceptHelperNode(id);
      if (node && Object.prototype.hasOwnProperty.call(ed.conceptHelper.answers, id)) out[node.key] = ed.conceptHelper.answers[id];
    });
    return out;
  }

  // A short answer that means "nothing" ("no" to "Any era, movie or
  // reference…?") — treated as left blank rather than written in.
  const CONCEPT_HELPER_NONE = /^(no|nope|nah|none|nothing|not really|not sure|idk|n\/?a|-+)$/i; ed.CONCEPT_HELPER_NONE = CONCEPT_HELPER_NONE;

  // What {key} stands for: the answer, trimmed of its closing punctuation —
  // '' when it's blank, a "nothing" answer or a plain yes/no.
  function conceptHelperValue(key, answers) {
    if (key === 'category') return conceptHelperCategoryLabel();
    const v = answers[key];
    if (typeof v !== 'string') return '';
    const text = v.trim().replace(/[.!?…]+$/, '');
    return CONCEPT_HELPER_NONE.test(text) ? '' : text;
  }

  // Where-answers that bring their own preposition ("on a rooftop", "at the
  // beach") take the place of the template's "in"/"at"/"on", rather than
  // reading "at at the beach".
  const CONCEPT_HELPER_PLACE_KEYS = /\b(in|at|on)\s+\{(world|place|setting)\}/gi;
  const CONCEPT_HELPER_HAS_PREPOSITION = /^(in|at|on|inside|outside|by|near|under|underneath|beneath|over|across|around|aboard|along|off|behind|beside|within|atop|up|down|through|from)\b/i;

  function conceptHelperFill(template, answers) {
    const value = (key) => conceptHelperValue(key, answers);
    let text = template.replace(CONCEPT_HELPER_PLACE_KEYS, (match, prep, key) => (
      CONCEPT_HELPER_HAS_PREPOSITION.test(value(key)) ? `{${key}}` : match));
    text = text.replace(/\[\[([\s\S]*?)\]\]/g, (_, inner) => {
      const keys = [...inner.matchAll(/\{(\w+)\}/g)].map(m => m[1]);
      return keys.every(k => value(k)) ? inner : '';
    });
    text = text.replace(/\{(\w+)\}/g, (_, k) => value(k));
    text = text.replace(/\s+/g, ' ').replace(/\s+([,.;:!?])/g, '$1').replace(/([,;:])\1+/g, '$1')
      .replace(/,\s*\./g, '.').replace(/…\./g, '.').replace(/\.{2,}/g, '.').trim();
    // A template whose opening segment was dropped (", caught …", ". When:
    // …") would otherwise start on that segment's leftover punctuation.
    text = text.replace(/^[\s,;:.]+/, '');
    if (!text) return '';
    text = text.charAt(0).toUpperCase() + text.slice(1);
    if (!/[.!?]$/.test(text)) text += '.';
    return text;
  }

  // The answers a template actually gets to use: the keys in the [[ ... ]]
  // segments that survive, plus any bare {key} that's filled.
  function conceptHelperFilledKeys(template, answers) {
    const keys = new Set();
    for (const [, inner] of template.matchAll(/\[\[([\s\S]*?)\]\]/g)) {
      const segKeys = [...inner.matchAll(/\{(\w+)\}/g)].map(m => m[1]);
      if (segKeys.every(k => conceptHelperValue(k, answers))) segKeys.forEach(k => keys.add(k));
    }
    const bare = template.replace(/\[\[[\s\S]*?\]\]/g, '');
    for (const [, k] of bare.matchAll(/\{(\w+)\}/g)) {
      if (conceptHelperValue(k, answers)) keys.add(k);
    }
    keys.delete('category');
    return keys;
  }

  // A summary's pitch/character/world: a few templates, fullest first, the
  // shorter ones there for long answers. Picks the one that uses the most
  // answers and still fits `max` (the earliest on a tie) — or, if none fits,
  // the shortest, which its box's count then flags. One that uses no answer
  // at all ("Their wedding day.") says nothing, so it's never picked; nor,
  // given `requireKeys`, one that uses none of those.
  function conceptHelperPick(templates, answers, max, requireKeys) {
    const results = [].concat(templates || [])
      .map(t => {
        const keys = conceptHelperFilledKeys(t, answers);
        return { text: conceptHelperFill(t, answers), used: keys.size, keys };
      })
      .filter(r => r.text && r.used > 0 && (!requireKeys || [...r.keys].some(k => requireKeys.has(k))));
    const fits = results.filter(r => r.text.length <= max);
    if (fits.length) return fits.reduce((best, r) => (r.used > best.used ? r : best)).text;
    return results.length ? results.reduce((a, b) => (b.text.length < a.text.length ? b : a)).text : '';
  }

  // Character/Personality and World-building notes are only on the page for
  // narrative categories (see updateCategoryTierUI).
  function conceptHelperHasStoryFields() {
    return !document.getElementById('narrativeFieldsBlock').hidden;
  }

  // Where the opt-in Character/World questions start once the main ones run
  // out — null if they've already been reached, the page has no boxes for
  // them, or the flow has none for the path taken.
  function conceptHelperDeeperStart() {
    const h = ed.conceptHelper;
    if (!h.flow.deeper || !conceptHelperHasStoryFields()) return null;
    const inDeeper = [...h.history, h.nodeId].some(id => {
      const node = id && conceptHelperNode(id);
      return node && node.section === 'deeper';
    });
    if (inDeeper) return null;
    const answers = conceptHelperAnswers();
    const match = h.flow.deeper.find(d => Object.entries(d.when || {}).every(([key, val]) => answers[key] === val));
    return match && conceptHelperNode(match.start) ? match.start : null;
  }

  function conceptHelperOutputEl(out) {
    return document.getElementById(out.boxId).closest('.concept-helper-output');
  }

  function conceptHelperShownOutputs() {
    return CONCEPT_HELPER_OUTPUTS.filter(out => !conceptHelperOutputEl(out).hidden);
  }

  // Compiles every box for the path taken. Character/World only once the
  // user's said yes to their questions and actually answered one of them —
  // otherwise all they'd hold is the Concept again. Any box but Concept
  // stays off the end screen when there's nothing to put in it.
  function fillConceptHelperOutputs() {
    const h = ed.conceptHelper;
    const answers = conceptHelperAnswers();
    const summary = h.flow.summaries.find(sum => Object.entries(sum.when || {})
      .every(([key, val]) => answers[key] === val));
    const deeperKeys = new Set([...h.history, h.nodeId]
      .map(id => id && conceptHelperNode(id))
      .filter(node => node && node.section === 'deeper' && node.type === 'short' && conceptHelperValue(node.key, answers))
      .map(node => node.key));
    const withStory = answers.deeper === true && deeperKeys.size > 0 && conceptHelperHasStoryFields();
    CONCEPT_HELPER_OUTPUTS.forEach(out => {
      let text = '';
      if (summary && out.key === 'concept') text = conceptHelperFill(summary.template, answers);
      else if (summary && out.key === 'pitch') text = conceptHelperPick(summary.pitch, answers, conceptHelperMax(out));
      else if (summary && withStory) text = conceptHelperPick(summary[out.key], answers, conceptHelperMax(out), deeperKeys);
      document.getElementById(out.boxId).value = text;
      conceptHelperOutputEl(out).hidden = out.key !== 'concept' && !text;
      // On a shoot that already has its own text there, say so — and that
      // Use this asks before replacing it (Replace / Keep mine).
      const field = document.getElementById(out.fieldId);
      conceptHelperOutputEl(out).querySelector('.concept-helper-keep').hidden = !(text && ed.hasText(field.value) && field.value.trim() !== text);
    });
  }

  function updateConceptHelperCount() {
    let over = false;
    let any = false;
    conceptHelperShownOutputs().forEach(out => {
      const len = document.getElementById(out.boxId).value.trim().length;
      const max = conceptHelperMax(out);
      const count = document.getElementById(out.countId);
      const outOver = len > max;
      count.textContent = outOver ? `${len}/${max}: trim a little to fit the ${out.label} box` : `${len}/${max}`;
      count.classList.toggle('over', outOver);
      over = over || outOver;
      any = any || len > 0;
    });
    document.getElementById('conceptHelperUseBtn').disabled = over || !any;
  }
};
;

// ---- pages/concept-helper/helper-steps.js ----
// "Need to think it through?": drawing a question, going on and back.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addConceptHelperHelperSteps = function addConceptHelperHelperSteps(ed) {
  Object.assign(ed, { renderConceptHelper, conceptHelperBlankIds, jumpConceptHelperTo, askConceptHelperLeave, closeConceptHelper });
  function renderConceptHelper() {
    const h = ed.conceptHelper;
    const show = (id, on) => { document.getElementById(id).hidden = !on; };
    const input = document.getElementById('conceptHelperInput');
    show('conceptHelperLeaveRow', !!h.leaving);
    if (h.leaving) {
      // Leaving before every question's answered (see askConceptHelperLeave).
      const blanks = conceptHelperBlankIds().length;
      const plural = blanks === 1 ? '' : 's';
      document.getElementById('conceptHelperStep').textContent = '';
      document.getElementById('conceptHelperTitle').textContent = h.leaving === 'close' ? 'Not done yet'
        : (blanks === 1 ? 'One left blank' : 'A few left blank');
      document.getElementById('conceptHelperText').textContent = h.leaving === 'close'
        ? `${blanks ? `You've left ${blanks} question${plural} blank, and there are` : 'There are'} a few more to go. If you leave now, your answers won't be kept.`
        : `You left ${blanks} question${plural} blank. Answer ${blanks === 1 ? 'it' : 'them'} for a fuller result, or go ahead without.`;
      document.getElementById('conceptHelperLeaveFirstBtn').textContent = !blanks ? 'Keep going'
        : (blanks === 1 ? 'Take me to it' : 'Go to the first one');
      document.getElementById('conceptHelperLeaveAnywayBtn').textContent = h.leaving !== 'use' ? 'Leave anyway'
        : (ed.conceptHelperShownOutputs().length > 1 ? 'Use these anyway' : 'Use this anyway');
      ['conceptHelperHint', 'conceptHelperInput', 'conceptHelperOutputs', 'conceptHelperYesNo', 'conceptHelperNextRow',
        'conceptHelperEndRow', 'conceptHelperEndNavRow', 'conceptHelperBackBtn', 'conceptHelperCloseRow'].forEach(id => show(id, false));
      return;
    }
    if (h.ended) {
      const several = ed.conceptHelperShownOutputs().length > 1;
      document.getElementById('conceptHelperStep').textContent = '';
      document.getElementById('conceptHelperTitle').textContent = "Here's your concept";
      document.getElementById('conceptHelperText').textContent = several
        ? 'Change anything you like, then use these or write your own.'
        : 'Change anything you like, then use it as your concept or write your own.';
      document.getElementById('conceptHelperUseBtn').textContent = several ? 'Use these' : 'Use this';
      show('conceptHelperHint', false);
      show('conceptHelperInput', false);
      show('conceptHelperOutputs', true);
      show('conceptHelperYesNo', false);
      show('conceptHelperNextRow', false);
      show('conceptHelperEndRow', true);
      // Back/Start over as a pair of buttons, and no Close: "Use this" and
      // "I'll write it myself" both close it already.
      show('conceptHelperEndNavRow', true);
      show('conceptHelperBackBtn', false);
      show('conceptHelperCloseRow', false);
      // Each box as tall as its text (the card scrolls), so nothing's
      // hidden inside a box of its own.
      ed.conceptHelperShownOutputs().forEach(out => ed.autoSizeTextarea(document.getElementById(out.boxId)));
      ed.updateConceptHelperCount();
      return;
    }
    const node = ed.conceptHelperNode(h.nodeId);
    const cat = ed.conceptHelperCategory();
    const text = (node.categoryText && node.categoryText[cat]) || node.text;
    document.getElementById('conceptHelperStep').textContent = `Question ${h.history.length + 1}`;
    document.getElementById('conceptHelperTitle').textContent = "Let's think it through";
    document.getElementById('conceptHelperText').textContent = text.replace(/\{category\}/g, ed.conceptHelperCategoryLabel());
    const hint = document.getElementById('conceptHelperHint');
    hint.textContent = node.hint || '';
    show('conceptHelperHint', !!node.hint);
    const isShort = node.type === 'short';
    // "Posed" / "Documentary" rather than No / Yes when it's an either/or.
    document.getElementById('conceptHelperYesBtn').textContent = node.yesLabel || 'Yes';
    document.getElementById('conceptHelperNoBtn').textContent = node.noLabel || 'No';
    show('conceptHelperInput', isShort);
    show('conceptHelperOutputs', false);
    show('conceptHelperYesNo', !isShort);
    show('conceptHelperNextRow', isShort);
    show('conceptHelperEndRow', false);
    show('conceptHelperEndNavRow', false);
    show('conceptHelperBackBtn', h.history.length > 0);
    show('conceptHelperCloseRow', true);
    if (isShort) {
      input.placeholder = node.placeholder || '';
      const prev = h.answers[h.nodeId];
      input.value = typeof prev === 'string' ? prev : '';
    }
    // Two answers side by side while both fit their half. The labels never
    // wrap (styles/concept-helper.css), so one that doesn't fit ("Documentary", or most on a
    // narrow phone) widens its button and squeezes the other — then the pair
    // stacks full width instead. A few px of slack: the white button's
    // border alone makes it ~2px wider.
    const yesNo = document.getElementById('conceptHelperYesNo');
    yesNo.classList.remove('concept-helper-choice-stacked');
    const rowWidth = yesNo.getBoundingClientRect().width;
    if (!isShort && rowWidth) {
      const half = (rowWidth - (parseFloat(getComputedStyle(yesNo).columnGap) || 0)) / 2;
      const widest = Math.max(
        document.getElementById('conceptHelperYesBtn').getBoundingClientRect().width,
        document.getElementById('conceptHelperNoBtn').getBoundingClientRect().width);
      if (widest > half + 3) yesNo.classList.add('concept-helper-choice-stacked');
    }
  }

  // Where a question leads: the next one, or — when the flow runs out — the
  // opt-in Character/World questions, or null for the end.
  function conceptHelperResolve(nextId) {
    return (!nextId || nextId === 'END' || !ed.conceptHelperNode(nextId)) ? ed.conceptHelperDeeperStart() : nextId;
  }

  // The branch a question's saved answer leads down — null when it has none
  // (or a blank one), which is where a resumed run stops.
  function conceptHelperSavedNext(node) {
    const answer = ed.conceptHelper.answers[node.id];
    if (node.type === 'short') return typeof answer === 'string' && answer.trim() ? (node.next || 'END') : null;
    if (answer === undefined) return null;
    if (answer === (node.yesValue !== undefined ? node.yesValue : true)) return node.yes || 'END';
    if (answer === (node.noValue !== undefined ? node.noValue : false)) return node.no || 'END';
    return null;
  }

  function goConceptHelper(nextId) {
    const h = ed.conceptHelper;
    h.history.push(h.nodeId);
    let id = conceptHelperResolve(nextId);
    // After "Go to the first one": straight past everything that's
    // already answered, to the next gap (or the end).
    while (id && h.resume) {
      const saved = conceptHelperSavedNext(ed.conceptHelperNode(id));
      if (!saved) break;
      h.history.push(id);
      h.nodeId = id;
      id = conceptHelperResolve(saved);
    }
    if (!id) {
      h.ended = true;
      h.resume = false;
      ed.fillConceptHelperOutputs();
    } else {
      h.nodeId = id;
    }
    renderConceptHelper();
  }

  // Questions already passed that were left empty. "None" and the like
  // count as answered — that was an answer. The question on screen isn't
  // "left" yet.
  function conceptHelperBlankIds() {
    const h = ed.conceptHelper;
    return h.history.filter((id, i) => {
      const node = ed.conceptHelperNode(id);
      const answer = h.answers[id];
      return h.history.indexOf(id) === i && node && node.type === 'short' && !(typeof answer === 'string' && answer.trim());
    });
  }

  // Back to a question, picking up from there; answering it then skips on
  // past whatever's already answered (see goConceptHelper).
  function jumpConceptHelperTo(id) {
    const h = ed.conceptHelper;
    const at = h.history.indexOf(id);
    if (at >= 0) h.history = h.history.slice(0, at);
    h.nodeId = id;
    h.ended = false;
    h.leaving = null;
    h.resume = true;
    renderConceptHelper();
  }

  // Every question's meant to be answered: leaving before the end (Close),
  // or using what's there with some left blank, asks first — with a way
  // straight to the first one that's missing.
  function askConceptHelperLeave(action) {
    const h = ed.conceptHelper;
    if (!h) return false;
    if (action === 'close' ? h.ended : !conceptHelperBlankIds().length) return false;
    const node = !h.ended && ed.conceptHelperNode(h.nodeId);
    // The box's value only means something on a short question (it keeps
    // its old text while hidden on a yes/no one).
    const typed = node && node.type === 'short' ? document.getElementById('conceptHelperInput').value.trim() : '';
    // Nothing answered yet (opened by mistake, say): nothing to lose.
    const anyAnswer = Object.values(h.answers).some(a => (typeof a === 'string' ? a.trim() : a !== undefined));
    if (action === 'close' && !typed && !anyAnswer) return false;
    // What's in the box on screen — even emptied — is what "Keep going" shows.
    if (node && node.type === 'short') h.answers[node.id] = typed;
    h.leaving = action;
    renderConceptHelper();
    return true;
  }

  function openConceptHelper() {
    if (!ed.CONCEPT_FLOWS.length) return;
    const flow = ed.conceptFlowFor(ed.conceptHelperCategory());
    ed.conceptHelper = { flow, nodeId: flow.start, history: [], answers: {}, ended: false };
    // Shown first: renderConceptHelper measures the answer buttons.
    document.getElementById('conceptHelperOverlay').hidden = false;
    renderConceptHelper();
  }

  function closeConceptHelper() {
    document.getElementById('conceptHelperOverlay').hidden = true;
    ed.conceptHelper = null;
    ed.queueShootBreak(250); // it may have just filled in a field
  }

  document.getElementById('conceptHelperBtn').addEventListener('click', openConceptHelper);

  document.getElementById('conceptHelperYesBtn').addEventListener('click', () => {
    if (!ed.conceptHelper || ed.conceptHelper.ended) return;
    const node = ed.conceptHelperNode(ed.conceptHelper.nodeId);
    ed.conceptHelper.answers[node.id] = node.yesValue !== undefined ? node.yesValue : true;
    goConceptHelper(node.yes);
  });

  document.getElementById('conceptHelperNoBtn').addEventListener('click', () => {
    if (!ed.conceptHelper || ed.conceptHelper.ended) return;
    const node = ed.conceptHelperNode(ed.conceptHelper.nodeId);
    ed.conceptHelper.answers[node.id] = node.noValue !== undefined ? node.noValue : false;
    goConceptHelper(node.no);
  });

  function nextConceptHelperShort() {
    if (!ed.conceptHelper || ed.conceptHelper.ended) return;
    const node = ed.conceptHelperNode(ed.conceptHelper.nodeId);
    if (node.type !== 'short') return;
    // Left blank, it's flagged when they try to leave or use the result (see
    // askConceptHelperLeave); that part of the summary is just left out.
    ed.conceptHelper.answers[node.id] = document.getElementById('conceptHelperInput').value.trim();
    goConceptHelper(node.next);
  }

  document.getElementById('conceptHelperNextBtn').addEventListener('click', nextConceptHelperShort);

  // keyCode 229: Safari sends the Enter that confirms an IME composition
  // (Japanese, Chinese…) after compositionend, with isComposing already false.
  document.getElementById('conceptHelperInput').addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' || e.isComposing || e.keyCode === 229) return;
    e.preventDefault();
    nextConceptHelperShort();
  });

  // The small Back link on a question, or the end screen's Back button.
  function backConceptHelper() {
    const h = ed.conceptHelper;
    if (!h || !h.history.length) return;
    h.nodeId = h.history.pop();
    h.ended = false;
    h.resume = false;
    renderConceptHelper();
  }

  document.getElementById('conceptHelperBackBtn').addEventListener('click', backConceptHelper);
  document.getElementById('conceptHelperEndBackBtn').addEventListener('click', backConceptHelper);

  document.getElementById('conceptHelperRestartBtn').addEventListener('click', () => {
    if (!ed.conceptHelper) return;
    const flow = ed.conceptHelper.flow;
    ed.conceptHelper = { flow, nodeId: flow.start, history: [], answers: {}, ended: false };
    renderConceptHelper();
  });
};
;

// ---- pages/concept-helper/helper-output.js ----
// "Need to think it through?": what comes out of it, and using it.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addConceptHelperHelperOutput = function addConceptHelperHelperOutput(ed) {
  Object.assign(ed, { askHelperReplace });
  ed.CONCEPT_HELPER_OUTPUTS.forEach(out => {
    document.getElementById(out.boxId).addEventListener('input', (e) => {
      ed.autoSizeTextarea(e.target);
      ed.updateConceptHelperCount();
    });
  });

  // "Concept", "Concept and Elevator pitch", "Concept, World-building notes
  // and Elevator pitch".
  function conceptHelperJoin(labels) {
    return labels.length > 1 ? `${labels.slice(0, -1).join(', ')} and ${labels[labels.length - 1]}` : labels[0];
  }

  // Both helpers ask this when what they wrote would go over text that's
  // already on the page. Replace is red: what's there is gone for good.
  // "Keep mine" leaves those fields as they are, and the helper still fills
  // any that were empty and closes. `fillsOthers`: some of them were, so
  // the popup says so.
  function askHelperReplace(labels, fillsOthers) {
    return ed.askConfirm({
      title: `Replace what's already in ${conceptHelperJoin(labels)}?`,
      text: fillsOthers
        ? 'Keep mine leaves what you wrote there and still fills in the rest.'
        : 'Keep mine leaves what you wrote there.',
      confirmLabel: 'Replace',
      cancelLabel: 'Keep mine',
      danger: true,
    });
  }

  // Fills each page field that has something in its box (the real fields —
  // on a wizard slide they're typed into directly) and lets the form's own
  // input listener save them. A box emptied on purpose leaves its field be,
  // and so does "Keep mine" for a field that already has its own text.
  async function useConceptHelperOutputs() {
    const h = ed.conceptHelper;
    // Once at a time: asking again would answer the first popup "Keep mine"
    // (see askConfirm) and fill twice.
    if (!h || h.asking) return;
    const picks = ed.conceptHelperShownOutputs()
      .map(out => ({ out, text: document.getElementById(out.boxId).value.trim(), field: document.getElementById(out.fieldId) }))
      .filter(pick => pick.text);
    if (!picks.length || picks.some(pick => pick.text.length > ed.conceptHelperMax(pick.out))) return;
    const replacing = picks.filter(pick => ed.hasText(pick.field.value) && pick.field.value.trim() !== pick.text);
    let keepExisting = false;
    if (replacing.length) {
      h.asking = true;
      keepExisting = !(await askHelperReplace(replacing.map(pick => pick.out.label), picks.length > replacing.length));
      h.asking = false;
      // Closed some other way while it asked: nothing to fill from.
      if (ed.conceptHelper !== h) return;
    }
    picks.filter(pick => !(keepExisting && replacing.includes(pick))).forEach(({ field, text }) => {
      field.value = text;
      field.dispatchEvent(new Event('input', { bubbles: true }));
      ed.syncFieldFilledState(field);
    });
    ed.closeConceptHelper();
  }

  document.getElementById('conceptHelperUseBtn').addEventListener('click', () => {
    if (!ed.askConceptHelperLeave('use')) useConceptHelperOutputs();
  });

  // "Now that you've got it": straight into writing the Concept — typed in
  // place on the wizard slide, or through its expand popup on the page,
  // where the field itself is read-only.
  function writeConceptHelperOwn() {
    ed.closeConceptHelper();
    const premise = document.getElementById('shootPremise');
    if (premise.readOnly) ed.openExpandField('shootPremise');
    else premise.focus();
  }

  document.getElementById('conceptHelperWriteBtn').addEventListener('click', () => {
    if (!ed.askConceptHelperLeave('write')) writeConceptHelperOwn();
  });

  document.getElementById('conceptHelperCloseBtn').addEventListener('click', () => {
    if (!ed.askConceptHelperLeave('close')) ed.closeConceptHelper();
  });

  document.getElementById('conceptHelperLeaveFirstBtn').addEventListener('click', () => {
    const h = ed.conceptHelper;
    if (!h) return;
    // A real blank: go there. Otherwise ("Keep going") just carry on where
    // they were, stepping through as before.
    const target = ed.conceptHelperBlankIds()[0];
    if (target) ed.jumpConceptHelperTo(target);
    else { h.leaving = null; ed.renderConceptHelper(); }
  });

  document.getElementById('conceptHelperLeaveAnywayBtn').addEventListener('click', () => {
    const h = ed.conceptHelper;
    if (!h) return;
    const action = h.leaving;
    h.leaving = null;
    if (action === 'write') writeConceptHelperOwn();
    else if (action === 'use') {
      // Back to the end screen first: it's what shows behind the replace
      // question, and what stays if there turns out to be nothing to fill.
      ed.renderConceptHelper();
      useConceptHelperOutputs();
    } else ed.closeConceptHelper();
  });
};
;

// ---- pages/reflection-helper/helper.js ----
// "Need help reflecting?": the flow for this shoot, its questions and answers.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addReflectionHelperHelper = function addReflectionHelperHelper(ed) {
  Object.assign(ed, { openReflectHelper });
  // ---------- Reflection helper ("Need help reflecting?") ----------
  // Under Reflection: a few short questions for each of its three fields,
  // picked by the shoot's category (REFLECTION_FLOWS). Back and Next move
  // freely, any question can be skipped, and Finish (or Close, partway) writes
  // whatever was answered straight into the matching fields — one sentence
  // per answer, each from its question's `say` ({a} = the answer; `lower`
  // lowercases a capital the answer starts a sentence with).
  const REFLECTION_FIELDS = {
    right: { fieldId: 'shootWentRight', label: 'What went right' },
    better: { fieldId: 'shootCouldBeBetter', label: "What could've gone better" },
    lessons: { fieldId: 'shootLessonsLearned', label: 'Lessons for next time' },
  };

  // One flow per kind of shoot, like CONCEPT_FLOWS ('' = no category yet):
  // what went right, what could've gone better, lessons — three each.
  const REFLECTION_FLOWS = window.EyeWords.reflectionFlows;

  // { flow, questions (the flow's, plus any wild card ones), index,
  //   answers: [text per question], voiceTip }
  ed.reflectHelper = null;

  // The first time the helper opens on this device, question 1 also says
  // talking works (the keyboard's mic). A page can't start dictation itself,
  // and the browser's own speech-to-text stops hearing after one go in a
  // Home Screen app on iOS 27, so this is a tip rather than a button.
  // Spoken answers run long, so each answer holds 1000 characters, and the
  // three reflection boxes hold 4000 so three of them still fit once they're
  // written as sentences.
  const REFLECT_VOICE_TIP_KEY = 'dailies_seen_reflect_voice_tip_v1';

  function reflectFlowFor(category) {
    return REFLECTION_FLOWS.find(f => f.categories.includes(category))
      || REFLECTION_FLOWS.find(f => f.categories.includes(''))
      || REFLECTION_FLOWS[0];
  }

  function storeReflectAnswer() {
    ed.reflectHelper.answers[ed.reflectHelper.index] = document.getElementById('reflectHelperInput').value.trim();
  }

  // A Wild card tapped "Tried it" on in Shoot mode gets a question of its
  // own, among the "What went right" ones — the three most recent, at most.
  // One whose words are already in that box (the helper run before) isn't
  // asked again. A bare "yes" still says something (sayYes); a "no" is
  // left out like any other.
  function wildCardReflectQuestions() {
    const shoot = ed.state.shoots.find(s => s.id === ed.currentShootId);
    const cards = shoot && Array.isArray(shoot.triedWildCards) ? shoot.triedWildCards : [];
    const wentRight = document.getElementById('shootWentRight').value;
    // Only a closing full stop comes off for the sentence: a card that ends
    // on a question keeps its question mark.
    return cards.map(card => ({ card, plain: card.trim().replace(/[.…]+$/, '') }))
      .filter(({ plain }) => plain && !wentRight.includes(plain))
      .slice(-3)
      .map(({ card, plain }) => ({
        field: 'right',
        text: `You tried “${card.trim()}” Did it give you anything?`,
        placeholder: 'e.g. the shot of her hands on the rail',
        say: `From the wild card “${plain}”: {a}.`,
        sayYes: `The wild card “${plain}” paid off.`,
        lower: true,
      }));
  }

  function renderReflectHelper() {
    const h = ed.reflectHelper;
    const questions = h.questions;
    const q = questions[h.index];
    const isLast = h.index === questions.length - 1;
    document.getElementById('reflectHelperStep').textContent = `Question ${h.index + 1} of ${questions.length}`;
    document.getElementById('reflectHelperTitle').textContent = REFLECTION_FIELDS[q.field].label;
    document.getElementById('reflectHelperText').textContent = q.text;
    // Said once, up front: nothing here has to be answered.
    const hint = document.getElementById('reflectHelperHint');
    hint.textContent = h.index === 0 ? "Answer what you can. Anything you skip is just left out." : '';
    if (h.index === 0 && h.voiceTip) {
      const tip = document.createElement('span');
      tip.className = 'field-hint-bold';
      tip.textContent = 'Tip:';
      hint.append(document.createElement('br'), tip, ' tap the mic on your keyboard and just talk.');
    }
    hint.hidden = !hint.textContent;
    const input = document.getElementById('reflectHelperInput');
    input.placeholder = q.placeholder || '';
    input.value = h.answers[h.index] || '';
    document.getElementById('reflectHelperBackBtn').hidden = h.index === 0;
    document.getElementById('reflectHelperNextBtn').textContent = isLast ? 'Finish' : 'Next';
  }

  function goReflectHelper(step) {
    const h = ed.reflectHelper;
    if (!h) return;
    storeReflectAnswer();
    const next = h.index + step;
    if (next >= h.questions.length) { finishReflectHelper(); return; }
    h.index = Math.max(0, next);
    renderReflectHelper();
  }

  // "Nothing really", "Nope, all good", "It didn't" — an answer that says
  // there's nothing to say.
  const REFLECTION_NOTHING = /^(no|nope|nah|none|nothing|nowhere|never|not really|not much|n\/?a|all good|it didn['’]?t|didn['’]?t)([\s,;:!.—–-]+(really|at all|all good|it didn['’]?t|nothing|it was fine|all fine|went fine))*$/i;

  // One answer as a sentence: trimmed of its closing punctuation, a leading
  // "yes" dropped, "no"-type answers left out, then put into its question's
  // `say`. For "Finish this: next time, I'll…", a retyped "next time" /
  // "I'll" isn't doubled, and an answer with its own "I…" ("I need to…")
  // uses `sayOwn` instead.
  function reflectSentence(q, answer) {
    if (q.sayYes && /^(yes|yeah|yep|yup|definitely|it did)[\s!.]*$/i.test((answer || '').trim())) return q.sayYes;
    let text = (answer || '').trim().replace(/[.!?…]+$/, '')
      .replace(/^(yes|yeah|yep|yup|definitely)\b[\s,;:!.—–-]*/i, '');
    if (!text || ed.CONCEPT_HELPER_NONE.test(text) || REFLECTION_NOTHING.test(text)) return '';
    let say = q.say;
    if (q.sayOwn) {
      text = text.replace(/^(\.{2,}|…)\s*/, '').replace(/^next time[,:]?\s*/i, '');
      const withoutLeadIn = text.replace(/^(i['’]ll|i will)\s+/i, '');
      if (withoutLeadIn !== text && withoutLeadIn) text = withoutLeadIn;
      else if (/^I(\s|['’])/.test(text)) say = q.sayOwn;
      if (!text) return '';
    }
    if (q.lower && say === q.say && /^[A-Z][a-z]/.test(text)) text = text.charAt(0).toLowerCase() + text.slice(1);
    // A function, so a "$" in the answer is never read as a pattern.
    const sentence = say.replace('{a}', () => text);
    return sentence.charAt(0).toUpperCase() + sentence.slice(1);
  }

  // Writes each field from its own answers — a field with none is left as
  // it is. Replacing text that's already there asks first (askHelperReplace).
  async function finishReflectHelper() {
    const h = ed.reflectHelper;
    // Once at a time: asking again would answer the first popup "Keep mine"
    // (see askConfirm) and fill twice.
    if (!h || h.asking) return;
    storeReflectAnswer();
    const fills = Object.keys(REFLECTION_FIELDS).map(key => {
      const field = document.getElementById(REFLECTION_FIELDS[key].fieldId);
      const text = h.questions
        .map((q, i) => (q.field === key ? reflectSentence(q, h.answers[i]) : ''))
        .filter(Boolean).join(' ')
        .slice(0, field.maxLength > 0 ? field.maxLength : 1000);
      return { key, field, text };
    }).filter(fill => fill.text);
    const replacing = fills.filter(fill => ed.hasText(fill.field.value) && fill.field.value.trim() !== fill.text);
    // Keep mine keeps what's there, but still fills the fields that were
    // empty — and closes either way, so Close is never a dead end.
    let keepExisting = false;
    if (replacing.length) {
      h.asking = true;
      keepExisting = !(await ed.askHelperReplace(replacing.map(fill => REFLECTION_FIELDS[fill.key].label), fills.length > replacing.length));
      h.asking = false;
      // Closed some other way while it asked: leave the page as it is.
      if (ed.reflectHelper !== h) return;
    }
    fills.filter(fill => !(keepExisting && replacing.includes(fill))).forEach(({ field, text }) => {
      field.value = text;
      field.dispatchEvent(new Event('input', { bubbles: true }));
      ed.syncFieldFilledState(field);
    });
    closeReflectHelper();
  }

  function openReflectHelper() {
    let voiceTip;
    try {
      voiceTip = localStorage.getItem(REFLECT_VOICE_TIP_KEY) !== '1';
      if (voiceTip) localStorage.setItem(REFLECT_VOICE_TIP_KEY, '1');
    } catch (err) { voiceTip = false; /* storage unavailable — nothing to remember it in, so not shown every time */ }
    const flow = reflectFlowFor(document.getElementById('shootCategory').value || '');
    // Wild card questions go after the flow's own "What went right" ones.
    const questions = [...flow.questions];
    const firstBetter = questions.findIndex(q => q.field !== 'right');
    questions.splice(firstBetter === -1 ? questions.length : firstBetter, 0, ...wildCardReflectQuestions());
    ed.reflectHelper = { flow, questions, index: 0, answers: [], voiceTip };
    renderReflectHelper();
    document.getElementById('reflectHelperOverlay').hidden = false;
  }

  function closeReflectHelper() {
    document.getElementById('reflectHelperOverlay').hidden = true;
    ed.queueShootBreak(250); // it may have just filled in a field
    // Whatever was waiting for the helper to close (the reflection prompt's
    // "Walk me through it" holds the deadline prompt back until now).
    const onClose = ed.reflectHelper && ed.reflectHelper.onClose;
    ed.reflectHelper = null;
    if (onClose) onClose();
  }

  document.getElementById('reflectHelperBtn').addEventListener('click', openReflectHelper);
  document.getElementById('reflectHelperBackBtn').addEventListener('click', () => goReflectHelper(-1));
  document.getElementById('reflectHelperNextBtn').addEventListener('click', () => goReflectHelper(1));
  // Close keeps what's been answered so far: same as Finish.
  document.getElementById('reflectHelperCloseBtn').addEventListener('click', finishReflectHelper);

  // Enter moves on (Shift+Enter still makes a new line; see the concept
  // helper's input for keyCode 229).
  document.getElementById('reflectHelperInput').addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' || e.shiftKey || e.isComposing || e.keyCode === 229) return;
    e.preventDefault();
    goReflectHelper(1);
  });

  document.getElementById('shootWizardDontShowBtn').addEventListener('click', () => {
    ed.setNewShootGuideOn(false);
    ed.endShootWizard();
    document.getElementById('shootWizardOffOverlay').hidden = false;
  });

  document.getElementById('shootWizardOffOkBtn').addEventListener('click', () => {
    document.getElementById('shootWizardOffOverlay').hidden = true;
  });

  // See queueShootWizard. animationend bubbles up from animated things inside
  // the modal too, so only the modal's own slide-in counts.
  ed.shootModalOverlay.querySelector('.modal').addEventListener('animationend', (e) => {
    if (e.target === e.currentTarget && ed.shootWizardPendingId) ed.startQueuedShootWizard();
  });
};
;

// ---- pages/shoot/shoot-open.js ----
// Opening a shoot: the shoot page filled in from what's saved.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootOpen = function addShootOpen(ed) {
  Object.assign(ed, { updateShootModalTitleFromScroll, openShootModal });
  // iOS scrolls a focused field into view before the keyboard has finished
  // shrinking the visible area (and the card with it, see
  // syncShootWizardViewport), which can leave it under the keyboard — so
  // once more after that resize. Same pattern as renderShotList's.
  document.getElementById('shootWizardBody').addEventListener('focusin', (e) => {
    const field = e.target;
    if (!window.visualViewport) return;
    if (!field.matches('textarea, input:not([type="checkbox"]):not([type="radio"]):not([type="file"])')) return;
    window.visualViewport.addEventListener('resize', () => {
      if (ed.shootWizardActive && document.activeElement === field) field.scrollIntoView({ block: 'nearest' });
    }, { once: true });
  });

  // Updates the sticky title to name whichever section has scrolled past
  // the header, so it always reads as "where am I" rather than a static
  // label — falls back to the original Edit/Log-a-Shoot title at the very
  // top, before any section has passed underneath the header yet.
  function updateShootModalTitleFromScroll() {
    const modalEl = ed.shootModalOverlay.querySelector('.modal');
    const containerRect = modalEl.getBoundingClientRect();
    const header = document.querySelector('.shoot-modal-header');
    const headerOffset = header ? header.getBoundingClientRect().bottom - containerRect.top : 0;
    let active = null;
    ed.SHOOT_MODAL_SECTIONS.forEach(sec => {
      const el = document.getElementById(sec.id);
      if (!el) return;
      const rect = el.getBoundingClientRect();
      if (rect.width === 0 && rect.height === 0) return;
      if (rect.top - containerRect.top <= headerOffset + 2) active = sec;
    });
    document.getElementById('shootModalTitle').textContent = active ? active.label : ed.shootModalBaseTitle;
  }

  ed.shootModalOverlay.querySelector('.modal').addEventListener('scroll', updateShootModalTitleFromScroll, { passive: true });

  function openShootModal(id) {
    // Hands back any fields a wizard still has borrowed — only possible after
    // a path that hid the overlay without closeShootModal (Delete, Complete,
    // Unarchive) — before anything below repopulates or measures them.
    ed.endShootWizard({ closing: true });
    ed.closeStatsDetail();
    ed.editingShootId = id;
    const s = id ? ed.state.shoots.find(x => x.id === id) : null;
    ed.currentShootId = id || ed.uid();
    ed.pendingProjectPhoto = s ? (s.projectPhoto || null) : null;
    // s.projectPhoto is only set once hydratePhotos()'s IndexedDB reads
    // resolve, which happens once at boot — opening a shoot before its own
    // read lands here leaves this seeded empty even though it has a saved
    // photo. Double-checked directly (bypassing the boot-time hydration
    // race entirely) so a talent added in the same session doesn't get
    // auto-claimed as the cover over an existing one it just hasn't seen
    // yet. Guarded against a since-closed/reopened modal.
    if (s && !s.projectPhoto) {
      const shootId = s.id;
      ed.idbGetImages(ed.projectPhotoKey(shootId)).then(entries => {
        const src = ed.photoFromEntries(entries);
        if (!src || ed.currentShootId !== shootId) return;
        // By id, not the captured `s` — an autosave since opening replaces
        // the shoot object, which would leave `s` an orphan.
        const live = ed.state.shoots.find(x => x.id === shootId);
        if (live && !live.projectPhoto) live.projectPhoto = src;
        ed.pendingProjectPhoto = src;
      }).catch(() => {});
    }
    ed.shootHasImages = false;

    ed.shootModalBaseTitle = s ? 'Edit Shoot' : ed.randomNewShootTitle();
    document.getElementById('shootModalTitle').textContent = ed.shootModalBaseTitle;
    ed.closeShootModalJumpMenu();
    document.getElementById('deleteShootBtn').hidden = !s;
    document.getElementById('shareShootBtn').hidden = !s;
    const isArchived = s ? !!s.archived : false;
    document.getElementById('saveShootBtn').hidden = isArchived;
    document.getElementById('saveShootBtn').textContent = ed.pickRandomSaveMessage();
    document.getElementById('unarchiveShootBtn').hidden = !isArchived;
    ed.shootModalOverlay.dataset.section = isArchived ? 'archive' : 'shoots';
    document.getElementById('completeShootBtn').hidden = !s || isArchived || s.status !== 'delivered';

    document.getElementById('shootTitle').value = s ? (s.title || '') : '';
    // Options depend on category (video swaps in its own edit steps), and the
    // category select isn't populated until further down, so the category is
    // read straight off the shoot here.
    ed.renderShootStatusSelectOptions(s ? (s.category || '') : '', s ? (s.status || 'prospect') : 'prospect');
    ed.previousStatusValue = document.getElementById('shootStatus').value;
    ed.currentOffScheduleDate = s ? s.offScheduleDate : undefined;
    ed.categoryRemap = null;
    ed.updateStatusSwatchDisplay();
    ed.updateEnterShootModeBtnVisibility();
    document.getElementById('shootDate').value = s ? (s.date || '') : '';
    document.getElementById('shootDeadline').value = s ? (s.deadline || '') : '';
    document.getElementById('shootStartTime').value = s ? (s.startTime || '') : '';
    document.getElementById('shootEndTime').value = s ? (s.endTime || '') : '';
    document.getElementById('shootCrewCallTime').value = s ? (s.crewCallTime || '') : '';
    document.getElementById('shootTalentCallTime').value = s ? (s.talentCallTime || '') : '';
    // Built from saved project membership (never from form data), so it has
    // to come after currentShootId is set above; a brand-new draft just gets
    // a fresh unticked row with Last day hidden.
    ed.updateMultiDayRow();
    ed.currentShootLocation = s ? ed.normalizeLocation(s.location) : { name: '', street: '', city: '', state: '', zip: '', country: ed.state.defaultCountry || '' };
    ed.updateLocationBtnDisplay();
    // Talents saved before they had ids get one assigned on load — needed as
    // a stable IndexedDB key for their photo (see talentPhotoKey).
    ed.currentTalents = s && Array.isArray(s.talents)
      ? s.talents.map(t => ({ id: t.id || ed.uid(), name: t.name || '', socialHandles: (t.socialHandles || []).map(sh => ({ ...sh })), photo: t.photo || '' }))
      : [];
    // Same safety net as the cover above: a talent whose photo hasn't reached
    // memory yet would show a blank card here and then have that blank saved
    // back over the in-memory talent on the next autosave. Only talents that
    // already had a saved id can have a stored photo to find.
    if (s) {
      const shootId = s.id;
      const savedTalentIds = new Set((s.talents || []).filter(t => t.id).map(t => t.id));
      ed.currentTalents.forEach(ct => {
        if (ct.photo || !savedTalentIds.has(ct.id)) return;
        ed.idbGetImages(ed.talentPhotoKey(shootId, ct.id)).then(entries => {
          const src = ed.photoFromEntries(entries);
          if (!src || ed.currentShootId !== shootId) return;
          const cur = ed.currentTalents.find(x => x.id === ct.id);
          if (cur && !cur.photo) { cur.photo = src; ed.renderTalents(); }
        }).catch(() => {});
      });
    }
    ed.renderTalents();
    document.getElementById('shootCategory').value = s ? (s.category || '') : '';
    ed.updateCategoryTierUI();
    document.getElementById('shootPremise').value = s ? (s.premise || '') : '';
    document.getElementById('shootCharacter').value = s ? (s.character || '') : '';
    document.getElementById('shootWorldNotes').value = s ? (s.worldNotes || '') : '';
    document.getElementById('shootGoals').value = s ? (s.shootGoals || '') : '';
    document.getElementById('shootElevatorPitch').value = s ? (s.elevatorPitch || '') : '';
    document.getElementById('shootDeliverables').value = s ? (s.deliverables || '') : '';
    document.getElementById('shootDeliverableDestinations').value = s ? (s.deliverableDestinations || '') : '';
    const savedAspectRatios = s ? ed.normalizeAspectRatios(s.aspectRatios) : [];
    document.querySelectorAll('#shootAspectRatios input[type="checkbox"]').forEach(cb => {
      cb.checked = savedAspectRatios.includes(cb.value);
    });
    document.getElementById('shootMoodboardComplete').checked = s ? !!s.moodboardComplete : false;
    // Also sets the Mood board/Storyboard wording (incl. the complete
    // checkbox label) and hides Final images for video.
    ed.updateVideoCategoryUI();
    ed.updateMoodboardCompleteVisibility();
    ed.currentReferences = s && Array.isArray(s.references) ? [...s.references] : [];
    ed.renderReferences();
    document.getElementById('shootWentRight').value = s ? (s.whatWentRight || '') : '';
    document.getElementById('shootCouldBeBetter').value = s ? (s.couldBeBetter || '') : '';
    document.getElementById('shootLessonsLearned').value = s ? (s.lessonsLearned || '') : '';
    document.getElementById('shootTalentDirections').value = s ? (s.talentDirections || '') : '';
    document.getElementById('shootTeamDirections').value = s ? (s.teamDirections || '') : '';
    document.getElementById('shootShootingNotes').value = s ? (s.shootingNotes || '') : '';
    document.getElementById('shootLocationDirections').value = s ? (s.locationDirections || '') : '';
    ed.currentShotList = s && Array.isArray(s.shotList) ? s.shotList.map(item => ({ ...item })) : [];
    ed.renderShotList();
    // Old-shaped setups (a single free-text checklist row, pre-redesign) map
    // their text into the new description field rather than losing it — name
    // and characteristics start blank since neither existed before.
    ed.currentLightingSetups = s && Array.isArray(s.lightingSetups)
      ? s.lightingSetups.map(item => ({
          id: item.id || ed.uid(),
          name: item.name || '',
          characteristics: item.characteristics || '',
          description: item.description !== undefined ? item.description : (item.text || ''),
        }))
      : [];
    ed.renderLightingSetups();

    // Also shows/hides the team list and Directions for team to match.
    ed.setTeamRequiredChoice(s ? (s.teamRequired || '') : '');
    document.getElementById('shootTeamFinalized').checked = s ? !!s.teamFinalized : false;
    ed.currentTeamMembers = s && s.teamMembers ? s.teamMembers.map(tm => ({ ...tm })) : [];
    ed.renderTeamMembers();

    ed.renderShootFrameworkTags(s);
    ed.renderShootNotes(s ? s.id : null);

    document.getElementById('postShootContent').hidden = !ed.isPostCaptureStatus(ed.previousStatusValue);
    document.getElementById('postShootPromptOverlay').hidden = true;
    ed.updateShootModalJumpMenuVisibility();

    const shootPhotosIn = Promise.all([ed.renderMoodboard(), ed.renderFinalImages(), ed.renderRefBoards()]);
    // Everything above is populated by now — a saved field should read as
    // written the instant the modal opens, not only after it's touched again.
    ed.syncAllShootFormFields();
    // Without this, a swipe that starts anywhere in the modal that isn't
    // itself a scrollable element (e.g. the header, or blank space around a
    // short pane) can fall through and scroll the page underneath, which is
    // still there and still scrollable behind the fixed overlay.
    if (ed.shootModalOverlay.hidden) ed.lockBodyScroll();
    ed.shootModalOverlay.hidden = false;
    // Only a brand-new shoot (the "+ New Shoot" buttons pass null) gets the
    // planning wizard. Its first slide covers the status button, so it takes
    // over from the one-time status intro there; an id that no longer
    // resolves to a shoot keeps the intro, as before.
    // Turned off (first slide's "Don't show again", or the app menu), a new
    // shoot opens straight to the page, with the status intro as before.
    if (!id && ed.isNewShootGuideOn()) ed.queueShootWizard();
    else if (!s) ed.maybeShowStatusSwatchIntro();

    // Back to the page this shoot was last open on, at its top.
    const remembered = ed.shootPageMemory[ed.currentShootId] || { id: 'basicInfoHeading', sub: 0 };
    ed.shootFlows = null;
    ed.shootSub = 0;
    ed.shootBreakChanged = [];
    ed.shootForm.querySelectorAll('.pg-off, .pg-first').forEach(el => el.classList.remove('pg-off', 'pg-first'));
    ed.showShootPage(remembered.id, { orFirst: true });
    // A later page may only exist once the photos have loaded.
    if (ed.shootPageId === remembered.id && remembered.sub > 0) {
      ed.shootWanted = { id: remembered.id, sub: remembered.sub };
      ed.shootSub = remembered.sub;
      if (ed.currentShootId) ed.shootPageMemory[ed.currentShootId] = remembered;
    }
    const opening = {};
    ed.shootOpening = opening;
    shootPhotosIn.catch(() => {}).then(() => {
      if (ed.shootOpening !== opening) return; // another shoot has opened since
      ed.shootOpening = null;
      if (ed.shootBreakWatch) ed.shootBreakWatch.takeRecords();
      if (ed.shootModalOverlay.hidden) ed.shootWanted = null; // closed already: its page stays remembered
      else ed.breakShootPages();
    });
    ed.breakShootPages();
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        // renderShotList() ran further up, while the overlay was still hidden,
        // so every row measured zero and kept its one-line default — a saved
        // multi-line shot would open clipped. This is the first frame where the
        // rows actually have layout, so it's the first chance to size them.
        ed.autoSizeAllListTextareas();
        // syncAllShootFormFields() ran earlier too, for the exact same reason
        // — every readonly notes field (Location directions, Character,
        // reflection fields, etc.) that had real content measured zero height
        // and was left at its bare rows="N" size, silently clipping whatever
        // didn't fit. autoSizeTextarea itself is idempotent, so re-running the
        // whole sync here is cheap and catches every field at once rather
        // than needing a bespoke re-measure per field.
        ed.syncAllShootFormFields();
        ed.breakShootPages();
      });
    });
  }
};
;

// ---- pages/shoot/moodboard.js ----
// The mood board, and boards from Ref (its Send to shoot, or + Import board).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootMoodboard = function addShootMoodboard(ed) {
  Object.assign(ed, { renderMoodboard, loadRefBoardShoots, refBoardsFor, renderRefBoards, freezeShotBoardsSoon, dropRefBoardsFor, restoreRefBoards, openShootFromBoard });
  function renderMoodboard() {
    const grid = document.getElementById('moodboardGrid');
    grid.innerHTML = '';
    return ed.idbGetImages(ed.currentShootId).then(images => {
      grid.innerHTML = images.length ? '' : '<p class="empty-hint">No photos yet.</p>';
      images.forEach((img, idx) => {
        const item = document.createElement('div');
        item.className = 'moodboard-item';
        item.innerHTML = `
          <div class="moodboard-thumb">
            <img src="${img.src}" alt="" data-idx="${idx}" />
            <button type="button" class="moodboard-thumb-delete" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>
          </div>
        `;
        grid.appendChild(item);
      });
      grid.querySelectorAll('.moodboard-thumb-delete').forEach(btn => {
        btn.addEventListener('click', async () => {
          // Taken before asking: the photo belongs to the shoot it was tapped on.
          const shootId = ed.currentShootId;
          if (!(await ed.askDeletePhoto())) return;
          ed.idbGetImages(shootId).then(imgs => {
            imgs.splice(Number(btn.dataset.idx), 1);
            return ed.idbSetImages(shootId, imgs);
          }).then(() => {
            renderMoodboard();
            ed.onShootImagesChanged(shootId, { board: true });
          });
        });
      });
      grid.querySelectorAll('.moodboard-thumb img').forEach(imgEl => {
        imgEl.addEventListener('click', () => {
          ed.openImageViewer(images, Number(imgEl.dataset.idx), ed.currentShootId, renderMoodboard);
        });
      });
    }).catch(() => { grid.innerHTML = ''; });
  }

  // ---------- Boards from Ref (its Send to shoot, or + Import board) ----------
  // Kept apart from this notebook's own data, in df-links (df-data.js): each
  // a link to a shoot plus the board's pages as pictures. One sent from Ref
  // inside Documenting Fictions stays live (Ref draws its pages again when it
  // changes) until the shoot is shot: then it's frozen, "Board as of" that
  // day. One imported from a file is fixed from the start.
  let refBoardUrls = [];
  const refBoardDay = iso => new Date(iso).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });

  function refBoardLinks(match) {
    if (!ed.refApi) return Promise.resolve([]);
    return ed.refApi.linksWhere({ toApp: 'the-eye', type: 'moodboard', ...match }).catch(() => []);
  }
  function loadRefBoardShoots() {
    return refBoardLinks({}).then(links => {
      ed.refBoardShootIds = new Set(links.filter(l => l.toId && !l.pending).map(l => l.toId));
      return links;
    });
  }
  // A board with its pictures, ready to show: { link, cover, pages } as object URLs.
  // Its URLs go in `urls`, for whoever shows them to let go of later.
  function refBoardsFor(shootId, urls) {
    return refBoardLinks({ toId: shootId }).then(links => Promise.all(links.map(l =>
      ed.refApi.linkPictures(l.id).catch(() => null).then(p => {
        const url = pic => { const u = ed.refApi.pictureUrl(pic); if (u) urls.push(u); return u; };
        const pages = p && Array.isArray(p.pages) ? p.pages.map(url).filter(Boolean) : [];
        return { link: l, cover: p && p.cover ? url(p.cover) : (pages[0] || ''), pages };
      }))));
  }
  const refBoardState = l => l.importedAt ? `Imported ${refBoardDay(l.importedAt)}`
    : l.frozenAt ? `Board as of ${refBoardDay(l.frozenAt)}`
    : 'Live from Ref';
  const canOpenInRef = l => !!(ed.refApi && ed.refApi.inSuite() && l.fromId && !l.importedAt);
  const showRefBoardPages = b => { if (b.pages.length) ed.openImageViewer(b.pages.map(src => ({ src, caption: '' })), 0, null, null, false); };

  function renderRefBoards() {
    const box = document.getElementById('refBoards');
    document.getElementById('importRefBoardBtn').hidden = !ed.refApi;
    if (!ed.refApi) { box.hidden = true; return Promise.resolve(); }
    const shootId = ed.currentShootId;
    const urls = [];
    return refBoardsFor(shootId, urls).then(boards => {
      if (shootId !== ed.currentShootId) { urls.forEach(u => URL.revokeObjectURL(u)); return; }
      refBoardUrls.forEach(u => URL.revokeObjectURL(u));
      refBoardUrls = urls;
      box.innerHTML = '';
      box.hidden = !boards.length;
      box.closest('.moodboard-section').classList.toggle('has-ref-boards', boards.length > 0); // no "No photos yet." under a board
      boards.forEach(b => {
        const l = b.link;
        const n = l.photoCount || 0;
        const row = document.createElement('div');
        row.className = 'ref-board';
        row.innerHTML = `
          <button type="button" class="ref-board-cover" aria-label="See ${ed.escapeHtml(l.name || 'the board')}">${b.cover ? `<img src="${b.cover}" alt="" />` : ''}</button>
          <div class="ref-board-text">
            <button type="button" class="ref-board-name">${ed.escapeHtml(l.name || 'Mood board')}</button>
            <span class="ref-board-meta">${n} ${n === 1 ? 'image' : 'images'} · ${ed.escapeHtml(refBoardState(l))}</span>
            <div class="ref-board-actions">
              ${canOpenInRef(l) ? '<button type="button" class="manage-link inline-manage-link" data-ref-open>Open in Ref</button>' : ''}
              <button type="button" class="manage-link inline-manage-link" data-ref-detach>Detach</button>
            </div>
          </div>`;
        row.querySelector('.ref-board-cover').addEventListener('click', () => showRefBoardPages(b));
        row.querySelector('.ref-board-name').addEventListener('click', () => showRefBoardPages(b));
        const openBtn = row.querySelector('[data-ref-open]');
        if (openBtn) openBtn.addEventListener('click', () => {
          ed.saveShootNow();
          location.href = ed.refApi.notebookUrl('ref', { board: l.fromId });
        });
        row.querySelector('[data-ref-detach]').addEventListener('click', async () => {
          const yes = await ed.askConfirm({
            title: 'Detach this board?',
            text: l.importedAt ? 'It comes off this shoot.' : 'It comes off this shoot. The board stays in Ref.',
            confirmLabel: 'Detach', cancelLabel: 'Keep it', danger: true,
          });
          if (!yes) return;
          await ed.refApi.dropLinks([l.id]).catch(() => {});
          await loadRefBoardShoots();
          renderRefBoards();
        });
        box.appendChild(row);
      });
    });
  }

  // + Import board: a board file from a Ref installed on its own.
  document.getElementById('importRefBoardBtn').addEventListener('click', () => {
    if (!ed.refApi) return;
    const shootId = ed.currentShootId;
    ed.refApi.pickFile('application/json,.json') // straight from the tap, or iOS won't open the picker
      .then(file => file && ed.refApi.readBoardFile(file))
      .then(got => {
        if (!got || shootId !== ed.currentShootId || ed.shootModalOverlay.hidden) return null;
        // A shoot not saved yet is saved now, so the board has a shoot to be on.
        if (!ed.state.shoots.some(x => x.id === shootId)) ed.autosaveShoot(true);
        const now = new Date().toISOString();
        return ed.refApi.saveLink({
          fromApp: 'ref', fromId: got.board.id, toApp: 'the-eye', toId: shootId, type: 'moodboard',
          name: got.board.name, pageCount: got.board.pageCount, photoCount: got.board.photoCount,
          drawnAt: now, frozenAt: null, importedAt: now, pending: false,
        }, got.pictures);
      })
      .then(saved => {
        if (!saved) return null;
        ed.showToast(`${saved.name} is on this shoot`);
        return loadRefBoardShoots().then(renderRefBoards);
      })
      .catch(err => ed.showToast((err && err.message) || "That board couldn't be imported."));
  });

  // Once a shoot is shot (Captured onward) or put away, its boards stop changing.
  function freezeShotBoardsSoon() {
    if (!ed.refApi || !ed.refBoardShootIds.size) return;
    clearTimeout(ed.refFreezeTimer);
    ed.refFreezeTimer = setTimeout(freezeShotBoards, 400);
  }
  function freezeShotBoards() {
    return refBoardLinks({}).then(links => {
      const shot = links.filter(l => {
        if (l.frozenAt || l.importedAt || l.pending || !l.toId) return false;
        const s = ed.state.shoots.find(x => x.id === l.toId);
        return !!s && (!!s.archived || ed.POST_CAPTURE_STATUSES.includes(s.status));
      });
      const now = new Date().toISOString();
      return Promise.all(shot.map(l => ed.refApi.saveLink({ ...l, frozenAt: now })));
    }).then(done => {
      if (done.length && !ed.shootModalOverlay.hidden) renderRefBoards();
    }).catch(() => {});
  }
  // A shoot deleted, or a new one left blank: its boards go with it (not from Ref).
  function dropRefBoardsFor(shootId) {
    if (!ed.refApi) return;
    refBoardLinks({ toId: shootId }).then(links => links.length && ed.refApi.dropLinks(links.map(l => l.id)))
      .then(() => loadRefBoardShoots()).catch(() => {});
  }
  // An old .json backup carries its boards, pictures as data URLs (the zip
  // backups carry df-links whole). One from before boards (no refBoards)
  // leaves the boards as they are.
  function restoreRefBoards(list) {
    if (!ed.refApi || !Array.isArray(list)) return Promise.resolve();
    const picture = u => fetch(u).then(r => r.blob()).then(b => b.arrayBuffer().then(bytes => ({ type: b.type || 'image/jpeg', bytes })));
    return refBoardLinks({})
      .then(old => old.length && ed.refApi.dropLinks(old.map(l => l.id)))
      .then(() => Promise.all(list.filter(b => b && b.link && b.link.id).map(b =>
        Promise.all([b.cover ? picture(b.cover) : null, Promise.all((b.pages || []).map(picture))])
          .then(([cover, pages]) => ed.refApi.saveLink(b.link, { cover, pages })))))
      .then(loadRefBoardShoots);
  }

  // Ref's + New shoot from this board: a new shoot, named for the board, with it on.
  function openShootFromBoard(linkId) {
    if (!ed.refApi) return;
    ed.refApi.getLink(linkId).then(l => {
      if (!l || !l.pending) return null;
      ed.openShootModal(null);
      const title = document.getElementById('shootTitle');
      title.value = l.name || '';
      ed.syncFieldFilledState(title);
      ed.updateShootRunningHead();
      ed.autosaveShoot(true);
      return ed.refApi.saveLink({ ...l, toId: ed.currentShootId, pending: false })
        .then(loadRefBoardShoots)
        .then(renderRefBoards);
    }).catch(() => {});
  }
  // On the way in: which shoots have boards, any shot since frozen, and a
  // new shoot from a board that never got made (left over a day) dropped.
  if (ed.refApi) {
    ed.refBoardsReady = loadRefBoardShoots().then(links => {
      const stale = links.filter(l => l.pending && Date.now() - Date.parse(l.createdAt) > 86400000).map(l => l.id);
      if (stale.length) ed.refApi.dropLinks(stale).catch(() => {});
      if (ed.refBoardShootIds.size) { ed.renderAll(); freezeShotBoards(); }
    });
  }

  document.getElementById('addMoodboardPhotos').addEventListener('click', () => {
    document.getElementById('moodboardFileInput').click();
  });

  document.getElementById('moodboardFileInput').addEventListener('change', (e) => {
    const files = [...e.target.files];
    e.target.value = '';
    if (!files.length) return;
    // The photos belong to the shoot they were picked on, even if resizing
    // takes long enough for that shoot to be closed and another opened.
    const uploadShootId = ed.currentShootId;
    const stillOpen = () => ed.currentShootId === uploadShootId && !ed.shootModalOverlay.hidden;
    let coverSet = false;
    Promise.all(files.map(f => ed.resizeImageFile(f, 1280, 0.72)))
      .then(newImages => {
        // A never-saved draft that was closed in the meantime is gone (its
        // rows were cleared on close) — don't leave orphaned photos behind.
        if (!stillOpen() && !ed.state.shoots.some(x => x.id === uploadShootId)) return null;
        return ed.idbGetImages(uploadShootId).then(existing => {
          const savedShoot = ed.state.shoots.find(x => x.id === uploadShootId);
          const hasCover = stillOpen() ? !!ed.pendingProjectPhoto : !!(savedShoot && savedShoot.projectPhoto);
          const shouldAutoSetProjectPhoto = existing.length === 0 && !hasCover && newImages.length > 0;
          const combined = existing.concat(newImages.map(src => ({ src, caption: '' })));
          return ed.idbSetImages(uploadShootId, combined).then(() => {
            if (shouldAutoSetProjectPhoto) {
              return ed.resizeDataUrlThumb(newImages[0], 200, 0.6).then(thumb => {
                coverSet = true;
                if (stillOpen()) ed.pendingProjectPhoto = thumb;
                else {
                  const live = ed.state.shoots.find(x => x.id === uploadShootId);
                  if (live) live.projectPhoto = thumb;
                }
                return ed.savePhotoToIdb(ed.projectPhotoKey(uploadShootId), thumb);
              });
            }
          }).then(() => true);
        });
      })
      .then((uploaded) => {
        if (!uploaded) return;
        if (stillOpen()) {
          ed.shootHasImages = true;
          ed.scheduleShootAutosave();
          renderMoodboard();
        } else {
          ed.renderAll();
        }
        ed.onShootImagesChanged(uploadShootId, { board: true, cover: coverSet });
      })
      .catch(ed.noteStorageFull);
  });
};
;

// ---- components/image-viewer.js ----
// The image viewer: a picture full size (mood boards, final images, the Journal).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addImageViewer = function addImageViewer(ed) {
  Object.assign(ed, { openImageViewer, showViewerImage, saveViewerCaption, closeImageViewer });
  // ---------- Image viewer (full-size view, shared by mood board + final images + journal photos) ----------
  const imageViewerOverlay = document.getElementById('imageViewerOverlay');
  const imageViewerImg = document.getElementById('imageViewerImg');
  const imageViewerMenu = document.getElementById('imageViewerMenu');
  const imageViewerMenuBtn = document.getElementById('imageViewerMenuBtn');
  const imageViewerStage = document.getElementById('imageViewerStage'); ed.imageViewerStage = imageViewerStage;
  const imageViewerCaptionOverlay = document.getElementById('imageViewerCaptionOverlay'); ed.imageViewerCaptionOverlay = imageViewerCaptionOverlay;
  const imageViewerCaptionText = document.getElementById('imageViewerCaptionText');
  const imageViewerAddCaptionBtn = document.getElementById('imageViewerAddCaptionBtn'); ed.imageViewerAddCaptionBtn = imageViewerAddCaptionBtn;
  const imageViewerCaptionInput = document.getElementById('imageViewerCaptionInput'); ed.imageViewerCaptionInput = imageViewerCaptionInput;
  ed.viewerImages = [];
  ed.viewerIndex = null;
  let viewerStorageKey = null;
  let viewerOnUpdate = null;

  function renderViewerCaption() {
    const img = ed.viewerImages[ed.viewerIndex];
    const caption = (img && img.caption) || '';
    imageViewerCaptionOverlay.hidden = !caption;
    imageViewerCaptionOverlay.classList.remove('caption-faded');
    imageViewerCaptionText.textContent = caption;
    imageViewerAddCaptionBtn.textContent = caption ? 'Edit caption' : '+ Add caption';
    // Captions live in the IndexedDB collection the viewer was opened from, so
    // an image with no collection behind it (a talent photo, stored on the
    // talent object) can't offer them.
    imageViewerAddCaptionBtn.hidden = !viewerStorageKey;
    imageViewerCaptionInput.hidden = true;
  }

  // onUpdate re-renders whichever grid opened the viewer after a caption
  // edit; allowProjectPhoto hides the shoot-only "set as project photo"
  // menu when the viewer is opened from a context with no project photo
  // (e.g. journal entry photos).
  function openImageViewer(images, idx, storageKey, onUpdate, allowProjectPhoto) {
    ed.viewerImages = images;
    ed.viewerIndex = idx;
    viewerStorageKey = storageKey;
    viewerOnUpdate = onUpdate || null;
    imageViewerImg.src = images[idx].src;
    imageViewerMenu.hidden = true;
    imageViewerMenuBtn.hidden = allowProjectPhoto === false;
    renderViewerCaption();
    imageViewerOverlay.hidden = false;
    allowViewportZoom(true);
  }

  // The page's own viewport meta pins maximum-scale=1 (no pinch-zoom
  // anywhere) so an accidental double-tap doesn't zoom the whole app while
  // filling out a form — but that blocks pinch-zoom on a full-screen photo
  // too, e.g. a mood board image in Shoot Mode, where it's exactly what
  // you'd want. Relaxed only while the image viewer is open, restored the
  // moment it closes, so the rest of the app keeps its normal no-zoom feel.
  function allowViewportZoom(allow) {
    const meta = document.querySelector('meta[name="viewport"]');
    if (!meta) return;
    meta.setAttribute(
      'content',
      allow
        ? 'width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=5, interactive-widget=resizes-content'
        : 'width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=1, interactive-widget=resizes-content'
    );
  }

  function showViewerImage(idx) {
    if (idx < 0 || idx >= ed.viewerImages.length || idx === ed.viewerIndex) return;
    if (!imageViewerCaptionInput.hidden) saveViewerCaption(imageViewerCaptionInput.value.trim());
    ed.viewerIndex = idx;
    imageViewerImg.src = ed.viewerImages[idx].src;
    renderViewerCaption();
  }

  function saveViewerCaption(newCaption) {
    // No collection key means nothing to write back to (see renderViewerCaption).
    if (!viewerStorageKey) return;
    const key = viewerStorageKey;
    const index = ed.viewerIndex;
    ed.idbGetImages(key).then(imgs => {
      // Opening the caption box and leaving it as it was isn't an edit —
      // nothing to write, and (for a multi-day project) nothing to mirror.
      if (!imgs[index] || (imgs[index].caption || '') === newCaption) {
        renderViewerCaption();
        return;
      }
      imgs[index].caption = newCaption;
      ed.viewerImages = imgs;
      return ed.idbSetImages(key, imgs).then(() => {
        renderViewerCaption();
        if (viewerOnUpdate) viewerOnUpdate();
        // A mood board's key is its shoot id (final images and journal
        // photos use other keys, which onShootImagesChanged ignores).
        ed.onShootImagesChanged(key, { board: true });
      });
    });
  }

  function closeImageViewer() {
    if (!imageViewerCaptionInput.hidden) saveViewerCaption(imageViewerCaptionInput.value.trim());
    imageViewerOverlay.hidden = true;
    imageViewerMenu.hidden = true;
    allowViewportZoom(false);
  }

  document.getElementById('closeImageViewer').addEventListener('click', closeImageViewer);

  document.getElementById('imageViewerMenuBtn').addEventListener('click', () => {
    imageViewerMenu.hidden = !imageViewerMenu.hidden;
  });

  document.getElementById('setProjectPhotoFromViewer').addEventListener('click', () => {
    const img = ed.viewerImages[ed.viewerIndex];
    if (!img) return;
    imageViewerMenu.hidden = true;
    ed.openProjectPhotoCrop(img.src);
  });

  document.getElementById('deleteImageFromViewer').addEventListener('click', async () => {
    imageViewerMenu.hidden = true;
    if (!ed.viewerImages[ed.viewerIndex]) return;
    // Which photo is taken before asking, so it's the one that was showing.
    const deletedIndex = ed.viewerIndex;
    const key = viewerStorageKey;
    if (!(await ed.askDeletePhoto())) return;
    // Only while the viewer's still up on the same photos — it should be,
    // with the popup sitting over it.
    if (imageViewerOverlay.hidden || viewerStorageKey !== key) return;
    ed.idbGetImages(key).then(imgs => {
      imgs.splice(deletedIndex, 1);
      return ed.idbSetImages(key, imgs).then(() => imgs);
    }).then(imgs => {
      ed.viewerImages = imgs;
      if (viewerOnUpdate) viewerOnUpdate();
      ed.onShootImagesChanged(key, { board: true });
      if (!imgs.length) {
        closeImageViewer();
        return;
      }
      ed.viewerIndex = Math.min(deletedIndex, imgs.length - 1);
      imageViewerImg.src = imgs[ed.viewerIndex].src;
      renderViewerCaption();
    });
  });
};
;

// ---- pages/projects/photo-crop.js ----
// Cropping a project's photo: drag to move it, the slider to zoom.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addProjectsPhotoCrop = function addProjectsPhotoCrop(ed) {
  Object.assign(ed, { openProjectPhotoCrop });
  // ---------- Project photo crop (drag to reposition, slider to zoom) ----------
  const cropOverlay = document.getElementById('projectPhotoCropOverlay');
  const cropStage = document.getElementById('cropStage');
  const cropImg = document.getElementById('cropImg');
  const cropZoomSlider = document.getElementById('cropZoomSlider');
  let cropBaseScale = 1;
  let cropZoom = 1;
  let cropOffsetX = 0;
  let cropOffsetY = 0;
  let cropStageWidth = 0;
  let cropStageHeight = 0;
  let cropDragging = false;
  let cropDragStartX = 0;
  let cropDragStartY = 0;
  let cropDragOffsetStartX = 0;
  let cropDragOffsetStartY = 0;
  const cropActivePointers = new Map();
  let cropPinchPrevDist = 0;
  // Set when the crop is opened from the shoot options kebab menu's project
  // photo picker (no shoot form open to autosave through) — confirming the
  // crop then writes straight to state.shoots by id instead of going through
  // pendingProjectPhoto/scheduleShootAutosave.
  ed.cropTargetShootId = null;

  // Keeps the image covering the full crop rectangle at all times — the
  // user can zoom in and reposition, but never past an edge into empty space.
  function clampCropOffsets() {
    const dispW = cropImg.naturalWidth * cropBaseScale * cropZoom;
    const dispH = cropImg.naturalHeight * cropBaseScale * cropZoom;
    const minX = Math.min(0, cropStageWidth - dispW);
    const minY = Math.min(0, cropStageHeight - dispH);
    cropOffsetX = Math.min(0, Math.max(minX, cropOffsetX));
    cropOffsetY = Math.min(0, Math.max(minY, cropOffsetY));
  }

  function applyCropTransform() {
    clampCropOffsets();
    cropImg.style.transform = `translate(${cropOffsetX}px, ${cropOffsetY}px) scale(${cropBaseScale * cropZoom})`;
  }

  // 'project' crops to the shoot bubble's thumbnail (96x120, a 4:5 ratio);
  // 'talent' crops to the 4:5 talent card photo box — same ratio, different
  // absolute size. The stage's own ratio comes from CSS, and the base-scale
  // math below measures the live box, so switching modes is just a class
  // swap plus the matching output canvas size.
  let cropMode = 'project';
  const CROP_OUTPUT = {
    project: { width: 192, height: 240 },
    talent: { width: 240, height: 300 },
  };

  function openProjectPhotoCrop(src, mode) {
    cropMode = mode === 'talent' ? 'talent' : 'project';
    cropStage.classList.toggle('crop-stage-talent', cropMode === 'talent');
    document.getElementById('cropModalTitle').textContent =
      cropMode === 'talent' ? 'Crop talent photo' : 'Set cover photo';
    cropZoom = 1;
    cropZoomSlider.value = '1';
    cropActivePointers.clear();
    cropDragging = false;
    cropImg.onload = () => {
      const stageRect = cropStage.getBoundingClientRect();
      cropStageWidth = stageRect.width;
      cropStageHeight = stageRect.height;
      // Base scale matches object-fit:cover — the shorter side fills the rectangle.
      cropBaseScale = Math.max(cropStageWidth / cropImg.naturalWidth, cropStageHeight / cropImg.naturalHeight);
      const dispW = cropImg.naturalWidth * cropBaseScale;
      const dispH = cropImg.naturalHeight * cropBaseScale;
      cropOffsetX = (cropStageWidth - dispW) / 2;
      cropOffsetY = (cropStageHeight - dispH) / 2;
      applyCropTransform();
    };
    cropImg.src = src;
    cropOverlay.hidden = false;
  }

  function closeProjectPhotoCrop() {
    cropOverlay.hidden = true;
    ed.cropTargetShootId = null;
  }

  cropZoomSlider.addEventListener('input', () => {
    cropZoom = Number(cropZoomSlider.value);
    applyCropTransform();
  });

  // Single finger pans; a second finger switches to pinch-to-zoom, anchored
  // on the midpoint between the two touches each frame so the point under
  // your fingers stays put as you zoom (rather than fighting the single-
  // pointer drag math, which is what caused the jitter on a second touch).
  cropStage.addEventListener('pointerdown', (e) => {
    cropActivePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    try { cropStage.setPointerCapture(e.pointerId); } catch (err) { /* capture is a nice-to-have, not required */ }

    if (cropActivePointers.size === 1) {
      cropDragging = true;
      cropDragStartX = e.clientX;
      cropDragStartY = e.clientY;
      cropDragOffsetStartX = cropOffsetX;
      cropDragOffsetStartY = cropOffsetY;
    } else if (cropActivePointers.size === 2) {
      cropDragging = false;
      const [p1, p2] = [...cropActivePointers.values()];
      cropPinchPrevDist = Math.hypot(p2.x - p1.x, p2.y - p1.y);
    }
  });

  cropStage.addEventListener('pointermove', (e) => {
    if (!cropActivePointers.has(e.pointerId)) return;
    cropActivePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

    if (cropActivePointers.size >= 2) {
      const [p1, p2] = [...cropActivePointers.values()];
      const dist = Math.hypot(p2.x - p1.x, p2.y - p1.y);
      if (cropPinchPrevDist > 0) {
        const rect = cropStage.getBoundingClientRect();
        const midX = (p1.x + p2.x) / 2 - rect.left;
        const midY = (p1.y + p2.y) / 2 - rect.top;
        const scale = cropBaseScale * cropZoom;
        const px = (midX - cropOffsetX) / scale;
        const py = (midY - cropOffsetY) / scale;
        const newZoom = Math.min(3, Math.max(1, cropZoom * (dist / cropPinchPrevDist)));
        cropOffsetX = midX - px * (cropBaseScale * newZoom);
        cropOffsetY = midY - py * (cropBaseScale * newZoom);
        cropZoom = newZoom;
        cropZoomSlider.value = String(cropZoom);
        applyCropTransform();
      }
      cropPinchPrevDist = dist;
    } else if (cropDragging) {
      cropOffsetX = cropDragOffsetStartX + (e.clientX - cropDragStartX);
      cropOffsetY = cropDragOffsetStartY + (e.clientY - cropDragStartY);
      applyCropTransform();
    }
  });

  function endCropPointer(e) {
    cropActivePointers.delete(e.pointerId);
    if (cropActivePointers.size === 1) {
      const [remaining] = [...cropActivePointers.values()];
      cropDragging = true;
      cropDragStartX = remaining.x;
      cropDragStartY = remaining.y;
      cropDragOffsetStartX = cropOffsetX;
      cropDragOffsetStartY = cropOffsetY;
    } else {
      cropDragging = false;
    }
  }
  cropStage.addEventListener('pointerup', endCropPointer);
  cropStage.addEventListener('pointercancel', endCropPointer);

  document.getElementById('cropCloseBtn').addEventListener('click', closeProjectPhotoCrop);

  cropOverlay.addEventListener('click', (e) => {
    if (e.target === cropOverlay) closeProjectPhotoCrop();
  });

  document.getElementById('cropConfirmBtn').addEventListener('click', () => {
    const scale = cropBaseScale * cropZoom;
    const sWidth = cropStageWidth / scale;
    const sHeight = cropStageHeight / scale;
    const sx = -cropOffsetX / scale;
    const sy = -cropOffsetY / scale;
    // Output at the same ratio as the crop stage for the current mode, just at
    // a higher resolution than the on-screen box.
    const { width: outputWidth, height: outputHeight } = CROP_OUTPUT[cropMode];
    const canvas = document.createElement('canvas');
    canvas.width = outputWidth;
    canvas.height = outputHeight;
    canvas.getContext('2d').drawImage(cropImg, sx, sy, sWidth, sHeight, 0, 0, outputWidth, outputHeight);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.7);
    const targetId = ed.cropTargetShootId;
    if (cropMode === 'talent') {
      // Held on the draft only — nothing persists (IndexedDB write, cover-
      // photo claim) until the talent popup's own Save commits it, same as
      // every other field in that popup.
      if (ed.talentModalDraft) {
        ed.talentModalDraft.photo = dataUrl;
        ed.renderTalentModalPhoto();
      }
      closeProjectPhotoCrop();
    } else if (targetId) {
      const idx = ed.state.shoots.findIndex(x => x.id === targetId);
      if (idx !== -1) {
        ed.state.shoots[idx] = { ...ed.state.shoots[idx], projectPhoto: dataUrl };
        ed.saveState();
        ed.savePhotoToIdb(ed.projectPhotoKey(targetId), dataUrl).catch(ed.noteStorageFull)
          .then(() => ed.onShootImagesChanged(targetId, { cover: true }));
        ed.renderAll();
      }
      closeProjectPhotoCrop();
      ed.closeShootOptions();
    } else {
      ed.pendingProjectPhoto = dataUrl;
      ed.scheduleShootAutosave();
      const coverShootId = ed.currentShootId;
      if (coverShootId) {
        ed.savePhotoToIdb(ed.projectPhotoKey(coverShootId), dataUrl).catch(ed.noteStorageFull)
          .then(() => ed.onShootImagesChanged(coverShootId, { cover: true }));
      }
      closeProjectPhotoCrop();
      ed.closeImageViewer();
    }
  });
};
;

// ---- components/image-viewer-touch.js ----
// The image viewer: swiping between pictures and writing a caption.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addImageViewerTouch = function addImageViewerTouch(ed) {
  // Tapping the photo itself fades the caption band in/out so it doesn't
  // permanently block the image; the "add/edit caption" control stays put.
  ed.imageViewerStage.addEventListener('click', () => {
    if (ed.imageViewerCaptionOverlay.hidden) return;
    ed.imageViewerCaptionOverlay.classList.toggle('caption-faded');
  });

  // Swipe left/right to move between images without leaving the viewer.
  let viewerTouchStartX = null;
  let viewerTouchStartY = null;

  ed.imageViewerStage.addEventListener('touchstart', (e) => {
    if (e.touches.length !== 1) { viewerTouchStartX = null; return; }
    viewerTouchStartX = e.touches[0].clientX;
    viewerTouchStartY = e.touches[0].clientY;
  }, { passive: true });

  ed.imageViewerStage.addEventListener('touchend', (e) => {
    if (viewerTouchStartX === null) return;
    const endX = e.changedTouches[0].clientX;
    const endY = e.changedTouches[0].clientY;
    const dx = endX - viewerTouchStartX;
    const dy = endY - viewerTouchStartY;
    viewerTouchStartX = null;
    viewerTouchStartY = null;
    if (Math.abs(dx) < 50 || Math.abs(dx) < Math.abs(dy) * 1.5) return;
    ed.showViewerImage(ed.viewerIndex + (dx < 0 ? 1 : -1));
  }, { passive: true });

  ed.imageViewerAddCaptionBtn.addEventListener('click', () => {
    const img = ed.viewerImages[ed.viewerIndex];
    ed.imageViewerCaptionInput.value = (img && img.caption) || '';
    ed.imageViewerAddCaptionBtn.hidden = true;
    ed.imageViewerCaptionInput.hidden = false;
    ed.imageViewerCaptionInput.focus();
  });

  ed.imageViewerCaptionInput.addEventListener('change', () => {
    ed.saveViewerCaption(ed.imageViewerCaptionInput.value.trim());
  });
};
;

// ---- pages/shoot/final-images.js ----
// Final images on the shoot page.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootFinalImages = function addShootFinalImages(ed) {
  Object.assign(ed, { renderFinalImages });
  function renderFinalImages() {
    const grid = document.getElementById('finalImagesGrid');
    grid.innerHTML = '';
    return ed.idbGetImages(ed.finalImagesKey(ed.currentShootId)).then(images => {
      grid.innerHTML = images.length ? '' : '<p class="empty-hint">No final images yet.</p>';
      images.forEach((img, idx) => {
        const thumb = document.createElement('div');
        thumb.className = 'moodboard-thumb';
        thumb.innerHTML = `<img src="${img.src}" alt="" data-idx="${idx}" /><button type="button" class="final-thumb-delete" data-idx="${idx}"><svg class="x-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6L18 18M18 6L6 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button>`;
        grid.appendChild(thumb);
      });
      grid.querySelectorAll('.final-thumb-delete').forEach(btn => {
        btn.addEventListener('click', async () => {
          // Taken before asking: the photo belongs to the shoot it was tapped on.
          const key = ed.finalImagesKey(ed.currentShootId);
          if (!(await ed.askDeletePhoto())) return;
          ed.idbGetImages(key).then(imgs => {
            imgs.splice(Number(btn.dataset.idx), 1);
            return ed.idbSetImages(key, imgs);
          }).then(renderFinalImages);
        });
      });
      grid.querySelectorAll('.moodboard-thumb img').forEach(imgEl => {
        imgEl.addEventListener('click', () => {
          ed.openImageViewer(images, Number(imgEl.dataset.idx), ed.finalImagesKey(ed.currentShootId), renderFinalImages);
        });
      });
    }).catch(() => { grid.innerHTML = ''; });
  }

  document.getElementById('addFinalPhotos').addEventListener('click', () => {
    document.getElementById('finalImagesFileInput').click();
  });

  document.getElementById('finalImagesFileInput').addEventListener('change', (e) => {
    const files = [...e.target.files];
    e.target.value = '';
    if (!files.length) return;
    // Belt-and-braces: the section is hidden for video, but a picker opened
    // just before a category flip could still land here.
    if (ed.isVideoCategory(document.getElementById('shootCategory').value)) return;
    Promise.all(files.map(f => ed.resizeImageFile(f, 1280, 0.72)))
      .then(newImages => ed.idbGetImages(ed.finalImagesKey(ed.currentShootId)).then(existing => {
        const shouldSetCover = existing.length === 0 && newImages.length > 0;
        const combined = existing.concat(newImages.map(src => ({ src, caption: '' })));
        return ed.idbSetImages(ed.finalImagesKey(ed.currentShootId), combined).then(() => {
          if (shouldSetCover) {
            return ed.resizeDataUrlThumb(newImages[0], 200, 0.6).then(thumb => {
              ed.pendingProjectPhoto = thumb;
              return ed.savePhotoToIdb(ed.projectPhotoKey(ed.currentShootId), thumb);
            });
          }
        });
      }))
      .then(() => {
        ed.shootHasImages = true;
        ed.scheduleShootAutosave();
        renderFinalImages();
      })
      .catch(ed.noteStorageFull);
  });
};
;

// ---- pages/shoot/shoot-save.js ----
// Saving a shoot as you go: what the form holds, and when it's saved.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootSave = function addShootSave(ed) {
  Object.assign(ed, { gatherShootFormData, applyStatusTimestamps, autosaveShoot, scheduleShootAutosave, saveShootNow });
  function gatherShootFormData() {
    const frameworkTags = [...document.querySelectorAll(ed.FRAMEWORK_TAG_CHECKED_SELECTOR)]
      .map(cb => ({ frameworkId: cb.dataset.fw, tag: cb.value }));

    const teamRequired = ed.getTeamRequiredChoice();

    return {
      title: document.getElementById('shootTitle').value.trim(),
      status: document.getElementById('shootStatus').value,
      date: document.getElementById('shootDate').value,
      // Always present, so a status moved back onto the schedule clears the
      // saved one in the {...oldShoot, ...data} spread (an undefined key is
      // left out of the JSON that's stored).
      offScheduleDate: ed.currentOffScheduleDate,
      deadline: document.getElementById('shootDeadline').value,
      startTime: document.getElementById('shootStartTime').value,
      endTime: document.getElementById('shootEndTime').value,
      crewCallTime: document.getElementById('shootCrewCallTime').value,
      talentCallTime: document.getElementById('shootTalentCallTime').value,
      location: { ...ed.currentShootLocation },
      talents: ed.currentTalents.map(t => ({ id: t.id, name: t.name.trim(), socialHandles: [...t.socialHandles], photo: t.photo || '' })),
      category: document.getElementById('shootCategory').value,
      premise: document.getElementById('shootPremise').value.trim(),
      character: document.getElementById('shootCharacter').value.trim(),
      shootGoals: document.getElementById('shootGoals').value.trim(),
      elevatorPitch: document.getElementById('shootElevatorPitch').value.trim(),
      // Video-only, but kept (not cleared) while hidden for other categories
      // so a flip away from Video and back doesn't lose them.
      deliverables: document.getElementById('shootDeliverables').value.trim(),
      aspectRatios: ed.normalizeAspectRatios([...document.querySelectorAll('#shootAspectRatios input[type="checkbox"]:checked')].map(cb => cb.value)),
      deliverableDestinations: document.getElementById('shootDeliverableDestinations').value.trim(),
      worldNotes: document.getElementById('shootWorldNotes').value.trim(),
      moodboardComplete: document.getElementById('shootMoodboardComplete').checked,
      teamRequired,
      teamFinalized: document.getElementById('shootTeamFinalized').checked,
      // Kept whatever the team answer: "Just me" only hides the list, so
      // switching back to "With a team" brings everyone straight back.
      teamMembers: [...ed.currentTeamMembers],
      references: ed.currentReferences.map(r => r.trim()).filter(r => r),
      frameworkTags,
      whatWentRight: document.getElementById('shootWentRight').value.trim(),
      couldBeBetter: document.getElementById('shootCouldBeBetter').value.trim(),
      lessonsLearned: document.getElementById('shootLessonsLearned').value.trim(),
      talentDirections: document.getElementById('shootTalentDirections').value.trim(),
      teamDirections: document.getElementById('shootTeamDirections').value.trim(),
      shootingNotes: document.getElementById('shootShootingNotes').value.trim(),
      locationDirections: document.getElementById('shootLocationDirections').value.trim(),
      shotList: [...ed.currentShotList],
      lightingSetups: [...ed.currentLightingSetups],
      // Omitted rather than set to null when there's nothing pending: there's
      // no "remove cover photo" action anywhere, so pendingProjectPhoto only
      // legitimately goes from empty to a real photo, never back down. If it
      // reads empty here it's because this shoot's photo hadn't finished
      // loading from IndexedDB yet when the modal opened (that's async, and
      // runs once at boot) — spreading an explicit null over the shoot's
      // existing photo on every autosave/blur was silently wiping the
      // thumbnail. Leaving the key out lets the {...oldShoot, ...data} spread
      // in autosaveShoot() keep whatever the shoot already had.
      ...(ed.pendingProjectPhoto ? { projectPhoto: ed.pendingProjectPhoto } : {}),
    };
  }

  // A brand-new, never-touched shoot draft shouldn't get written to state
  // just because the modal was opened — only once it actually has content.
  function isShootDataBlank(data) {
    // The country field pre-fills itself from state.defaultCountry on every
    // brand-new shoot draft, so it can't count as "the user entered
    // something" here or every untouched New Shoot would silently save.
    const loc = data.location;
    const locationEffectivelyBlank = !ed.hasText(loc.name) && !ed.hasText(loc.street) && !ed.hasText(loc.city) && !ed.hasText(loc.zip) && !ed.hasText(loc.state);
    return !ed.hasText(data.title) && locationEffectivelyBlank && !ed.hasText(data.startTime) && !ed.hasText(data.endTime)
      && !ed.hasText(data.crewCallTime) && !ed.hasText(data.talentCallTime)
      && !ed.hasText(data.deliverables) && data.aspectRatios.length === 0 && !ed.hasText(data.deliverableDestinations)
      && data.talents.every(t => !ed.hasText(t.name) && t.socialHandles.length === 0 && !ed.hasText(t.photo)) && !ed.hasText(data.premise) && !ed.hasText(data.character) && !ed.hasText(data.shootGoals) && !ed.hasText(data.elevatorPitch)
      && !ed.hasText(data.worldNotes) && !ed.hasText(data.deadline)
      && !ed.hasText(data.whatWentRight) && !ed.hasText(data.couldBeBetter) && !ed.hasText(data.lessonsLearned)
      && !ed.hasText(data.talentDirections) && !ed.hasText(data.teamDirections) && !ed.hasText(data.locationDirections)
      && !ed.hasText(data.shootingNotes) && data.shotList.length === 0
      && data.lightingSetups.length === 0
      && data.frameworkTags.length === 0 && data.references.length === 0
      && data.teamMembers.length === 0 && !data.moodboardComplete && !data.teamRequired && !data.teamFinalized
      && !data.projectPhoto;
  }

  // Records the first time a shoot reaches "captured" and the edit (Editing
  // for photo shoots; Rough cut/Client review/Revisions for video) so the
  // daily report can compute "N days since capture" / "N days since editing".
  // Never overwrites an already-set timestamp, even if status bounces back
  // and forth, so it always reflects the first time each milestone was hit.
  // Delivered is the exception: deliveredAt is when it was last marked
  // Delivered, for the Monday brief's count of last week's deliveries — one
  // sent back for revisions and delivered again went out that second time.
  function applyStatusTimestamps(shoot, oldStatus, newStatus) {
    if (oldStatus === newStatus) return;
    if (ed.isPostCaptureStatus(newStatus) && !shoot.capturedAt) {
      shoot.capturedAt = new Date().toISOString();
    }
    if (ed.isInTheEditStatus(newStatus) && !shoot.editingAt) {
      shoot.editingAt = new Date().toISOString();
    }
    if (newStatus === 'delivered') {
      shoot.deliveredAt = new Date().toISOString();
    }
  }

  // `force` is only ever passed (as exactly true) by the Multi-day "Create
  // days" flow: Day 1 has to exist as a real saved shoot before a project can
  // link to it or days can be copied from it, even when the date is the only
  // thing filled in so far — and isShootDataBlank deliberately ignores the
  // date. Checked with === true so the timer/listener paths that call this
  // with no argument can never trip it by accident. Returns the saved shoot,
  // or undefined when a blank draft was skipped.
  function autosaveShoot(force) {
    const data = gatherShootFormData();
    const idx = ed.state.shoots.findIndex(x => x.id === ed.currentShootId);
    let shoot;
    if (idx === -1) {
      if (force !== true && isShootDataBlank(data) && !ed.shootHasImages) return;
      shoot = { id: ed.currentShootId, ...data };
      applyStatusTimestamps(shoot, null, shoot.status);
      ed.state.shoots.push(shoot);
      document.getElementById('deleteShootBtn').hidden = false;
    } else {
      const oldStatus = ed.state.shoots[idx].status;
      shoot = { ...ed.state.shoots[idx], ...data };
      applyStatusTimestamps(shoot, oldStatus, shoot.status);
      ed.state.shoots[idx] = shoot;
    }
    ed.saveState();
    return shoot;
  }

  function scheduleShootAutosave() {
    clearTimeout(ed.shootSaveTimer);
    // Only a backstop for text still being typed — leaving the field and
    // backgrounding the app both save immediately (see below), so this doesn't
    // need to be eager. It used to be 500ms, which meant a save on every
    // natural pause mid-sentence.
    ed.shootSaveTimer = setTimeout(autosaveShoot, 2000);
    // Every change made on a wizard slide passes through here — typed and
    // picked fields via the form listeners below, and the popup saves and
    // list edits (talent, location, team, deadline, shots, setups, links,
    // photos) that fire no form event — so it's the one hook the wizard's
    // step count and filled-in field looks need.
    if (ed.shootWizardActive) ed.refreshShootWizard();
  }

  function saveShootNow() {
    if (ed.shootModalOverlay.hidden || !ed.currentShootId) return;
    clearTimeout(ed.shootSaveTimer);
    autosaveShoot();
  }

  ed.shootForm.addEventListener('input', scheduleShootAutosave);
  // Delegated at the form level rather than per-field, so it covers inputs
  // rendered later by the talent/team/references list renderers without
  // needing its own listener wired up at every render site.
  ed.shootForm.addEventListener('input', (e) => ed.syncFieldFilledState(e.target));
  ed.shootForm.addEventListener('change', scheduleShootAutosave);
  ed.shootForm.addEventListener('submit', (e) => e.preventDefault());
  // Commit as soon as focus leaves a field, so the pending-debounce window is
  // only ever open while you're actually still in a field typing.
  ed.shootForm.addEventListener('focusout', saveShootNow);
};
;

// ---- pages/shoot/multi-day.js ----
// A multi-day shoot, in Logistics: its days and dates.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootMultiDay = function addShootMultiDay(ed) {
  Object.assign(ed, { multiDayDatesText, multiDayMembership, resetMultiDayDraft, updateMultiDayRow, markShootModalAsSaved });
  // ---------- Multi-day shoot (Logistics) ----------
  // A checkbox under Shoot date that turns this shoot into Day 1 of a new
  // project, with one copied shoot per following day (see
  // copyShootForProject). Never part of the shoot's own data: nothing here is
  // read by gatherShootFormData, and both controls stop their input/change
  // events at the source so they never schedule an autosave of their own.
  // Membership only changes through the explicit actions below (Create days,
  // or unticking a member), and the row is always rebuilt from saved state by
  // updateMultiDayRow().
  const MULTI_DAY_MAX_DAYS = 14;
  ed.multiDayPromptDates = null;
  ed.multiDayCreating = false;

  // 'YYYY-MM-DD' shifted by n calendar days. Done on a local Date's day field
  // rather than by adding n * 86400000ms, so a DST change in between can
  // never land it a day off.
  function addDaysToDateStr(dateStr, n) {
    const d = ed.parseShootDate(dateStr);
    d.setDate(d.getDate() + n);
    return ed.formatDate(d);
  }

  // Every date from start to end, inclusive. Stops one past the limit —
  // enough for the caller to tell "too long" apart without walking a
  // mis-picked year-long range a day at a time.
  function multiDayDateRange(startStr, endStr) {
    const dates = [];
    let d = startStr;
    while (d <= endStr && dates.length <= MULTI_DAY_MAX_DAYS) {
      dates.push(d);
      d = addDaysToDateStr(d, 1);
    }
    return dates;
  }

  // "Oct 14, 15 and 16" — the month is only repeated when it changes
  // ("Oct 31 and Nov 1"). Past 4 days a full list stops being readable, so
  // it collapses to "Oct 14 – Oct 20 (7 days)".
  function multiDayDatesText(dates) {
    const monthDay = (ds) => ed.parseShootDate(ds).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    if (dates.length > 4) {
      return `${monthDay(dates[0])} – ${monthDay(dates[dates.length - 1])} (${dates.length} days)`;
    }
    return ed.joinWithAnd(dates.map((ds, i) => (
      i > 0 && ds.slice(0, 7) === dates[i - 1].slice(0, 7)
        ? String(ed.parseShootDate(ds).getDate())
        : monthDay(ds)
    )));
  }

  // The open shoot's saved project membership as { shoot, project }, or null.
  // Read by id from saved state, never the form, so a never-saved draft is
  // always "not a member". A projectId pointing at a missing project counts
  // as no project, same as collapseProjects.
  function multiDayMembership() {
    const shoot = ed.state.shoots.find(x => x.id === ed.currentShootId);
    const project = shoot && shoot.projectId ? ed.findProject(shoot.projectId) : null;
    return project ? { shoot, project } : null;
  }

  // Back to a plain unticked row with the Last day picker hidden and empty.
  function resetMultiDayDraft() {
    document.getElementById('shootMultiDay').checked = false;
    const lastDayInput = document.getElementById('shootLastDay');
    lastDayInput.value = '';
    lastDayInput.removeAttribute('min');
    lastDayInput.removeAttribute('max');
    document.getElementById('multiDayLastDayLabel').hidden = true;
  }

  // Rebuilds the row from saved membership: a member reads as a ticked
  // "Part of <project> · Day N of M" (the day suffix only when projectDayInfo
  // has one — dated, not postponed/canceled, 2+ live dates in the project);
  // anything else is a fresh unticked "Multi-day shoot". Called from
  // openShootModal and after every membership change made while the shoot
  // modal is open.
  function updateMultiDayRow() {
    resetMultiDayDraft();
    const label = document.getElementById('multiDayLabel');
    const membership = multiDayMembership();
    if (!membership) {
      label.textContent = 'Multi-day shoot';
      return;
    }
    const info = ed.projectDayInfo(membership.shoot);
    document.getElementById('shootMultiDay').checked = true;
    // Says how this day relates to its project's lead day, when it has one:
    // the lead, a day mirroring it, or a day that's been made its own.
    const lead = ed.projectLeadOf(membership.project);
    let mirrorText = '';
    if (lead && lead.id === membership.shoot.id) {
      mirrorText = ' · mirrored to the other days';
    } else if (lead) {
      const leadInfo = ed.projectDayInfo(lead);
      mirrorText = membership.shoot.followsLead
        ? ` · mirrors ${leadInfo ? `Day ${leadInfo.day}` : 'the first day'}`
        : ' · has its own changes';
    }
    label.textContent = `Part of ${membership.project.name}${info ? ` · Day ${info.day} of ${info.total}` : ''}${mirrorText}`;
  }

  // Keeps the Last day picker's allowed range anchored to the shoot date:
  // from the day after it up to 13 days after it (14 days in all).
  function setLastDayRange(startDate) {
    const lastDayInput = document.getElementById('shootLastDay');
    lastDayInput.min = addDaysToDateStr(startDate, 1);
    lastDayInput.max = addDaysToDateStr(startDate, MULTI_DAY_MAX_DAYS - 1);
  }

  // A brand-new draft that Create days just force-saved is a real saved shoot
  // now — so the modal switches to behaving like Edit Shoot for it, showing
  // the same edit-only controls openShootModal(id) would have (Share, Delete,
  // Shoot mode, Complete). No-op for a shoot that was already open for editing.
  function markShootModalAsSaved() {
    if (ed.editingShootId === ed.currentShootId) return;
    ed.editingShootId = ed.currentShootId;
    document.getElementById('deleteShootBtn').hidden = false;
    document.getElementById('shareShootBtn').hidden = false;
    const isArchived = !document.getElementById('unarchiveShootBtn').hidden;
    document.getElementById('completeShootBtn').hidden = isArchived || document.getElementById('shootStatus').value !== 'delivered';
    ed.updateEnterShootModeBtnVisibility();
  }

  // Neither control is shoot data, so neither may reach the form-level
  // input/change listeners (scheduleShootAutosave, syncFieldFilledState).
  ['shootMultiDay', 'shootLastDay'].forEach(id => {
    document.getElementById(id).addEventListener('input', (e) => e.stopPropagation());
  });

  document.getElementById('shootMultiDay').addEventListener('change', async (e) => {
    e.stopPropagation();
    const checkbox = e.target;
    const membership = multiDayMembership();
    if (membership) {
      // A member's box only ever goes from ticked to unticked by hand —
      // that's the "take it out of the project" gesture.
      if (checkbox.checked) return;
      // Ticked again while it asks: the box only reads unticked once the
      // shoot really is out (updateMultiDayRow below), so "Keep it in"
      // needs nothing undone.
      checkbox.checked = true;
      const shootId = membership.shoot.id;
      const ok = await ed.askConfirm({
        title: `Take this shoot out of ${membership.project.name}?`,
        text: 'It stays as its own shoot.',
        confirmLabel: 'Take it out',
        cancelLabel: 'Keep it in',
      });
      // Still this shoot's page, and still in that project (the popup sits
      // over the page, so both should be).
      const current = multiDayMembership();
      if (!ok || ed.shootModalOverlay.hidden || !current || current.shoot.id !== shootId) return;
      // Commit any edit still sitting in the debounce first, so the lists
      // re-rendered below already show it.
      ed.saveShootNow();
      ed.setShootProject(current.shoot.id, '');
      ed.saveState();
      ed.renderAll();
      ed.refreshOpenStatBoxDetail();
      updateMultiDayRow();
      return;
    }
    if (!checkbox.checked) {
      resetMultiDayDraft();
      return;
    }
    const startDate = document.getElementById('shootDate').value;
    if (!startDate) {
      checkbox.checked = false;
      ed.showToast('Set the shoot date first');
      return;
    }
    document.getElementById('shootLastDay').value = '';
    setLastDayRange(startDate);
    document.getElementById('multiDayLastDayLabel').hidden = false;
    maybeShowMultiDayNotice();
  });

  // A heads-up the moment Multi-day is ticked — on the shoot page or in the
  // new-shoot guide — that each day gets a shoot page of its own, before the
  // Last day picker and the confirm popup. "Don't show again" is remembered
  // on this device.
  const MULTI_DAY_NOTICE_HIDDEN_KEY = 'dailies_multi_day_notice_hidden_v1';

  function maybeShowMultiDayNotice() {
    let hidden;
    try { hidden = localStorage.getItem(MULTI_DAY_NOTICE_HIDDEN_KEY) === '1'; } catch (err) { hidden = false; }
    if (!hidden) document.getElementById('multiDayNoticeOverlay').hidden = false;
  }

  document.getElementById('multiDayNoticeOkBtn').addEventListener('click', () => {
    document.getElementById('multiDayNoticeOverlay').hidden = true;
  });

  document.getElementById('multiDayNoticeHideBtn').addEventListener('click', () => {
    try { localStorage.setItem(MULTI_DAY_NOTICE_HIDDEN_KEY, '1'); } catch (err) { /* storage unavailable — nothing to remember it in */ }
    document.getElementById('multiDayNoticeOverlay').hidden = true;
  });

  document.getElementById('shootLastDay').addEventListener('change', (e) => {
    e.stopPropagation();
    const lastDayInput = e.target;
    const lastDay = lastDayInput.value;
    if (!lastDay || multiDayMembership()) return;
    // Desktop keyboards fire change mid-typing ("0002-10-16" after the first
    // year digit) — wait for a real four-digit year before checking it.
    if (lastDay.slice(0, 4) < '1000') return;
    const startDate = document.getElementById('shootDate').value;
    if (!startDate) {
      resetMultiDayDraft();
      ed.showToast('Set the shoot date first');
      return;
    }
    if (lastDay <= startDate) {
      lastDayInput.value = '';
      ed.showToast('Pick a last day after the shoot date');
      return;
    }
    const dates = multiDayDateRange(startDate, lastDay);
    if (dates.length > MULTI_DAY_MAX_DAYS) {
      lastDayInput.value = '';
      ed.showToast(`Multi-day shoots can be up to ${MULTI_DAY_MAX_DAYS} days`);
      return;
    }
    // Dismisses the native date picker so it isn't left floating over the
    // prompt (the focusout this fires runs the usual saveShootNow — harmless).
    lastDayInput.blur();
    ed.openMultiDayPrompt(dates);
  });

  // The shoot date moving — or being cleared — changes what the row should
  // say. A member's "Day N of M" is worked out from saved dates, so the edit
  // is committed first; a non-member's in-progress pick has its Last day
  // range re-anchored, or is dropped entirely if there's no date left to
  // anchor it to.
  function syncMultiDayRowToShootDate() {
    if (multiDayMembership()) {
      ed.saveShootNow();
      updateMultiDayRow();
      return;
    }
    if (!document.getElementById('shootMultiDay').checked) return;
    const startDate = document.getElementById('shootDate').value;
    if (!startDate) {
      resetMultiDayDraft();
      return;
    }
    document.getElementById('shootLastDay').value = '';
    setLastDayRange(startDate);
  }

  document.getElementById('shootDate').addEventListener('change', syncMultiDayRowToShootDate);
};
;

// ---- pages/shoot/multi-day-prompt.js ----
// Multi-day: back on schedule, and the prompt for the other days.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootMultiDayPrompt = function addShootMultiDayPrompt(ed) {
  Object.assign(ed, { openMultiDayPrompt });
  // A new date on a Postponed or Canceled shoot most likely means it's back
  // on, so the page asks, with the answers named for what they do. Keeping
  // the status leaves the new date as the plan it's moved to (it isn't the
  // date it went off the schedule with, see isOriginalPlanDate); "Back on
  // the schedule" moves it to Active planning the way the status button
  // does, so that change's own follow-ups run too. Asked once the date field
  // is let go of — a date typed on a keyboard changes on every digit — and
  // only while the page is still open on that shoot, still off the schedule,
  // with a date that isn't the one it went off the schedule with.
  let backOnScheduleAskFor = null;

  async function askBackOnSchedule() {
    const shootId = backOnScheduleAskFor;
    backOnScheduleAskFor = null;
    const select = document.getElementById('shootStatus');
    const status = select.value;
    const date = document.getElementById('shootDate').value;
    if (!ed.shootPageOpenOn(shootId) || !ed.isOffScheduleShoot({ status }) || !date || date === ed.currentOffScheduleDate) return;
    const label = ed.STATUS_LABELS[status].toLowerCase();
    const backOn = await ed.askConfirm({
      title: 'New date. Is it back on?',
      text: `This shoot is ${label}. Put it back on the schedule for ${ed.prettyDate(date)}, or keep it ${label} for now?`,
      cancelLabel: `Keep ${label}`,
      confirmLabel: 'Back on the schedule',
    });
    // Nothing to do if the page closed or the status moved meanwhile.
    if (!backOn || !ed.shootPageOpenOn(shootId) || select.value !== status) return;
    select.value = 'planning';
    select.dispatchEvent(new Event('change', { bubbles: true }));
    ed.saveShootNow();
  }

  document.getElementById('shootDate').addEventListener('change', (e) => {
    if (!ed.isOffScheduleShoot({ status: document.getElementById('shootStatus').value })) return;
    backOnScheduleAskFor = ed.currentShootId;
    if (document.activeElement !== e.target) askBackOnSchedule();
  });
  document.getElementById('shootDate').addEventListener('blur', () => {
    if (backOnScheduleAskFor) askBackOnSchedule();
  });
  // A status change never touches the date any more (Postponed/Canceled keep
  // it), so a non-member's Last day pick is left alone; but a member's "Day
  // N of M" still moves with it, since a postponed or canceled day stops
  // counting as a day of the project (isProjectLiveShoot).
  document.getElementById('shootStatus').addEventListener('change', () => {
    if (!ed.multiDayMembership()) return;
    ed.saveShootNow();
    ed.updateMultiDayRow();
  });

  function openMultiDayPrompt(dates) {
    ed.multiDayPromptDates = dates;
    const term = ed.moodboardTerm(document.getElementById('shootCategory').value).toLowerCase();
    document.getElementById('multiDayPromptText').textContent =
      `This makes a separate shoot for each day: ${ed.multiDayDatesText(dates)}. Everything on Day 1 (talent, team, location, concept, notes, ${term} and lighting setups) is mirrored to the other days, including any changes you make to Day 1 later. Each day keeps its own date, times, status, shot list and reflection. Note: if you change anything on another day yourself, that day keeps its own version and won't pick up later changes to Day 1.`;
    // Read off the form rather than saved state — a brand-new draft has
    // nothing saved yet, and an existing shoot may have unsaved edits.
    const talent = ed.currentTalents.find(t => ed.hasText(t.name));
    document.getElementById('multiDayProjectNameInput').value =
      document.getElementById('shootTitle').value.trim() || (talent ? talent.name.trim() : '') || ed.UNTITLED_PROJECT_NAME;
    document.getElementById('multiDayPromptOverlay').hidden = false;
  }

  function closeMultiDayPrompt() {
    document.getElementById('multiDayPromptOverlay').hidden = true;
    ed.multiDayPromptDates = null;
  }

  document.getElementById('multiDayPromptCancelBtn').addEventListener('click', () => {
    if (ed.multiDayCreating) return;
    closeMultiDayPrompt();
    ed.resetMultiDayDraft();
  });

  document.getElementById('multiDayProjectNameInput').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') document.getElementById('multiDayPromptCreateBtn').click();
  });

  document.getElementById('multiDayPromptCreateBtn').addEventListener('click', async () => {
    if (ed.multiDayCreating) return;
    const dates = ed.multiDayPromptDates;
    if (!dates || dates.length < 2 || ed.shootModalOverlay.hidden || ed.multiDayMembership()) {
      closeMultiDayPrompt();
      ed.updateMultiDayRow();
      return;
    }
    ed.multiDayCreating = true;
    const createBtn = document.getElementById('multiDayPromptCreateBtn');
    createBtn.textContent = 'Creating…';
    let project = null;
    let sourceId = null;
    try {
      const name = document.getElementById('multiDayProjectNameInput').value.trim() || ed.UNTITLED_PROJECT_NAME;
      // Day 1 must be a real saved shoot before a project can point at it or
      // anything can be copied from it. Forced: a draft whose only content so
      // far is its date reads as blank to isShootDataBlank (the date is
      // deliberately not counted), so a normal autosave would skip it — and
      // closeShootModal would then wipe it as an abandoned draft.
      clearTimeout(ed.shootSaveTimer);
      const day1 = ed.autosaveShoot(true);
      sourceId = day1.id;
      ed.markShootModalAsSaved();
      project = ed.createProject(name);
      ed.setShootProject(sourceId, project.id);
      // Saved straight away so the link survives even if the app is
      // backgrounded and discarded while the days below are still copying.
      ed.saveState();
      // setShootProject spread-writes a new object — copy from the live one.
      const source = ed.state.shoots.find(x => x.id === sourceId);
      try {
        // One at a time, in date order, so the new shoots land in
        // state.shoots (and their IndexedDB rows) in the same order as
        // their days.
        for (const date of dates.slice(1)) {
          const day = await ed.copyShootForProject(source, 'day', { date, projectId: project.id });
          // Each new day follows Day 1 (see syncProjectMirrors).
          if (day && day.projectId === project.id) {
            day.followsLead = true;
            day.mirrorSig = ed.mirrorSignature(day);
          }
        }
      } catch (err) {
        // An IndexedDB write failing part-way (e.g. storage full) keeps the
        // days that did get made; the toast below says how many that was.
      }
      // Day 1 becomes the lead the other days mirror; its current details
      // are what they were just copied from.
      const liveProject = ed.findProject(project.id);
      const lead = ed.state.shoots.find(x => x.id === sourceId);
      if (liveProject && lead) {
        liveProject.leadShootId = sourceId;
        liveProject.mirrorSig = ed.mirrorSignature(lead);
      }
      ed.saveState();
    } finally {
      ed.multiDayCreating = false;
      createBtn.textContent = 'Create days';
    }
    closeMultiDayPrompt();
    ed.renderAll();
    ed.refreshOpenStatBoxDetail();
    if (!ed.shootModalOverlay.hidden && ed.currentShootId === sourceId) ed.updateMultiDayRow();
    const total = ed.projectMembers(project.id).length;
    ed.showToast(total === dates.length
      ? `${total} days created in ${project.name}`
      : `Only ${total} of ${dates.length} days could be created in ${project.name}`);
  });
};
;

// ---- pages/shoot/shoot-close.js ----
// Closing a shoot, and deleting one.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootClose = function addShootClose(ed) {
  Object.assign(ed, { closeShootModal, deleteShootById, askDeleteShoot, syncPaneTrackHeight });
  function closeShootModal() {
    // First: every borrowed field goes home (with its readonly back) before
    // the scroll position is recorded and the draft saved or discarded.
    ed.endShootWizard({ closing: true });
    clearTimeout(ed.shootSaveTimer);
    ed.autosaveShoot();
    if (!ed.state.shoots.some(x => x.id === ed.currentShootId)) {
      ed.dropRefBoardsFor(ed.currentShootId);
      ed.idbDeleteImages(ed.currentShootId).catch(() => {});
      ed.idbDeleteImages(ed.finalImagesKey(ed.currentShootId)).catch(() => {});
      // Abandoned blank shoot — drop any photo rows it managed to create too.
      ed.idbDeleteImages(ed.projectPhotoKey(ed.currentShootId)).catch(() => {});
      ed.currentTalents.forEach(t => {
        if (t.id) ed.idbDeleteImages(ed.talentPhotoKey(ed.currentShootId, t.id)).catch(() => {});
      });
    }
    if (!ed.shootModalOverlay.hidden) ed.unlockBodyScroll();
    ed.shootModalOverlay.hidden = true;
    ed.editingShootId = null;
    ed.renderAll();
    ed.refreshOpenStatBoxDetail();
  }

  document.getElementById('saveShootBtn').addEventListener('click', closeShootModal);

  function deleteShootById(id) {
    const doomed = ed.state.shoots.find(x => x.id === id);
    ed.state.shoots = ed.state.shoots.filter(x => x.id !== id);
    ed.state.journalEntries = ed.state.journalEntries.filter(e => e.sourceShootId !== id);
    // A project is only its shoots, so one whose last shoot this was goes too.
    ed.pruneEmptyProjects();
    ed.idbDeleteImages(id).catch(() => {});
    ed.idbDeleteImages(ed.finalImagesKey(id)).catch(() => {});
    ed.dropRefBoardsFor(id);
    // Cover + per-talent photos live under their own keys, so they need
    // explicit cleanup or they'd linger as orphaned rows.
    if (doomed) ed.shootPhotoKeys(doomed).forEach(k => ed.idbDeleteImages(k).catch(() => {}));
    ed.saveState();
  }

  // The page's Delete shoot and the ⋮ menu's ask the same thing.
  function askDeleteShoot() {
    return ed.askConfirm({ title: 'Delete this shoot?', text: "This can't be undone.", confirmLabel: 'Delete shoot', cancelLabel: 'Keep it', danger: true });
  }

  document.getElementById('deleteShootBtn').addEventListener('click', async () => {
    const id = ed.currentShootId;
    // Only if the page is still on that shoot — it should be, with the
    // popup sitting over it.
    if (!(await askDeleteShoot()) || ed.currentShootId !== id || ed.shootModalOverlay.hidden) return;
    clearTimeout(ed.shootSaveTimer);
    deleteShootById(id);
    if (!ed.shootModalOverlay.hidden) ed.unlockBodyScroll();
    ed.shootModalOverlay.hidden = true;
    ed.editingShootId = null;
    ed.renderAll();
    ed.refreshOpenStatBoxDetail();
  });

  document.getElementById('shareShootBtn').addEventListener('click', () => {
    // buildShootPdf reads from state.shoots, not the live form fields — so
    // an edit still sitting in the 2s autosave debounce (e.g. just closed
    // the expand-field editor for Directions for talent/team, then tapped
    // Share right away) would otherwise get left out of the PDF.
    ed.saveShootNow();
    if (ed.editingShootId) ed.openPdfSectionsModal(ed.editingShootId);
  });

  // A pane track (kebab-menu slide-over, app menu) is a horizontal row of
  // same-width panes moved via transform, one shown at a time — as a flex
  // row its own height still auto-sizes to the TALLEST pane regardless of
  // which one is actually showing, so switching to a shorter pane (e.g. the
  // theme picker vs the full app menu list) left blank space below its
  // content, same underlying issue as the Stats carousel. Call this after
  // every classList change that shows a different pane.
  function syncPaneTrackHeight(track) {
    const panes = [...track.children].filter(el => el.classList.contains('options-pane'));
    let idx = 0;
    if (track.classList.contains('show-fifth')) idx = 4;
    else if (track.classList.contains('show-fourth')) idx = 3;
    else if (track.classList.contains('show-third')) idx = 2;
    else if (track.classList.contains('show-second')) idx = 1;
    const active = panes[idx];
    if (active) track.style.height = active.offsetHeight + 'px';
  }
};
;

// ---- pages/shoot-options/shoot-options.js ----
// A shoot's options (its menu on a row or card).
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootOptions = function addShootOptions(ed) {
  Object.assign(ed, { openShootOptions, closeShootOptions, focusPaneInput });
  // ---------- Shoot options (row/card kebab menu) ----------
  const shootOptionsOverlay = document.getElementById('shootOptionsOverlay'); ed.shootOptionsOverlay = shootOptionsOverlay;
  const shootOptionsPaneTrack = document.getElementById('shootOptionsPaneTrack'); ed.shootOptionsPaneTrack = shootOptionsPaneTrack;
  ed.optionsShootId = null;

  function openShootOptions(id) {
    ed.optionsShootId = id;
    const s = ed.state.shoots.find(x => x.id === id);
    document.getElementById('archiveShootOptionBtn').textContent = (s && s.archived) ? 'Unarchive shoot' : 'Archive shoot';
    // Same idea as Archive/Unarchive just above: the item keeps its slot and
    // says which project a member is already in, so the sheet it opens
    // reads as "manage" for a member rather than "add".
    const optionsProject = (s && s.projectId) ? ed.findProject(s.projectId) : null;
    document.getElementById('projectShootOptionBtn').textContent = optionsProject ? `Project: ${optionsProject.name}` : 'Add to project';
    // The pane track slides via CSS transform, not native scrolling — reset
    // any stray scroll position (e.g. from a focused input the browser tried
    // to "reveal") so it can't stack with the transform and misalign panes.
    shootOptionsOverlay.querySelector('.modal').scrollLeft = 0;
    shootOptionsOverlay.hidden = false;
    ed.syncPaneTrackHeight(shootOptionsPaneTrack);
  }

  function closeShootOptions() {
    shootOptionsOverlay.hidden = true;
    ed.optionsShootId = null;
    shootOptionsPaneTrack.classList.remove('show-second');
    shootOptionsPaneTrack.classList.remove('show-third');
    shootOptionsPaneTrack.classList.remove('show-fourth');
    shootOptionsPaneTrack.classList.remove('show-fifth');
  }

  // Focusing an input inside a pane that's off its untransformed (layout)
  // position — every pane past the first is, since the track slides via
  // CSS transform rather than scrolling — can make the browser auto-scroll
  // the modal to "reveal" it, even with preventScroll set (unreliable on
  // some engines). That scroll then stacks with the transform and shoves
  // every pane out of view, so force it back to 0 right after focusing.
  function focusPaneInput(input) {
    input.focus({ preventScroll: true });
    shootOptionsOverlay.querySelector('.modal').scrollLeft = 0;
  }
};
;

// ---- pages/shoot-options/change-title.js ----
// Changing a shoot's title.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootOptionsChangeTitle = function addShootOptionsChangeTitle(ed) {
  // ---------- Change shoot title (kebab menu slide-over) ----------
  document.getElementById('changeTitleOptionBtn').addEventListener('click', () => {
    const s = ed.state.shoots.find(x => x.id === ed.optionsShootId);
    const input = document.getElementById('shootTitleRenameInput');
    input.value = s ? (s.title || '') : '';
    ed.shootOptionsPaneTrack.classList.add('show-third');
    ed.syncPaneTrackHeight(ed.shootOptionsPaneTrack);
    ed.focusPaneInput(input);
  });

  document.getElementById('titleOptionsBackBtn').addEventListener('click', () => {
    ed.shootOptionsPaneTrack.classList.remove('show-third');
    ed.syncPaneTrackHeight(ed.shootOptionsPaneTrack);
  });

  function saveTitleOption() {
    const id = ed.optionsShootId;
    const newTitle = document.getElementById('shootTitleRenameInput').value.trim();
    ed.closeShootOptions();
    if (!id) return;
    const idx = ed.state.shoots.findIndex(x => x.id === id);
    if (idx === -1) return;
    ed.state.shoots[idx] = { ...ed.state.shoots[idx], title: newTitle };
    ed.saveState();
    ed.renderAll();
  }

  document.getElementById('saveTitleOptionBtn').addEventListener('click', saveTitleOption);

  document.getElementById('shootTitleRenameInput').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') saveTitleOption();
  });
};
;

// ---- pages/shoot-options/change-photo.js ----
// Changing a project's photo.
// (Loaded before app.js, which runs it in its turn.)
window.EyeParts = window.EyeParts || {};
window.EyeParts.addShootOptionsChangePhoto = function addShootOptionsChangePhoto(ed) {
  // ---------- Change project photo (kebab menu slide-over) ----------
  document.getElementById('changeProjectPhotoOptionBtn').addEventListener('click', () => {
    const id = ed.optionsShootId;
    const grid = document.getElementById('projectPhotoPickerGrid');
    grid.innerHTML = '';
    ed.shootOptionsPaneTrack.classList.add('show-fourth');
    ed.syncPaneTrackHeight(ed.shootOptionsPaneTrack);
    if (!id) return;
    // Video has no final images (any left from before a switch to video
    // stay hidden), so only its storyboard is offered.
    const pickerShoot = ed.state.shoots.find(x => x.id === id);
    const finalImagesPromise = ed.isVideoShoot(pickerShoot) ? Promise.resolve([]) : ed.idbGetImages(ed.finalImagesKey(id));
    Promise.all([ed.idbGetImages(id), finalImagesPromise]).then(([moodboardImages, finalImages]) => {
      const allImages = moodboardImages.concat(finalImages);
      grid.innerHTML = allImages.length ? '' : '<p class="empty-hint">No photos yet.</p>';
      allImages.forEach(img => {
        const thumb = document.createElement('div');
        thumb.className = 'moodboard-thumb';
        thumb.innerHTML = `<img src="${img.src}" alt="" />`;
        thumb.querySelector('img').addEventListener('click', () => {
          ed.cropTargetShootId = id;
          ed.openProjectPhotoCrop(img.src);
        });
        grid.appendChild(thumb);
      });
      // The grid's own contents load async, and its height can change once
      // photos land (the grid scrolls internally past a cap, but "no photos
      // yet" vs a full row is still a real height difference).
      ed.syncPaneTrackHeight(ed.shootOptionsPaneTrack);
    }).catch(() => { grid.innerHTML = ''; });
  });

  document.getElementById('projectPhotoBackBtn').addEventListener('click', () => {
    ed.shootOptionsPaneTrack.classList.remove('show-fourth');
    ed.syncPaneTrackHeight(ed.shootOptionsPaneTrack);
  });

  document.getElementById('addProjectPhotoFromDeviceBtn').addEventListener('click', () => {
    document.getElementById('projectPhotoFileInput').click();
  });

  document.getElementById('projectPhotoFileInput').addEventListener('change', (e) => {
    const file = e.target.files[0];
    e.target.value = '';
    if (!file) return;
    const id = ed.optionsShootId;
    if (!id) return;
    ed.resizeImageFile(file, 1280, 0.72).then(dataUrl => {
      ed.cropTargetShootId = id;
      ed.openProjectPhotoCrop(dataUrl);
    }).catch(() => {});
  });
};
;

// ---- pages/shoot-options/change-deadline.js ----
// Changing a shoot's deadline.
